VBI({"OBJ-00400":{"k":"object","n":"Psalm 32","d":"David's Contemplation on the blessedness of the one whose sin is forgiven (Psalm 32)","f":[{"p":"contents","r":"Psalms 32:1–11; Romans 4:6–8","v":"Blessed is the one whose transgression is forgiven and whose sin is covered: while David kept silent his bones wasted under the LORD's heavy hand, but when he confessed his sin the LORD forgave it; the LORD is his hiding place and promises to instruct and guide him, and mercy surrounds the one who trusts in Him"},{"p":"designation","r":"Psalms 32","v":"A Psalm of David"},{"p":"designation","r":"NKJV notes, note on Psalm 32:1; Psalms 32","v":"A Contemplation"},{"p":"made by","r":"Psalms 32; Romans 4:6–8","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00401":{"k":"object","n":"Psalm 33","d":"The psalm of praise to the LORD, by whose word the heavens were made (Psalm 33)","f":[{"p":"contents","r":"Psalms 33:1–22","v":"The righteous are called to praise the LORD with the harp, an instrument of ten strings and a new song; by His word the heavens were made, for He spoke and it was done; He gathers the sea as a heap, brings the counsel of the nations to nothing and sees all the sons of men; blessed is the nation whose God is the LORD, for no king is saved by an army, nor anyone by a horse"},{"p":"designation","r":"Psalms 33:1","v":"Rejoice in the LORD, O you righteous"}],"nm":{}},"OBJ-00402":{"k":"object","n":"Psalm 34","d":"David's psalm when he pretended madness before Abimelech, who drove him away (Psalm 34)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 34:7; Psalms 34:1–22","v":"David will bless the LORD at all times, for He heard this poor man and saved him out of all his troubles; the angel of the LORD encamps around those who fear Him; he bids all taste and see the LORD's goodness, and teaches the fear of the LORD: keep the tongue from evil and seek peace, for the LORD is near the brokenhearted and guards all the bones of the righteous"},{"p":"designation","r":"Psalms 34","v":"A Psalm of David"},{"p":"made by","r":"Psalms 34","e":"PER-00661"},{"p":"occasion","r":"Psalms 34","e":"EVT-01118"}],"nm":{"EVT-01118":"David feigns madness before Achish","PER-00661":"David"}},"OBJ-00403":{"k":"object","n":"Psalm 35","d":"David's plea that the LORD fight those who fight against him (Psalm 35)","f":[{"p":"contents","r":"Psalms 35:1–28","v":"David asks the LORD to plead his cause and fight those who fight him, letting the angel of the LORD chase them like chaff; false witnesses repay him evil for good, though he fasted in sackcloth when they were sick, and they hate him without a cause; he asks the LORD to awake to his vindication, and will praise Him in the great assembly"},{"p":"designation","r":"Psalms 35","v":"A Psalm of David"},{"p":"made by","r":"Psalms 35","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00404":{"k":"object","n":"Psalm 36","d":"David's psalm of the wicked man's transgression and the LORD's lovingkindness (Psalm 36)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 36:6; Psalms 36:1–12","v":"The wicked man has no fear of God before his eyes, flatters himself and plots evil on his bed; but the LORD's mercy reaches the heavens and His faithfulness the clouds, His righteousness is like the great mountains (by the note, the mountains of God), and men trust under the shadow of His wings, for with Him is the fountain of life, and in His light they see light"},{"p":"designation","r":"Psalms 36","v":"A Psalm of David"},{"p":"made by","r":"Psalms 36","e":"PER-00661"},{"p":"purpose","r":"Psalms 36","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00405":{"k":"object","n":"Psalm 37","d":"David's counsel not to fret because of evildoers (Psalm 37)","f":[{"p":"contents","r":"Psalms 37:1–40","v":"David counsels not to fret because of evildoers, who will soon wither like grass, but to trust in the LORD, delight in Him and commit one's way to Him; the meek shall inherit the earth and the LORD upholds the righteous; now old, David has never seen the righteous forsaken nor their children begging bread, while the wicked shall be cut off"},{"p":"designation","r":"Psalms 37","v":"A Psalm of David"},{"p":"made by","r":"Psalms 37","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00406":{"k":"object","n":"Psalm 38","d":"David's psalm in time of chastening, to bring to remembrance (Psalm 38)","f":[{"p":"contents","r":"Psalms 38:1–22","v":"David begs the LORD not to rebuke him in wrath, for His arrows pierce him and there is no health in his bones because of his sin; his wounds fester, his friends stand aloof and his enemies lay snares, yet like a deaf and mute man he waits in hope, confesses his iniquity, and asks the LORD, his salvation, to hurry to help him"},{"p":"designation","r":"Psalms 38","v":"A Psalm of David"},{"p":"made by","r":"Psalms 38","e":"PER-00661"},{"p":"purpose","r":"Psalms 38","v":"To bring to remembrance"}],"nm":{"PER-00661":"David"}},"OBJ-00407":{"k":"object","n":"Psalm 39","d":"David's psalm on the measure of his days, given to Jeduthun (Psalm 39)","f":[{"p":"contents","r":"Psalms 39:1–13","v":"David resolved to guard his tongue before the wicked, but as he mused the fire burned and he asked the LORD to show him the measure of his days, for every man at his best is but vapor and walks about like a shadow; his hope is in the LORD, and he asks to be heard, for he is a stranger and sojourner with Him, as all his fathers were"},{"p":"designation","r":"Psalms 39","v":"A Psalm of David"},{"p":"made by","r":"Psalms 39","e":"PER-00661"},{"p":"purpose","r":"Psalms 39","v":"Given to the Chief Musician"},{"p":"purpose","r":"Psalms 39","v":"Given to Jeduthun"}],"nm":{"PER-00661":"David"}},"OBJ-00408":{"k":"object","n":"Psalm 40","d":"David's psalm of the new song, who came to do God's will (Psalm 40)","f":[{"p":"contents","r":"Psalms 40:1–17; Hebrews 10:5–7","v":"David waited patiently for the LORD, who drew him out of a horrible pit and miry clay, set his feet on a rock and gave him a new song; the LORD did not desire sacrifice and offering, but David came to do His will, with His law in his heart, words Hebrews applies to Christ; he proclaimed His righteousness in the great assembly, and asks Him to hurry to deliver him from evils more than the hairs of his head"},{"p":"designation","r":"Psalms 40","v":"A Psalm of David"},{"p":"made by","r":"Psalms 40","e":"PER-00661"},{"p":"purpose","r":"Psalms 40","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00409":{"k":"object","n":"Psalm 41","d":"David's psalm of the one who considers the poor, betrayed by his familiar friend (Psalm 41)","f":[{"p":"contents","r":"Psalms 41:1–13; John 13:18","v":"Blessed is the one who considers the poor: the LORD will keep him alive and strengthen him on his sickbed; David's enemies wait for him to die, and even his familiar friend who ate his bread has lifted up his heel against him, words Jesus applied to His betrayer; the LORD upholds David in his integrity, and the psalm, and Book One, close with a blessing of the LORD God of Israel"},{"p":"designation","r":"Psalms 41","v":"A Psalm of David"},{"p":"made by","r":"Psalms 41","e":"PER-00661"},{"p":"purpose","r":"Psalms 41","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00410":{"k":"object","n":"Psalm 42","d":"The sons of Korah's psalm of the soul that thirsts for the living God (Psalm 42)","f":[{"p":"contents","r":"Psalms 42:1–11","v":"Like a deer longing for streams of water, the psalmist's soul thirsts for the living God; tears are his food while men ask where his God is, and he remembers going with the festive multitude to the house of God; cast down, he remembers God from the land of the Jordan, the heights of Hermon and the Hill Mizar, and bids his soul hope in God"},{"p":"designation","r":"NKJV notes, note on Psalm 42:1; Psalms 42","v":"A Contemplation of the sons of Korah"},{"p":"made by","r":"Psalms 42","e":"GRP-00086"},{"p":"purpose","r":"Psalms 42","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00411":{"k":"object","n":"Psalm 43","d":"The psalm that asks God to send His light and truth to bring the psalmist to His holy hill (Psalm 43)","f":[{"p":"contents","r":"Psalms 43:1–5","v":"The psalmist asks God to vindicate him against an ungodly nation and a deceitful man, and to send out His light and truth to bring him to His holy hill and tabernacle, where he will go to the altar of God, his exceeding joy, and praise Him on the harp; he bids his downcast soul hope in God"},{"p":"designation","r":"Psalms 43:1","v":"Vindicate me, O God"}],"nm":{}},"OBJ-00412":{"k":"object","n":"Psalm 44","d":"The sons of Korah's psalm of the deeds of old and of Israel cast off (Psalm 44)","f":[{"p":"contents","r":"Psalms 44:1–26; Romans 8:36","v":"The fathers told how God drove out the nations by His hand and planted Israel, who won the land not by their own sword but by His right arm; yet now He has cast them off, given them up like sheep for food, scattered them among the nations and made them a byword, though they have not forgotten His covenant; for His sake they are killed all day long, words Paul quotes, and they ask Him to awake and redeem them"},{"p":"designation","r":"NKJV notes, note on Psalm 44:1; Psalms 44","v":"A Contemplation of the sons of Korah"},{"p":"made by","r":"Psalms 44","e":"GRP-00086"},{"p":"purpose","r":"Psalms 44","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00413":{"k":"object","n":"Psalm 45","d":"The sons of Korah's song of love for the King and His bride (Psalm 45)","f":[{"p":"contents","r":"Psalms 45:1–17; Hebrews 1:8–9","v":"The psalmist recites his composition for the King, fairer than the sons of men, who rides out in majesty for truth and righteousness; the King, addressed as God, has a throne that is forever and is anointed with the oil of gladness, words Hebrews applies to the Son; the queen stands at His right hand in gold from Ophir, the daughter of Tyre comes with a gift, and the royal bride and her companions are brought into the King's palace"},{"p":"designation","r":"NKJV notes, note on Psalm 45:1; Psalms 45","v":"A Contemplation of the sons of Korah"},{"p":"designation","r":"Psalms 45","v":"A Song of Love"},{"p":"feature","r":"NKJV notes, note on Psalm 45:1; Psalms 45","v":"Set to 'The Lilies' (Hebrew Shoshannim)"},{"p":"made by","r":"Psalms 45","e":"GRP-00086"},{"p":"purpose","r":"Psalms 45","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00414":{"k":"object","n":"Psalm 46","d":"The sons of Korah's song of God their refuge, whose river makes glad the city of God (Psalm 46)","f":[{"p":"contents","r":"Psalms 46:1–11","v":"God is His people's refuge and strength, so they will not fear though the earth be removed and the mountains carried into the sea; a river makes glad the city of God, the holy dwelling of the Most High, and God is in her midst; the LORD of hosts, the God of Jacob, is with them, who makes wars cease to the end of the earth; they are bidden be still and know that He is God"},{"p":"designation","r":"Psalms 46","v":"A Psalm of the sons of Korah"},{"p":"feature","r":"Psalms 46","v":"A song set for Alamoth"},{"p":"made by","r":"Psalms 46","e":"GRP-00086"},{"p":"purpose","r":"Psalms 46","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00415":{"k":"object","n":"Psalm 47","d":"The sons of Korah's psalm of the LORD Most High, King over all the earth (Psalm 47)","f":[{"p":"contents","r":"Psalms 47:1–9","v":"All peoples are called to clap their hands and shout to God, for the LORD Most High is awesome, a great King over all the earth, who subdues the nations under His people and chooses their inheritance; God has gone up with a shout, reigns over the nations and sits on His holy throne, and the princes of the peoples gather as the people of the God of Abraham"},{"p":"designation","r":"Psalms 47","v":"A Psalm of the sons of Korah"},{"p":"made by","r":"Psalms 47","e":"GRP-00086"},{"p":"purpose","r":"Psalms 47","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00416":{"k":"object","n":"Psalm 48","d":"The sons of Korah's song of Mount Zion, the city of the great King (Psalm 48)","f":[{"p":"contents","r":"Psalms 48:1–14","v":"Great is the LORD in the city of our God, His holy mountain: Mount Zion, lofty and beautiful, the joy of the whole earth, the city of the great King, where God is known in her palaces as a refuge; kings who assembled against her saw it and fled in fear, as when the east wind breaks the ships of Tarshish; all are bidden walk about Zion, count her towers, mark her bulwarks and consider her palaces, to tell the next generation"},{"p":"designation","r":"Psalms 48","v":"A Psalm of the sons of Korah"},{"p":"made by","r":"Psalms 48","e":"GRP-00086"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00417":{"k":"object","n":"Psalm 49","d":"The sons of Korah's psalm on the folly of trusting in riches (Psalm 49)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 49:15; Psalms 49:1–20","v":"The psalmist calls all peoples, low and high, to hear his riddle on the harp: those who trust in wealth cannot redeem a brother or give God a ransom to live forever; wise and foolish alike die and leave their wealth to others, and man in honor without understanding is like the beasts that perish; but God will redeem his soul from the power of the grave (or Sheol, by the NKJV note)"},{"p":"designation","r":"Psalms 49","v":"A Psalm of the sons of Korah"},{"p":"made by","r":"Psalms 49","e":"GRP-00086"},{"p":"purpose","r":"Psalms 49","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00418":{"k":"object","n":"Psalm 50","d":"Asaph's psalm of God the Judge, who shines out of Zion (Psalm 50)","f":[{"p":"contents","r":"Psalms 50:1–23","v":"The Mighty One, God the LORD, calls the earth and shines out of Zion, the perfection of beauty, to judge His people; He does not need their bulls and goats, for every beast and the cattle on a thousand hills are His, but asks thanksgiving and vows paid to the Most High; He rebukes the wicked who recite His covenant yet join thieves and adulterers and slander their brothers"},{"p":"designation","r":"Psalms 50","v":"A Psalm of Asaph"},{"p":"made by","r":"Psalms 50","e":"PER-01496"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00419":{"k":"object","n":"Psalm 51","d":"David's prayer of repentance when Nathan the prophet came to him after Bathsheba (Psalm 51)","f":[{"p":"contents","r":"Psalms 51:1–19","v":"David asks God, by His lovingkindness, to blot out his transgressions and wash him from his sin, which is ever before him and was against God alone; brought forth in iniquity, he asks to be purged with hyssop and made whiter than snow, to be given a clean heart, not to be cast from God's presence nor have His Holy Spirit taken from him, and to be delivered from the guilt of bloodshed; God desires a broken and contrite heart, and David prays that He will build the walls of Jerusalem"},{"p":"designation","r":"Psalms 51","v":"A Psalm of David"},{"p":"made by","r":"Psalms 51","e":"PER-00661"},{"p":"occasion","r":"Psalms 51","e":"EVT-01278"},{"p":"purpose","r":"Psalms 51","v":"Given to the Chief Musician"}],"nm":{"EVT-01278":"Nathan rebukes David","PER-00661":"David"}},"OBJ-00420":{"k":"object","n":"Psalm 52","d":"David's Contemplation when Doeg the Edomite told Saul that David had gone to Ahimelech (Psalm 52)","f":[{"p":"contents","r":"Psalms 52:1–9","v":"David asks the mighty man why he boasts in evil, with a tongue like a sharp razor, loving lies more than truth; God will uproot him from the land of the living, and the righteous will say he trusted in his riches and not in God; but David is like a green olive tree in the house of God, trusting in His mercy forever"},{"p":"designation","r":"NKJV notes, note on Psalm 52:1; Psalms 52","v":"A Contemplation of David"},{"p":"made by","r":"Psalms 52","e":"PER-00661"},{"p":"occasion","r":"Psalms 52","e":"EVT-01124"},{"p":"purpose","r":"Psalms 52","v":"Given to the Chief Musician"}],"nm":{"EVT-01124":"Doeg tells of David at Nob","PER-00661":"David"}},"OBJ-00421":{"k":"object","n":"Psalm 53","d":"David's Contemplation of the fool who says there is no God, set to 'Mahalath' (Psalm 53)","f":[{"p":"contents","r":"Psalms 14:1–7; 53:1–6","v":"The fool says in his heart there is no God; God looks down from heaven and finds none who does good; the workers of iniquity are put in great fear, for God has scattered the bones of him who encamps against His people; David longs for Israel's salvation to come out of Zion; the psalm nearly repeats Psalm 14"},{"p":"designation","r":"NKJV notes, note on Psalm 53:1; Psalms 53","v":"A Contemplation of David"},{"p":"feature","r":"Psalms 53","v":"Set to 'Mahalath'"},{"p":"made by","r":"Psalms 53","e":"PER-00661"},{"p":"purpose","r":"Psalms 53","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00422":{"k":"object","n":"Psalm 54","d":"David's Contemplation when the Ziphites told Saul he was hiding with them (Psalm 54)","f":[{"p":"contents","r":"Psalms 54:1–7","v":"David asks God to save him by His name, for strangers and oppressors seek his life without regard for God; God is his helper and will repay his enemies, and David will freely sacrifice and praise His name, for He has delivered him from all trouble"},{"p":"designation","r":"NKJV notes, note on Psalm 54:1; Psalms 54","v":"A Contemplation of David"},{"p":"feature","r":"NKJV notes, note on Psalm 54:1; Psalms 54","v":"With stringed instruments (Hebrew neginoth)"},{"p":"made by","r":"Psalms 54","e":"PER-00661"},{"p":"occasion","r":"1 Samuel 23:19; 26:1; Psalms 54","e":"EVT-01135","b":"inferred","c":"probable","w":"The title gives the Ziphites' words to Saul as 1 Samuel 23:19 gives them; they came to him again in 1 Samuel 26:1."},{"p":"purpose","r":"Psalms 54","v":"Given to the Chief Musician"}],"nm":{"EVT-01135":"The Ziphites betray David","PER-00661":"David"}},"OBJ-00423":{"k":"object","n":"Psalm 55","d":"David's Contemplation on the treachery of a companion (Psalm 55)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 55:15; Psalms 55:1–23","v":"In terror David wishes for wings like a dove to fly away and be at rest, for violence and strife fill the city; it is not an enemy who reproaches him but his own companion, with whom he walked to the house of God, whose words were smoother than butter while war was in his heart; David calls on God evening, morning and noon, and bids all cast their burden on the LORD, who will sustain them"},{"p":"designation","r":"NKJV notes, note on Psalm 55:1; Psalms 55","v":"A Contemplation of David"},{"p":"feature","r":"NKJV notes, note on Psalm 55:1; Psalms 55","v":"With stringed instruments (Hebrew neginoth)"},{"p":"made by","r":"Psalms 55","e":"PER-00661"},{"p":"purpose","r":"Psalms 55","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00424":{"k":"object","n":"Psalm 56","d":"David's Michtam when the Philistines seized him in Gath (Psalm 56)","f":[{"p":"contents","r":"Psalms 56:1–13","v":"Hounded all day by enemies who twist his words and lie in wait for his life, David trusts in God and will not fear what man can do to him; God counts his wanderings and keeps his tears in His bottle, and David will pay his vows, for God has delivered his soul from death"},{"p":"designation","r":"Psalms 56","v":"A Michtam of David"},{"p":"feature","r":"NKJV notes, note on Psalm 56:1; Psalms 56","v":"Set to 'The Silent Dove in Distant Lands' (Hebrew Jonath Elem Rechokim)"},{"p":"made by","r":"Psalms 56","e":"PER-00661"},{"p":"occasion","r":"1 Samuel 21:10–15; Psalms 56","e":"EVT-01118","b":"inferred","c":"probable","w":"The title has the Philistines seize David in Gath; 1 Samuel 21:10–15 tells how Achish's servants knew him there and he was very much afraid."},{"p":"purpose","r":"Psalms 56","v":"Given to the Chief Musician"}],"nm":{"EVT-01118":"David feigns madness before Achish","PER-00661":"David"}},"OBJ-00425":{"k":"object","n":"Psalm 57","d":"David's Michtam when he fled from Saul into the cave (Psalm 57)","f":[{"p":"contents","r":"Psalms 57:1–11","v":"David takes refuge in the shadow of God's wings until calamities pass, crying to God Most High, who will send from heaven and save him; his soul is among lions whose teeth are spears, but his heart is steadfast, and he will awaken the dawn with lute and harp and praise God among the nations, whose mercy reaches the heavens"},{"p":"designation","r":"Psalms 57","v":"A Michtam of David"},{"p":"feature","r":"NKJV notes, note on Psalm 57:1; Psalms 57","v":"Set to 'Do Not Destroy' (Hebrew Al Tashcheth)"},{"p":"made by","r":"Psalms 57","e":"PER-00661"},{"p":"occasion","r":"1 Samuel 22:1; 24:3; Psalms 57","e":"EVT-01119","b":"inferred","c":"possible","w":"The title has David flee from Saul into the cave: he escaped to the cave of Adullam (1 Samuel 22:1), and later hid in a cave in the wilderness of En Gedi when Saul came in (1 Samuel 24:3)."},{"p":"occasion","r":"1 Samuel 22:1; 24:3; Psalms 57","e":"EVT-01138","b":"inferred","c":"possible","w":"The title has David flee from Saul into the cave: he escaped to the cave of Adullam (1 Samuel 22:1), and later hid in a cave in the wilderness of En Gedi when Saul came in (1 Samuel 24:3)."},{"p":"purpose","r":"Psalms 57","v":"Given to the Chief Musician"}],"nm":{"EVT-01119":"David gathers four hundred men at the cave of Adullam","EVT-01138":"David spares Saul in the cave","PER-00661":"David"}},"OBJ-00426":{"k":"object","n":"Psalm 58","d":"David's Michtam on unjust judges, whom God will judge (Psalm 58)","f":[{"p":"contents","r":"Psalms 58:1–11","v":"David asks the rulers whether they judge uprightly, for they work wickedness and are like a deaf cobra that will not hear the charmer; he asks God to break their teeth and sweep them away, so that men will say there is a reward for the righteous and a God who judges in the earth"},{"p":"designation","r":"Psalms 58","v":"A Michtam of David"},{"p":"feature","r":"NKJV notes, note on Psalm 58:1; Psalms 58","v":"Set to 'Do Not Destroy' (Hebrew Al Tashcheth)"},{"p":"made by","r":"Psalms 58","e":"PER-00661"},{"p":"purpose","r":"Psalms 58","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00427":{"k":"object","n":"Psalm 59","d":"David's Michtam when Saul sent men to watch his house to kill him (Psalm 59)","f":[{"p":"contents","r":"Psalms 59:1–17","v":"David asks the LORD God of hosts to deliver him from bloodthirsty men who lie in wait for him through no fault of his; at evening they come back, growl like dogs and prowl around the city, but the LORD laughs at them, and David sings of His power and mercy, for God is his defense and refuge in the day of trouble"},{"p":"designation","r":"Psalms 59","v":"A Michtam of David"},{"p":"feature","r":"NKJV notes, note on Psalm 59:1; Psalms 59","v":"Set to 'Do Not Destroy' (Hebrew Al Tashcheth)"},{"p":"made by","r":"Psalms 59","e":"PER-00661"},{"p":"occasion","r":"1 Samuel 19:11; Psalms 59","e":"EVT-01109"},{"p":"purpose","r":"Psalms 59","v":"Given to the Chief Musician"}],"nm":{"EVT-01109":"Michal lets David down through a window","PER-00661":"David"}},"OBJ-00428":{"k":"object","n":"Psalm 60","d":"David's Michtam, for teaching, from his wars with Syria of Zobah and the Valley of Salt (Psalm 60)","f":[{"p":"contents","r":"Psalms 60:1–12","v":"God has cast His people off and made the land tremble, yet He has given a banner to those who fear Him; He has spoken in His holiness that He will divide Shechem and measure out the Valley of Succoth, that Gilead, Manasseh, Ephraim and Judah are His, that Moab is His washpot, over Edom He casts His shoe, and over Philistia He triumphs; David asks who will bring him to the strong city of Edom, for through God they will do valiantly"},{"p":"designation","r":"Psalms 60","v":"A Michtam of David"},{"p":"feature","r":"NKJV notes, note on Psalm 60:1; Psalms 60","v":"Set to 'Lily of the Testimony' (Hebrew Shushan Eduth)"},{"p":"made by","r":"Psalms 60","e":"PER-00661"},{"p":"occasion","r":"Psalms 60","e":"EVT-01256"},{"p":"occasion","r":"Psalms 60","e":"EVT-01261"},{"p":"occasion","r":"2 Samuel 10:16–18; 1 Chronicles 19:6; Psalms 60","e":"EVT-01268","b":"inferred","c":"possible","w":"The title has David fight Mesopotamia; the Syrians he fought at Helam came from beyond the River (2 Samuel 10:16–18), and the Ammonites had hired chariots from Mesopotamia (1 Chronicles 19:6)."},{"p":"purpose","r":"Psalms 60","v":"Given to the Chief Musician"},{"p":"purpose","r":"Psalms 60","v":"For teaching"}],"nm":{"EVT-01256":"David defeats Hadadezer king of Zobah","EVT-01261":"Eighteen thousand are struck in the Valley of Salt","EVT-01268":"David defeats the Syrians at Helam","PER-00661":"David"}},"OBJ-00429":{"k":"object","n":"Psalm 61","d":"David's cry to be led to the rock that is higher than he (Psalm 61)","f":[{"p":"contents","r":"Psalms 61:1–8","v":"From the end of the earth David cries to God to lead him to the rock that is higher than he, for God has been his shelter and strong tower; he will abide in His tabernacle under the shelter of His wings, and asks God to prolong the king's life for many generations"},{"p":"designation","r":"Psalms 61","v":"A Psalm of David"},{"p":"feature","r":"NKJV notes, note on Psalm 61:1; Psalms 61","v":"On a stringed instrument (Hebrew neginah)"},{"p":"made by","r":"Psalms 61","e":"PER-00661"},{"p":"purpose","r":"Psalms 61","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00430":{"k":"object","n":"Psalm 62","d":"David's psalm of waiting silently for God alone, given to Jeduthun (Psalm 62)","f":[{"p":"contents","r":"Psalms 62:1–12; Romans 2:6","v":"David's soul waits silently for God alone, his rock, salvation and defense, while men plot to cast him down and bless with their mouths but curse inwardly; men high and low are lighter than vapor, riches are not to be trusted, power belongs to God and mercy to the LORD, who renders to each according to his work"},{"p":"designation","r":"Psalms 62","v":"A Psalm of David"},{"p":"made by","r":"Psalms 62","e":"PER-00661"},{"p":"purpose","r":"Psalms 62","v":"Given to the Chief Musician"},{"p":"purpose","r":"Psalms 62","v":"Given to Jeduthun"}],"nm":{"PER-00661":"David"}},"OBJ-00431":{"k":"object","n":"Psalm 63","d":"David's psalm when he was in the wilderness of Judah (Psalm 63)","f":[{"p":"contents","r":"Psalms 63:1–11","v":"Early David seeks God, his soul thirsting for Him in a dry and thirsty land; he has looked for His power and glory in the sanctuary, and since His lovingkindness is better than life he will praise Him, remember Him in the night watches and rejoice in the shadow of His wings; those who seek his life will fall by the sword, but the king shall rejoice in God"},{"p":"designation","r":"Psalms 63","v":"A Psalm of David"},{"p":"made by","r":"Psalms 63","e":"PER-00661"},{"p":"occasion","r":"2 Samuel 15:23, 28; Psalms 63, 11","e":"EVT-01295","b":"inferred","c":"possible","w":"The title sets the psalm in the wilderness of Judah, and it speaks of the king (Psalm 63:11); fleeing from Absalom, David crossed the Brook Kidron toward the wilderness and waited in its plains (2 Samuel 15:23, 28)."}],"nm":{"EVT-01295":"David flees from Jerusalem","PER-00661":"David"}},"OBJ-00432":{"k":"object","n":"Psalm 64","d":"David's prayer to be hidden from the secret plots of the wicked (Psalm 64)","f":[{"p":"contents","r":"Psalms 64:1–10","v":"David asks God to hide him from the secret plots of the workers of iniquity, who sharpen their tongues like swords and shoot bitter words at the blameless; God will shoot at them with an arrow and make them stumble over their own tongues, so that all men fear and the righteous are glad in the LORD"},{"p":"designation","r":"Psalms 64","v":"A Psalm of David"},{"p":"made by","r":"Psalms 64","e":"PER-00661"},{"p":"purpose","r":"Psalms 64","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00433":{"k":"object","n":"Psalm 65","d":"David's song of praise awaiting God in Zion for His goodness to the earth (Psalm 65)","f":[{"p":"contents","r":"Psalms 65:1–13","v":"Praise awaits God in Zion, who hears prayer and provides atonement for transgressions; blessed is the one He chooses to dwell in His courts; He set the mountains in place, stills the seas and the tumult of the peoples, waters the earth from the river of God, provides grain, and crowns the year with His goodness, so that pastures and valleys shout for joy"},{"p":"designation","r":"Psalms 65","v":"A Psalm of David"},{"p":"designation","r":"Psalms 65","v":"A Song"},{"p":"made by","r":"Psalms 65","e":"PER-00661"},{"p":"purpose","r":"Psalms 65","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00434":{"k":"object","n":"Psalm 66","d":"The song calling all the earth to see the awesome works of God (Psalm 66)","f":[{"p":"contents","r":"Psalms 66:1–20","v":"All the earth is called to shout to God and see His awesome works: He turned the sea into dry land and they went through the river on foot; He tested His people like silver and brought them through fire and water to abundance; the psalmist will pay his vows in God's house with burnt offerings, for God heard his prayer and did not turn His mercy from him"},{"p":"designation","r":"Psalms 66","v":"A Song. A Psalm"},{"p":"purpose","r":"Psalms 66","v":"Given to the Chief Musician"}],"nm":{}},"OBJ-00435":{"k":"object","n":"Psalm 67","d":"The song asking God to bless His people, that all nations may praise Him (Psalm 67)","f":[{"p":"contents","r":"Psalms 67:1–7","v":"A prayer that God be merciful, bless His people and make His face shine on them, so that His way and salvation be known among all nations; the peoples are called to praise Him, for He judges them righteously, and the earth yields her increase as all its ends fear Him"},{"p":"designation","r":"Psalms 67","v":"A Psalm. A Song"},{"p":"feature","r":"NKJV notes, note on Psalm 67:1; Psalms 67","v":"On stringed instruments (Hebrew neginoth)"},{"p":"purpose","r":"Psalms 67","v":"Given to the Chief Musician"}],"nm":{}},"OBJ-00436":{"k":"object","n":"Psalm 68","d":"David's song of God's march from Sinai and His procession into the sanctuary (Psalm 68)","f":[{"p":"contents","r":"Psalms 68:1–35; Ephesians 4:8","v":"Let God arise and scatter His enemies; the righteous sing to Him whose name is YAH, a father of the fatherless and defender of widows; when He marched before His people through the wilderness the earth shook and Sinai itself was moved; kings of armies fled, and when the Almighty scattered kings it was white as snow in Zalmon; the many-peaked mountain of Bashan envies the mountain God chose to dwell in; He ascended on high, led captivity captive and received gifts among men, words Paul applies to Christ; His procession enters the sanctuary with singers, players and maidens with timbrels, little Benjamin, and the princes of Judah, Zebulun and Naphtali; kings will bring presents for His temple at Jerusalem, envoys will come from Egypt, and Ethiopia will stretch out her hands to God"},{"p":"designation","r":"Psalms 68","v":"A Psalm of David"},{"p":"designation","r":"Psalms 68","v":"A Song"},{"p":"made by","r":"Psalms 68","e":"PER-00661"},{"p":"purpose","r":"Psalms 68","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00437":{"k":"object","n":"Psalm 69","d":"David's cry from the deep waters, hated without a cause (Psalm 69)","f":[{"p":"contents","r":"Psalms 69:1–36; Matthew 27:34; John 2:17; 15:25; Acts 1:16, 20; Romans 11:9–10","v":"David sinks in deep mire with the waters up to his neck; those who hate him without a cause are more than the hairs of his head; zeal for God's house has eaten him up, and he has become a stranger to his brothers and the song of drunkards; they gave him gall for food and vinegar to drink; he prays that their dwelling be desolate and that they be blotted out of the book of the living; God will save Zion and build the cities of Judah; the Gospels and Acts apply its words to Jesus and to Judas"},{"p":"designation","r":"Psalms 69","v":"A Psalm of David"},{"p":"feature","r":"NKJV notes, note on Psalm 69:1; Psalms 69","v":"Set to 'The Lilies' (Hebrew Shoshannim)"},{"p":"made by","r":"Psalms 69; Acts 1:16, 20; Romans 11:9–10","e":"PER-00661"},{"p":"purpose","r":"Psalms 69","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00438":{"k":"object","n":"Psalm 70","d":"David's plea for God to hurry to help him, to bring to remembrance (Psalm 70)","f":[{"p":"contents","r":"Psalms 40:13–17; 70:1–5","v":"David asks God to hurry to deliver him and to shame those who seek his life and mock him, and to let all who seek Him rejoice, for he is poor and needy; the psalm repeats the close of Psalm 40"},{"p":"designation","r":"Psalms 70","v":"A Psalm of David"},{"p":"made by","r":"Psalms 70","e":"PER-00661"},{"p":"purpose","r":"Psalms 70","v":"Given to the Chief Musician"},{"p":"purpose","r":"Psalms 70","v":"To bring to remembrance"}],"nm":{"PER-00661":"David"}},"OBJ-00439":{"k":"object","n":"Psalm 71","d":"The prayer of one who trusted God from his youth, that He not forsake him in old age (Psalm 71)","f":[{"p":"contents","r":"Psalms 71:1–24","v":"The psalmist, who has trusted the LORD from his youth and was upheld by Him from birth, asks not to be cast off in old age when his strength fails, while his enemies say God has forsaken him; old and gray, he will declare God's strength to the next generation and praise Him with lute and harp as the Holy One of Israel"},{"p":"designation","r":"Psalms 71:1","v":"In You, O LORD"}],"nm":{}},"OBJ-00440":{"k":"object","n":"Psalm 72","d":"Solomon's psalm of the king's righteous reign from sea to sea (Psalm 72)","f":[{"p":"contents","r":"Psalms 72:1–20","v":"A prayer that God give the king His judgments and the king's son His righteousness, so that he judges the poor with justice and has dominion from sea to sea and from the River to the ends of the earth; the kings of Tarshish and the isles, of Sheba and Seba, will bring gifts, and the gold of Sheba will be given him; grain will wave like Lebanon on the mountaintops, his name will endure as long as the sun, and all nations will call him blessed; the psalm closes Book Two with a blessing of the LORD God of Israel and the note that David's prayers are ended"},{"p":"designation","r":"Psalms 72","v":"A Psalm of Solomon"},{"p":"made by","r":"Psalms 72","e":"PER-00765"}],"nm":{"PER-00765":"Solomon"}},"OBJ-00441":{"k":"object","n":"Psalm 73","d":"Asaph's psalm of the prosperity of the wicked and the end he saw in the sanctuary (Psalm 73)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 73:26; Psalms 73:1–28","v":"Asaph confesses that he nearly slipped, envying the proud and wicked, who prosper at ease and ask how God can know, until he went into the sanctuary of God and understood their end, cast down in a moment; though his flesh and heart fail, God is the strength (by the NKJV note, the rock) of his heart and his portion forever, and it is good to draw near to Him"},{"p":"designation","r":"Psalms 73","v":"A Psalm of Asaph"},{"p":"made by","r":"Psalms 73","e":"PER-01496"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00442":{"k":"object","n":"Psalm 74","d":"Asaph's Contemplation on the sanctuary set on fire by the enemy (Psalm 74)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 74:14; Psalms 74:1–23","v":"Asaph asks why God has cast off the sheep of His pasture and bids Him remember Mount Zion, where He dwelt: enemies roared in His meeting place, broke down its carved work with axes and hammers, set His sanctuary on fire and burned all the meeting places of God in the land, and no prophet is left; yet God, King from of old, divided the sea, broke the heads of the sea monsters and of Leviathan (a sea creature of unknown identity, by the NKJV note), dried up mighty rivers and set the borders of the earth; Asaph asks Him to arise and plead His own cause"},{"p":"designation","r":"NKJV notes, note on Psalm 74:1; Psalms 74","v":"A Contemplation of Asaph"},{"p":"made by","r":"Psalms 74","e":"PER-01496"},{"p":"occasion","r":"2 Kings 25:9; Ezra 2:41; Psalms 74, 3–8","e":"EVT-01905","b":"inferred","c":"possible","w":"The psalm laments the sanctuary set on fire and the meeting places of God burned (Psalm 74:3–8), as the house of the LORD was burned when Jerusalem fell (2 Kings 25:9)."}],"nm":{"EVT-01905":"Nebuzaradan burns the temple and Jerusalem","PER-01496":"Asaph"}},"OBJ-00443":{"k":"object","n":"Psalm 75","d":"Asaph's song of thanks to God the Judge, set to 'Do Not Destroy' (Psalm 75)","f":[{"p":"contents","r":"Psalms 75:1–10","v":"Thanks to God, whose name is near: at the time He chooses He will judge uprightly, and He holds up the pillars of the earth; exaltation comes from no quarter of the earth but from God the Judge, who puts down one and exalts another, and the wicked will drain the cup in the LORD's hand"},{"p":"designation","r":"Psalms 75","v":"A Psalm of Asaph"},{"p":"designation","r":"Psalms 75","v":"A Song"},{"p":"feature","r":"NKJV notes, note on Psalm 75:1; Psalms 75","v":"Set to 'Do Not Destroy' (Hebrew Al Tashcheth)"},{"p":"made by","r":"Psalms 75","e":"PER-01496"},{"p":"purpose","r":"Psalms 75","v":"Given to the Chief Musician"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00444":{"k":"object","n":"Psalm 76","d":"Asaph's song of God known in Judah, whose tabernacle is in Salem (Psalm 76)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 76:2; Psalms 76:1–12","v":"God is known in Judah; His tabernacle is in Salem (Jerusalem, by the NKJV note) and His dwelling in Zion, where He broke the arrows, the shield and the sword of battle; at His rebuke chariot and horse fell into a dead sleep; He arose to judgment to save the oppressed of the earth, and the kings of the earth must fear Him"},{"p":"designation","r":"Psalms 76","v":"A Psalm of Asaph"},{"p":"designation","r":"Psalms 76","v":"A Song"},{"p":"feature","r":"NKJV notes, note on Psalm 76:1; Psalms 76","v":"On stringed instruments (Hebrew neginoth)"},{"p":"made by","r":"Psalms 76","e":"PER-01496"},{"p":"purpose","r":"Psalms 76","v":"Given to the Chief Musician"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00445":{"k":"object","n":"Psalm 77","d":"Asaph's psalm remembering God's wonders of old at the sea, given to Jeduthun (Psalm 77)","f":[{"p":"contents","r":"Psalms 77:1–20","v":"In the day of trouble Asaph cried to God and refused to be comforted, asking whether the Lord would cast off forever and had forgotten to be gracious; then he remembered the years of the right hand of the Most High and His wonders of old: God redeemed the sons of Jacob and Joseph, the waters saw Him and trembled, His way was in the sea and His path in the great waters, and He led His people like a flock by the hand of Moses and Aaron"},{"p":"designation","r":"Psalms 77","v":"A Psalm of Asaph"},{"p":"made by","r":"Psalms 77","e":"PER-01496"},{"p":"purpose","r":"Psalms 77","v":"Given to the Chief Musician"},{"p":"purpose","r":"Psalms 77","v":"Given to Jeduthun"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00446":{"k":"object","n":"Psalm 78","d":"Asaph's Contemplation telling Israel's history from Egypt to the choosing of David (Psalm 78)","f":[{"p":"contents","r":"Psalms 78:1–72; Matthew 13:35","v":"Asaph opens his mouth in a parable, which Matthew applies to Jesus' parables, to tell the coming generation the LORD's works and law, that they may not be stubborn like their fathers: God did wonders in Egypt and the field of Zoan, divided the sea, led them with the cloud and the fire and split the rock; yet they tested Him in the wilderness, and though He rained manna and quail, His wrath struck down their strongest men; He sent the plagues on Egypt, led His people like a flock, brought them to His holy mountain and divided their inheritance; when they provoked Him with high places and carved images He forsook the tabernacle of Shiloh and gave His strength into captivity, then beat back His enemies, chose Judah and Mount Zion, built His sanctuary, and took David His servant from the sheepfolds to shepherd Israel"},{"p":"designation","r":"NKJV notes, note on Psalm 78:1; Psalms 78","v":"A Contemplation of Asaph"},{"p":"made by","r":"Psalms 78","e":"PER-01496"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00447":{"k":"object","n":"Psalm 79","d":"Asaph's lament that the nations have defiled the temple and laid Jerusalem in heaps (Psalm 79)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 79:1; Psalms 79:1–13","v":"The nations have come into God's inheritance, defiled His holy temple and laid Jerusalem in heaps (in ruins, by the NKJV note); the bodies of His servants are left for the birds and beasts with none to bury them; Asaph asks how long He will be angry, prays that He not remember former iniquities but help them, the sheep of His pasture, for His name's sake, and avenge His servants' blood"},{"p":"designation","r":"Psalms 79","v":"A Psalm of Asaph"},{"p":"made by","r":"Psalms 79","e":"PER-01496"},{"p":"occasion","r":"2 Kings 25:9; Ezra 2:41; Psalms 79, 1–3","e":"EVT-01905","b":"inferred","c":"possible","w":"The psalm laments the temple defiled and Jerusalem laid in heaps (Psalm 79:1–3), as the house of the LORD and the houses of Jerusalem were burned when the city fell (2 Kings 25:9)."}],"nm":{"EVT-01905":"Nebuzaradan burns the temple and Jerusalem","PER-01496":"Asaph"}},"OBJ-00448":{"k":"object","n":"Psalm 80","d":"Asaph's prayer to the Shepherd of Israel to restore His vine brought out of Egypt (Psalm 80)","f":[{"p":"contents","r":"Psalms 80:1–19","v":"The Shepherd of Israel, who leads Joseph like a flock and dwells between the cherubim, is asked to stir up His strength before Ephraim, Benjamin and Manasseh and make His face shine; He brought a vine out of Egypt, cast out the nations and planted it, and it filled the land and sent its boughs to the Sea and its branches to the River; now its hedges are broken down and it is burned and cut down, and the psalm asks the LORD God of hosts to revive His people"},{"p":"designation","r":"Psalms 80","v":"A Testimony of Asaph"},{"p":"feature","r":"NKJV notes, note on Psalm 80:1; Psalms 80","v":"Set to 'The Lilies' (Hebrew Shoshannim); a Testimony (Hebrew Eduth)"},{"p":"made by","r":"Psalms 80","e":"PER-01496"},{"p":"purpose","r":"Psalms 80","v":"Given to the Chief Musician"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00449":{"k":"object","n":"Psalm 81","d":"Asaph's call to keep the feast and to hear the LORD who brought Israel out of Egypt (Psalm 81)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 81:7; Psalms 81:1–16","v":"Israel is called to sing aloud to God and blow the trumpet at the New Moon and the full moon, a statute He set in Joseph when He went out over Egypt; He freed their shoulders from the burden, answered them from the thunder and tested them at the waters of Meribah (Strife, by the NKJV note); He forbids foreign gods, and laments that His people would not listen, for He would have subdued their enemies and fed them with the finest wheat and honey from the rock"},{"p":"designation","r":"Psalms 81","v":"A Psalm of Asaph"},{"p":"feature","r":"NKJV notes, note on Psalm 81:1; Psalms 81","v":"On an instrument of Gath (Hebrew Al Gittith)"},{"p":"made by","r":"Psalms 81","e":"PER-01496"},{"p":"purpose","r":"Psalms 81","v":"Given to the Chief Musician"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00450":{"k":"object","n":"Psalm 82","d":"Asaph's psalm of God judging among the 'gods' (Psalm 82)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 82:1; Psalms 82:1–8; John 10:34–35","v":"God stands in the congregation of the mighty and judges among the 'gods' (judges, by the NKJV note), asking how long they will judge unjustly; they are to defend the poor and fatherless, but they walk in darkness, and though He called them gods and children of the Most High, words Jesus quotes, they will die like men; God is asked to arise and judge the earth"},{"p":"designation","r":"Psalms 82","v":"A Psalm of Asaph"},{"p":"made by","r":"Psalms 82","e":"PER-01496"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00451":{"k":"object","n":"Psalm 83","d":"Asaph's prayer against the confederacy of the nations conspiring to cut Israel off (Psalm 83)","f":[{"p":"contents","r":"Psalms 83:1–18","v":"God's enemies conspire to cut Israel off from being a nation: Edom, the Ishmaelites, Moab, the Hagrites, Gebal, Ammon, Amalek, Philistia with Tyre, and Assyria helping the children of Lot; Asaph asks God to deal with them as with Midian, as with Sisera and Jabin at the Brook Kishon, who perished at En Dor, and to make their nobles like Oreb and Zeeb and their princes like Zebah and Zalmunna, that they may know that He alone, whose name is the LORD, is the Most High over all the earth"},{"p":"designation","r":"Psalms 83","v":"A Psalm of Asaph"},{"p":"designation","r":"Psalms 83","v":"A Song"},{"p":"made by","r":"Psalms 83","e":"PER-01496"}],"nm":{"PER-01496":"Asaph"}},"OBJ-00452":{"k":"object","n":"Psalm 84","d":"The sons of Korah's psalm of longing for the courts of the LORD of hosts (Psalm 84)","f":[{"p":"contents","r":"Psalms 84:1–12","v":"The psalmist's soul longs for the courts of the LORD of hosts, where even the sparrow and swallow nest by His altars; blessed are those who dwell in His house and whose hearts are set on pilgrimage, who pass through the Valley of Baca and make it a spring, going from strength to strength until each appears before God in Zion; a day in His courts is better than a thousand, and the LORD God is a sun and shield to the upright"},{"p":"designation","r":"Psalms 84","v":"A Psalm of the sons of Korah"},{"p":"feature","r":"NKJV notes, note on Psalm 84:1; Psalms 84","v":"On an instrument of Gath (Hebrew Al Gittith)"},{"p":"made by","r":"Psalms 84","e":"GRP-00086"},{"p":"purpose","r":"Psalms 84","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00453":{"k":"object","n":"Psalm 85","d":"The sons of Korah's prayer that the LORD revive His people, having brought back Jacob's captivity (Psalm 85)","f":[{"p":"contents","r":"Psalms 85:1–13","v":"The LORD has been favorable to His land, brought back the captivity of Jacob and forgiven His people's sin; the psalmist asks Him to turn His anger away and revive them, and hears Him speak peace: mercy and truth have met together, righteousness and peace have kissed, and the land will yield its increase"},{"p":"designation","r":"Psalms 85","v":"A Psalm of the sons of Korah"},{"p":"made by","r":"Psalms 85","e":"GRP-00086"},{"p":"occasion","r":"Ezra 2:1; Psalms 85, 1","e":"EVT-02074","b":"inferred","c":"possible","w":"The psalm thanks God for bringing back the captivity of Jacob (Psalm 85:1), as the exiles came back from Babylon to Jerusalem and Judah (Ezra 2:1)."},{"p":"purpose","r":"Psalms 85","v":"Given to the Chief Musician"}],"nm":{"EVT-02074":"The exiles return from Babylon with Zerubbabel","GRP-00086":"Korahites"}},"OBJ-00454":{"k":"object","n":"Psalm 86","d":"David's prayer to the Lord, good and ready to forgive, for an undivided heart (Psalm 86)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 86:13; Psalms 86:1–17","v":"Poor and needy, David asks the Lord, good, ready to forgive and abundant in mercy, to hear him; none among the gods is like Him, and all nations He made will worship Him; David asks to be taught His way and given a united heart to fear His name, for He delivered his soul from the depths of Sheol, and asks for a sign for good against the proud"},{"p":"designation","r":"Psalms 86","v":"A Prayer of David"},{"p":"made by","r":"Psalms 86","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00455":{"k":"object","n":"Psalm 87","d":"The sons of Korah's song of Zion, the city of God, where the nations are counted as born (Psalm 87)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 87:4; Psalms 87:1–7","v":"The LORD founded His city on the holy mountains and loves the gates of Zion more than all the dwellings of Jacob; glorious things are spoken of the city of God; He will mention Rahab (Egypt, by the NKJV note) and Babylon, Philistia and Tyre with Ethiopia among those who know Him, and when He registers the peoples He will record that this one and that one were born in Zion"},{"p":"designation","r":"Psalms 87","v":"A Psalm of the sons of Korah"},{"p":"designation","r":"Psalms 87","v":"A Song"},{"p":"made by","r":"Psalms 87","e":"GRP-00086"}],"nm":{"GRP-00086":"Korahites"}},"OBJ-00456":{"k":"object","n":"Psalm 88","d":"The Contemplation of Heman the Ezrahite, crying from the edge of the grave (Psalm 88)","f":[{"p":"contents","r":"Psalms 88:1–18","v":"Crying day and night to the LORD, God of his salvation, Heman says his soul is full of troubles and his life near the grave; he is counted with those who go down to the pit, laid in darkness under God's wrath, and his acquaintances and loved ones are put far from him; he asks whether the dead will praise God, and why God hides His face, for he has been afflicted from his youth"},{"p":"designation","r":"Psalms 88","v":"A Psalm of the sons of Korah"},{"p":"designation","r":"NKJV notes, note on Psalm 88:1; Psalms 88","v":"A Contemplation of Heman the Ezrahite"},{"p":"feature","r":"Psalms 88","v":"Set to 'Mahalath Leannoth'"},{"p":"made by","r":"Psalms 88","e":"GRP-00086"},{"p":"made by","r":"1 Kings 4:31; Psalms 88; 89","e":"PER-00933","b":"inferred","c":"probable","w":"The title calls him Heman the Ezrahite; Heman is named with Ethan the Ezrahite among the wisest of men (1 Kings 4:31), and Psalm 89 is by Ethan the Ezrahite."},{"p":"made by","r":"1 Chronicles 6:33–37; Psalms 88","e":"PER-01510","b":"inferred","c":"possible","s":"alternative","w":"The title also calls the psalm one of the sons of Korah, and Heman the singer descended from Korah (1 Chronicles 6:33–37)."},{"p":"purpose","r":"Psalms 88","v":"Given to the Chief Musician"}],"nm":{"GRP-00086":"Korahites","PER-00933":"Heman","PER-01510":"Heman"}},"OBJ-00457":{"k":"object","n":"Psalm 89","d":"The Contemplation of Ethan the Ezrahite on the LORD's covenant with David (Psalm 89)","f":[{"p":"contents","r":"Psalms 89:1–52","v":"Ethan sings of the LORD's mercies and faithfulness: He made a covenant with David His chosen, to establish his seed and throne forever; none in the heavens is like the LORD God of hosts, who rules the raging sea, broke Rahab in pieces and created north and south, so that Tabor and Hermon rejoice in His name; He anointed David with His holy oil, made him His firstborn, highest of the kings of the earth, and swore that if his sons forsook His law He would punish them but not break His covenant; yet now He has cast off His anointed, profaned his crown and ruined his strongholds, and Ethan asks how long; the psalm, and Book Three, end with a blessing of the LORD"},{"p":"designation","r":"NKJV notes, note on Psalm 89:1; Psalms 89","v":"A Contemplation of Ethan the Ezrahite"},{"p":"made by","r":"Psalms 89","e":"PER-00932"}],"nm":{"PER-00932":"Ethan"}},"OBJ-00458":{"k":"object","n":"Psalm 90","d":"The prayer of Moses the man of God on God's eternity and man's frailty (Psalm 90)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 90:1; Psalms 90:1–17","v":"The Lord has been His people's dwelling place in all generations, God from everlasting before the mountains were born; a thousand years are to Him as yesterday, while men are swept away like grass that withers by evening; consumed by His wrath, they live seventy years, or eighty by strength, and Moses asks God to teach them to number their days, to satisfy them early with His mercy, and to establish the work of their hands"},{"p":"designation","r":"Psalms 90","v":"A Prayer of Moses"},{"p":"made by","r":"Psalms 90","e":"PER-00353"}],"nm":{"PER-00353":"Moses"}},"OBJ-00459":{"k":"object","n":"Psalm 91","d":"The psalm of safety under the shadow of the Almighty (Psalm 91)","f":[{"p":"contents","r":"Psalms 91:1–16; Matthew 4:6","v":"One who dwells in the secret place of the Most High abides under the shadow of the Almighty, his refuge and fortress; He delivers him from the fowler's snare and the pestilence, so that he need not fear terror by night or arrow by day though thousands fall beside him, for God gives His angels charge to bear him up, words the tempter quoted to Jesus; because he loves God, God will deliver him and satisfy him with long life"},{"p":"designation","r":"Psalms 91:1","v":"He who dwells in the secret place"}],"nm":{}},"OBJ-00460":{"k":"object","n":"Psalm 92","d":"The song for the Sabbath day, giving thanks to the Most High (Psalm 92)","f":[{"p":"contents","r":"Psalms 92:1–15","v":"It is good to give thanks to the Most High, declaring His lovingkindness in the morning and His faithfulness at night with ten-stringed instrument, lute and harp; the wicked spring up like grass only to be destroyed, but the psalmist's horn is exalted and he is anointed with fresh oil; the righteous flourish like a palm and grow like a cedar in Lebanon, planted in the LORD's house and bearing fruit in old age"},{"p":"designation","r":"Psalms 92","v":"A Song for the Sabbath day"},{"p":"purpose","r":"Psalms 92","v":"For the Sabbath day"}],"nm":{}},"OBJ-00461":{"k":"object","n":"Psalm 93","d":"The psalm that the LORD reigns, mightier than the floods (Psalm 93)","f":[{"p":"contents","r":"Psalms 93:1–5","v":"The LORD reigns, clothed with majesty and strength; the world is established and His throne is from of old; the floods lift up their voice, but the LORD on high is mightier than the waves of the sea; His testimonies are sure, and holiness adorns His house forever"},{"p":"designation","r":"Psalms 93:1","v":"The LORD reigns"}],"nm":{}},"OBJ-00462":{"k":"object","n":"Psalm 94","d":"The prayer to God, to whom vengeance belongs, the Judge of the earth (Psalm 94)","f":[{"p":"contents","r":"Psalms 94:1–23","v":"The Judge of the earth is asked to repay the proud, who crush His people, kill the widow, the stranger and the fatherless, and say the LORD does not see; He who planted the ear and formed the eye hears and sees, and blessed is the man He instructs, for He will not cast off His people; the LORD has been the psalmist's defense and the rock of his refuge"},{"p":"designation","r":"Psalms 94:1","v":"O God, to whom vengeance belongs"}],"nm":{}},"OBJ-00463":{"k":"object","n":"Psalm 95","d":"The call to worship the LORD, and not to harden the heart as at Meribah (Psalm 95)","f":[{"p":"contents","r":"Psalms 95:1–11; Hebrews 3:7–11; 4:7","v":"All are called to sing to the Rock of their salvation, the great God and great King above all gods, who holds the depths and heights of the earth and made the sea and the dry land, and to kneel before the LORD their Maker, for they are the sheep of His pasture; today they must not harden their hearts as in the rebellion and the day of trial in the wilderness (Meribah and Massah, by the NKJV notes), when their fathers tested Him for forty years and He swore they would not enter His rest; Hebrews quotes the warning as said in David"},{"p":"designation","r":"Psalms 95:1","v":"Oh come, let us sing"},{"p":"made by","r":"Hebrews 4:7","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00464":{"k":"object","n":"Psalm 96","d":"The new song to the LORD, who is coming to judge the earth (Psalm 96)","f":[{"p":"contents","r":"Psalms 96:1–13","v":"All the earth is called to sing the LORD a new song and declare His glory among the nations, for the gods of the peoples are idols but the LORD made the heavens; the families of the peoples are to give Him glory, bring an offering into His courts and worship Him in the beauty of holiness, saying among the nations that the LORD reigns; heaven, earth, sea, field and trees rejoice, for He is coming to judge the world with righteousness"},{"p":"designation","r":"Psalms 96:1","v":"Oh, sing to the LORD"},{"p":"made by","r":"1 Chronicles 16:7, 23–33; Psalms 96:1–13","e":"PER-00661","b":"inferred","c":"probable","w":"Its words are, nearly all, in the psalm David first delivered to Asaph on the day the ark was set in its place (1 Chronicles 16:7, 23–33)."}],"nm":{"PER-00661":"David"}},"OBJ-00465":{"k":"object","n":"Psalm 97","d":"The psalm that the LORD reigns over the whole earth and Zion is glad (Psalm 97)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 97:1; Psalms 97:1–12","v":"The LORD reigns, and the earth and the many isles are to rejoice; clouds and darkness surround Him, righteousness and justice are the foundation of His throne, fire goes before Him and the mountains melt like wax before the Lord of the whole earth; those who serve images are put to shame, Zion hears and is glad, and light is sown for the righteous"},{"p":"designation","r":"Psalms 97:1","v":"The LORD reigns; let the earth rejoice"}],"nm":{}},"OBJ-00466":{"k":"object","n":"Psalm 98","d":"The psalm of a new song to the LORD, who has made known His salvation (Psalm 98)","f":[{"p":"contents","r":"Psalms 98:1–9","v":"All are called to sing the LORD a new song, for His right hand has won the victory and He has made known His salvation to the nations and remembered His mercy to Israel; the earth is to shout with harp, trumpets and horn before the LORD the King, the sea to roar and the rivers to clap their hands, for He is coming to judge the world with righteousness"},{"p":"designation","r":"Psalms 98","v":"A Psalm"}],"nm":{}},"OBJ-00467":{"k":"object","n":"Psalm 99","d":"The psalm of the holy LORD who reigns between the cherubim and answered Moses, Aaron and Samuel (Psalm 99)","f":[{"p":"contents","r":"Psalms 99:1–9","v":"The LORD reigns between the cherubim and is great in Zion, and His name is holy; He has done justice in Jacob; Moses and Aaron were among His priests and Samuel among those who called on His name, and He answered them and spoke to them in the cloudy pillar; He was God-Who-Forgives to them, though He punished their deeds; all are to worship at His holy hill"},{"p":"designation","r":"Psalms 99:1","v":"The LORD reigns; let the peoples tremble"}],"nm":{}},"OBJ-00468":{"k":"object","n":"Psalm 100","d":"The psalm of thanksgiving calling all lands to serve the LORD with gladness (Psalm 100)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 100:3; Psalms 100:1–5","v":"All lands are called to shout to the LORD, serve Him with gladness and know that He is God, who made them, His people and the sheep of His pasture; they are to enter His gates with thanksgiving and His courts with praise, for He is good and His mercy is everlasting"},{"p":"designation","r":"Psalms 100","v":"A Psalm of Thanksgiving"},{"p":"purpose","r":"Psalms 100","v":"For thanksgiving"}],"nm":{}},"OBJ-00469":{"k":"object","n":"Psalm 101","d":"David's vow to walk with a perfect heart and to cut off evildoers (Psalm 101)","f":[{"p":"contents","r":"Psalms 101:1–8","v":"David sings of mercy and justice and vows to walk in his house with a perfect heart, to set no wicked thing before his eyes, to destroy the slanderer and not endure the proud, to keep the faithful of the land near him and no liar in his presence, and early to cut off all evildoers from the city of the LORD"},{"p":"designation","r":"Psalms 101","v":"A Psalm of David"},{"p":"made by","r":"Psalms 101","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00470":{"k":"object","n":"Psalm 102","d":"The prayer of one afflicted and overwhelmed, who asks the LORD to have mercy on Zion (Psalm 102)","f":[{"p":"contents","r":"Psalms 102:1–28; Hebrews 1:10–12","v":"The afflicted man's days vanish like smoke, he is like a lone sparrow on the housetop and eats ashes like bread under God's wrath; but the LORD endures forever and will arise and have mercy on Zion, for the set time has come and His servants love her stones; He will build up Zion and appear in His glory, and this will be written for a generation to come; He laid the earth's foundations, and while heaven and earth wear out like a garment, He remains the same, words Hebrews applies to the Son"},{"p":"designation","r":"Psalms 102","v":"A Prayer of the afflicted"},{"p":"purpose","r":"Psalms 102","v":"For one overwhelmed, pouring out his complaint before the LORD"}],"nm":{}},"OBJ-00471":{"k":"object","n":"Psalm 103","d":"David's psalm blessing the LORD for all His benefits and mercies (Psalm 103)","f":[{"p":"contents","r":"Psalms 103:1–22","v":"David bids his soul bless the LORD and forget none of His benefits: He forgives, heals, redeems and renews youth like the eagle's; He made His ways known to Moses; He is merciful and gracious, slow to anger, and removes transgressions as far as the east is from the west, pitying those who fear Him as a father pities his children, for man's days are like grass but His mercy is everlasting; His throne is in heaven, and His angels, hosts and works are to bless Him"},{"p":"designation","r":"Psalms 103","v":"A Psalm of David"},{"p":"made by","r":"Psalms 103","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00472":{"k":"object","n":"Psalm 104","d":"The psalm blessing the LORD for His works in creation and His care for all He made (Psalm 104)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 104:18; NKJV notes, note on Psalm 104:26; Psalms 104:1–35","v":"The LORD is clothed with light and majesty; He stretches out the heavens, rides the clouds and makes His angels spirits; He set the earth on its foundations, covered it with the deep, then rebuked the waters and set them a boundary; He sends springs to the valleys, grass for cattle, and wine, oil and bread for man; He planted the cedars of Lebanon, gave the high hills to the wild goats and the cliffs to the rock badgers, and appointed the moon for seasons; the wide sea holds countless creatures, the ships and Leviathan; all wait on Him for food, and when He sends forth His Spirit they are created and the earth renewed"},{"p":"designation","r":"Psalms 104:1","v":"Bless the LORD, O my soul"}],"nm":{}},"OBJ-00473":{"k":"object","n":"Psalm 105","d":"The psalm of the LORD's faithfulness to His covenant from Abraham to the land of Canaan (Psalm 105)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 105:18; Psalms 105:1–45","v":"The seed of Abraham are called to give thanks and remember the covenant the LORD made with Abraham, swore to Isaac and confirmed to Jacob, to give them Canaan; when they were few and strangers He let no one wrong them and rebuked kings for them; He called a famine and sent Joseph ahead, sold as a slave and laid in irons until the king released him and made him lord of his house; Israel came into the land of Ham, and Moses and Aaron worked His signs there; He brought His people out with silver and gold, gave them a cloud for covering and fire for light, quail, bread from heaven and water from the rock, and gave them the lands of the nations, that they might keep His laws"},{"p":"designation","r":"Psalms 105:1","v":"Oh, give thanks to the LORD"},{"p":"made by","r":"1 Chronicles 16:7–22; Psalms 105:1–15","e":"PER-00661","b":"inferred","c":"possible","w":"Its first fifteen verses are in the psalm David first delivered to Asaph on the day the ark was set in its place (1 Chronicles 16:7–22)."}],"nm":{"PER-00661":"David"}},"OBJ-00474":{"k":"object","n":"Psalm 106","d":"The psalm confessing Israel's sins from the Red Sea to Canaan and the LORD's many deliverances (Psalm 106)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 106:32; Psalms 106:1–48","v":"The psalmist gives thanks to the LORD, whose mercy endures forever, and confesses that Israel sinned with their fathers: they rebelled at the Red Sea, yet He saved them; they lusted in the wilderness and He sent leanness; they envied Moses and Aaron, made a calf in Horeb, despised the pleasant land and joined Baal of Peor, and angered Him at the waters of strife (Meribah, by the NKJV note); in the land they mingled with the nations, served their idols and sacrificed their children to demons, so He gave them into the hands of their enemies, yet many times delivered them and made their captors pity them; he prays to be gathered from among the nations, and Book Four closes with a blessing of the LORD God of Israel"},{"p":"designation","r":"NKJV notes, note on Psalm 106:1; Psalms 106:1","v":"Praise the LORD"},{"p":"made by","r":"1 Chronicles 16:7, 34–36; Psalms 106:1, 47–48","e":"PER-00661","b":"inferred","c":"possible","w":"Its first and last verses are in the psalm David first delivered to Asaph on the day the ark was set in its place (1 Chronicles 16:7, 34–36)."}],"nm":{"PER-00661":"David"}},"OBJ-00475":{"k":"object","n":"Psalm 107","d":"The thanksgiving of the redeemed whom the LORD gathered from every land (Psalm 107)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 107:34; Psalms 107:1–43","v":"The redeemed, gathered from east, west, north and south, are bidden to give thanks to the LORD for His goodness: wanderers in the desolate wilderness He led to a city to dwell in; prisoners in darkness for rebelling against the Most High He freed, breaking gates of bronze; fools near death He healed by sending His word; and sailors whose storm He calmed He guided to their haven; He turns rivers into wilderness and fruitful land into a salty waste for the wickedness of its people, and wilderness into pools where the hungry build a city"},{"p":"designation","r":"Psalms 107:1","v":"Oh, give thanks to the LORD"}],"nm":{}},"OBJ-00476":{"k":"object","n":"Psalm 108","d":"David's song of a steadfast heart and of God's victory over Edom (Psalm 108)","f":[{"p":"contents","r":"Psalms 57:7–11; 60:5–12; 108:1–13","v":"David's heart is steadfast to sing and awaken the dawn and praise the LORD among the nations, for His mercy is above the heavens; God has spoken that He will divide Shechem and measure out the Valley of Succoth, that Gilead, Manasseh, Ephraim and Judah are His, Moab His washpot, Edom under His shoe and Philistia His triumph; through God His people will do valiantly; the psalm joins the close of Psalm 57 to the close of Psalm 60"},{"p":"designation","r":"Psalms 108","v":"A Psalm of David"},{"p":"designation","r":"Psalms 108","v":"A Song"},{"p":"made by","r":"Psalms 108","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00477":{"k":"object","n":"Psalm 109","d":"David's plea that God judge his false accusers (Psalm 109)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 109:6; Psalms 109:1–31; Acts 1:20","v":"David asks the God of his praise not to keep silent, for lying accusers repay his love with hatred; he prays that an accuser (Hebrew satan, by the NKJV note) stand at the wicked man's right hand, that his days be few and another take his office, words Acts applies to Judas, and that his name be blotted out; poor, needy and weak from fasting, David asks the LORD to save him, for He stands at the right hand of the poor"},{"p":"designation","r":"Psalms 109","v":"A Psalm of David"},{"p":"made by","r":"Psalms 109; Acts 1:16, 20","e":"PER-00661"},{"p":"purpose","r":"Psalms 109","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00478":{"k":"object","n":"Psalm 110","d":"David's psalm of the LORD's word to his Lord, a priest forever after the order of Melchizedek (Psalm 110)","f":[{"p":"contents","r":"Psalms 110:1–7; Matthew 22:43–45; Acts 2:34–35; Hebrews 1:13; 5:6; 7:17","v":"The LORD said to David's Lord, sit at My right hand till I make Your enemies Your footstool, words Jesus, Acts and Hebrews apply to the Christ; the LORD will send the rod of His strength out of Zion, His people will offer themselves willingly in the day of His power, and the LORD has sworn that He is a priest forever according to the order of Melchizedek; the Lord at His right hand will break kings in the day of His wrath and judge the nations"},{"p":"designation","r":"Psalms 110","v":"A Psalm of David"},{"p":"made by","r":"Psalms 110; Matthew 22:43–45; Luke 20:42; Acts 2:34","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00479":{"k":"object","n":"Psalm 111","d":"The praise of the LORD's great works, whose fear is the beginning of wisdom (Psalm 111)","f":[{"p":"contents","r":"Psalms 111:1–10","v":"The psalmist praises the LORD with his whole heart in the congregation: His works are great and glorious, He is gracious and full of compassion, has given food to those who fear Him, keeps His covenant, gave His people the heritage of the nations and sent them redemption; holy and awesome is His name, and the fear of the LORD is the beginning of wisdom"},{"p":"designation","r":"NKJV notes, note on Psalm 111:1; Psalms 111:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00480":{"k":"object","n":"Psalm 112","d":"The psalm of the blessed man who fears the LORD (Psalm 112)","f":[{"p":"contents","r":"Psalms 112:1–10; 2 Corinthians 9:9","v":"Blessed is the man who fears the LORD and delights in His commandments: his descendants will be mighty and his house rich, light rises for him in darkness, he lends graciously and gives to the poor, words Paul quotes, his heart is steadfast and unafraid of evil tidings, and his righteousness endures forever, while the desire of the wicked perishes"},{"p":"designation","r":"NKJV notes, note on Psalm 112:1; Psalms 112:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00481":{"k":"object","n":"Psalm 113","d":"The psalm of the LORD high above the nations, who raises the poor from the dust (Psalm 113)","f":[{"p":"contents","r":"Psalms 113:1–9","v":"The servants of the LORD are to praise His name from the rising of the sun to its setting; He is high above all nations and dwells on high, yet humbles Himself to look on heaven and earth, raises the poor from the dust to sit with princes, and gives the barren woman a home as a joyful mother of children"},{"p":"designation","r":"NKJV notes, note on Psalm 113:1; Psalms 113:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00482":{"k":"object","n":"Psalm 114","d":"The psalm of Israel's going out of Egypt, when the sea fled and the Jordan turned back (Psalm 114)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 114:1; Psalms 114:1–8","v":"When Israel went out of Egypt, from a people of strange language, Judah became God's sanctuary and Israel His dominion; the sea saw it and fled, the Jordan turned back, the mountains skipped like rams and the hills like lambs; the earth is to tremble before the God of Jacob, who turned the rock into a pool and the flint into a fountain"},{"p":"designation","r":"Psalms 114:1","v":"When Israel went out of Egypt"}],"nm":{}},"OBJ-00483":{"k":"object","n":"Psalm 115","d":"The psalm giving glory not to us but to the LORD's name, and mocking idols (Psalm 115)","f":[{"p":"contents","r":"Psalms 115:1–18","v":"Glory belongs not to His people but to the LORD's name; their God is in heaven and does whatever He pleases, while the idols of the nations are silver and gold that cannot speak, see, hear or walk, and their makers are like them; Israel, the house of Aaron and all who fear the LORD are to trust Him as their help and shield, for He will bless them; the heavens are His, but He has given the earth to the children of men"},{"p":"designation","r":"Psalms 115:1","v":"Not unto us, O LORD"}],"nm":{}},"OBJ-00484":{"k":"object","n":"Psalm 116","d":"The thanksgiving of one the LORD delivered from death, paying his vows in Jerusalem (Psalm 116)","f":[{"p":"contents","r":"Psalms 116:1–19; 2 Corinthians 4:13","v":"The psalmist loves the LORD, who heard him when the pains of death and Sheol took hold of him and delivered his soul from death, his eyes from tears and his feet from falling; he believed and therefore spoke, words Paul quotes; he will take up the cup of salvation and pay his vows before all the people in the courts of the LORD's house in Jerusalem, for the death of His saints is precious in His sight"},{"p":"designation","r":"Psalms 116:1","v":"I love the LORD"}],"nm":{}},"OBJ-00485":{"k":"object","n":"Psalm 117","d":"The shortest psalm, calling all nations to praise the LORD (Psalm 117)","f":[{"p":"contents","r":"Psalms 117:1–2; Romans 15:11","v":"All Gentiles and peoples are called to praise the LORD, words Paul quotes, for His merciful kindness toward His people is great and His truth endures forever"},{"p":"designation","r":"Psalms 117:1","v":"Praise the LORD, all you Gentiles"}],"nm":{}},"OBJ-00486":{"k":"object","n":"Psalm 118","d":"The psalm of the LORD's enduring mercy and the stone the builders rejected (Psalm 118)","f":[{"p":"contents","r":"Psalms 118:1–29; Matthew 21:9, 42; Acts 4:11","v":"Israel, the house of Aaron and all who fear the LORD are to say that His mercy endures forever; the psalmist called in distress and the LORD answered, so he will not fear man, for it is better to trust the LORD than princes; all nations surrounded him like bees, but in the LORD's name he cut them off; he will not die but live; the gates of righteousness open to him, the stone the builders rejected has become the chief cornerstone, this is the day the LORD has made, and blessed is he who comes in the name of the LORD, words the Gospels and Acts apply to Jesus"},{"p":"designation","r":"Psalms 118:1","v":"Oh, give thanks to the LORD"}],"nm":{}},"OBJ-00487":{"k":"object","n":"Psalm 119","d":"The longest psalm, in twenty-two alphabetic stanzas on the word of God (Psalm 119)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 119:89; Psalms 119:1–176","v":"The psalmist blesses those who walk in the LORD's law and keep His testimonies; a young man keeps his way pure by heeding His word, which the psalmist hides in his heart so as not to sin; he asks to have his eyes opened to wonders in the law, sings the statutes as a stranger on the earth, rises at midnight to give thanks, and finds it good that he was afflicted; the LORD's word is settled forever in heaven; he loves the law and meditates on it all day, finds it sweeter than honey, a lamp to his feet and a light to his path, weeps because men do not keep it, praises God seven times a day, and ends asking God to seek him, for he has strayed like a lost sheep yet does not forget His commandments"},{"p":"designation","r":"NKJV notes, note on Psalm 119:1; Psalms 119:1","v":"Blessed are the undefiled in the way"},{"p":"feature","r":"Psalms 119:1–176","v":"Twenty-two stanzas of eight verses, each headed in order by a letter of the Hebrew alphabet, from Aleph to Tau"}],"nm":{}},"OBJ-00488":{"k":"object","n":"Psalm 120","d":"The Song of Ascents of one who dwells too long among those who hate peace, in Meshech and Kedar (Psalm 120)","f":[{"p":"contents","r":"Psalms 120:1–7","v":"In distress the psalmist cries to the LORD to deliver him from lying lips and a deceitful tongue, which will be repaid with a warrior's arrows and coals of broom; woe to him that he dwells in Meshech among the tents of Kedar, with those who hate peace, for when he speaks for peace they are for war"},{"p":"designation","r":"Psalms 120","v":"A Song of Ascents"}],"nm":{}},"OBJ-00489":{"k":"object","n":"Psalm 121","d":"The Song of Ascents of help from the LORD, Israel's keeper who never sleeps (Psalm 121)","f":[{"p":"contents","r":"Psalms 121:1–8","v":"The psalmist lifts his eyes to the hills and declares that his help comes from the LORD, maker of heaven and earth; He who keeps Israel neither slumbers nor sleeps, is His people's shade, and will keep them from all evil, in their going out and coming in, forever"},{"p":"designation","r":"Psalms 121","v":"A Song of Ascents"}],"nm":{}},"OBJ-00490":{"k":"object","n":"Psalm 122","d":"David's Song of Ascents of the joy of going up to the house of the LORD in Jerusalem (Psalm 122)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 122:4; Psalms 122:1–9","v":"David was glad when told they would go to the house of the LORD; their feet stand within the gates of Jerusalem, built as a city compact together, where the tribes of the LORD go up to give thanks to His name and the thrones of David's house are set for judgment; all are to pray for her peace, for peace within her walls and prosperity in her palaces"},{"p":"designation","r":"Psalms 122","v":"A Song of Ascents"},{"p":"made by","r":"Psalms 122","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00491":{"k":"object","n":"Psalm 123","d":"The Song of Ascents of eyes lifted to the LORD for mercy (Psalm 123)","f":[{"p":"contents","r":"Psalms 123:1–4","v":"The people lift their eyes to the LORD who dwells in the heavens, as servants look to their master's hand, until He has mercy, for they are filled with the scorn of those at ease and the contempt of the proud"},{"p":"designation","r":"Psalms 123","v":"A Song of Ascents"}],"nm":{}},"OBJ-00492":{"k":"object","n":"Psalm 124","d":"David's Song of Ascents: had the LORD not been on Israel's side (Psalm 124)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 124:7; Psalms 124:1–8","v":"Israel is to say that had the LORD not been on their side when men rose up against them, they would have been swallowed alive and swept away by the waters; blessed be the LORD, for they escaped like a bird from the fowlers' snare, and their help is in the name of the LORD, maker of heaven and earth"},{"p":"designation","r":"Psalms 124","v":"A Song of Ascents"},{"p":"made by","r":"Psalms 124","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00493":{"k":"object","n":"Psalm 125","d":"The Song of Ascents of those who trust in the LORD, unmoved like Mount Zion (Psalm 125)","f":[{"p":"contents","r":"Psalms 125:1–5","v":"Those who trust in the LORD are like Mount Zion, which cannot be moved; as the mountains surround Jerusalem, so the LORD surrounds His people forever; the scepter of wickedness will not rest on the land of the righteous, and the LORD will do good to the upright but lead away those who turn to crooked ways; peace be on Israel"},{"p":"designation","r":"Psalms 125","v":"A Song of Ascents"}],"nm":{}},"OBJ-00494":{"k":"object","n":"Psalm 126","d":"The Song of Ascents of the captivity of Zion brought back (Psalm 126)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 126:1; Psalms 126:1–6","v":"When the LORD brought back the captivity of Zion they were like dreamers, their mouths filled with laughter, and the nations said the LORD had done great things for them; they ask Him to bring back their captivity like streams in the South, for those who sow in tears will reap in joy and come again bringing their sheaves"},{"p":"designation","r":"Psalms 126","v":"A Song of Ascents"},{"p":"occasion","r":"Ezra 2:1; Psalms 126:1","e":"EVT-02074","b":"inferred","c":"possible","w":"The psalm remembers when the LORD brought back the captivity of Zion (Psalm 126:1), as the exiles came back from Babylon to Jerusalem and Judah (Ezra 2:1)."}],"nm":{"EVT-02074":"The exiles return from Babylon with Zerubbabel"}},"OBJ-00495":{"k":"object","n":"Psalm 127","d":"Solomon's Song of Ascents: unless the LORD builds the house (Psalm 127)","f":[{"p":"contents","r":"Psalms 127:1–5","v":"Unless the LORD builds the house its builders labor in vain, and unless He guards the city the watchman wakes in vain; it is vain to rise early and toil late, for He gives His beloved sleep; children are a heritage from the LORD, like arrows in a warrior's hand, and happy is the man whose quiver is full of them"},{"p":"designation","r":"Psalms 127","v":"A Song of Ascents"},{"p":"made by","r":"Psalms 127","e":"PER-00765"}],"nm":{"PER-00765":"Solomon"}},"OBJ-00496":{"k":"object","n":"Psalm 128","d":"The Song of Ascents of the blessed home of one who fears the LORD (Psalm 128)","f":[{"p":"contents","r":"Psalms 128:1–6","v":"Blessed is everyone who fears the LORD and walks in His ways: he will eat the labor of his hands, his wife will be like a fruitful vine in his house and his children like olive plants around his table; may the LORD bless him out of Zion, may he see the good of Jerusalem all his days and his children's children"},{"p":"designation","r":"Psalms 128","v":"A Song of Ascents"}],"nm":{}},"OBJ-00497":{"k":"object","n":"Psalm 129","d":"The Song of Ascents of Israel afflicted from her youth but not overcome (Psalm 129)","f":[{"p":"contents","r":"Psalms 129:1–8","v":"Israel is to say that many a time she has been afflicted from her youth, the plowers plowing long furrows on her back, yet they have not prevailed, for the righteous LORD has cut the cords of the wicked; those who hate Zion are to wither like grass on the housetops, unblessed by passersby"},{"p":"designation","r":"Psalms 129","v":"A Song of Ascents"}],"nm":{}},"OBJ-00498":{"k":"object","n":"Psalm 130","d":"The Song of Ascents crying to the LORD out of the depths (Psalm 130)","f":[{"p":"contents","r":"Psalms 130:1–8","v":"Out of the depths the psalmist cries to the LORD: if He marked iniquities none could stand, but there is forgiveness with Him; his soul waits for the LORD more than watchmen for the morning, and Israel is to hope in Him, for with Him is abundant redemption"},{"p":"designation","r":"Psalms 130","v":"A Song of Ascents"}],"nm":{}},"OBJ-00499":{"k":"object","n":"Psalm 131","d":"David's Song of Ascents of a soul calmed like a weaned child (Psalm 131)","f":[{"p":"contents","r":"Psalms 131:1–3","v":"David's heart is not proud nor does he busy himself with things too great for him; he has calmed and quieted his soul like a weaned child with its mother, and bids Israel hope in the LORD forever"},{"p":"designation","r":"Psalms 131","v":"A Song of Ascents"},{"p":"made by","r":"Psalms 131","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00500":{"k":"object","n":"Psalm 132","d":"The Song of Ascents of David's vow to find a dwelling for the LORD, and the LORD's choice of Zion (Psalm 132)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 132:6; NKJV notes, note on Psalm 132:17; Psalms 132:1–18","v":"The LORD is asked to remember David's afflictions and his vow to the Mighty One of Jacob not to sleep until he found a dwelling for the LORD; they heard of it in Ephrathah and found it in the fields of the woods (Jaar, by the NKJV note); the LORD is to arise to His resting place with the ark of His strength and not turn away from His Anointed, for He swore to David that his offspring would sit on his throne if they kept His covenant, and He has chosen Zion as His resting place forever, where He will make the horn of David grow and prepare a lamp for His Anointed"},{"p":"designation","r":"Psalms 132","v":"A Song of Ascents"}],"nm":{}},"OBJ-00501":{"k":"object","n":"Psalm 133","d":"David's Song of Ascents of brethren dwelling together in unity (Psalm 133)","f":[{"p":"contents","r":"Psalms 133:1–3","v":"It is good and pleasant for brethren to dwell together in unity: it is like the precious oil on the head running down Aaron's beard to the edge of his garments, and like the dew of Hermon descending on the mountains of Zion, where the LORD commanded the blessing of life forevermore"},{"p":"designation","r":"Psalms 133","v":"A Song of Ascents"},{"p":"made by","r":"Psalms 133","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00502":{"k":"object","n":"Psalm 134","d":"The last Song of Ascents, calling the LORD's servants in His house by night to bless Him (Psalm 134)","f":[{"p":"contents","r":"Psalms 134:1–3","v":"All the servants of the LORD who stand by night in the house of the LORD are called to lift their hands in the sanctuary and bless Him, and the LORD who made heaven and earth is asked to bless them from Zion"},{"p":"designation","r":"Psalms 134","v":"A Song of Ascents"}],"nm":{}},"OBJ-00503":{"k":"object","n":"Psalm 135","d":"The praise of the LORD who chose Israel, struck Egypt and gave Israel the land of Sihon and Og (Psalm 135)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 135:4; Psalms 135:1–21","v":"The servants who stand in the courts of the LORD's house are to praise Him, for He chose Jacob as His special treasure and is above all gods, doing whatever He pleases in heaven, earth and sea; He struck the firstborn of Egypt, man and beast, sent signs on Pharaoh and his servants, slew Sihon king of the Amorites, Og king of Bashan and all the kingdoms of Canaan, and gave their land to Israel as a heritage; the idols of the nations cannot speak or see; the houses of Israel, Aaron and Levi are to bless the LORD, who dwells in Jerusalem"},{"p":"designation","r":"Psalms 135:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00504":{"k":"object","n":"Psalm 136","d":"The thanksgiving whose every verse answers that His mercy endures forever (Psalm 136)","f":[{"p":"contents","r":"Psalms 136:1–26","v":"Thanks are given to the God of gods and Lord of lords, who alone does great wonders: who made the heavens by wisdom, laid the earth above the waters and made the great lights, the sun by day and the moon and stars by night; who struck Egypt's firstborn and brought Israel out with a strong hand, divided the Red Sea, overthrew Pharaoh and his army in it and led His people through the wilderness; who slew Sihon king of the Amorites and Og king of Bashan and gave their land to Israel; who remembered them in their low estate and gives food to all flesh; thanks to the God of heaven"},{"p":"designation","r":"Psalms 136:1","v":"Oh, give thanks to the LORD"},{"p":"feature","r":"Psalms 136:1–26","v":"Every verse closes with the refrain that His mercy endures forever"}],"nm":{}},"OBJ-00505":{"k":"object","n":"Psalm 137","d":"The lament of the captives by the rivers of Babylon, who remembered Zion (Psalm 137)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 137:7; Psalms 137:1–9","v":"By the rivers of Babylon the captives sat and wept when they remembered Zion and hung their harps on the willows, for their captors asked them for songs of Zion and they could not sing the LORD's song in a foreign land; the psalmist swears never to forget Jerusalem, asks the LORD to remember against the sons of Edom the day of Jerusalem, when they cried to raze it to its foundation, and pronounces a blessing on whoever repays the daughter of Babylon"},{"p":"designation","r":"Psalms 137:1","v":"By the rivers of Babylon"},{"p":"occasion","r":"2 Kings 25:11; Psalms 137:1–3, 7","e":"EVT-01906","b":"inferred","c":"probable","w":"The psalm is sung by captives sitting by the rivers of Babylon who remember Zion and the day of Jerusalem (Psalm 137:1–7); Nebuzaradan carried the people of Jerusalem away to the king of Babylon (2 Kings 25:11)."}],"nm":{"EVT-01906":"Nebuzaradan carries the people of Jerusalem captive"}},"OBJ-00506":{"k":"object","n":"Psalm 138","d":"David's thanks with his whole heart to the LORD, who regards the lowly (Psalm 138)","f":[{"p":"contents","r":"Psalms 138:1–8","v":"David praises the LORD with his whole heart before the gods and worships toward His holy temple, for He answered him when he cried and has magnified His word above all His name; all the kings of the earth will praise Him; the LORD on high regards the lowly but knows the proud from afar, and He will revive David in trouble and perfect what concerns him"},{"p":"designation","r":"Psalms 138","v":"A Psalm of David"},{"p":"made by","r":"Psalms 138","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00507":{"k":"object","n":"Psalm 139","d":"David's psalm of the LORD who has searched and known him and formed him in the womb (Psalm 139)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 139:8; Psalms 139:1–24","v":"The LORD has searched and known David, his sitting and rising, his thoughts and every word; he cannot flee from His Spirit, for in heaven or Sheol, at the far end of the sea or in darkness, God is there; God formed his inward parts and wove him in his mother's womb, he is fearfully and wonderfully made, and all his days were written in God's book before one of them came; he asks God to slay the wicked, and to search him and lead him in the everlasting way"},{"p":"designation","r":"Psalms 139","v":"A Psalm of David"},{"p":"made by","r":"Psalms 139","e":"PER-00661"},{"p":"purpose","r":"Psalms 139","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00508":{"k":"object","n":"Psalm 140","d":"David's prayer to be kept from violent men with serpents' tongues (Psalm 140)","f":[{"p":"contents","r":"Psalms 140:1–13","v":"David asks the LORD to keep him from violent men who plan evil, sharpen their tongues like a serpent and set snares for him; God the Lord, the strength of his salvation, covered his head in the day of battle; he asks that burning coals fall on his enemies, for the LORD will maintain the cause of the afflicted and the upright will dwell in His presence"},{"p":"designation","r":"Psalms 140","v":"A Psalm of David"},{"p":"made by","r":"Psalms 140","e":"PER-00661"},{"p":"purpose","r":"Psalms 140","v":"Given to the Chief Musician"}],"nm":{"PER-00661":"David"}},"OBJ-00509":{"k":"object","n":"Psalm 141","d":"David's prayer that his prayer rise like incense and his lips be guarded (Psalm 141)","f":[{"p":"contents","r":"Psalms 141:1–10","v":"David asks that his prayer be set before the LORD as incense and the lifting of his hands as the evening sacrifice, that a guard be set over his mouth and his heart not turn to evil; he welcomes the rebuke of the righteous, keeps his eyes on God the Lord, and asks to be kept from the snares of the wicked, who will fall into their own nets"},{"p":"designation","r":"Psalms 141","v":"A Psalm of David"},{"p":"made by","r":"Psalms 141","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00510":{"k":"object","n":"Psalm 142","d":"David's Contemplation, a prayer when he was in the cave (Psalm 142)","f":[{"p":"contents","r":"Psalms 142:1–7","v":"David pours out his complaint to the LORD: when his spirit was overwhelmed God knew his path, though snares were set for him and no one cared for his soul; the LORD is his refuge and his portion in the land of the living, and he asks to be delivered from persecutors stronger than he and brought out of prison to praise His name"},{"p":"designation","r":"NKJV notes, note on Psalm 142:1; Psalms 142","v":"A Contemplation of David"},{"p":"designation","r":"Psalms 142","v":"A Prayer when he was in the cave"},{"p":"made by","r":"Psalms 142","e":"PER-00661"},{"p":"occasion","r":"1 Samuel 22:1; 24:3; Psalms 142","e":"EVT-01119","b":"inferred","c":"possible","w":"The title sets the prayer when David was in the cave: he escaped to the cave of Adullam (1 Samuel 22:1), and later hid in a cave in the wilderness of En Gedi when Saul came in (1 Samuel 24:3)."},{"p":"occasion","r":"1 Samuel 22:1; 24:3; Psalms 142","e":"EVT-01138","b":"inferred","c":"possible","w":"The title sets the prayer when David was in the cave: he escaped to the cave of Adullam (1 Samuel 22:1), and later hid in a cave in the wilderness of En Gedi when Saul came in (1 Samuel 24:3)."}],"nm":{"EVT-01119":"David gathers four hundred men at the cave of Adullam","EVT-01138":"David spares Saul in the cave","PER-00661":"David"}},"OBJ-00511":{"k":"object","n":"Psalm 143","d":"David's plea not to be judged, and to be taught to do God's will (Psalm 143)","f":[{"p":"contents","r":"Psalms 143:1–12","v":"David asks the LORD to answer in His faithfulness and not enter into judgment with His servant, for no one living is righteous before Him; crushed by the enemy and dwelling in darkness, he remembers the days of old and thirsts for God like a dry land; he asks to hear His lovingkindness in the morning, to be taught to do His will, and to be led by His good Spirit in the land of uprightness"},{"p":"designation","r":"Psalms 143","v":"A Psalm of David"},{"p":"made by","r":"Psalms 143","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00512":{"k":"object","n":"Psalm 144","d":"David's song of the LORD his Rock, who trains his hands for war (Psalm 144)","f":[{"p":"contents","r":"Psalms 144:1–15","v":"Blessed be the LORD, David's Rock, who trains his hands for war and is his fortress, high tower, deliverer and shield; man is like a breath, yet the LORD is asked to bow the heavens, come down and rescue David from foreigners whose words are lies; David will sing a new song on a harp of ten strings to the One who gives salvation to kings and delivers David His servant from the deadly sword; happy is the people whose sons and daughters flourish, whose barns and flocks are full, and whose God is the LORD"},{"p":"designation","r":"Psalms 144","v":"A Psalm of David"},{"p":"made by","r":"Psalms 144","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00513":{"k":"object","n":"Psalm 145","d":"David's Praise of God the King, whose kingdom is everlasting (Psalm 145)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 145:13; Psalms 145:1–21","v":"David extols God the King and will bless His name every day; His greatness is beyond searching, and each generation will declare His mighty acts to the next; the LORD is gracious, full of compassion, slow to anger and great in mercy, good to all; His kingdom is everlasting; He upholds all who fall, gives all their food in due season, is near to all who call on Him in truth, and preserves all who love Him but destroys the wicked"},{"p":"designation","r":"Psalms 145","v":"A Praise of David"},{"p":"made by","r":"Psalms 145","e":"PER-00661"}],"nm":{"PER-00661":"David"}},"OBJ-00514":{"k":"object","n":"Psalm 146","d":"The Hallelujah psalm of trust in the God of Jacob rather than in princes (Psalm 146)","f":[{"p":"contents","r":"Psalms 146:1–10","v":"The psalmist will praise the LORD all his life; no one is to trust in princes, whose plans perish when their breath departs, but happy is he whose help is the God of Jacob, maker of heaven, earth and sea, who keeps truth, does justice for the oppressed, feeds the hungry, frees prisoners, opens the eyes of the blind and watches over strangers, the fatherless and the widow; the LORD, Zion's God, will reign forever"},{"p":"designation","r":"NKJV notes, note on Psalm 146:1; Psalms 146:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00515":{"k":"object","n":"Psalm 147","d":"The Hallelujah psalm of the LORD who builds up Jerusalem and counts the stars (Psalm 147)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 147:20; Psalms 147:1–20","v":"It is good to praise God, for the LORD builds up Jerusalem, gathers the outcasts of Israel and heals the brokenhearted; He counts the stars and calls them by name, sends rain and grass and feeds the beasts and the young ravens, delighting not in the strength of horse or man but in those who fear Him; Jerusalem and Zion are to praise Him, for He has strengthened the bars of their gates, blessed their children and given peace in their borders; He sends snow, frost and hail and melts them by His word, and has declared His statutes to Jacob as to no other nation"},{"p":"designation","r":"NKJV notes, note on Psalm 147:1; Psalms 147:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00516":{"k":"object","n":"Psalm 148","d":"The Hallelujah psalm calling all creation in heaven and earth to praise the LORD (Psalm 148)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 148:14; Psalms 148:1–14","v":"All in the heavens, His angels and hosts, sun, moon and stars and the waters above the heavens are to praise the LORD, for He commanded and they were created; and from the earth the sea creatures and the depths, fire, hail, snow and wind, mountains, trees and cedars, beasts and birds, kings, peoples, young and old are to praise His name, which alone is exalted; He has exalted the horn of His people Israel, a people near to Him"},{"p":"designation","r":"NKJV notes, note on Psalm 148:1; Psalms 148:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00517":{"k":"object","n":"Psalm 149","d":"The Hallelujah psalm of Israel rejoicing in their Maker and King (Psalm 149)","f":[{"p":"contents","r":"Psalms 149:1–9","v":"A new song is to be sung in the assembly of saints: Israel is to rejoice in their Maker and the children of Zion in their King, praising Him with dance, timbrel and harp, for He takes pleasure in His people; with God's high praises in their mouths and a two-edged sword in their hands the saints are to execute the written judgment on the nations and bind their kings with chains"},{"p":"designation","r":"NKJV notes, note on Psalm 149:1; Psalms 149:1","v":"Praise the LORD"}],"nm":{}},"OBJ-00518":{"k":"object","n":"Psalm 150","d":"The last psalm: let everything that has breath praise the LORD (Psalm 150)","f":[{"p":"contents","r":"NKJV notes, note on Psalm 150:1; Psalms 150:1–6","v":"God is to be praised in His sanctuary and in His mighty firmament, for His mighty acts and excellent greatness, with every instrument, and everything that has breath is to praise the LORD; the psalm closes the Book of Psalms"},{"p":"designation","r":"NKJV notes, note on Psalm 150:1; Psalms 150:1","v":"Praise the LORD"},{"p":"feature","r":"NKJV notes, note on Psalm 150:3; Psalms 150:3–5","v":"It calls for praise with trumpet, lute, harp, timbrel, dance, stringed instruments, flutes and loud and clashing cymbals"}],"nm":{}},"OBJ-00519":{"k":"object","n":"The Book of Proverbs","d":"The book of the proverbs of Solomon the son of David, with the words of the wise, of Agur and of King Lemuel (Proverbs 1–31)","f":[{"p":"contents","r":"Proverbs 1:1; 10:1; 22:17; 24:23; 25:1; 30:1; 31:1, 10","v":"It holds Solomon's instruction in wisdom (chapters 1–9), the proverbs of Solomon (10:1–22:16), the words of the wise and their further sayings (22:17–24:34), the proverbs of Solomon the men of Hezekiah copied (25–29), the words of Agur (30), and the words of King Lemuel with the praise of the virtuous wife (31)"},{"p":"designation","r":"Proverbs 1:1","v":"The proverbs of Solomon"},{"p":"feature","r":"Proverbs 1:7; 9:10","v":"At its head it sets fearing the LORD as the beginning of knowledge, which fools despise"},{"p":"made by","r":"1 Kings 4:32; Proverbs 1:1","e":"PER-00765"},{"p":"made by","r":"Proverbs 30:1","e":"PER-02845"},{"p":"made by","r":"Proverbs 31:1","e":"PER-02849"},{"p":"purpose","r":"Proverbs 1:2–6","v":"To give wisdom, instruction and understanding of justice and equity; to make the simple prudent and give the young knowledge and discretion, so that the wise grow in learning and understand proverbs, riddles and the sayings of the wise"}],"nm":{"PER-00765":"Solomon","PER-02845":"Agur","PER-02849":"Lemuel"}},"OBJ-00520":{"k":"object","n":"Solomon's instruction in wisdom","d":"The first part of Proverbs: a father's teaching to his son to get wisdom and keep from evil, with Wisdom's calls to the simple (Proverbs 1–9)","f":[{"p":"contents","r":"Proverbs 1:8–33","v":"A son is to keep his father's instruction and his mother's teaching and refuse sinners who would have him lie in wait for innocent blood and share their plunder, for they ambush their own lives; Wisdom cries out in the streets and at the gates that the simple and scorners who refuse her rebuke will call on her in their calamity unanswered, but whoever listens to her will live securely"},{"p":"contents","r":"Proverbs 2:1–22","v":"If the son seeks wisdom like silver and hidden treasure, he will come to fear the LORD and know God, who gives wisdom and guards the way of His saints; discretion will keep him from men of perverse speech and from the immoral woman who forsakes her husband and forgets her God's covenant, whose house is the road down to death; the upright will dwell in the land, but the wicked will be cut off"},{"p":"contents","r":"Proverbs 3:1–35; Hebrews 12:5–6; James 4:6; 1 Peter 5:5","v":"The son is to keep his father's commands, which bring long life and peace; to trust the LORD wholeheartedly rather than his own understanding; to honor the LORD with his wealth and firstfruits; and not to despise the LORD's chastening, for He corrects those He loves as a father does his son, words Hebrews quotes; wisdom is worth more than rubies and is a tree of life, and by it the LORD founded the earth; he is to do good to his neighbor when it is in his power, for the LORD scorns the scornful but shows grace to the humble, words James and Peter quote"},{"p":"contents","r":"Proverbs 4:1–27","v":"The father tells his children that when he was young and tender his own father taught him to get wisdom and understanding above all, for she would guard and honor him; the son is to shun the path of the wicked, who cannot sleep unless they have done evil, for the just man's path shines ever brighter like the sun; he is to guard his heart with all diligence, since the springs of life flow from it, and keep his mouth honest, his eyes straight ahead and his feet from evil"},{"p":"contents","r":"NKJV notes, note on Proverbs 5:5; Proverbs 5:1–23","v":"The immoral woman's lips drip honey, but her end is bitter as wormwood and her steps lead to the grave (Sheol, by the NKJV note); the son is to keep far from her door, lest strangers take his strength and wealth and he groan at the last that he hated instruction; he is to drink from his own cistern and rejoice in the wife of his youth, for the LORD watches all a man's paths and the wicked are held by the cords of their own sin"},{"p":"contents","r":"Proverbs 6:1–35","v":"The son is to free himself quickly from a pledge given for a neighbor; the sluggard is to go to the ant, which with no ruler over it gathers its food in summer, lest poverty come on him like a prowler; the worthless man who winks and sows discord will be broken suddenly; the LORD hates six things, even seven, from a proud look and a lying tongue to a false witness and one who sows discord among brethren; the adulterer, like a man who carries fire against his chest, destroys his own soul, and the jealous husband will take no ransom"},{"p":"contents","r":"NKJV notes, note on Proverbs 7:27; Proverbs 7:1–27","v":"The father bids his son call wisdom his sister, and tells how from the window of his house he watched a young man lacking sense pass near a harlot's corner at nightfall: crafty of heart, she kissed him, said she had paid her vows and her husband had gone on a long journey, and led him away like an ox to the slaughter; her house is the way to the grave (Sheol, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Proverbs 8:30; Proverbs 8:1–36","v":"Wisdom calls at the heights, the crossroads and the city gates: her words are true and worth more than silver, gold or rubies; she hates pride and the perverse mouth; by her kings reign and princes rule; the LORD possessed her at the beginning of His way, before the depths, the mountains and the earth, and she was beside Him as a master craftsman (or one brought up, by a Jewish tradition the NKJV notes), His delight, when He prepared the heavens, set the clouds above and gave the sea its limit; whoever finds her finds life and the LORD's favor, and all who hate her love death"},{"p":"contents","r":"NKJV notes, note on Proverbs 9:18; Proverbs 9:1–18","v":"Wisdom has built her house on seven pillars, prepared meat and mixed wine, and sends her maidens to call the simple to eat and live; the scoffer hates correction but the wise man grows wiser; fearing the LORD is where wisdom begins, and knowing the Holy One is understanding; the foolish woman, loud and knowing nothing, also calls the simple, saying stolen water is sweet, but her guests are in the depths of the grave (Sheol, by the NKJV note)"},{"p":"designation","r":"Proverbs 1:8; 4:1","v":"the instruction of a father"},{"p":"feature","r":"Proverbs 1:8, 10; 2:1; 3:1, 11, 21; 4:1, 10, 20; 5:1, 7; 6:1, 20; 7:1, 24","v":"Its discourses mostly open by addressing 'my son' or 'my children', bidding him hear and keep his father's words"},{"p":"feature","r":"Proverbs 1:20–21; 8:1–4; 9:1–6, 13–18","v":"Wisdom is pictured as a woman who calls aloud in the streets, at the city gates and from the heights, builds her house and spreads her feast; a foolish woman calls the simple against her"},{"p":"made by","r":"Proverbs 1:1","e":"PER-00765"}],"nm":{"PER-00765":"Solomon"}},"OBJ-00521":{"k":"object","n":"The proverbs of Solomon","d":"The first collection of Solomon's sayings, most of them single proverbs of two lines (Proverbs 10:1–22:16)","f":[{"p":"contents","r":"Proverbs 10:1–32; 1 Peter 4:8","v":"It begins with the wise son who gladdens his father and the foolish son who grieves his mother, and sets the righteous against the wicked and the diligent against the lazy: the righteous are remembered with blessing while the wicked's name rots; hatred stirs up strife, but love covers all sins, words Peter quotes; the LORD's blessing brings wealth without sorrow; fearing the LORD prolongs life"},{"p":"contents","r":"Proverbs 11:1–31; 1 Peter 4:18","v":"The LORD abhors dishonest scales but delights in a just weight; pride brings shame, but wisdom is with the humble; riches do not profit in the day of wrath; the upright exalt a city, and many counselors bring safety; whoever stands surety for a stranger will suffer; a lovely woman without discretion is like a gold ring in a swine's snout; the generous will be enriched; the fruit of the righteous is a tree of life, and if the righteous are repaid on earth, how much more the wicked and the sinner, words Peter quotes"},{"p":"contents","r":"NKJV notes, note on Proverbs 12:4; Proverbs 12:1–28","v":"Loving instruction is loving knowledge; an excellent wife (a wife of valor, by the NKJV note) is her husband's crown, but a shameful one is like decay in his bones; the righteous man's house stands; a righteous man cares for his animal; whoever tills his land will have bread; a fool's way seems right to himself, but the wise heed counsel; truthful lips last forever, but the LORD abhors lying lips; the diligent will rule, but the lazy are put to forced labor"},{"p":"contents","r":"Proverbs 13:1–25","v":"The wise son listens to his father's instruction; whoever guards his mouth keeps his life; hope put off sickens the heart, but desire fulfilled is a tree of life; the teaching of the wise is a fountain of life; walking with the wise makes one wise, but fools' companions come to ruin; a good man leaves an inheritance to his grandchildren; to spare the rod is to hate one's son, but a loving father disciplines him promptly"},{"p":"contents","r":"Proverbs 14:1–35","v":"A wise woman builds up her house, but the foolish pulls it down with her own hands; a way may seem right to a man yet end in death; the simple believe every word, but the prudent watch their steps; whoever despises his neighbor sins, but whoever shows mercy to the poor is happy; fearing the LORD gives strong confidence and is a fountain of life; whoever oppresses the poor reproaches his Maker; righteousness exalts a nation, but sin disgraces any people"},{"p":"contents","r":"NKJV notes, note on Proverbs 15:11; Proverbs 15:1–33","v":"A gentle answer turns away wrath, but a harsh word rouses anger; the LORD's eyes are everywhere, watching the evil and the good; He abhors the sacrifice of the wicked but delights in the prayer of the upright; Sheol and Abaddon (by the NKJV notes) lie open before Him, and how much more men's hearts; a little, with reverence for the LORD, is better than great treasure with trouble, and a meal of herbs with love better than a fatted calf where there is hatred; plans fail without counsel; fearing the LORD teaches wisdom, and humility comes before honor"},{"p":"contents","r":"Proverbs 16:1–33","v":"A man plans his way, but the LORD directs his steps and weighs the spirits, and the lot cast into the lap is decided by Him; when the LORD is pleased with a man's ways, He gives him peace even with his enemies; a throne stands by righteousness, and the king's favor is like a cloud of spring rain; wisdom is better than gold; pride comes before destruction and haughtiness before a fall; gray hair is a glorious crown when found in righteousness; self-control is better than taking a city"},{"p":"contents","r":"Proverbs 17:1–28","v":"A dry morsel in quiet is better than a feasting house full of strife; the LORD tests hearts as the furnace tests gold; mocking the poor insults the poor man's Maker; grandchildren are the crown of the old; whoever repays evil for good will never be rid of evil; a friend's love never fails, and a brother is born to share hardship; a merry heart heals like medicine; a silent fool is thought wise"},{"p":"contents","r":"Proverbs 18:1–24","v":"A fool delights only in airing his own mind; a gossip's words are like tasty morsels; the LORD's name is a strong tower, where the righteous run and are safe, while the rich man trusts his wealth as a high wall; whoever answers before he hears is a fool; a gift opens the way for its giver; the tongue holds the power of death and life; to find a wife is to find a good thing and favor from the LORD; some friends stay closer than a brother"},{"p":"contents","r":"Proverbs 19:1–29","v":"The poor man of integrity is better than a perverse fool; false witnesses will be punished; it is a man's glory to pass over an offense; a foolish son ruins his father, and a quarrelsome wife is a continual dripping, but a prudent wife comes from the LORD; kindness to the poor is a loan to the LORD, who will repay; a son is to be disciplined while there is hope; man has many plans, but the LORD's counsel will stand; fearing the LORD brings life"},{"p":"contents","r":"Proverbs 20:1–30","v":"Wine mocks and strong drink brawls; the king's wrath is like a lion's roar; no one can say he has made his heart pure; the LORD abhors dishonest weights and measures; the LORD made both ear and eye; whoever curses father or mother will have his lamp put out; a man is not to repay evil himself but wait for the LORD to save him; the LORD orders a man's steps, and a man's spirit is the LORD's lamp searching his inmost heart; young men's glory is their strength, and old men's their gray hair"},{"p":"contents","r":"NKJV notes, note on Proverbs 21:1; Proverbs 21:1–31","v":"The LORD holds the king's heart in His hand and turns it as He wishes, like channels of water; doing righteousness and justice pleases the LORD more than sacrifice; it is better to live on a corner of the roof, or in the wilderness, than with a quarrelsome woman; whoever will not hear the poor man's cry will himself cry unheard; whoever guards his mouth keeps himself from trouble; no wisdom or counsel stands against the LORD, and the horse is made ready for battle, but deliverance comes from the LORD"},{"p":"contents","r":"Proverbs 22:1–16","v":"A good name is worth more than great riches; rich and poor alike were made by the LORD; humility and fearing the LORD bring riches, honor and life; a child trained in the right way keeps to it when he is old; the borrower serves the lender; the generous man is blessed, for he shares his bread with the poor; the lazy man says a lion is outside; whoever oppresses the poor for gain, or gives to the rich, will come to want"},{"p":"designation","r":"Proverbs 10:1","v":"The proverbs of Solomon"},{"p":"feature","r":"Proverbs 10:1–15:33","v":"Its sayings are mostly single proverbs of two lines; in chapters 10–15 the second line most often sets an opposite against the first, joined by 'but'"},{"p":"feature","r":"Proverbs 16:8, 10–15, 19, 32; 17:1; 19:1, 12; 20:2, 8, 26, 28; 21:1, 9, 19","v":"From chapter 16 the sayings more often set like beside like, or weigh one thing 'better' than another, and many speak of the king"},{"p":"made by","r":"Proverbs 10:1","e":"PER-00765"}],"nm":{"PER-00765":"Solomon"}},"OBJ-00522":{"k":"object","n":"The words of the wise","d":"Sayings of the wise that follow Solomon's first collection, opened by a call to hear them and trust the LORD (Proverbs 22:17–24:22)","f":[{"p":"contents","r":"Proverbs 22:22–29","v":"The hearer is not to rob the poor or crush the afflicted at the gate, for the LORD will plead their cause; not to befriend an angry man; not to stand surety for debts he cannot pay; not to move the ancient landmark his fathers set; and a man skilled in his work will stand before kings"},{"p":"contents","r":"NKJV notes, note on Proverbs 23:14; Proverbs 23:1–21","v":"At a ruler's table he is to restrain his appetite; he is not to wear himself out to be rich, for riches sprout wings and fly off like an eagle; not to eat a miser's bread or speak in a fool's hearing; not to move the ancient landmark or enter the fields of the fatherless, for their Redeemer is mighty; a child is not to go uncorrected, for the rod will save his soul from Sheol (by the NKJV note); the son is not to envy sinners but be zealous to fear the LORD, and not to keep company with drunkards and gluttons"},{"p":"contents","r":"Proverbs 23:22–35","v":"He is to listen to the father who begot him and not despise his mother when she is old; to buy the truth and never sell it; to give his heart to his father, for a harlot is a deep pit; and those who linger long over wine have woe, sorrow, wounds without cause and red eyes, for in the end it bites like a snake, and on waking the drunkard seeks another drink"},{"p":"contents","r":"Proverbs 24:1–22","v":"He is not to envy evil men; by wisdom a house is built and by knowledge its rooms are filled; the wise man is strong, and many counselors bring safety; he is to rescue those drawn toward death, for the One who weighs hearts knows and will repay each man by his deeds; the righteous rise again though they fall seven times; he is not to gloat when his enemy falls; and he is to fear the LORD as well as the king and keep away from those given to change"},{"p":"designation","r":"Proverbs 22:17","v":"the words of the wise"},{"p":"feature","r":"Proverbs 22:17–21; 23:15, 19, 26; 24:13, 21","v":"It speaks to the hearer in the first person as excellent things written for him, and calls him 'my son'"},{"p":"feature","r":"Proverbs 22:22–29; 23:1–35; 24:1–22","v":"Its sayings are mostly commands of two verses or more, each with its reason"},{"p":"purpose","r":"Proverbs 22:19–21","v":"That the hearer's trust may be in the LORD, and that he may know the certainty of true words and answer truly those who send him"}],"nm":{}},"OBJ-00523":{"k":"object","n":"The further sayings of the wise","d":"A short collection headed as also belonging to the wise, ending with the lesson of the lazy man's field (Proverbs 24:23–34)","f":[{"p":"contents","r":"Proverbs 24:23–34","v":"Partiality in judgment is not good, and whoever calls the wicked righteous will be cursed by the peoples, but those who rebuke the wicked will be blessed; a right answer is like a kiss on the lips; a man is to make ready his work in the field before he builds his house; he is not to witness against his neighbor without cause or repay him as he was treated; and the speaker tells how he passed the field and vineyard of the lazy man, overgrown with thorns and nettles and its stone wall in ruins, and learned that a little sleep and slumber bring poverty like a prowler"},{"p":"designation","r":"Proverbs 24:23","v":"These things also belong to the wise"},{"p":"feature","r":"Proverbs 6:10–11; 24:33–34","v":"Its closing lesson repeats the saying of chapter 6 on sleep, slumber and poverty"}],"nm":{}},"OBJ-00524":{"k":"object","n":"The proverbs of Solomon copied by the men of Hezekiah","d":"Proverbs of Solomon that the men of Hezekiah king of Judah copied (Proverbs 25–29)","f":[{"p":"contents","r":"Proverbs 25:2–28; Romans 12:20","v":"It is God's glory to conceal a matter and the glory of kings to search one out; the wicked are to be removed from before the king, and no one is to put himself forward in the king's presence, for it is better to be told to come up; a well-timed word is like golden apples set in silver; a faithful messenger refreshes like cold snow at harvest; gentle speech can break a bone; a man is to feed his hungry enemy and give him water, so heaping fiery coals on his head, and the LORD will reward him, words Paul quotes; good news from far away is like cold water to the weary; a man without rule over his spirit is like a city whose walls are broken down"},{"p":"contents","r":"NKJV notes, note on Proverbs 26:10; Proverbs 26:1–28; 2 Peter 2:22","v":"Honor no more suits a fool than snow suits summer; a causeless curse does not alight; a fool is both not to be answered and to be answered according to his folly, lest the answerer become like him or the fool think himself wise; sending a message by a fool is like cutting off one's own feet; the great God who formed everything gives fool and transgressor their wages (a hard verse, by the NKJV note); like a dog going back to its vomit, a fool repeats his folly, words Peter quotes; there is more hope for a fool than for a man who thinks himself wise; the lazy man turns on his bed like a door on its hinges; without a talebearer strife dies down, as fire without wood; the pit-digger falls into his own pit"},{"p":"contents","r":"NKJV notes, note on Proverbs 27:20; Proverbs 27:1–27","v":"No one should boast of tomorrow, for he does not know what a day will bring; let another praise him, not his own mouth; open rebuke is better than hidden love, and a friend's wounds are faithful; a near neighbor is better than a distant brother; iron sharpens iron, and so a man sharpens his friend; Sheol and Abaddon (by the NKJV notes) are never full, nor are man's eyes satisfied; a man is to know the state of his flocks and herds, for riches and crowns do not last, while lambs and goats will clothe and feed his household"},{"p":"contents","r":"Proverbs 28:1–28","v":"The wicked run though no one chases them, while the righteous are bold as a lion; those who keep the law contend with the wicked; the poor man of integrity is better than the perverse rich; hiding one's sins brings no success, but confessing and forsaking them brings mercy; a wicked ruler over the poor is like a roaring lion or charging bear; the man in haste to be rich will be punished; whoever trusts the LORD will prosper, but trusting one's own heart is folly; the giver to the poor lacks nothing; men hide when the wicked rise, and the righteous multiply when they perish"},{"p":"contents","r":"NKJV notes, note on Proverbs 29:18; Proverbs 29:1–27","v":"Whoever hardens his neck under rebuke will be broken suddenly; when the righteous are in authority the people rejoice, but under a wicked ruler they groan; a king makes his land stand by justice; scoffers inflame a city, but the wise turn away wrath; the LORD gives sight to both the poor and the oppressor; the king who judges the poor truly will have his throne established forever; where there is no revelation (prophetic vision, by the NKJV note) the people throw off restraint, but the one who keeps the law is happy; fearing man is a snare, but whoever trusts the LORD will be safe; a man's justice comes from the LORD"},{"p":"designation","r":"Proverbs 25:1","v":"These also are proverbs of Solomon"},{"p":"feature","r":"Proverbs 25:11–14, 18–20, 25–28; 26:1–3, 6–11, 14, 17–23; 27:8, 15–19; 28:1–29:27","v":"Chapters 25–27 gather many sayings of likeness, setting a picture beside its lesson; chapters 28–29 return to sayings of contrast, many on rulers, the law and the poor"},{"p":"feature","r":"Proverbs 18:8; 20:16; 21:9; 22:3; 25:24; 26:22; 27:12, 13","v":"Several of its sayings repeat ones of the first collection of Solomon's proverbs almost word for word"},{"p":"made by","r":"Proverbs 25:1","e":"PER-00765"},{"p":"occasion","r":"Proverbs 25:1","e":"EVT-02291"}],"nm":{"EVT-02291":"The men of Hezekiah copy proverbs of Solomon","PER-00765":"Solomon"}},"OBJ-00525":{"k":"object","n":"The words of Agur","d":"The utterance of Agur the son of Jakeh, which he declared to Ithiel and Ucal (Proverbs 30)","f":[{"p":"contents","r":"NKJV notes, note on Proverbs 30:5; Proverbs 30:1–9","v":"Agur owns that he has not learned wisdom, and asks who has gone up to heaven and come down, gathered the wind in His fists and bound the waters in a garment, and what is the name of that One and of His Son; God's every word is pure (tested and refined, by the NKJV note) and He shields those who trust Him, and no one is to add to His words; Agur asks to be kept from lies and given neither poverty nor riches"},{"p":"contents","r":"NKJV notes, note on Proverbs 30:16; NKJV notes, note on Proverbs 30:28; NKJV notes, note on Proverbs 30:31; Proverbs 30:10–33","v":"A servant is not to be slandered to his master; there is a generation that curses its father, thinks itself pure, looks down on others and devours the poor; the leech's two daughters cry 'Give', and the grave (Sheol, by the NKJV note), the barren womb, the dry earth and fire never have enough; ravens will pick out the eye that mocks father and mother; too wonderful are the way of an eagle, a serpent, a ship at sea and a man with a virgin, and the adulteress says she has done no wrong; the earth cannot bear four things, a servant who reigns among them; ants, rock badgers, locusts and the spider (or lizard, by the NKJV note) are small but exceedingly wise; the lion, the greyhound (or strutting rooster, by the NKJV note), the male goat and a king with his troops are stately in walk; and forcing wrath produces strife"},{"p":"designation","r":"Proverbs 30:1","v":"The words of Agur"},{"p":"feature","r":"Proverbs 30:15–31","v":"Most of it is numbered sayings, three things and then a fourth"},{"p":"made by","r":"Proverbs 30:1","e":"PER-02845"},{"p":"purpose","r":"Proverbs 30:1","v":"Declared to Ithiel and Ucal"}],"nm":{"PER-02845":"Agur"}},"OBJ-00526":{"k":"object","n":"The words of King Lemuel","d":"The utterance King Lemuel's mother taught him, on wine, justice and the cause of the poor (Proverbs 31:1–9)","f":[{"p":"contents","r":"NKJV notes, note on Proverbs 31:5; NKJV notes, note on Proverbs 31:8; Proverbs 31:2–9","v":"Lemuel's mother tells him not to give his strength to women or his ways to what destroys kings; it is not for kings to drink wine, lest they forget the law and pervert the justice due the afflicted, but strong drink is for the perishing and wine for the bitter of heart; he is to speak up for the speechless and all who are appointed to die, judge righteously and defend the poor and needy"},{"p":"designation","r":"Proverbs 31:1","v":"The words of King Lemuel"},{"p":"made by","r":"Proverbs 31:1","e":"PER-02849"},{"p":"made by","r":"Proverbs 31:1","e":"PER-02850"}],"nm":{"PER-02849":"Lemuel","PER-02850":"Lemuel's mother"}},"OBJ-00527":{"k":"object","n":"The praise of the virtuous wife","d":"The closing poem of Proverbs, on the virtuous wife whose worth is far above rubies (Proverbs 31:10–31)","f":[{"p":"contents","r":"NKJV notes, note on Proverbs 31:10; Proverbs 31:10–31","v":"The virtuous wife (a wife of valor, in every kind of excellence, by the NKJV note) is worth far more than rubies; her husband trusts her and lacks no gain; she works wool and flax, brings food from afar like merchant ships, rises before dawn to feed her household, buys a field and plants a vineyard from her earnings, spins with distaff and spindle, gives to the poor, clothes her household in scarlet and herself in fine linen and purple, and sells linen garments and sashes; her husband is known in the gates among the elders; she speaks with wisdom and kindness and is never idle; her children call her blessed and her husband praises her above all; charm deceives and beauty passes, but the woman who reveres the LORD is to be praised"},{"p":"designation","r":"Proverbs 31:10","v":"Who can find a virtuous wife?"},{"p":"feature","r":"NKJV notes, note on Proverbs 31:10; Proverbs 31:10–31","v":"Its verses form an alphabetic acrostic in Hebrew, by the NKJV note"},{"p":"made by","r":"Proverbs 31:1, 10–31","e":"PER-02849","b":"inferred","c":"possible","w":"Proverbs 31 is headed the words of King Lemuel (31:1); whether his words run on through the poem of the virtuous wife (31:10–31) is not said."}],"nm":{"PER-02849":"Lemuel"}},"OBJ-00528":{"k":"object","n":"The Book of Ecclesiastes","d":"The words of the Preacher, the son of David, king in Jerusalem, on the vanity of all that is done under the sun (Ecclesiastes 1–12)","f":[{"p":"contents","r":"Ecclesiastes 1:1–18","v":"The Preacher asks what profit a man has from his toil under the sun: generations pass while the earth remains, the sun, the wind and the rivers go round and round, the eye and ear are never satisfied, and under the sun nothing is new; as king over Israel in Jerusalem he searched out by wisdom all that is done under heaven, found it vanity and grasping for the wind, and learned that much wisdom brings much grief"},{"p":"contents","r":"Ecclesiastes 2:1–26","v":"He tested pleasure, laughter and wine; he built houses, planted vineyards, made gardens, orchards and pools, and gathered servants, herds, silver, gold, the treasures of kings and singers, becoming greater than all before him in Jerusalem, yet found all his labor vanity; wisdom excels folly as light excels darkness, but the wise man dies like the fool and must leave his labor to whoever comes after him; to eat, drink and enjoy one's labor is from God's hand"},{"p":"contents","r":"Ecclesiastes 3:1–22","v":"There is a season for everything, a time to be born and to die, to weep and to laugh, to love and to hate, of war and of peace; God has made everything beautiful in its time and set eternity in men's hearts, and what He does lasts forever, so that men should fear Him; God will judge the righteous and the wicked; man, like the beast, comes from dust and returns to dust"},{"p":"contents","r":"Ecclesiastes 4:1–16","v":"The oppressed weep with no comforter, and the dead and the unborn are better off; toil springs from envy; a handful in quiet is better than two hands full of toil; the lone man toils without end for no one; two do better than one, and a cord of three strands holds fast; a poor wise youth is better than an old foolish king, yet the crowds forget even the youth who rose from prison to reign"},{"p":"contents","r":"Ecclesiastes 5:1–20","v":"A man is to go to the house of God to listen rather than to offer the sacrifice of fools, and let his words be few, for God is in heaven; he is to pay his vows without delay, since it is better not to vow at all than to break a vow; the lover of silver never has enough of it; the laborer sleeps sweetly, but the rich man's abundance keeps him awake; naked a man came from the womb and naked he returns; to eat, drink and enjoy one's labor and riches is the gift of God"},{"p":"contents","r":"NKJV notes, note on Ecclesiastes 6:3; Ecclesiastes 6:1–12","v":"God gives some men riches, wealth and honor but not the power to enjoy them; a man may have a hundred children and a long life, yet if his soul is not satisfied a stillborn child (or miscarriage, by the NKJV note) is better off; all a man's labor is for his mouth, yet his appetite is never filled; no one can tell a man what will come after him under the sun"},{"p":"contents","r":"Ecclesiastes 7:1–29","v":"A good name is worth more than fine ointment, and the house of mourning than the house of feasting; the end of a thing is better than its beginning, and patience than pride; no one is to ask why former days were better; wisdom, like money, protects, and gives life to those who have it; God appointed both prosperity and adversity; no one on earth is so righteous that he does good and never sins; searching out the reason of things, the Preacher found the woman whose heart is snares more bitter than death, and found that God made man upright, but men have sought out many schemes"},{"p":"contents","r":"Ecclesiastes 8:1–17","v":"A man's wisdom makes his face shine; he is to keep the king's command for the sake of his oath to God, for the king's word carries power; no one has power over the day of death; because sentence on an evil work is not carried out speedily, men's hearts are set on evil, yet it will go well with those who fear God; the Preacher commends enjoyment, since no one, however wise, can find out the work of God done under the sun"},{"p":"contents","r":"Ecclesiastes 9:1–18","v":"One event comes to the righteous and the wicked alike, and the dead know nothing and are forgotten; even a living dog has more hope than a dead lion; a man is to eat with joy, live joyfully with the wife he loves, and do with all his might whatever his hand finds to do, for there is no work or wisdom in the grave; the race does not go to the swift nor the battle to the strong, but time and chance overtake everyone; a poor wise man delivered a little city besieged by a great king, yet no one remembered him, for a poor man's wisdom is scorned, though wisdom is better than weapons of war"},{"p":"contents","r":"Ecclesiastes 10:1–20","v":"A little folly spoils one honored for wisdom, as dead flies spoil the perfumer's ointment; folly is set on high while the rich sit low, and servants ride horses while princes walk; the pit-digger may fall into his pit; wisdom brings success, as a sharpened ax saves strength; a fool multiplies words; woe to the land whose king is a child, but blessed is the land whose king is the son of nobles; through laziness the roof leaks; no one is to curse the king even in thought, for a bird may carry the words"},{"p":"contents","r":"NKJV notes, note on Ecclesiastes 11:5; Ecclesiastes 11:1–10","v":"A man is to cast his bread on the waters, for he will find it after many days, and give a portion to seven and to eight; whoever watches the wind will not sow; as no one knows the way of the wind (or spirit, by the NKJV note) or how bones grow in the womb, so no one knows the works of God who makes everything; light is sweet, but the days of darkness will be many; the young man is to rejoice in his youth, but know that God will bring him into judgment for it all"},{"p":"contents","r":"Ecclesiastes 12:1–14","v":"He is to remember his Creator in the days of his youth, before the hard days of age come, pictured as a house whose keepers tremble, whose grinders cease and whose windows grow dim, before the silver cord comes loose and the golden bowl breaks, when the dust returns to the earth and the spirit to God, its giver; the Preacher, being wise, taught the people knowledge and set many proverbs in order, seeking words both pleasing and true; the words of the wise are like goads and well-driven nails, given by one Shepherd; there is no end to the making of books; the conclusion is to fear God and obey His commands, for God will bring every work into judgment, every secret thing, good or evil"},{"p":"designation","r":"Ecclesiastes 1:1","v":"The words of the Preacher"},{"p":"feature","r":"NKJV notes, note on Ecclesiastes 1:2; Ecclesiastes 1:2; 12:8","v":"It opens and closes with the Preacher's cry, vanity of vanities, all is vanity (absurdity, frustration or futility, by the NKJV note)"},{"p":"feature","r":"Ecclesiastes 1:3, 14; 2:11, 17, 26; 4:4, 16; 6:9","v":"Again and again it weighs what is done under the sun and finds it vanity and grasping for the wind"},{"p":"feature","r":"Ecclesiastes 1:1–2, 12; 7:27; 12:8–10","v":"It speaks mostly in the first person as the Preacher, while its opening and close speak of him by that name"},{"p":"feature","r":"Ecclesiastes 3:1–8","v":"A poem of fourteen pairs of times, a season for each thing under heaven"},{"p":"feature","r":"Ecclesiastes 12:13–14","v":"Its conclusion: to fear God and obey His commandments, which is everything for man, since God will judge every deed"},{"p":"made by","r":"Ecclesiastes 1:1, 12","e":"PER-00765","b":"inferred","c":"probable","w":"The Preacher calls himself the son of David and king over Israel in Jerusalem (Ecclesiastes 1:1, 1:12); of David's sons only Solomon was king over Israel in Jerusalem, though the book does not name him."}],"nm":{"PER-00765":"Solomon"}},"OBJ-00529":{"k":"object","n":"The Song of Solomon","d":"The song of songs, which is Solomon's: the love of the Shulamite and her beloved (Song of Solomon 1–8)","f":[{"p":"contents","r":"Song of Solomon 1:1–17","v":"The Shulamite longs for her beloved, whose love is better than wine, and says the king has brought her into his chambers; dark from the sun yet lovely, she tells the daughters of Jerusalem that her brothers made her keep the vineyards; she asks where her beloved feeds his flock, and he bids her follow the tracks of the flock; they praise each other, he likening her to a filly among Pharaoh's chariots, she him to a bundle of myrrh and to henna blooms in the vineyards of En Gedi"},{"p":"contents","r":"Song of Solomon 2:1–17","v":"She calls herself the rose of Sharon and a lily of the valleys, and he calls her a lily among thorns; in his banqueting house love is the banner he raises over her, and she is lovesick; she charges the daughters of Jerusalem not to stir up love until it pleases; her beloved comes leaping over the hills like a gazelle and calls her to rise and come away, for the winter is past and the flowers have appeared; the little foxes that ruin the vines are to be caught; she belongs to her beloved and he to her"},{"p":"contents","r":"Song of Solomon 3:1–11","v":"By night she seeks the one she loves through the city, asks the watchmen, finds him and brings him to her mother's house; a procession comes up from the wilderness like pillars of smoke: Solomon's couch with sixty valiant men of Israel, armed against fear in the night, and the palanquin he made of the wood of Lebanon, silver, gold and purple; the daughters of Zion are bidden to see King Solomon in the crown his mother set on him on his wedding day"},{"p":"contents","r":"Song of Solomon 4:1–16","v":"The beloved praises her beauty, from her eyes behind her veil to her neck like the tower of David hung with a thousand shields, and calls her to come with him from Lebanon, from the tops of Amana, Senir and Hermon and the lions' dens; his sister, his spouse, has ravished his heart; she is a garden enclosed, a spring shut up, a fountain sealed, an orchard of spices, a living well and streams from Lebanon; she bids the north and south winds blow on her garden for her beloved"},{"p":"contents","r":"Song of Solomon 5:1–16","v":"He comes to his garden and bids his friends eat and drink; asleep with her heart awake, she hears him knock with his head wet with dew, but when she opens he has gone; seeking him, she is struck and wounded by the watchmen and her veil is taken by the keepers of the walls; she charges the daughters of Jerusalem to tell him she is lovesick, and when they ask what makes him more than another she describes him, white and ruddy, chief among ten thousand, his head like fine gold and his countenance like Lebanon, altogether lovely"},{"p":"contents","r":"NKJV notes, note on Song of Solomon 6:12; NKJV notes, note on Song of Solomon 6:13; Song of Solomon 6:1–13","v":"The daughters of Jerusalem offer to seek her beloved, who has gone down to his garden to feed his flock among the lilies; she belongs to her beloved and he to her; he calls her beautiful as Tirzah, lovely as Jerusalem and awesome as an army with banners; among sixty queens, eighty concubines and countless virgins his dove is the only one, and the queens praise her; she goes down to the garden of nuts and finds herself as the chariots of her noble people (Ammi Nadib, by the NKJV note); and she is called back, O Shulamite, to be looked on as at the dance of the two camps (Mahanaim, by the NKJV note)"},{"p":"contents","r":"Song of Solomon 7:1–13","v":"He praises the prince's daughter from her feet to her hair: her neck like an ivory tower, her eyes like the pools in Heshbon by the gate of Bath Rabbim, her nose like the tower of Lebanon that looks toward Damascus, her head like Mount Carmel and her stature like a palm tree, so that her tresses hold a king captive; she belongs to her beloved and his desire is for her, and she calls him out to the fields and vineyards, where she will give him her love"},{"p":"contents","r":"NKJV notes, note on Song of Solomon 8:6; Song of Solomon 8:1–14","v":"She wishes her beloved were like a brother she could kiss openly and bring to her mother's house, and charges the daughters of Jerusalem not to awaken love until it pleases; coming up from the wilderness leaning on her beloved, she asks him to set her as a seal on his heart, for love rivals death in strength, its flames a most vehement flame (a flame of Yah, by the NKJV note), and no flood can quench it; her brothers ask what to do for their little sister when she is spoken for; Solomon's vineyard at Baal Hamon was let to keepers for a thousand silver coins, but her own vineyard is before her; she bids her beloved hurry like a gazelle on the mountains of spices"},{"p":"designation","r":"Song of Solomon 1:1","v":"The song of songs"},{"p":"feature","r":"NKJV notes, note on Song of Solomon 1:2; Song of Solomon 1:2","v":"Its speakers, the Shulamite, her beloved, the daughters of Jerusalem and her brothers, are known by the Hebrew words' gender, number and person, as the NKJV note explains, though at times who speaks is uncertain"},{"p":"feature","r":"Song of Solomon 2:7; 3:5; 8:4","v":"Three times the Shulamite charges the daughters of Jerusalem not to stir up or awaken love until it pleases"},{"p":"feature","r":"Song of Solomon 4:1–15; 5:10–16; 6:4–9; 7:1–9","v":"The lovers praise each other's beauty limb by limb, in pictures drawn from nature and from places such as Gilead, Lebanon, Tirzah, Heshbon and Carmel"},{"p":"feature","r":"NKJV notes, note on Song of Solomon 8:6; Song of Solomon 8:6","v":"God's name appears in it only within its 'most vehement flame', which is literally a flame of Yah, by the NKJV note"},{"p":"made by","r":"Song of Solomon 1:1","e":"PER-00765"}],"nm":{"PER-00765":"Solomon"}},"OBJ-00530":{"k":"object","n":"Solomon's palanquin","d":"The couch King Solomon made himself of the wood of Lebanon, borne with sixty valiant men around it (Song of Solomon 3:7–10)","f":[{"p":"designation","r":"Song of Solomon 3:7","v":"Solomon's couch"},{"p":"feature","r":"NKJV notes, note on Song of Solomon 3:9; Song of Solomon 3:9–10","v":"A portable enclosed chair, by the NKJV note, its inside lined with love by the daughters of Jerusalem"},{"p":"made by","r":"Song of Solomon 3:9","e":"PER-00765"},{"p":"material","r":"Song of Solomon 3:9–10","v":"The wood of Lebanon, with pillars of silver, a support of gold and a seat of purple"},{"p":"owner","r":"Song of Solomon 3:7, 9","e":"PER-00765"}],"nm":{"PER-00765":"Solomon"}},"OBJ-00531":{"k":"object","n":"The Book of Isaiah","d":"The vision of Isaiah the son of Amoz concerning Judah and Jerusalem, seen in the days of Uzziah, Jotham, Ahaz and Hezekiah (Isaiah 1–66)","f":[{"p":"contents","r":"Isaiah 1:1–31; Romans 9:29","v":"Heaven and earth are called to hear that the children the LORD raised have rebelled: the ox knows its owner but Israel does not; the land is desolate and burned, Zion is left like a booth in a vineyard, and but for a very small remnant they would have been like Sodom and Gomorrah, words Paul quotes; their sacrifices, New Moons and feasts burden the LORD while their hands are full of blood; they are to wash, seek justice and defend the fatherless and widow, and sins like scarlet would become white as snow; the faithful city has become a harlot, but Zion will be redeemed by justice and called the city of righteousness"},{"p":"contents","r":"Isaiah 2:1–22","v":"Under a second heading: in the latter days the LORD's house will stand on the highest of the mountains and all nations will stream to it to learn His ways, for the law will go forth from Zion; He will judge the nations, and they will beat swords into plowshares and learn war no more; but the house of Jacob, full of eastern ways, silver, horses and idols, will be humbled in the day of the LORD of hosts, which comes on the cedars of Lebanon, the oaks of Bashan and the ships of Tarshish, when men hide in the rocks and throw their idols to the moles and bats"},{"p":"contents","r":"Isaiah 3:1–26","v":"The LORD of hosts will take from Jerusalem and Judah every support, bread and water, warriors, judges, prophets and elders, and give them children as princes; Jerusalem has stumbled because its words and deeds defy the LORD, and they parade their sin like Sodom; He will judge the elders and princes who have eaten up the vineyard and ground the poor; because the daughters of Zion are haughty He will strip away all their finery, and their men will fall by the sword"},{"p":"contents","r":"Isaiah 4:1–6","v":"Seven women will take hold of one man to be called by his name; in that day the Branch of the LORD will be beautiful and glorious, those left in Zion will be called holy, and the LORD will create over Mount Zion a cloud by day and a flaming fire by night, a shelter from heat and storm"},{"p":"contents","r":"Isaiah 5:1–30","v":"Isaiah sings of his Well-beloved's vineyard on a fruitful hill, tended with every care, which yielded only wild grapes, so He will lay it waste: the vineyard is the house of Israel, and He looked for justice but found oppression; woes follow on those who join house to house, chase strong drink from morning, call evil good and good evil, are wise in their own sight and acquit the wicked for a bribe; so His people go into captivity, Sheol opens its mouth, and the LORD will whistle for a nation from far off that comes swiftly, roaring like lions"},{"p":"contents","r":"Isaiah 6:1–13; Matthew 13:14–15; Mark 4:12; John 12:39–41; Acts 28:25–27","v":"In the year King Uzziah died Isaiah saw the LORD on a high throne, His train filling the temple, with six-winged seraphim crying holy, holy, holy; undone as a man of unclean lips, he was cleansed with a live coal from the altar and answered the LORD's call, 'Here am I! Send me'; he was sent to a people who would hear without understanding, words the Gospels and Acts quote, John adding that Isaiah saw His glory, until the land lay waste and only a holy stump remained"},{"p":"contents","r":"Isaiah 7:1–25; Matthew 1:22–23","v":"When Rezin of Syria and Pekah of Israel came against Jerusalem, the LORD sent Isaiah with his son Shear-Jashub to meet Ahaz at the aqueduct of the upper pool and tell him not to fear: their plot to make the son of Tabel king would not stand, and within sixty-five years Ephraim would be broken; when Ahaz would not ask a sign, the LORD gave one, the virgin who would conceive and bear a Son called Immanuel, words Matthew applies to the birth of Jesus; before the child knew good from evil both kings' lands would be forsaken, and the king of Assyria would come on Judah like a hired razor"},{"p":"contents","r":"Isaiah 8:1–22; Romans 9:33; Hebrews 2:13; 1 Peter 2:8; 3:14–15","v":"Isaiah wrote on a large scroll concerning Maher-Shalal-Hash-Baz before the witnesses Uriah the priest and Zechariah, and the prophetess bore him a son of that name, for before he could say 'My father' Assyria would carry off the riches of Damascus and Samaria; because the people refused the gentle waters of Shiloah, Assyria would flood Judah to the neck; the LORD of hosts would be a sanctuary but a stone of stumbling, words Paul and Peter quote; Isaiah sealed the law among his disciples and waited on the LORD, he and his children being signs in Israel, as Hebrews quotes; those who seek mediums instead of God will be driven into darkness"},{"p":"contents","r":"Isaiah 9:1–21; Matthew 4:13–16","v":"The land of Zebulun and Naphtali, Galilee of the Gentiles, once brought low, will see a great light, words Matthew applies to Jesus; the yoke of the oppressor is broken as in the day of Midian, for a Child is born and a Son given, called Wonderful, Counselor, Mighty God, Everlasting Father, Prince of Peace, whose government on David's throne will have no end; yet the LORD's word falls on proud Ephraim and Samaria, and His hand is stretched out still as Syrians and Philistines devour Israel and Manasseh and Ephraim turn on each other"},{"p":"contents","r":"Isaiah 10:1–34; Romans 9:27–28","v":"Woe to those who write unjust decrees to rob the poor; Assyria is the rod of the LORD's anger against a godless nation, but its king boasts that Calno, Hamath and Samaria fell like Carchemish, Arpad and Damascus, so the Light of Israel will burn his forest; a remnant of Israel will return to the Mighty God, though the people be as the sand of the sea, words Paul quotes; the Assyrian marches through Aiath, Migron, Michmash and Geba, past Ramah, Gibeah of Saul, Gallim, Laish, Anathoth, Madmenah and Gebim to Nob, shaking his fist at Zion, but the LORD of hosts will lop off the bough"},{"p":"contents","r":"Isaiah 11:1–16; Romans 15:12","v":"A Rod will come from the stem of Jesse, and the Spirit of the LORD will rest on Him; He will judge the poor with righteousness; the wolf will dwell with the lamb and a little child lead them, for the earth will be full of the knowledge of the LORD; the Root of Jesse will stand as a banner, and the Gentiles will seek Him, words Paul quotes; the LORD will gather His remnant a second time from Assyria, Egypt, Pathros, Cush, Elam, Shinar and Hamath, and make a highway for them as when Israel came out of Egypt"},{"p":"contents","r":"Isaiah 12:1–6","v":"A song for that day: the LORD's anger is turned away and He comforts; God is my salvation, and YAH, the LORD, is my strength and song; with joy water is drawn from the wells of salvation; Zion is to shout, for great is the Holy One of Israel in her midst"},{"p":"contents","r":"Isaiah 13:1–22","v":"The burden against Babylon which Isaiah saw: the LORD of hosts musters an army from a far country for the day of the LORD, when sun, moon and stars are darkened and the proud are laid low; He will stir up the Medes, who care nothing for silver or gold, and Babylon, the glory of kingdoms, will be overthrown like Sodom and Gomorrah and never inhabited again, a haunt of wild beasts and jackals"},{"p":"contents","r":"NKJV notes, note on Isaiah 14:12; Isaiah 14:1–32","v":"The LORD will have mercy on Jacob and settle Israel in its land, and Israel will taunt the king of Babylon: the oppressor has ceased and Sheol stirs to meet him; Lucifer, son of the morning (Day Star, by the NKJV note), who said he would ascend above the stars of God and be like the Most High, is brought down to the Pit; Babylon will be swept with the broom of destruction; the LORD has sworn to break the Assyrian in His land; and in the year King Ahaz died came the burden warning Philistia not to rejoice, for a viper would come from the serpent's root, while the LORD has founded Zion"},{"p":"contents","r":"NKJV notes, note on Isaiah 15:5; Isaiah 15:1–9","v":"The burden against Moab: in a night Ar of Moab and Kir of Moab are laid waste; Moab wails at Dibon, Nebo and Medeba, Heshbon, Elealeh and Jahaz cry out, and its fugitives flee to Zoar, up the Ascent of Luhith and by the way of Horonaim, as the waters of Nimrim fail, wealth is carried to the Brook of the Willows, the wailing reaches Eglaim and Beer Elim, and the waters of Dimon run with blood"},{"p":"contents","r":"Isaiah 16:1–14","v":"Moab is to send the lamb to the ruler of the land and shelter Israel's outcasts, for a throne will be established in mercy in the tabernacle of David; because of Moab's pride Kir Hareseth will be stricken and the fields of Heshbon and the vine of Sibmah, which reached to Jazer, broken down, and the prophet weeps for them; within three years, as a hired man counts them, Moab's glory will be despised"},{"p":"contents","r":"NKJV notes, note on Isaiah 17:8; Isaiah 17:1–14","v":"The burden against Damascus: it will cease to be a city and become a ruinous heap, the cities of Aroer will be left to flocks, and the kingdom will cease from Damascus and the fortress from Ephraim; the glory of Jacob will wane to a gleaning, as in the Valley of Rephaim, and men will look to their Maker and not to their altars and wooden images (Asherim, by the NKJV note), for they forgot the Rock of their stronghold; the nations roar like the sea, but God rebukes them, and before morning the plunderer is no more"},{"p":"contents","r":"NKJV notes, note on Isaiah 18:1; Isaiah 18:1–7","v":"Woe to the land beyond the rivers of Ethiopia (Cush, by the NKJV note), which sends envoys in vessels of reed to a tall, smooth-skinned people whose land the rivers divide: the LORD will watch quietly from His dwelling and cut off the branches before harvest, and in that time a present will be brought from that people to the LORD of hosts at Mount Zion"},{"p":"contents","r":"NKJV notes, note on Isaiah 19:13; NKJV notes, note on Isaiah 19:18; Isaiah 19:1–25","v":"The burden against Egypt: the LORD rides a swift cloud into Egypt, its idols totter, Egyptian fights Egyptian, and a cruel master and fierce king will rule it; the Nile and its reeds dry up, the princes of Zoan and Noph are fools; yet in that day five cities in Egypt will speak the language of Canaan, one called the City of Destruction (or of the Sun, by the NKJV note), an altar to the LORD will stand in Egypt, He will send them a Savior, and Egypt, Assyria and Israel will be blessed together"},{"p":"contents","r":"Isaiah 20:1–6","v":"In the year Tartan, sent by Sargon king of Assyria, fought against Ashdod and took it, the LORD told Isaiah to put off his sackcloth and sandals, and he walked naked and barefoot three years as a sign that the king of Assyria would lead Egypt and Ethiopia away captive, to the shame of all who looked to them for help"},{"p":"contents","r":"Isaiah 21:1–17","v":"The burden against the Wilderness of the Sea: a distressing vision bids Elam and Media besiege, the prophet is seized with pangs, and the watchman set in the tower sees chariots and horsemen and cries that Babylon is fallen, is fallen, and her gods' images broken; the burden against Dumah, where one calls out of Seir, Watchman, what of the night?; and the burden against Arabia, where Dedanite caravans lodge and Tema brings water to fugitives, for within a year the glory of Kedar will fail and its archers be few"},{"p":"contents","r":"Isaiah 22:1–25; 1 Corinthians 15:32; Revelation 3:7","v":"The burden against the Valley of Vision: the tumultuous city goes up to its housetops while its rulers flee and are captured; Elam and Kir come with chariots; the people look to the armor of the House of the Forest, gather the waters of the lower pool, break down houses to fortify the wall and make a reservoir between the two walls, yet do not look to the One who made it, and feast, saying let us eat and drink, for tomorrow we die, words Paul quotes; Shebna the steward, who hewed himself a tomb on high, will be thrown into a large country, and Eliakim the son of Hilkiah given the key of the house of David, words Revelation applies to Christ"},{"p":"contents","r":"NKJV notes, note on Isaiah 23:1; NKJV notes, note on Isaiah 23:3; Isaiah 23:1–18","v":"The burden against Tyre: the ships of Tarshish are to wail, for Tyre is laid waste, as word comes from Cyprus (Kittim, by the NKJV note); Sidon and Egypt mourn the crowning city whose merchants were princes and whose revenue was the grain of Shihor; the LORD of hosts purposed it to humble all pride; Tyre will be forgotten seventy years, the days of one king, then return to her trade, but her gain will be holy to the LORD"},{"p":"contents","r":"Isaiah 24:1–23","v":"The LORD empties and lays waste the earth, people and priest, master and servant alike, for they broke the everlasting covenant; the city of confusion is broken down and all joy is gone; songs rise from the ends of the earth, but the prophet cries that he is ruined; the earth reels like a drunkard, the LORD punishes the exalted host on high and the kings of the earth, and the LORD of hosts reigns gloriously on Mount Zion and in Jerusalem"},{"p":"contents","r":"Isaiah 25:1–12; 1 Corinthians 15:54; Revelation 21:4","v":"The prophet praises the LORD for making a fortified city a ruin and being a refuge to the poor; on this mountain the LORD of hosts will spread a feast for all peoples, remove the veil over the nations and swallow up death forever, wiping away tears from all faces, words Paul and Revelation take up; in that day they will say this is our God, for whom they waited, and Moab will be trampled down like straw"},{"p":"contents","r":"NKJV notes, note on Isaiah 26:4; Isaiah 26:1–21","v":"A song for the land of Judah: a strong city whose open gates admit the righteous; the LORD keeps in perfect peace the mind stayed on Him, for in YAH is everlasting strength (or the Rock of Ages, by the NKJV note); He brings down the lofty city; His people longed for Him in the night, and though other lords ruled them, their dead will live and the earth will cast out the dead; they are to hide in their rooms until the indignation is past"},{"p":"contents","r":"NKJV notes, note on Isaiah 27:9; NKJV notes, note on Isaiah 27:12; Isaiah 27:1–13","v":"In that day the LORD will punish Leviathan the fleeing serpent with His great sword; He keeps His vineyard night and day, and Israel will blossom and fill the world with fruit; Jacob's iniquity will be covered when the altar stones are crushed and the wooden images (Asherim, by the NKJV note) fall, though the fortified city is left desolate; the LORD will thresh from the River to the Brook of Egypt, and at the great trumpet the outcasts in Assyria and Egypt will come and worship on the holy mount at Jerusalem"},{"p":"contents","r":"NKJV notes, note on Isaiah 28:21; Isaiah 28:1–29; Romans 9:33; 10:11; 1 Corinthians 14:21; 1 Peter 2:6","v":"Woe to the crown of pride, the drunkards of Ephraim, whose beauty is a fading flower the Lord's mighty one will trample; the LORD of hosts will be a crown of glory to the remnant; priest and prophet reel with wine, so the LORD will speak to them with stammering lips and another tongue, words Paul quotes; Jerusalem's scoffing rulers have made a covenant with death, but the Lord GOD lays in Zion a tried, precious cornerstone, a sure foundation, words Paul and Peter quote, and He will rise up as at Mount Perazim and the Valley of Gibeon to do His unusual work; the farmer's ways too come from the LORD of hosts"},{"p":"contents","r":"NKJV notes, note on Isaiah 29:1; Isaiah 29:1–24; Matthew 15:7–9; Mark 7:6–7; Romans 11:8; 1 Corinthians 1:19","v":"Woe to Ariel, the city where David dwelt (Jerusalem, by the NKJV note): the LORD will besiege it till its voice whispers from the dust, yet the nations that fight against Mount Zion will vanish like a dream of the night; the LORD has poured on the people a spirit of deep sleep, the vision is to them a sealed book, and because they honor Him with their lips while their hearts are far off, the wisdom of their wise will perish, words Jesus and Paul quote; soon Lebanon will be a fruitful field, the deaf will hear and the blind see, and Jacob will no longer be ashamed"},{"p":"contents","r":"NKJV notes, note on Isaiah 30:7; Isaiah 30:1–33","v":"Woe to the rebellious children who go down to Egypt for help, whose princes reached Zoan and envoys Hanes; the burden against the beasts of the South calls Egypt Rahab-Hem-Shebeth (Rahab Sits Idle, by the NKJV note); the people tell the seers not to see, but in returning and rest they would be saved; the LORD waits to be gracious, they will dwell in Zion and hear a word behind them, This is the way, walk in it; at His voice Assyria will be beaten down, and Tophet is prepared for the king"},{"p":"contents","r":"Isaiah 31:1–9","v":"Woe to those who go down to Egypt and trust in horses and chariots and do not look to the Holy One of Israel: the Egyptians are men and not God; but the LORD of hosts will come down like a lion to fight for Mount Zion and defend Jerusalem like hovering birds, and Assyria will fall by a sword not of man"},{"p":"contents","r":"Isaiah 32:1–20","v":"A king will reign in righteousness and princes rule with justice, each a shelter from the storm and a rock's shade in a weary land; the fool will no longer be called noble; the complacent women are to tremble, for within a year and some days the vintage will fail and the palaces be forsaken, until the Spirit is poured out from on high, the wilderness becomes a fruitful field, and the work of righteousness is peace"},{"p":"contents","r":"Isaiah 33:1–24","v":"Woe to the plunderer, who will himself be plundered; the LORD, who dwells on high, has filled Zion with justice; the land mourns, Lebanon withers, Sharon is a wilderness and Bashan and Carmel shake off their fruit, but now the LORD will rise; the sinners in Zion ask who can dwell with the devouring fire, and the upright will dwell on high; their eyes will see the King in His beauty and Jerusalem a quiet home, a tent never taken down, for the LORD is our Judge, Lawgiver and King, and its people will be forgiven"},{"p":"contents","r":"NKJV notes, note on Isaiah 34:14; Isaiah 34:1–17; Revelation 6:13–14","v":"The nations are to hear: the LORD's indignation is on all of them, the host of heaven will be dissolved and the heavens rolled up like a scroll, an image Revelation takes up; His sword will come down on Edom, a sacrifice in Bozrah and a great slaughter in the land of Edom, the year of recompense for Zion; Edom's streams will turn to pitch and it will lie waste forever, possessed by owls, ravens, jackals and the night creature (lilith, by the NKJV note), as the book of the LORD says"},{"p":"contents","r":"NKJV notes, note on Isaiah 35:1; Isaiah 35:1–10; Matthew 11:4–5; Hebrews 12:12","v":"The desert (the Arabah, by the NKJV note) will rejoice and blossom like the rose, given the glory of Lebanon and the excellence of Carmel and Sharon; weak hands are to be strengthened, words Hebrews takes up, for God will come and save; the eyes of the blind will be opened, the deaf will hear and the lame leap like a deer, as Jesus told John's disciples; waters will burst out in the wilderness, and on the Highway of Holiness the ransomed of the LORD will return to Zion with everlasting joy"},{"p":"contents","r":"NKJV notes, note on Isaiah 36:2; Isaiah 36:1–22","v":"In Hezekiah's fourteenth year Sennacherib took the fortified cities of Judah and sent the Rabshakeh (a title, by the NKJV note) from Lachish with a great army to the aqueduct of the upper pool; before Eliakim, Shebna and Joah he mocked Hezekiah's trust in Egypt, that broken reed, and in the LORD, and called out in Hebrew to the people on the wall that no god had saved any land from Assyria; the people kept silent, and the officials came to Hezekiah with their clothes torn"},{"p":"contents","r":"Isaiah 37:1–38","v":"Hezekiah went into the house of the LORD in sackcloth and sent to Isaiah, who answered that the king of Assyria would hear a rumor, go home and fall by the sword; when Sennacherib's letter came, Hezekiah spread it before the LORD and prayed; Isaiah sent the LORD's answer that the virgin daughter of Zion laughed him to scorn and that he would not enter the city, and the angel of the LORD struck a hundred and eighty-five thousand in the Assyrian camp; Sennacherib went home to Nineveh, where his sons Adrammelech and Sharezer killed him in the house of Nisroch"},{"p":"contents","r":"Isaiah 38:1–22","v":"Hezekiah was sick and near death, and Isaiah told him to set his house in order; he turned to the wall and wept, and the LORD added fifteen years to his life, promised to defend the city, and gave the sign of the shadow going back ten degrees on the sundial of Ahaz; Hezekiah wrote of his sickness and recovery; a lump of figs had been laid on his boil"},{"p":"contents","r":"NKJV notes, note on Isaiah 39:1; Isaiah 39:1–8","v":"Merodach-Baladan (Berodach-Baladan, by the NKJV note) the son of Baladan, king of Babylon, sent letters and a present to Hezekiah, who showed his envoys all his treasures; Isaiah told him the LORD's word that everything would be carried to Babylon and some of his sons would serve as eunuchs in its king's palace, and Hezekiah called the word good, for there would be peace and truth in his days"},{"p":"contents","r":"Isaiah 40:1–31; Matthew 3:1–3; Luke 3:4–6; John 1:23; Romans 11:34; 1 Peter 1:24–25","v":"Comfort My people: Jerusalem's warfare is ended and her iniquity pardoned; a voice cries in the wilderness to prepare the way of the LORD, words the Gospels apply to John the Baptist; all flesh is grass, but the word of our God stands forever, words Peter quotes; Zion is to say to Judah's cities, Behold your God, who will feed His flock like a shepherd; He weighs the mountains, the nations are a drop in a bucket, no one taught Him, as Paul asks; He sits above the circle of the earth, calls the stars by name and never faints, and those who wait on the LORD renew their strength and mount up with wings like eagles"},{"p":"contents","r":"Isaiah 41:1–29","v":"The coastlands are summoned to judgment: the LORD raised one from the east and gave nations before him; Israel is His servant, Jacob His chosen, the seed of Abraham His friend, and need not fear, for He will help them and make the wilderness springs of water; the idols are challenged to declare what is to come and are nothing; the LORD has raised one from the north who will tread princes like clay, and gives Jerusalem one who brings good tidings"},{"p":"contents","r":"Isaiah 42:1–25; Matthew 12:17–21","v":"Behold My Servant, My Elect One, on whom I have put My Spirit: He will bring justice to the Gentiles and not break a bruised reed, words Matthew applies to Jesus; the LORD gives Him as a covenant to the people and a light to the Gentiles to open blind eyes; a new song is to rise from the coastlands, Kedar and Sela, as the LORD goes forth like a man of war; yet His servant Israel is blind and deaf, robbed and plundered because it would not walk in His law"},{"p":"contents","r":"Isaiah 43:1–28","v":"The LORD who formed Israel has redeemed and called it by name, giving Egypt, Ethiopia and Seba for its ransom, and will gather its children from every direction; they are His witnesses that He alone is God and there is no savior besides Him; for their sake He will send to Babylon and bring down the Chaldeans; He will do a new thing, a road in the wilderness, and He blots out their sins for His own sake, though they have wearied Him with their iniquities"},{"p":"contents","r":"Isaiah 44:1–28","v":"The LORD will pour His Spirit on Jacob's offspring, called Jeshurun; He is the First and the Last, and there is no other Rock; the maker of idols cuts down a tree, burns half to bake his bread and falls down before the rest, a deceived heart feeding on ashes; the LORD has blotted out Israel's sins like a cloud, and He who makes all things says of Jerusalem that it will be inhabited and of Cyrus that he is His shepherd, who will say to Jerusalem, You shall be built, and to the temple, Your foundation shall be laid"},{"p":"contents","r":"Isaiah 45:1–25; Romans 14:11; Philippians 2:10–11","v":"The LORD speaks to His anointed, Cyrus, whose right hand He holds: He will go before him, break gates of bronze and give him hidden treasures, calling him by name for Jacob's sake though Cyrus does not know Him; the LORD forms light and creates darkness; woe to him who strives with his Maker; Cyrus will build His city and free His exiles, not for price; Egypt, Cush and the Sabeans will bow to Israel; the LORD did not create the earth in vain, and to Him every knee will bow and every tongue swear, words Paul quotes"},{"p":"contents","r":"Isaiah 46:1–13","v":"Bel bows down and Nebo stoops, their idols loaded on weary beasts and gone into captivity, but the LORD has carried the house of Jacob from birth and will carry them to old age; idols must be carried and cannot answer; the LORD declares the end from the beginning, calls a bird of prey from the east to do His counsel, and will place salvation in Zion"},{"p":"contents","r":"Isaiah 47:1–15; Revelation 18:7–8","v":"The virgin daughter of Babylon is to sit in the dust without a throne and grind meal, no longer called the Lady of Kingdoms, for she showed no mercy to the LORD's people; she said she would never sit as a widow, but loss of children and widowhood will come on her in one day, a picture Revelation takes up, and her astrologers and stargazers, burned like stubble, cannot save her"},{"p":"contents","r":"NKJV notes, note on Isaiah 48:16; Isaiah 48:1–22; Revelation 18:4","v":"The LORD declared the former things long before so that obstinate Israel could not credit its idols; He has refined them in the furnace of affliction for His own name; the one He loves will do His pleasure on Babylon; the Lord GOD and His Spirit have sent the speaker; had Israel heeded, its peace would have been like a river; they are to go forth from Babylon with singing, a call Revelation echoes, for the LORD has redeemed His servant Jacob, but there is no peace for the wicked"},{"p":"contents","r":"Isaiah 49:1–26; Acts 13:47; 2 Corinthians 6:2","v":"The Servant speaks: the LORD called Him from the womb and made His mouth like a sharp sword; it is too small a thing only to restore Israel, so He gives Him as a light to the Gentiles, words Paul and Barnabas take up, and in an acceptable time as a covenant to the people, words Paul quotes; the prisoners go free and the people come from the north, the west and the land of Sinim; Zion says the LORD has forgotten her, but a mother may forget her child and He will not, for she is inscribed on His palms; her children will crowd the land, kings will be her foster fathers, and all flesh will know the LORD as her Savior and the Mighty One of Jacob"},{"p":"contents","r":"Isaiah 50:1–11","v":"Israel's mother was put away for its own transgressions, not by any bill of divorce; the LORD's hand is not shortened; the Servant, given the tongue of the learned, did not turn back but gave His back to those who struck Him and His cheeks to those who plucked the beard, and set His face like a flint, for the Lord GOD helps Him; those who walk in darkness are to trust in the LORD"},{"p":"contents","r":"Isaiah 51:1–23","v":"Those who seek the LORD are to look to Abraham and Sarah; He will make Zion's wilderness like Eden and her desert like the garden of the LORD; His salvation outlasts the heavens; the arm that cut Rahab apart and dried up the sea for the redeemed will bring the ransomed back to Zion with singing; Jerusalem has drunk the cup of His fury, but He takes the cup of trembling from her hand and puts it into the hand of her tormentors"},{"p":"contents","r":"Isaiah 52:1–15; Romans 2:24; 10:15; 15:21; 2 Corinthians 6:17","v":"Zion is to awake and Jerusalem, the holy city, to put on her beautiful garments and shake off the dust, redeemed without money, for the LORD's name is blasphemed, as Paul quotes; how beautiful on the mountains are the feet of him who brings good news, words Paul quotes, and all the ends of the earth will see the LORD's salvation; they are to depart and touch no unclean thing, bearing the vessels of the LORD, a call Paul takes up; then the Servant who will be exalted, His visage marred more than any man's, will sprinkle many nations, and kings will see what they were not told, as Paul quotes"},{"p":"contents","r":"Isaiah 53:1–12; Matthew 8:17; Luke 22:37; John 12:38; Acts 8:32–35; Romans 10:16; 1 Peter 2:22–25","v":"Who has believed the report? The Servant grew up like a root out of dry ground, despised and rejected, a Man of sorrows; He bore our griefs and was wounded for our transgressions, and by His stripes we are healed; all have gone astray like sheep and the LORD laid on Him the iniquity of all; He was led as a lamb to the slaughter and opened not His mouth, cut off for the people's transgression, His grave with the wicked and with the rich; His soul made an offering for sin, He will see His seed, justify many and bear their iniquities, numbered with the transgressors; the Gospels, Acts, Romans and 1 Peter apply these words to Jesus"},{"p":"contents","r":"Isaiah 54:1–17; John 6:45; Galatians 4:27","v":"The barren one is to sing, for the desolate will have more children than the married, words Paul quotes; she is to enlarge her tent, for her Maker is her husband, the LORD of hosts, the God of the whole earth; He forsook her for a moment but will gather her with great mercies, and as He swore after the waters of Noah, so He swears His covenant of peace will not be removed; He will build her with sapphires and rubies, her children will all be taught by the LORD, words Jesus quotes, and no weapon formed against her will prosper"},{"p":"contents","r":"Isaiah 55:1–13; Acts 13:34","v":"Everyone who thirsts is called to come and buy without money; the LORD will make an everlasting covenant, the sure mercies of David, words Paul applies to Jesus raised from the dead; the wicked are to seek the LORD while He may be found, for His thoughts are higher than theirs; as rain waters the earth, His word will not return void, and His people will go out with joy while the trees of the field clap their hands"},{"p":"contents","r":"Isaiah 56:1–12; Matthew 21:13","v":"Blessed is the one who keeps justice and the Sabbath; foreigners and eunuchs who hold fast the covenant will have a name better than sons and daughters in the LORD's house, which will be called a house of prayer for all nations, words Jesus quotes in the temple; but Israel's watchmen are blind, dumb dogs that cannot bark, and greedy shepherds given to strong drink"},{"p":"contents","r":"Isaiah 57:1–21; Ephesians 2:17","v":"The righteous perish and no one considers that they are taken away from evil; the offspring of the sorceress inflame themselves with gods under every green tree, slay their children in the valleys and send their envoys down to Sheol, but whoever trusts in the LORD will possess the land; the High and Lofty One who inhabits eternity dwells with the contrite and humble, and speaks peace to the far and the near, as Paul echoes; there is no peace for the wicked"},{"p":"contents","r":"Isaiah 58:1–14","v":"The prophet is to cry aloud like a trumpet: the people fast, yet exploit their workers and quarrel; the fast the LORD chooses is to loose the bonds of wickedness, free the oppressed, share bread with the hungry and clothe the naked; then their light will break forth like the morning, they will be called the Repairer of the Breach, and if they call the Sabbath a delight they will ride on the heights and feed on the heritage of Jacob"},{"p":"contents","r":"Isaiah 59:1–21; Romans 3:15–17; 11:26–27; Ephesians 6:14–17","v":"The LORD's hand is not too short to save, but Israel's iniquities have separated them from God; their hands are bloodied, they hatch vipers' eggs, and their feet run to evil, words Paul quotes; they grope for the wall like the blind and confess their sins; seeing no justice and no intercessor, the LORD's own arm brought salvation, and He put on righteousness as a breastplate and a helmet of salvation, words Paul takes up; the Redeemer will come to Zion, as Paul quotes, and the LORD's Spirit and words will not depart from His people"},{"p":"contents","r":"Isaiah 60:1–22; Revelation 21:23","v":"Zion is to arise and shine, for her light has come; the Gentiles and kings will come to it, her sons from afar, the camels of Midian and Ephah, gold and incense from Sheba, the flocks of Kedar, the rams of Nebaioth and the ships of Tarshish; foreigners will build her walls, her gates will stand open day and night, the glory of Lebanon will adorn the sanctuary, and she will be called the City of the LORD, Zion of the Holy One of Israel, her walls Salvation and her gates Praise; the LORD will be her everlasting light, as Revelation also pictures"},{"p":"contents","r":"Isaiah 61:1–11; Luke 4:16–21","v":"The Spirit of the Lord GOD is upon the Anointed One to preach good tidings to the poor, heal the brokenhearted, proclaim liberty to the captives and the acceptable year of the LORD, words Jesus read at Nazareth and said were fulfilled that day; the mourners in Zion receive beauty for ashes; they will rebuild the old ruins and be named priests of the LORD, with an everlasting covenant; the prophet rejoices, clothed with the garments of salvation like a bride"},{"p":"contents","r":"NKJV notes, note on Isaiah 62:4; NKJV notes, note on Isaiah 62:12; Isaiah 62:1–12","v":"For Zion's sake the LORD will not rest till her righteousness shines; she will have a new name, no longer Forsaken (Azubah) but Hephzibah, and her land no longer Desolate (Shemamah) but Beulah, for the LORD delights in her; watchmen are set on Jerusalem's walls; the LORD has sworn that foreigners will not eat her grain; the highway is to be built, for her salvation comes, and they will be called the Holy People, the Redeemed of the LORD, and she Sought Out, a City Not Forsaken"},{"p":"contents","r":"Isaiah 63:1–19","v":"One comes from Edom in garments dyed red from Bozrah, mighty to save, who has trodden the winepress alone in His anger, for the day of vengeance and the year of His redeemed have come; the prophet recalls the LORD's lovingkindness, how in all Israel's affliction He was afflicted and the Angel of His Presence saved them, though they rebelled and grieved His Holy Spirit, and how He led them through the sea by the right hand of Moses; You are our Father, though Abraham does not know us, our Redeemer from Everlasting; the adversaries have trodden down the sanctuary"},{"p":"contents","r":"Isaiah 64:1–12; 1 Corinthians 2:9","v":"Oh, that the LORD would rend the heavens and come down; since the world began no eye has seen any God besides Him who acts for those who wait for Him, words Paul echoes; all our righteousnesses are like filthy rags, yet He is our Father, we the clay and He our potter; Zion is a wilderness, Jerusalem a desolation, and the holy and beautiful temple burned with fire"},{"p":"contents","r":"NKJV notes, note on Isaiah 65:11; Isaiah 65:1–25; Romans 10:20–21","v":"The LORD was found by those who did not seek Him and stretched out His hands all day to a rebellious people, words Paul quotes; as new wine is kept in the cluster He will spare His servants, and Sharon and the Valley of Achor will be pasture, but those who set a table for Gad and Meni (pagan gods, by the NKJV notes) will fall by the sword; He will create new heavens and a new earth and make Jerusalem a rejoicing, where no one will die young and they will build and inhabit, and the wolf and the lamb will feed together"},{"p":"contents","r":"NKJV notes, note on Isaiah 66:19; Isaiah 66:1–24; Mark 9:48; Acts 7:48–50","v":"Heaven is the LORD's throne and earth His footstool, words Stephen quotes, and He looks to the contrite who tremble at His word, not to empty sacrifices; Zion gives birth to a nation in one day, and He will extend peace to Jerusalem like a river and comfort His people as a mother does; He will come with fire to judge all flesh, gather all nations to see His glory, and send survivors to Tarshish, Pul, Lud, Tubal and Javan; all flesh will worship before Him, and the transgressors' worm will not die nor their fire be quenched, words Jesus uses"},{"p":"designation","r":"Isaiah 1:1","v":"The vision of Isaiah"},{"p":"feature","r":"Isaiah 1:1","v":"Its visions concern Judah and Jerusalem and were seen in the days of Uzziah, Jotham, Ahaz and Hezekiah, kings of Judah"},{"p":"feature","r":"2 Kings 18:13–20:19; Isaiah 36:1–39:8","v":"Chapters 36–39 tell Hezekiah's deliverance from Sennacherib, his sickness and the envoys from Babylon, much as 2 Kings 18–20 does, adding Hezekiah's writing after his sickness"},{"p":"identified with","r":"2 Chronicles 32:32; Isaiah 1:1; 36:1–39:8","e":"OBJ-00323","b":"inferred","c":"probable","w":"Isaiah 1:1 heads the book 'the vision of Isaiah the son of Amoz', and it tells Hezekiah's deeds (Isaiah 36–39), as 2 Chronicles 32:32 says the vision of Isaiah does."},{"p":"made by","r":"Isaiah 1:1","e":"PER-01125"}],"nm":{"OBJ-00323":"The vision of Isaiah the prophet","PER-01125":"Isaiah"}},"OBJ-00532":{"k":"object","n":"Hezekiah's writing after his sickness","d":"The writing Hezekiah king of Judah made when he had been sick and had recovered (Isaiah 38:9–20)","f":[{"p":"contents","r":"NKJV notes, note on Isaiah 38:11; Isaiah 38:10–20","v":"Hezekiah thought that in the prime of life he would go to the gates of Sheol and never again see YAH in the land of the living, his life cut off like a weaver's thread and broken as by a lion, and he mourned like a dove; but the LORD restored him and lovingly delivered him from the pit, casting all his sins behind His back, for Sheol cannot praise Him, but the living praise Him and fathers make His truth known to their children"},{"p":"designation","r":"Isaiah 38:9","v":"the writing of Hezekiah king of Judah"},{"p":"made by","r":"Isaiah 38:9","e":"PER-01108"},{"p":"occasion","r":"Isaiah 38:9","e":"EVT-01838"},{"p":"purpose","r":"Isaiah 38:20","v":"Songs to be sung with stringed instruments in the house of the LORD all the days of their life"}],"nm":{"EVT-01838":"Hezekiah's illness and recovery","PER-01108":"Hezekiah"}},"OBJ-00533":{"k":"object","n":"The Book of Jeremiah","d":"The words of Jeremiah the son of Hilkiah, of the priests in Anathoth, to whom the word of the LORD came from the thirteenth year of King Josiah (Jeremiah 1–52)","f":[{"p":"contents","r":"Jeremiah 1:1–19","v":"The heading names Jeremiah the son of Hilkiah, of the priests in Anathoth, and the kings in whose days the LORD's word came to him; the LORD tells Jeremiah He knew him before forming him in the womb and appointed him a prophet to the nations, answers his protest that he is only a youth, touches his mouth and sets him over nations and kingdoms; He shows him an almond branch, for He watches over His word, and a boiling pot facing away from the north, for calamity will break out from the north on all the land; and He makes Jeremiah a fortified city against the kings, princes, priests and people of the land"},{"p":"contents","r":"Jeremiah 2:1–37","v":"Jeremiah is sent to cry in Jerusalem's hearing: the LORD remembers Israel's devotion when it followed Him in the wilderness, yet their fathers went after worthless idols, and the priests, rulers and prophets did not seek Him; no nation has changed its gods, but His people exchanged their Glory for what does not profit, forsaking Him, the fountain of living waters, for broken cisterns; the people of Noph and Tahpanhes have struck Israel's head, yet they run to Egypt and Assyria; the noble vine He planted has turned wild, they chase the Baals like a wild donkey in heat and call a tree their father, and they will be ashamed of Egypt as they were of Assyria"},{"p":"contents","r":"Jeremiah 3:1–25","v":"Israel has played the harlot with many lovers and the latter rain has been withheld, yet the LORD bids her return; in Josiah's days He showed Jeremiah that backsliding Israel, put away with a certificate of divorce, was more righteous than her treacherous sister Judah, who turned back only in pretense; Jeremiah is to call toward the north for the backsliding children to return, for the LORD will bring them to Zion and give them shepherds after His heart, the ark of the covenant will no more come to mind, Jerusalem will be called the Throne of the LORD, and Judah and Israel will come together out of the north; the people confess that they have sinned from their youth"},{"p":"contents","r":"Jeremiah 4:1–31","v":"If Israel returns and puts away its abominations it will not be moved, and the nations will bless themselves in the LORD; the men of Judah are to break up their fallow ground and circumcise their hearts; the trumpet is to sound, for the LORD brings disaster from the north: a lion, the destroyer of nations, has set out, with chariots like a whirlwind and horses swifter than eagles; Jeremiah is pained to his very heart at the alarm of war; he beholds the earth without form and void, the mountains trembling and the fruitful land a wilderness, yet the LORD will not make a full end; the daughter of Zion cries out like a woman in labor"},{"p":"contents","r":"Jeremiah 5:1–31","v":"Not one man is found in Jerusalem's streets who does justice and seeks the truth; poor and great alike have broken the yoke, so a lion, a wolf and a leopard will tear them; the LORD will make His words in Jeremiah's mouth fire and the people wood; He will bring a mighty and ancient nation from afar whose language they do not know, yet not make a complete end, and as they served foreign gods in their land they will serve aliens in a land not theirs; the foolish people do not fear Him who set the sand as the bound of the sea; rich men trap men like birds, the prophets prophesy falsely, the priests rule by their own power, and the people love it so"},{"p":"contents","r":"Jeremiah 6:1–30; Matthew 11:29","v":"The children of Benjamin are to flee from Jerusalem, blow the trumpet in Tekoa and raise a signal-fire in Beth Haccerem, for disaster looms from the north; enemies will cut down trees and build a mound against Jerusalem, a city full of oppression; Jeremiah is full of the LORD's fury; from prophet to priest everyone deals falsely, healing the people's hurt lightly with 'Peace, peace' when there is no peace; they are told to ask for the old paths and find rest for their souls, words Jesus echoes, but refuse; their incense from Sheba is not accepted; a cruel people from the north country will come against the daughter of Zion; the LORD sets Jeremiah to test His people, whom He calls rejected silver"},{"p":"contents","r":"Jeremiah 7:1–34; Matthew 21:13; Mark 11:17; Luke 19:46","v":"The LORD sends Jeremiah to stand in the gate of His house and tell all who enter that they must amend their ways, not trusting lying words about the temple of the LORD while they steal, murder, commit adultery and burn incense to Baal; His house has become a den of thieves in their eyes, words Jesus takes up in the temple, and He will do to it as He did to Shiloh; Jeremiah is not to pray for them, for the families make cakes for the queen of heaven; the LORD commanded obedience, not sacrifices, when He brought their fathers out of Egypt; they burn their children in Tophet, so the Valley of the Son of Hinnom will be called the Valley of Slaughter, and the voice of bridegroom and bride will cease"},{"p":"contents","r":"Jeremiah 8:1–22","v":"The bones of Judah's kings, princes, priests, prophets and people will be spread before the sun and moon they worshiped; the stork knows her times but the people do not know the LORD's judgment, the scribes' pen works falsehood, and prophet and priest heal the hurt lightly, saying peace when there is no peace; the snorting of the enemy's horses is heard from Dan; Jeremiah mourns for the hurt of his people: the harvest is past and they are not saved, and he asks whether there is no balm in Gilead and no physician there"},{"p":"contents","r":"Jeremiah 9:1–26; 1 Corinthians 1:31; 2 Corinthians 10:17","v":"Jeremiah wishes his head were waters to weep for the slain of his people, and longs for a lodging in the wilderness to leave them, for they bend their tongues like bows for lies; the LORD will make Jerusalem a heap of ruins and a den of jackals, feed the people wormwood and scatter them among the Gentiles; the wailing women are called to lament, for death has come through the windows; the wise, the mighty and the rich are not to glory in themselves, but he who glories is to glory in knowing the LORD, words Paul quotes; the LORD will punish the circumcised with the uncircumcised: Egypt, Judah, Edom, Ammon and Moab"},{"p":"contents","r":"Jeremiah 10:1–25; Revelation 15:4","v":"Israel is not to learn the way of the Gentiles or fear the signs of heaven, for their idols are trees cut from the forest, decorated with silver from Tarshish and gold from Uphaz, nailed down and carried, unable to speak or walk; none is like the LORD, the King of the nations whom all should fear, as Revelation also sings; He is the true God, the living God and the everlasting King, who made the earth by His power, and the gods who did not make heaven and earth will perish; the Portion of Jacob is the Maker of all things; the inhabitants of the land are to gather up their wares, for a commotion out of the north will make Judah's cities a den of jackals; Jeremiah asks the LORD to correct him with justice"},{"p":"contents","r":"NKJV notes, note on Jeremiah 11:5; Jeremiah 11:1–23","v":"The LORD tells Jeremiah to proclaim the words of the covenant He made when He brought their fathers out of the iron furnace of Egypt: cursed is the man who does not obey them; Jeremiah answers, So be it (Amen, by the NKJV note); a conspiracy is found among the men of Judah and Jerusalem, who have turned back to other gods, so calamity will come that they cannot escape, and the gods to whom they burn incense will not save them; Jeremiah is not to pray for them; the LORD, who once called His beloved a green olive tree, has kindled fire on it; the LORD shows Jeremiah that the men of Anathoth plot against him, and He will punish them"},{"p":"contents","r":"Jeremiah 12:1–17","v":"Jeremiah pleads with the LORD, asking why the way of the wicked prospers when He is near in their mouth but far from their mind; the LORD answers that if the footmen have wearied him, he cannot contend with horses, for even his brothers and his father's house have dealt treacherously with him; the LORD has forsaken His house and given the beloved of His soul into her enemies' hands, for many rulers have destroyed His vineyard; He will pluck the evil neighbors out of their land, then have compassion and bring them back, and if they learn to swear by His name they will be established among His people"},{"p":"contents","r":"NKJV notes, note on Jeremiah 13:4; Jeremiah 13:1–27","v":"Jeremiah gets a linen sash, wears it, hides it in a hole in the rock by the Euphrates (Perath, by the NKJV note), and after many days finds it ruined: so the LORD will ruin the pride of Judah and Jerusalem, whom He had made to cling to Him as a sash clings to a man's waist, though they would not hear; the saying that every bottle will be filled with wine means He will fill the kings, priests, prophets and all Jerusalem with drunkenness and dash them against one another; the king and the queen mother are to humble themselves, for the cities of the South will be shut up and Judah carried away captive; the Ethiopian cannot change his skin nor the leopard its spots, nor can they do good who are used to evil"},{"p":"contents","r":"Jeremiah 14:1–22","v":"The word to Jeremiah concerning the droughts: Judah and Jerusalem mourn, the nobles' servants find the cisterns dry, and the deer and wild donkeys find no grass; the people confess their sins and call on the Hope of Israel, but the LORD will not accept their fasts and offerings and will consume them by sword, famine and pestilence; the prophets promise peace, but they prophesy lies in His name and will themselves be consumed; Jeremiah weeps for the broken virgin daughter of his people, and the people plead not to be abhorred, for no idol can give rain"},{"p":"contents","r":"Jeremiah 15:1–21","v":"Even if Moses and Samuel stood before the LORD, He would not favor the people: some are for death, the sword, famine or captivity, because of what Manasseh did in Jerusalem; Jeremiah mourns that his mother bore him a man of strife whom everyone curses; he ate the LORD's words and they were his joy, yet his pain is perpetual; the LORD answers that if he returns he will be as His mouth, and He will make him a fortified bronze wall to the people, delivering him from the wicked"},{"p":"contents","r":"Jeremiah 16:1–21","v":"Jeremiah is to take no wife and have no sons or daughters in that place, nor enter a house of mourning or of feasting, for the people will die unburied and unmourned and the voices of mirth and of bridegroom and bride will cease; they have done worse than their fathers and will be cast into a land they do not know; yet the LORD will bring Israel back from the land of the north, sending fishermen and hunters for them, and the Gentiles will come to Him from the ends of the earth, owning that their fathers inherited lies"},{"p":"contents","r":"Jeremiah 17:1–27; Revelation 2:23","v":"The sin of Judah is engraved with an iron pen on their heart and on the horns of their altars; cursed is the one who trusts in man, like a shrub in the desert, and blessed is the one who trusts in the LORD, like a tree planted by the waters; the heart is deceitful above all things, and the LORD searches the heart and tests the mind to give each one according to his ways, words repeated in Revelation; Jeremiah prays to be healed and saved while his persecutors mock; he is sent to the gates of Jerusalem to charge the kings and people to hallow the Sabbath day"},{"p":"contents","r":"Jeremiah 18:1–23","v":"The LORD sends Jeremiah down to the potter's house, where a vessel is spoiled in the potter's hand and he makes it into another: as the clay is in the potter's hand, so is the house of Israel in the LORD's; if a nation He has threatened turns from evil He relents of the disaster, and if a nation He has promised to build does evil He relents of the good; He is fashioning a disaster against Judah and calls them to return, but they say it is hopeless and they will follow their own plans; His people have forgotten Him, and their land will be a perpetual hissing; the people plot to attack Jeremiah with the tongue, and he asks the LORD not to forgive those who dug a pit for him"},{"p":"contents","r":"Jeremiah 19:1–15","v":"Jeremiah takes a potter's earthen flask and elders of the people and of the priests to the Valley of the Son of Hinnom by the Potsherd Gate, to proclaim that because the kings and people burned incense to other gods, filled the place with innocent blood and burned their sons to Baal, it will be called the Valley of Slaughter; in the siege they will eat the flesh of their own children; he is to break the flask before the men, for so the LORD will break the people and the city beyond mending; coming back from Tophet, Jeremiah repeats the doom in the court of the LORD's house"},{"p":"contents","r":"Jeremiah 20:1–18","v":"Pashhur the son of Immer, the priest and chief governor in the LORD's house, strikes Jeremiah and puts him in the stocks; released the next day, Jeremiah tells him the LORD calls him Magor-Missabib, Fear on Every Side by the NKJV note, and that he and his house will die captive in Babylon; Jeremiah complains that the LORD persuaded him and that he is mocked all day, yet the LORD's word is like a fire shut up in his bones; the LORD is with him as a mighty, awesome One; he curses the day he was born and asks why he came out of the womb to see labor and sorrow"},{"p":"contents","r":"Jeremiah 21:1–14","v":"When Nebuchadnezzar makes war on Jerusalem, King Zedekiah sends Pashhur the son of Melchiah and Zephaniah the son of Maaseiah, the priest, to ask Jeremiah to inquire of the LORD; the LORD answers that He Himself will fight against the city with pestilence and give Zedekiah and the survivors into Nebuchadnezzar's hand; He sets before the people the way of life and the way of death, for whoever stays in the city will die and whoever goes out to the Chaldeans will live; the city will be burned; the house of David is to execute judgment in the morning, lest His fury burn like fire"},{"p":"contents","r":"Jeremiah 22:1–30","v":"Jeremiah is sent down to the house of the king of Judah: if the king does justice and righteousness, kings on David's throne will still enter its gates, but if not, the house will become a desolation and the nations will ask why the LORD did so to this great city; Shallum the son of Josiah will never return from captivity; woe to the king who builds his house by unrighteousness and pays his workers nothing, unlike his father who judged the cause of the poor: Jehoiakim will be buried with the burial of a donkey, unmourned; Coniah, though he were the signet on the LORD's right hand, will be given into Nebuchadnezzar's hand and cast out with his mother, and is to be written down as childless, for none of his descendants will prosper on David's throne"},{"p":"contents","r":"NKJV notes, note on Jeremiah 23:6; Jeremiah 23:1–40","v":"Woe to the shepherds who scatter the LORD's flock: He will punish them, gather the remnant from all the countries and set up shepherds who will feed them; He will raise to David a Branch of righteousness, a King who will reign and execute judgment, in whose days Judah will be saved, and His name will be THE LORD OUR RIGHTEOUSNESS (YHWH Tsidkenu, by the NKJV note); Jeremiah's heart is broken because of the prophets: prophet and priest are profane, the prophets of Samaria prophesied by Baal, and the prophets of Jerusalem walk in lies and are like Sodom and Gomorrah; they speak visions of their own heart and promise peace to those who despise the LORD; He did not send them, yet they ran; they tell dreams and steal His words from one another, but His word is like a fire and a hammer; the people are no longer to speak of the oracle (burden, by the NKJV note) of the LORD"},{"p":"contents","r":"Jeremiah 24:1–10","v":"After Nebuchadnezzar carried away Jeconiah the son of Jehoiakim with the princes, craftsmen and smiths, the LORD shows Jeremiah two baskets of figs before the temple, one very good and one too bad to eat: the good figs are the captives of Judah sent to the land of the Chaldeans for their good, whom He will bring back, build and plant, and give a heart to know Him; the bad figs are Zedekiah, his princes and those left in the land or living in Egypt, whom He will make a reproach and consume by sword, famine and pestilence"},{"p":"contents","r":"NKJV notes, note on Jeremiah 25:26; Jeremiah 25:1–38","v":"In the fourth year of Jehoiakim, the first year of Nebuchadnezzar, Jeremiah reminds the people that he has spoken the LORD's word to them for twenty-three years, since the thirteenth year of Josiah, and they have not listened; the LORD will bring Nebuchadnezzar His servant against the land and the nations around, and they will serve the king of Babylon seventy years, after which He will punish Babylon; Jeremiah takes the cup of the LORD's fury and makes the nations drink it, from Jerusalem and Pharaoh to the kings of the earth, and last the king of Sheshach, a code word for Babylon by the NKJV note; the LORD will roar from on high and His slain will lie from one end of the earth to the other, and the shepherds will wail"},{"p":"contents","r":"Jeremiah 26:1–24","v":"In the beginning of Jehoiakim's reign Jeremiah warns in the court of the LORD's house that unless the people listen, the house will become like Shiloh; the priests, the prophets and the people seize him, saying he must die, but the princes of Judah, sitting at the New Gate, say he has spoken in the LORD's name, and some of the elders recall that Hezekiah did not kill Micah of Moresheth for a like word; Jehoiakim has Urijah the son of Shemaiah, who prophesied as Jeremiah did, brought back from Egypt and killed; Ahikam the son of Shaphan keeps Jeremiah from being put to death"},{"p":"contents","r":"NKJV notes, note on Jeremiah 27:1; Jeremiah 27:1–22","v":"The LORD tells Jeremiah to make bonds and yokes for his neck and send them to the kings of Edom, Moab, Ammon, Tyre and Sidon by their messengers who came to Zedekiah: the LORD, who made the earth, has given all these lands to Nebuchadnezzar His servant, and the nations will serve him, his son and his grandson; whoever will not bear his yoke will be punished, and whoever serves him will stay in his land; Jeremiah tells Zedekiah and the priests not to listen to the prophets who promise that the vessels of the LORD's house will soon be brought back, for even the pillars, the Sea and the carts left behind will go to Babylon until the day the LORD brings them back; the NKJV text of 27:1 dates the word to the beginning of Jehoiakim's reign, and its note gives Zedekiah from other witnesses"},{"p":"contents","r":"Jeremiah 28:1–17","v":"In the fifth month of Zedekiah's fourth year Hananiah the son of Azur, the prophet from Gibeon, declares in the LORD's house that within two full years the LORD will break the yoke of Babylon and bring back the vessels, Jeconiah and the captives; Jeremiah says Amen, but a prophet of peace is known only when his word comes to pass; Hananiah breaks the yoke from Jeremiah's neck, and the LORD sends Jeremiah to tell him that the wooden yokes have become yokes of iron and that he will die that year for teaching rebellion; Hananiah dies in the seventh month"},{"p":"contents","r":"Jeremiah 29:1–32","v":"Jeremiah sends a letter by Elasah the son of Shaphan and Gemariah the son of Hilkiah to the elders, priests, prophets and people carried captive to Babylon: they are to build houses, plant gardens, marry and seek the peace of the city, and not listen to their prophets, for after seventy years at Babylon the LORD will bring them back, His thoughts toward them being of peace, to give them a future and a hope; those left in Jerusalem will be like rotten figs; Ahab the son of Kolaiah and Zedekiah the son of Maaseiah, who prophesy lies, will be roasted in the fire by the king of Babylon; Shemaiah the Nehelamite writes to Zephaniah the priest to have Jeremiah rebuked, and the LORD says Shemaiah and his descendants will not see the good He will do"},{"p":"contents","r":"NKJV notes, note on Jeremiah 30:18; Jeremiah 30:1–24","v":"The LORD tells Jeremiah to write in a book all the words He has spoken to him, for He will bring Israel and Judah back from captivity to their fathers' land; there is a voice of trembling, the time of Jacob's trouble, but he will be saved out of it, the yoke will be broken, and they will serve the LORD and David their king; Jacob is not to fear, for the LORD will correct him in justice but not make a full end of him; Zion's wound is incurable, yet the LORD will heal it, and the city will be rebuilt on its mound (ruins, by the NKJV note), with a ruler from among them"},{"p":"contents","r":"Jeremiah 31:1–40; Matthew 2:16–18; Hebrews 8:8–12; 10:16–17","v":"The LORD has loved Israel with an everlasting love and will build her again, with vines on the mountains of Samaria and watchmen on Mount Ephraim calling the people up to Zion; He will bring a great throng from the north country, for He is a Father to Israel and Ephraim is His firstborn; Rachel weeps in Ramah for her children, as Matthew says was fulfilled when Herod killed the children of Bethlehem, but they will come back; He will have mercy on Ephraim, and Jeremiah awakes from a sweet sleep; each will die for his own sin; He will make a new covenant, putting His law in their minds and writing it on their hearts, as Hebrews quotes it; Israel will not cease while sun and moon endure, and the city will be built for the LORD from the Tower of Hananel to the Corner Gate"},{"p":"contents","r":"Jeremiah 32:1–44","v":"In Zedekiah's tenth year, the eighteenth of Nebuchadnezzar, with Babylon's army besieging Jerusalem, Jeremiah is shut up in the court of the prison, for Zedekiah objected to his word that the city would fall and the king be taken to Babylon; at the LORD's word Jeremiah buys the field of Hanamel his uncle's son at Anathoth for seventeen shekels of silver, has the deed signed, sealed and witnessed, and gives the sealed and open deeds to Baruch the son of Neriah to keep in an earthen vessel, for houses and fields will again be bought; he prays to the Great and Mighty God, for whom nothing is too hard; the LORD answers that the Chaldeans will burn the city for its idolatry, but He will gather His people again and make an everlasting covenant with them"},{"p":"contents","r":"NKJV notes, note on Jeremiah 33:16; Jeremiah 33:1–26","v":"While Jeremiah is still shut up, the LORD tells him to call to Him: the houses pulled down against the siege mounds will be filled with the dead, but He will heal the city, bring back the captives of Judah and Israel and pardon them, and the voices of joy, of bridegroom and bride and of thanksgiving will again be heard; He will cause a Branch of righteousness to grow up to David, and Jerusalem will be called THE LORD OUR RIGHTEOUSNESS (YHWH Tsidkenu, by the NKJV note); David will never lack a man on the throne nor the Levites a man to offer, as surely as His covenant with day and night stands"},{"p":"contents","r":"Jeremiah 34:1–22","v":"While Nebuchadnezzar's army fights against Jerusalem and the last fortified cities, Lachish and Azekah, Jeremiah tells Zedekiah that the city will be burned and he will see the king of Babylon face to face and go to Babylon, yet die in peace and be mourned; Zedekiah makes a covenant with the people to free their Hebrew slaves, and they obey, but afterward take them back; the LORD recalls His law of release after six years, and because they cut the calf in two and broke the covenant, He proclaims to them a liberty to sword, pestilence and famine, and will bring back Babylon's army, which has withdrawn, to take and burn the city"},{"p":"contents","r":"Jeremiah 35:1–19","v":"In the days of Jehoiakim the LORD sends Jeremiah to bring the Rechabites into a chamber of His house and offer them wine; Jaazaniah and his brothers refuse, for Jonadab the son of Rechab commanded them to drink no wine, build no house, sow no seed and plant no vineyard, but to live in tents; they came to Jerusalem only for fear of the Chaldeans and Syrians; the LORD contrasts their obedience with Judah's refusal to hear Him, and promises that Jonadab will never lack a man to stand before Him"},{"p":"contents","r":"NKJV notes, note on Jeremiah 36:4; Jeremiah 36:1–32","v":"In Jehoiakim's fourth year the LORD tells Jeremiah to write on a scroll all His words since the days of Josiah, that Judah might turn and be forgiven; Baruch writes them from Jeremiah's mouth, by the NKJV note, and reads them in the LORD's house at the fast of the ninth month of the fifth year; the princes hear the scroll, tell Baruch and Jeremiah to hide, and report to the king; in the winter house Jehoiakim cuts the scroll with the scribe's knife column by column and burns it on the hearth, unafraid, and orders Baruch and Jeremiah seized, but the LORD hides them; the LORD says Jehoiakim will have no one on David's throne and his body will be thrown out, and Baruch writes the words again on another scroll with many like words added"},{"p":"contents","r":"Jeremiah 37:1–21","v":"Zedekiah, made king by Nebuchadnezzar instead of Coniah, does not heed the LORD's words, yet sends Jehucal and Zephaniah to ask Jeremiah to pray; when Pharaoh's army comes up the Chaldeans withdraw, but the LORD says they will come back and burn the city; going out to the land of Benjamin, Jeremiah is seized at the Gate of Benjamin as a deserter, beaten by the princes and imprisoned in Jonathan the scribe's house; Zedekiah asks him secretly for a word and hears that he will be given to the king of Babylon, and at Jeremiah's plea commits him to the court of the prison with a daily piece of bread from the bakers' street"},{"p":"contents","r":"NKJV notes, note on Jeremiah 38:6; Jeremiah 38:1–28","v":"For saying that whoever stays in the city will die and whoever goes out to the Chaldeans will live, the princes have Jeremiah put into the miry dungeon of Malchiah the king's son, with the king's consent; Ebed-Melech the Ethiopian pleads for him and with thirty men draws him up with ropes and old rags; Zedekiah meets him secretly at the third entrance of the LORD's house and swears not to kill him, and Jeremiah tells him that if he surrenders he and the city will be spared, but if not, his wives and children will be taken and the city burned; Jeremiah keeps the talk from the princes and stays in the court of the prison until Jerusalem is taken"},{"p":"contents","r":"NKJV notes, note on Jeremiah 39:3; Jeremiah 39:1–18","v":"In Zedekiah's ninth year, tenth month, Nebuchadnezzar besieges Jerusalem, and in the eleventh year, fourth month, ninth day, the city is broken into; the princes of the king of Babylon sit in the Middle Gate, among them Rabsaris and Rabmag, titles by the NKJV note; Zedekiah flees by night, is overtaken in the plains of Jericho and judged at Riblah, where his sons and the nobles of Judah are killed and he is blinded and bound; the Chaldeans burn the houses and break down the walls, and Nebuzaradan carries the people away, leaving the poor with vineyards and fields; at Nebuchadnezzar's charge Jeremiah is taken from the court of the prison and committed to Gedaliah; the LORD promises Ebed-Melech that his life will be spared because he trusted in Him"},{"p":"contents","r":"Jeremiah 40:1–16","v":"Nebuzaradan, finding Jeremiah bound among the captives at Ramah, tells him the LORD has done as He said, frees him and lets him choose to go to Babylon or stay, and Jeremiah goes to Gedaliah at Mizpah; the captains and their men come to Gedaliah, who swears it will be well if they serve the king of Babylon, and the Jews scattered in Moab, Ammon, Edom and other lands return and gather wine and summer fruit; Johanan warns Gedaliah that Baalis king of the Ammonites has sent Ishmael to kill him and offers to kill Ishmael, but Gedaliah does not believe him"},{"p":"contents","r":"NKJV notes, note on Jeremiah 41:7; Jeremiah 41:1–18","v":"In the seventh month Ishmael the son of Nethaniah, of the royal family, eats with Gedaliah at Mizpah and kills him with the Jews and Chaldeans there; on the second day he lures eighty mourning men from Shechem, Shiloh and Samaria into the city, kills them and fills with them the pit (or cistern, by the NKJV note) that Asa made, sparing ten who promise stores of wheat, barley, oil and honey; he carries off the king's daughters and the people toward the Ammonites, but Johanan overtakes him at the great pool in Gibeon, the captives return, and Ishmael escapes with eight men; fearing the Chaldeans, Johanan's company stops at the habitation of Chimham near Bethlehem on the way to Egypt"},{"p":"contents","r":"NKJV notes, note on Jeremiah 42:20; Jeremiah 42:1–22","v":"The captains and all the people ask Jeremiah to pray for the remnant and swear to obey whatever the LORD answers; after ten days He answers that if they stay in the land He will build and plant them and deliver them from the king of Babylon, but if they go to Egypt the sword and famine they fear will overtake them there and none will escape; Jeremiah tells them they deceived themselves when they sent him, and will die in the place where they want to go"},{"p":"contents","r":"NKJV notes, note on Jeremiah 43:13; Jeremiah 43:1–13","v":"Azariah the son of Hoshaiah, Johanan and all the proud men tell Jeremiah he speaks falsely and that Baruch has set him against them; Johanan and the captains take the whole remnant, the king's daughters, Jeremiah and Baruch to Egypt, as far as Tahpanhes; there Jeremiah hides large stones in the brick courtyard at the entrance to Pharaoh's house, for the LORD will bring Nebuchadnezzar to set his throne over them, strike Egypt, burn the houses of its gods and break the sacred pillars of Beth Shemesh, the House of the Sun, ancient On, by the NKJV note"},{"p":"contents","r":"NKJV notes, note on Jeremiah 44:1; Jeremiah 44:1–30","v":"The word to all the Jews living in Egypt, at Migdol, Tahpanhes, Noph (ancient Memphis, by the NKJV note) and Pathros: they have seen the desolation of Judah, yet burn incense to other gods, and the remnant who went to Egypt will be consumed there, only a few escaping back; the men and women answer that they will keep burning incense to the queen of heaven, for they prospered when they did; the LORD swears that His name will no more be named by any man of Judah in Egypt, and as a sign He will give Pharaoh Hophra into the hand of his enemies, as He gave Zedekiah to Nebuchadnezzar"},{"p":"contents","r":"NKJV notes, note on Jeremiah 45:1; Jeremiah 45:1–5","v":"In the fourth year of Jehoiakim, when Baruch had written Jeremiah's words in a book, Jeremiah tells him that the LORD has heard his complaint that grief is added to his sorrow: Baruch is not to seek great things for himself, for the LORD will break down what He built, but He will give Baruch his life as a prize wherever he goes"},{"p":"contents","r":"NKJV notes, note on Jeremiah 46:25; Jeremiah 46:1–28","v":"The words against the nations begin with Egypt: concerning Pharaoh Necho's army by the Euphrates at Carchemish, which Nebuchadnezzar defeated in Jehoiakim's fourth year, the horsemen and the Ethiopians, Libyans and Lydians (Cush and Put, by the NKJV notes) flee, for the LORD has a sacrifice in the north country, and Egypt will find no cure in Gilead's balm; Nebuchadnezzar will come and strike Egypt, Noph will be desolate, and the LORD will punish Amon of No (a sun god and ancient Thebes, by the NKJV notes), Pharaoh and Egypt's gods, though afterward Egypt will be inhabited as of old; Jacob is not to fear, for he will be saved from afar"},{"p":"contents","r":"NKJV notes, note on Jeremiah 47:4; Jeremiah 47:1–7","v":"Against the Philistines, before Pharaoh attacked Gaza: waters rise out of the north and flood the land, fathers flee without their children, and the LORD will plunder the Philistines, the remnant of Caphtor (Crete, by the NKJV note), cutting off every helper of Tyre and Sidon; Gaza is shaved bald and Ashkelon cut off, for the LORD has charged His sword against Ashkelon and the seashore"},{"p":"contents","r":"NKJV notes, note on Jeremiah 48:1; Jeremiah 48:1–20","v":"Against Moab: woe to Nebo and Kirjathaim and the high stronghold (Misgab, by the NKJV note); in Heshbon they plot to cut Moab off, Madmen will be cut down, and a cry rises from Horonaim and the Ascent of Luhith; because Moab trusted in its works and treasures, Chemosh will go into captivity with his priests and princes; Moab, at ease from his youth and settled on his dregs, will be poured out and be ashamed of Chemosh as Israel was ashamed of Bethel; Dibon, Aroer and the Arnon will hear that Moab is plundered"},{"p":"contents","r":"Jeremiah 48:21–47","v":"Judgment comes on the cities of the plain country, from Holon to Bozrah, and the horn of Moab is cut off; Moab will wallow in his vomit for exalting himself against the LORD and mocking Israel, for his pride is great; the LORD wails for Moab and the men of Kir Heres, weeps for the vine of Sibmah with the weeping of Jazer, and ends the joy of the vintage; one will fly like an eagle over Moab, Kerioth will be taken, fear, the pit and the snare will come, and fire will go out of Heshbon; yet the LORD will bring back the captives of Moab in the latter days"},{"p":"contents","r":"NKJV notes, note on Jeremiah 49:1; Jeremiah 49:1–22","v":"Against the Ammonites: Milcom (Malcam, an Ammonite god, by the NKJV note) has taken Gad's inheritance, but an alarm of war will sound in Rabbah, which will become a desolate mound, and Milcom will go into captivity; afterward the LORD will bring back Ammon's captives; against Edom: wisdom has gone from Teman, the calamity of Esau will come, Bozrah will be a desolation, and Edom, nesting high in the clefts of the rock, will be brought down and left empty like Sodom and Gomorrah, its fall heard at the Red Sea"},{"p":"contents","r":"Jeremiah 49:23–39","v":"Against Damascus: Hamath and Arpad are shamed, Damascus grows feeble, and fire will consume the palaces of Ben-Hadad; against Kedar and the kingdoms of Hazor, which Nebuchadnezzar will strike: their tents, flocks and camels will be taken from the nation that dwells securely without gates, and Hazor will be a haunt of jackals; against Elam, in the beginning of Zedekiah's reign: the LORD will break Elam's bow, scatter its people to the four winds and set His throne there, but will bring back its captives in the latter days"},{"p":"contents","r":"NKJV notes, note on Jeremiah 50:2; Jeremiah 50:1–46","v":"The word against Babylon and the land of the Chaldeans: Babylon is taken, Bel shamed and Merodach (Marduk, by the NKJV note) broken, by a nation from the north; Israel and Judah will come weeping to seek the LORD and join Him in a perpetual covenant; His people, lost sheep devoured first by Assyria and then by Nebuchadnezzar, will be brought back and pardoned; Merathaim and Pekod will be destroyed and the hammer of the whole earth broken, for Babylon was proud against the Holy One of Israel; their Redeemer is strong, and a sword and a drought will come on Babylon until wild beasts dwell there as in Sodom and Gomorrah"},{"p":"contents","r":"NKJV notes, note on Jeremiah 51:1; Jeremiah 51:1–64; Revelation 18:4, 21","v":"A destroying wind comes against Babylon and Leb Kamai (a code word for Chaldea, by the NKJV note); Babylon, a golden cup in the LORD's hand that made the earth drunk, has suddenly fallen; the LORD has stirred up the kings of the Medes for the vengeance of His temple, and calls Ararat, Minni and Ashkenaz against her; the destroying mountain will be a burnt mountain, Sheshach taken, Bel punished and the wall of Babylon fallen; His people are to go out of her, words echoed in Revelation; in Zedekiah's fourth year Jeremiah writes the evil to come on Babylon in a book for Seraiah to read there and sink in the Euphrates, as Revelation pictures Babylon thrown down; thus far are the words of Jeremiah"},{"p":"contents","r":"NKJV notes, note on Jeremiah 52:31; Jeremiah 52:1–34","v":"The fall of Jerusalem reviewed: Zedekiah reigns eleven years, does evil and rebels; the city is besieged from his ninth year until famine in the eleventh, the wall is broken through and he flees, is judged at Riblah, sees his sons and the princes of Judah killed, and is blinded and imprisoned in Babylon until he dies; in Nebuchadnezzar's nineteenth year Nebuzaradan burns the LORD's house and the city, breaks down the walls, carries away the people and the bronze of the pillars, carts and Sea, and takes the chief priests and leaders to be killed at Riblah; the three deportations number 4,600; in the thirty-seventh year of Jehoiachin's captivity Evil-Merodach (Awil-Marduk, by the NKJV note) brings him out of prison and provides for him all his days"},{"p":"designation","r":"Jeremiah 1:1","v":"The words of Jeremiah"},{"p":"feature","r":"Jeremiah 1:1–3","v":"Its heading dates the word of the LORD to Jeremiah from Josiah's thirteenth year, through Jehoiakim's reign, to the end of Zedekiah's eleventh year, when Jerusalem was carried away captive in the fifth month"},{"p":"made by","r":"Jeremiah 1:1; 30:2","e":"PER-02205"}],"nm":{"PER-02205":"Jeremiah"}},"OBJ-00534":{"k":"object","n":"Jeremiah's letter to the captives","d":"The letter Jeremiah sent from Jerusalem to the elders, priests, prophets and people carried captive to Babylon (Jeremiah 29:1–23)","f":[{"p":"contents","r":"Jeremiah 29:4–23","v":"The LORD tells the captives to build houses, plant gardens, marry and have children, and seek the peace of the city where they are captive; not to be deceived by their prophets and diviners; that after seventy years at Babylon He will bring them back; that the king on David's throne and the people left in Jerusalem will meet sword, famine and pestilence; and that Ahab and Zedekiah, who prophesy lies, will be slain by the king of Babylon"},{"p":"designation","r":"Jeremiah 29:1","v":"the letter that Jeremiah the prophet sent"},{"p":"made by","r":"Jeremiah 29:1","e":"PER-02205"},{"p":"occasion","r":"Jeremiah 29:1–3","e":"EVT-02380"}],"nm":{"EVT-02380":"Jeremiah sends a letter to the captives in Babylon","PER-02205":"Jeremiah"}},"OBJ-00535":{"k":"object","n":"The deeds of the field at Anathoth","d":"The purchase deeds of Jeremiah's field at Anathoth, one sealed and one open, put in an earthen vessel to last many days (Jeremiah 32:10–14)","f":[{"p":"contents","r":"Jeremiah 32:10–12","v":"The deed of purchase, one copy sealed according to the law and custom and one open, signed by Jeremiah and the witnesses"},{"p":"designation","r":"NKJV notes, note on Jeremiah 32:10; Jeremiah 32:11–12, 14, 16","v":"the purchase deed"},{"p":"made by","r":"Jeremiah 32:10–11","e":"PER-02205"},{"p":"purpose","r":"Jeremiah 32:14–15","v":"Kept in an earthen vessel to last many days, as a sign that houses, fields and vineyards would again be possessed in the land"}],"nm":{"PER-02205":"Jeremiah"}},"OBJ-00536":{"k":"object","n":"The scroll Jehoiakim burned","d":"The scroll on which Baruch wrote from Jeremiah's mouth all the words the LORD had spoken to him, which King Jehoiakim cut up and burned (Jeremiah 36:2–23)","f":[{"p":"contents","r":"Jeremiah 36:2","v":"All the words the LORD had spoken to Jeremiah against Israel, Judah and all the nations, from the days of Josiah to the fourth year of Jehoiakim"},{"p":"designation","r":"Jeremiah 36:2, 4","v":"a scroll of a book"},{"p":"made by","r":"NKJV notes, note on Jeremiah 36:4; Jeremiah 36:4, 18","e":"PER-02891"},{"p":"made by","r":"Jeremiah 36:4, 18","e":"PER-02205"},{"p":"occasion","r":"Jeremiah 36:1–4","e":"EVT-02394"}],"nm":{"EVT-02394":"Jeremiah has Baruch write the LORD's words on a scroll","PER-02205":"Jeremiah","PER-02891":"Baruch"}},"OBJ-00537":{"k":"object","n":"The second scroll of Jeremiah's words","d":"The scroll on which Baruch wrote again from Jeremiah's mouth all the words of the burned scroll, with many like words added (Jeremiah 36:28, 32)","f":[{"p":"contents","r":"Jeremiah 36:32","v":"All the words of the scroll Jehoiakim burned, and many similar words besides"},{"p":"designation","r":"Jeremiah 36:28, 32","v":"another scroll"},{"p":"made by","r":"NKJV notes, note on Jeremiah 36:32; Jeremiah 36:32","e":"PER-02891"},{"p":"made by","r":"Jeremiah 36:32","e":"PER-02205"},{"p":"occasion","r":"Jeremiah 36:27–28, 32","e":"EVT-02399"}],"nm":{"EVT-02399":"Jeremiah has the scroll written again","PER-02205":"Jeremiah","PER-02891":"Baruch"}},"OBJ-00538":{"k":"object","n":"The stones Jeremiah hid at Tahpanhes","d":"The large stones Jeremiah hid in the clay of the brick courtyard at Pharaoh's house in Tahpanhes, over which Nebuchadnezzar would set his throne (Jeremiah 43:9–10)","f":[{"p":"designation","r":"Jeremiah 43:9","v":"large stones"},{"p":"placed at","r":"NKJV notes, note on Jeremiah 43:9; Jeremiah 43:9","e":"PLC-01326"},{"p":"purpose","r":"Jeremiah 43:10","v":"A sign that Nebuchadnezzar would set his throne and spread his royal pavilion over them"}],"nm":{"PLC-01326":"The brick courtyard at Pharaoh's house in Tahpanhes"}},"OBJ-00539":{"k":"object","n":"The book of the evil to come on Babylon","d":"The book in which Jeremiah wrote all the evil that would come on Babylon, which Seraiah was to read in Babylon and throw into the Euphrates with a stone tied to it (Jeremiah 51:60–64)","f":[{"p":"contents","r":"Jeremiah 51:60","v":"All the evil that would come on Babylon, all the words written against Babylon"},{"p":"designation","r":"Jeremiah 51:60, 63","v":"a book"},{"p":"made by","r":"Jeremiah 51:60","e":"PER-02205"},{"p":"occasion","r":"Jeremiah 51:59–60","e":"EVT-02441"},{"p":"purpose","r":"Jeremiah 51:61–64","v":"To be read in Babylon, then tied to a stone and thrown into the Euphrates, as a sign that Babylon would sink and not rise"}],"nm":{"EVT-02441":"Jeremiah charges Seraiah to sink the book in the Euphrates","PER-02205":"Jeremiah"}},"OBJ-00540":{"k":"object","n":"The Book of Lamentations","d":"Five poems mourning the destruction of Jerusalem and the captivity of Judah, the last a prayer that the LORD would turn His people back to Himself (Lamentations 1–5)","f":[{"p":"contents","r":"NKJV notes, note on Lamentations 1:1; Lamentations 1:1–22","v":"Jerusalem, once crowded and great among nations, sits deserted like a widow and serves as a slave (a forced laborer, by the NKJV note); Judah has gone into captivity among the nations, the roads to Zion mourn with none coming to the feasts, her friends have turned enemies and her adversaries prosper, for the LORD afflicted her for her many transgressions; the nations have entered her sanctuary and her people trade their treasures for food; the city asks all who pass by whether any sorrow is like the one the LORD has brought on her, owns that He is righteous and she rebelled, and asks Him to deal with her enemies as He has dealt with her"},{"p":"contents","r":"Lamentations 2:1–22","v":"In His anger the Lord has darkened the daughter of Zion as with a cloud, devoured every dwelling of Jacob without pity, thrown down Judah's strongholds and profaned its kingdom and princes; He spurned His altar and sanctuary, let the feasts and Sabbaths be forgotten in Zion and gave the walls of her palaces to the enemy, who shouted in His house as at a feast; He purposed to destroy Zion's wall, her gates sank into the ground, her king and princes are among the nations, the Law is no more and her prophets receive no vision; the elders sit silent in sackcloth on the ground while children faint with hunger in the streets; her prophets saw only false visions for her, those passing by mock the city once called the perfection of beauty, and her enemies gloat; the LORD has done what He purposed, fulfilling His word of old; the wall of Zion is bidden to weep day and night and lift its hands to Him for the children, and the city asks whether women should eat their own offspring and priest and prophet be slain in the LORD's sanctuary"},{"p":"contents","r":"Lamentations 3:1–66","v":"A man afflicted under the rod of the LORD's wrath tells how He led him into darkness, wore out his flesh, walled him in, shut out his prayer, made him a target for His arrows and the taunt of his people, and filled him with bitterness; yet he takes hope, for the LORD's mercies keep them from being consumed and are new each morning, His faithfulness is great, and it is good to wait quietly for His salvation, since He will not cast off forever nor afflict willingly; the people are urged to search their ways and turn back to the LORD, and they confess that they have sinned and He has not pardoned; the man tells how enemies hunted him like a bird and silenced him in a pit, how he called on the LORD's name from the lowest pit and the LORD drew near and told him not to fear, and he asks the LORD to repay his enemies"},{"p":"contents","r":"NKJV notes, note on Lamentations 4:7; Lamentations 4:1–22","v":"The gold has grown dim: Zion's precious sons are counted as clay pots, infants thirst and the young beg bread, those raised in luxury lie on ash heaps, and the daughter of my people bears a punishment greater than Sodom's, which was overthrown in a moment; her Nazirites (or nobles, by the NKJV note), once brighter than snow, are blackened past recognition, those killed by the sword fare better than those who starve, and compassionate women have cooked their own children; the LORD poured out His anger and kindled a fire in Zion that consumed its foundations, though the kings of the earth would not have believed an enemy could enter Jerusalem's gates, for the sins of her prophets and priests who shed the blood of the just; the people watched in vain for a nation that could not save them, their pursuers ran them down on the mountains and in the wilderness, and the LORD's anointed, under whose shadow they hoped to live, was caught in their pits; the daughter of Edom, dwelling in the land of Uz, is told that the cup will reach her too, while Zion's punishment is complete and she will be sent into captivity no more"},{"p":"contents","r":"Lamentations 5:1–22","v":"The people pray the LORD to remember their disgrace: their inheritance has gone to strangers and their houses to foreigners, they are fatherless and their mothers like widows, they pay for their water and wood, they gave their hand to Egypt and Assyria for bread, and they bear the iniquities of fathers who sinned and are gone; servants rule them, women were violated in Zion and in Judah's cities, princes were hung up by their hands, young men ground at the mill and boys stumbled under wood, the elders have left the gate, their dancing has turned to mourning and they have lost their crown, and Mount Zion lies desolate with foxes roaming it; yet the LORD reigns forever, and they ask Him to turn them back to Himself and make their days new as in former times, unless He has utterly rejected them"},{"p":"designation","r":"Lamentations 1:1","v":"How lonely sits the city"},{"p":"feature","r":"Lamentations 1:1; 2:1; 4:1","v":"Its five poems mourn Jerusalem, and three of them open with the cry 'How' over the deserted city, the LORD's anger and the dimmed gold"},{"p":"feature","r":"Lamentations 1:12–22","v":"In its first poem the city itself speaks, asking all who pass by whether any sorrow is like the one the LORD has brought on her"},{"p":"feature","r":"Lamentations 3:1, 21–24","v":"Its third poem is spoken by a man afflicted under the rod of the LORD's wrath, who turns from his complaint to hope in the LORD's mercies"},{"p":"feature","r":"Lamentations 5:1, 21","v":"Its last poem is the people's prayer that the LORD would remember their disgrace and turn them back to Himself"},{"p":"occasion","r":"2 Kings 25:1–21; Lamentations 1:3; 2:8–9; 4:11–12","e":"EVT-01899","b":"inferred","c":"probable","w":"Lamentations does not name the event, but it mourns Jerusalem after the enemy entered its gates and a fire devoured Zion (Lamentations 4:11–12), after its wall was destroyed and its king and princes were taken among the nations (2:8–9), and after Judah went into captivity (1:3); 2 Kings 25:1–21 tells how Jerusalem fell to Nebuchadnezzar's army, its walls broken down, the city burned and its people carried away."}],"nm":{"EVT-01899":"The fall of Jerusalem"}},"OBJ-00541":{"k":"object","n":"The Book of Ezekiel","d":"The visions and words of the LORD that came to Ezekiel the priest, the son of Buzi, among the captives by the River Chebar, from the fifth year of King Jehoiachin's captivity (Ezekiel 1–48)","f":[{"p":"contents","r":"NKJV notes, note on Ezekiel 1:22; Ezekiel 1:1–28; Revelation 4:6–8","v":"In the thirtieth year, on the fifth day of the fourth month, the fifth year of King Jehoiachin's captivity, the heavens open to Ezekiel the priest, the son of Buzi, among the captives by the River Chebar: out of a whirlwind from the north, in a great cloud of fire and brightness, come four living creatures, each with four faces, of a man, a lion, an ox and an eagle, and four wings, going straight ahead wherever the spirit went, with a wheel within a wheel beside each and rims full of eyes; over their heads is a firmament (or expanse, by the NKJV note) like awesome crystal, and above it a throne like sapphire with a likeness like a man, surrounded by fire and brightness like a rainbow, the appearance of the LORD's glory, before which Ezekiel falls on his face; Revelation 4:6–8 likewise sees four living creatures like a lion, a calf, a man and a flying eagle"},{"p":"contents","r":"Ezekiel 2:1–10","v":"The LORD sets Ezekiel on his feet by the Spirit and sends him, son of man, to the children of Israel, a rebellious nation as impudent and stubborn as their fathers, to tell them what the Lord GOD says, whether they hear or refuse, so that they will know a prophet has been among them; he is not to fear them, though he dwells among briers, thorns and scorpions, nor to be rebellious himself, but to eat what he is given, and a hand holds out a scroll written inside and out with lamentations, mourning and woe"},{"p":"contents","r":"NKJV notes, note on Ezekiel 3:14; Ezekiel 3:1–27; Revelation 10:9–10","v":"Ezekiel eats the scroll, sweet as honey in his mouth, as John's little book is in Revelation 10:9–10, and is sent to the house of Israel, who will not listen to him because they will not listen to the LORD; the LORD makes his forehead harder than flint; the Spirit lifts him up, the wings of the living creatures and the wheels thunder behind him, and he goes in bitterness to the captives at Tel Abib by the River Chebar and sits astonished among them seven days; then the LORD makes him a watchman for the house of Israel, who must warn the wicked and the righteous or answer for their blood; in the plain he sees the glory of the LORD again and is told to shut himself in his house, where he will be bound and mute until the LORD opens his mouth to speak His words"},{"p":"contents","r":"NKJV notes, note on Ezekiel 4:14; Ezekiel 4:1–17","v":"Ezekiel is to portray Jerusalem on a clay tablet and lay siege to it with a siege wall, a mound, camps and battering rams, with an iron plate between him and the city, as a sign to the house of Israel; to lie on his left side three hundred and ninety days bearing the iniquity of the house of Israel and on his right side forty days for the house of Judah, a day for each year; and to eat bread of mixed grain by weight and drink water by measure, baked over human waste, for so the children of Israel will eat defiled bread among the Gentiles; when he protests that he has never eaten unclean flesh, he may use cow dung instead; Jerusalem's bread and water will fail"},{"p":"contents","r":"Ezekiel 5:1–17","v":"Ezekiel is to shave his head and beard with a sharp sword, weigh the hair and divide it in three, burning a third in the city, striking a third with the sword and scattering a third to the wind, keeping a few hairs in his garment's edge; for Jerusalem, set among the nations, has rebelled against the LORD's judgments more than they, and defiled His sanctuary, so He will do in her what He has never done: fathers will eat their sons, a third will die of pestilence and famine, a third fall by the sword and a third be scattered to the winds, and she will be a reproach and a lesson to the nations"},{"p":"contents","r":"NKJV notes, note on Ezekiel 6:3; Ezekiel 6:1–14","v":"Ezekiel is to prophesy against the mountains of Israel: the LORD will bring a sword on them, destroy their high places (places for pagan worship, by the NKJV note), lay the slain before their idols and scatter their bones around their altars; yet a remnant who escape among the nations will remember Him and loathe themselves for their abominations; he is to strike his hands and stamp his feet over the house of Israel, which will fall by sword, famine and pestilence, and the land will be made more desolate than the wilderness toward Diblah"},{"p":"contents","r":"Ezekiel 7:1–27","v":"The end has come on the four corners of the land of Israel: the LORD will judge it by its ways without pity; the sword is outside and pestilence and famine within, survivors will mourn on the mountains like doves, their silver and gold will not deliver them in the day of the LORD's wrath, the ornaments they made into idols will be plunder for strangers, robbers will defile His secret place, the worst of the Gentiles will possess their houses, and they will seek a vision from a prophet in vain while the king mourns"},{"p":"contents","r":"NKJV notes, note on Ezekiel 8:14; Ezekiel 8:1–18","v":"In the sixth year, on the fifth day of the sixth month, as Ezekiel sits in his house with the elders of Judah, a likeness of fire and amber takes him by a lock of hair and the Spirit brings him in visions of God to Jerusalem: at the north gate of the inner court stands the image of jealousy; through a hole dug in the court's wall seventy elders of the house of Israel, Jaazaniah the son of Shaphan among them, offer incense in the dark before creeping things and idols portrayed on the walls, saying the LORD does not see; at the north gate of the LORD's house women weep for Tammuz (a Sumerian fertility god like Adonis, by the NKJV note); and between the porch and the altar about twenty-five men turn their backs to the temple and worship the sun, so the LORD will act in fury without pity"},{"p":"contents","r":"Ezekiel 9:1–11","v":"At the LORD's call six men with battle-axes come from the upper gate facing north, and a man clothed with linen, with a writer's inkhorn, marks the foreheads of those who sigh and cry over Jerusalem's abominations; the others go through the city killing all without the mark, beginning at the sanctuary with the elders; Ezekiel, left alone, cries out whether the LORD will destroy all the remnant of Israel, and He answers that the iniquity of Israel and Judah is exceedingly great and the land full of bloodshed"},{"p":"contents","r":"Ezekiel 10:1–22","v":"Above the cherubim appears a throne like sapphire; the man clothed with linen is sent in among the wheels for coals of fire from among the cherubim, to scatter over the city; the glory of the LORD rises from the cherub to the threshold of the temple and fills the court with brightness, then departs and stands over the cherubim at the door of the East Gate; Ezekiel knows them now as the living creatures he saw by the River Chebar, with four faces and four wings and the wheels beside them"},{"p":"contents","r":"Ezekiel 11:1–25","v":"At the East Gate twenty-five men, among them Jaazaniah the son of Azzur and Pelatiah the son of Benaiah, princes of the people, counsel that the city is the caldron and they the meat; Ezekiel prophesies that they will be brought out and judged at the border of Israel, and Pelatiah dies; the LORD promises the exiles, whom Jerusalem's inhabitants disown, that He will be a little sanctuary to them among the nations, gather them to the land of Israel and give them one heart and a new spirit, a heart of flesh for a heart of stone; the glory goes up from the city to the mountain on its east, and the Spirit brings Ezekiel back to Chaldea, where he tells the captives all the LORD has shown him"},{"p":"contents","r":"NKJV notes, note on Ezekiel 12:10; Ezekiel 12:1–28","v":"Ezekiel, dwelling among a rebellious house that has eyes but does not see, carries out his belongings by day as if going into captivity, digs through the wall at evening and goes out at twilight with his face covered; in the morning the LORD tells him this burden (oracle, by the NKJV note) concerns the prince in Jerusalem, who will go out through the wall with covered face, be caught in the LORD's net and brought to Babylon, which he will not see though he dies there; Ezekiel is to eat his bread with quaking, for Jerusalem's people will eat theirs with anxiety; and the proverb that the days are prolonged and every vision fails is laid to rest, for the LORD's word will no more be postponed"},{"p":"contents","r":"NKJV notes, note on Ezekiel 13:10; Ezekiel 13:1–23","v":"Woe to the foolish prophets of Israel who follow their own spirit and have seen nothing, like foxes in the deserts, who have not gone up into the gaps, who say the LORD says when He has not sent them, and see visions of peace for Jerusalem when there is no peace, as men who plaster a wall with untempered mortar (or whitewash, by the NKJV note) that rain, hail and wind will bring down; and woe to the women who sew magic charms and make veils to hunt souls for handfuls of barley and pieces of bread, from whose hand the LORD will deliver His people"},{"p":"contents","r":"Ezekiel 14:1–23","v":"Some of the elders of Israel sit before Ezekiel with idols set up in their hearts, and the LORD will answer such inquirers Himself, cutting them off, and the prophet who is enticed with them, and calls the house of Israel to repent; when a land sins against Him, even if Noah, Daniel and Job were in it they would deliver only themselves by their righteousness, and how much more when He sends His four severe judgments of sword, famine, wild beasts and pestilence on Jerusalem; yet a remnant of sons and daughters will be brought out to the exiles, and seeing their ways the exiles will know He did nothing without cause"},{"p":"contents","r":"Ezekiel 15:1–8","v":"The wood of the vine is no better than other wood: no object or peg can be made of it, and it is thrown into the fire for fuel; so the LORD will give up the inhabitants of Jerusalem, who will go out from one fire only to be devoured by another, and make the land desolate for their unfaithfulness"},{"p":"contents","r":"NKJV notes, note on Ezekiel 16:8; NKJV notes, note on Ezekiel 16:16; Ezekiel 16:1–63","v":"The LORD makes known to Jerusalem her abominations: born of the land of Canaan, her father an Amorite and her mother a Hittite, she was cast out unwashed on the day of her birth until He passed by, bade her live, and when she was grown spread His wing (or the corner of His garment, by the NKJV note) over her, swore an oath and made her His in covenant, washing, clothing and adorning her until her beauty was famous; but she trusted in her beauty and played the harlot, made high places and male images with His gifts, sacrificed her children to idols, and played the harlot with Egypt, Assyria and Chaldea, paying her lovers instead of being paid; so He will gather her lovers against her to strip and stone her and burn her houses; like mother, like daughter, she is more corrupt than her elder sister Samaria and her younger sister Sodom, whose captives He will bring back with hers; yet He will remember His covenant of her youth, establish an everlasting covenant, and provide her atonement"},{"p":"contents","r":"Ezekiel 17:1–24","v":"Ezekiel poses a riddle: a great eagle crops the topmost twig of the cedar of Lebanon and sets it in a city of merchants, then plants a seed that becomes a low spreading vine, which bends its roots toward another great eagle and will wither; the LORD explains that the king of Babylon took Jerusalem's king and princes to Babylon and made a covenant with the king's offspring, who broke his oath by sending to Egypt for horses and men, so he will die in Babylon and Pharaoh will not help him; and the LORD Himself will plant a tender twig from the top of the high cedar on a high mountain of Israel, to become a majestic cedar sheltering birds of every sort"},{"p":"contents","r":"Jeremiah 31:29–30; Ezekiel 18:1–32","v":"The LORD forbids the proverb that the fathers have eaten sour grapes and the children's teeth are set on edge, which Jeremiah 31:29–30 also sets aside: all souls are His, and the soul who sins shall die; a just man shall live, his violent son shall die, and that son's righteous son shall live; the wicked who turns shall live and his transgressions not be remembered, the righteous who turns to iniquity shall die; the LORD has no pleasure in the death of the wicked, and calls the house of Israel to cast away their transgressions, get a new heart and a new spirit, and turn and live"},{"p":"contents","r":"Ezekiel 19:1–14","v":"A lament for the princes of Israel: their mother was a lioness whose young lion learned to devour men and was brought with chains to the land of Egypt, and whose next young lion laid waste cities until the nations caught him and brought him in a cage to the king of Babylon; she was a fruitful vine with strong branches for rulers' scepters, but she was plucked up in fury, planted in a dry wilderness, and fire from one of her branches devoured her fruit, leaving no strong branch for a scepter"},{"p":"contents","r":"NKJV notes, note on Ezekiel 20:29; Ezekiel 20:1–49","v":"In the seventh year, on the tenth day of the fifth month, elders of Israel come to inquire of the LORD, who will not be inquired of by them; He makes known the abominations of their fathers: in Egypt they kept its idols, in the wilderness they despised His statutes and profaned His Sabbaths, and in the land they sacrificed on every high hill (so the high place is called Bamah, High Place by the NKJV note), while He spared them for His name's sake; and they still make their sons pass through the fire; yet He will bring them out from the peoples into the wilderness of the peoples, make them pass under the rod, purge the rebels, and accept the whole house of Israel on His holy mountain in the land He swore to their fathers; then Ezekiel prophesies a fire in the forest of the South that no one can quench, and they say he only speaks parables"},{"p":"contents","r":"NKJV notes, note on Ezekiel 21:21; Ezekiel 21:1–32","v":"The LORD draws His sword from its sheath against Jerusalem and the land of Israel, to cut off righteous and wicked alike, and Ezekiel sighs with a breaking heart at the news to come; a sword is sharpened and polished for slaughter against the princes of Israel; Ezekiel marks two roads for the sword of the king of Babylon, to Rabbah of the Ammonites and to Jerusalem, and the king at the fork divines with arrows, images (teraphim, by the NKJV note) and a liver, and the lot falls for Jerusalem; the profane, wicked prince of Israel is to remove his crown, for it shall be overthrown until He comes whose right it is; and a sword is drawn against the Ammonites, who will be judged in their own land and not remembered"},{"p":"contents","r":"Ezekiel 22:1–31","v":"Ezekiel is to show the bloody city her abominations: her princes shed blood, father and mother are despised, the stranger, the fatherless and the widow oppressed, the LORD's holy things and Sabbaths profaned, lewdness committed, bribes, usury and extortion taken, and He forgotten, so He will scatter her among the nations; the house of Israel has become dross, and He will gather them into Jerusalem as metals into a furnace and melt them in His fury; her prophets devour like a roaring lion, her priests make no difference between holy and unholy, her princes are like wolves, her prophets plaster with untempered mortar, the people oppress the poor and the stranger, and the LORD sought a man to stand in the gap before Him for the land and found none"},{"p":"contents","r":"NKJV notes, note on Ezekiel 23:4; NKJV notes, note on Ezekiel 23:17; Ezekiel 23:1–49","v":"Two sisters, daughters of one mother, played the harlot in Egypt in their youth: Oholah the elder, who is Samaria, and Oholibah, who is Jerusalem; Oholah lusted for the Assyrians and the LORD gave her into their hand, and they slew her with the sword; Oholibah saw it and was more corrupt, lusting for the Assyrians, then for Chaldeans portrayed on the wall, then again for Egypt; so her lovers, the Babylonians, all the Chaldeans, Pekod, Shoa, Koa and the Assyrians, will come against her from every side, she will drink her sister's cup of horror and desolation, and an assembly will stone them, slay their sons and daughters and burn their houses, for they sacrificed their children to idols and the same day defiled the LORD's sanctuary"},{"p":"contents","r":"NKJV notes, note on Ezekiel 24:17; Ezekiel 24:1–27","v":"In the ninth year, on the tenth day of the tenth month, Ezekiel is to write down the day, for the king of Babylon began his siege of Jerusalem that very day, and to speak a parable of a pot set on the fire and filled with choice cuts: woe to the bloody city, a pot whose scum will not come off, whose blood lies on a bare rock; the LORD will heap on the wood and set the pot empty on the coals till its filth is consumed; then the LORD takes the desire of Ezekiel's eyes with one stroke, his wife dies at evening, and he does not mourn, a sign that the LORD will profane His sanctuary, the desire of their eyes, and they will pine away without mourning; on the day it comes one who escapes will tell him, and his mouth will be opened"},{"p":"contents","r":"NKJV notes, note on Ezekiel 25:15; Ezekiel 25:1–17","v":"Because the Ammonites said Aha over the profaned sanctuary, the desolate land and Judah's captivity, the LORD will give them to the men of the East and make Rabbah a stable for camels; because Moab and Seir said Judah is like all the nations, He will open Moab's frontier cities, Beth Jeshimoth, Baal Meon and Kirjathaim, to the men of the East; because Edom took vengeance on Judah, He will make it desolate from Teman to Dedan by the hand of His people Israel; and because the Philistines took vengeance with an old hatred (or perpetual, by the NKJV note), He will cut off the Cherethites and the remnant of the seacoast"},{"p":"contents","r":"NKJV notes, note on Ezekiel 26:7; NKJV notes, note on Ezekiel 26:8; Ezekiel 26:1–21","v":"In the eleventh year, on the first day of the month, the LORD speaks against Tyre, which said Aha over Jerusalem, broken and laid waste: He will bring many nations against her like the waves of the sea, to destroy her walls and towers and scrape her bare as the top of a rock, a place for spreading nets; Nebuchadnezzar (Nebuchadrezzar, by the NKJV note) king of Babylon, king of kings, will come from the north with horses, chariots and an army, raise a siege mound against her, break down her towers with his axes, enter her gates, slay her people and lay her stones, timber and soil in the water; she will never be rebuilt; the coastlands will shake at her fall, the princes of the sea will come down from their thrones to lament the renowned city, and the LORD will bring her down to the Pit, to be no more"},{"p":"contents","r":"NKJV notes, note on Ezekiel 27:6; Ezekiel 27:1–36","v":"Ezekiel takes up a lamentation for Tyre, who sits at the entrance of the sea and said she was perfect in beauty: a ship of fir from Senir with a cedar mast from Lebanon, oars of oak from Bashan, ivory from Cyprus (Kittim, by the NKJV note), a sail of Egyptian linen and an awning of blue and purple from Elishah, rowed by men of Sidon and Arvad and caulked by the elders of Gebal, with men of Persia, Lydia and Libya in her army; Tarshish, Javan, Tubal, Meshech, the house of Togarmah, Dedan, Syria, Judah and the land of Israel, Damascus, Arabia and Kedar, Sheba and Raamah, Haran, Canneh, Eden, Assyria and Chilmad traded with her; but the east wind breaks her in the midst of the seas, her wealth and her people sink on the day of her ruin, and the mariners lament on the shore, asking what city is like Tyre"},{"p":"contents","r":"NKJV notes, note on Ezekiel 28:2; Ezekiel 28:1–26","v":"The prince of Tyre, whose heart is lifted up, says he is a god sitting in the seat of gods in the midst of the seas, though he is a man; he is wiser than Daniel and has gathered riches by his trade, so strangers, the most terrible of the nations, will bring him down to the Pit, and he will die the death of the uncircumcised; Ezekiel laments the king of Tyre, the seal of perfection, who was in Eden, the garden of God, covered with precious stones, the anointed cherub who covered, on the holy mountain of God, until iniquity was found in him through his trading and the LORD cast him out and turned him to ashes; the LORD will judge Sidon with pestilence and the sword, and gather the house of Israel to dwell safely in the land He gave to His servant Jacob"},{"p":"contents","r":"NKJV notes, note on Ezekiel 29:3; NKJV notes, note on Ezekiel 29:21; Ezekiel 29:1–21","v":"In the tenth year, on the twelfth day of the tenth month, the LORD speaks against Pharaoh king of Egypt, the great monster lying in the midst of his rivers, who said the River (the Nile, by the NKJV note) was his own and he had made it: He will put hooks in his jaws, draw him out with the fish of his rivers clinging to his scales and leave him in the wilderness as food for beasts and birds; Egypt has been a staff of reed to the house of Israel, so it will be desolate from Migdol to Syene, as far as Ethiopia, uninhabited forty years, and its people scattered; after forty years the LORD will bring them back to Pathros, the land of their origin, as the lowliest of kingdoms; in the twenty-seventh year, on the first day of the first month, He says that Nebuchadnezzar made his army labor hard against Tyre without wages, so He will give him the land of Egypt as wages for his army, and in that day He will make the horn of the house of Israel spring forth"},{"p":"contents","r":"NKJV notes, note on Ezekiel 30:4; NKJV notes, note on Ezekiel 30:13; Ezekiel 30:1–26","v":"Ezekiel is to wail, for the day of the LORD is near, a day of clouds, the time of the Gentiles: the sword will come on Egypt, anguish on Ethiopia (Cush, by the NKJV note), and her allies, Libya, Lydia, the mingled people and Chub, will fall with her; Nebuchadnezzar king of Babylon and his people, the most terrible of the nations, will fill the land with the slain; the LORD will dry the rivers, destroy the idols of Noph (Memphis, by the NKJV note), make Pathros desolate, set fire to Zoan and judge No, Sin, Aven, Pi Beseth and Tehaphnehes; in the eleventh year, on the seventh day of the first month, He says He has broken the arm of Pharaoh king of Egypt and will break both his arms, but strengthen the arms of the king of Babylon and put His sword in his hand"},{"p":"contents","r":"NKJV notes, note on Ezekiel 31:15; NKJV notes, note on Ezekiel 31:16; Ezekiel 31:1–18","v":"In the eleventh year, on the first day of the third month, the LORD asks Pharaoh and his multitude whom he is like in his greatness: Assyria was a cedar in Lebanon, watered by the deep, taller than all the trees of the field, with the birds nesting in its boughs, the beasts bearing young under it and great nations dwelling in its shade, so that no tree in the garden of God was like it and all the trees of Eden envied it; because its heart was lifted up in its height, the LORD gave it into the hand of the mighty one of the nations, aliens cut it down, the peoples left its shade, and it went down to hell (or Sheol, by the NKJV note) with those who go down to the Pit, while Lebanon mourned and the nations shook; so Pharaoh and all his multitude will be brought down with the trees of Eden to lie among the uncircumcised"},{"p":"contents","r":"Ezekiel 32:1–32","v":"In the twelfth year, on the first day of the twelfth month, Ezekiel takes up a lamentation for Pharaoh, a young lion among the nations and a monster in the seas fouling the rivers: the LORD will draw him up in His net, cast him on the open field for the birds and beasts, water the land with his blood and darken the sun, moon and stars over him; the sword of the king of Babylon will come on Egypt, plunder its pomp and destroy its multitude, and the daughters of the nations will lament her; in the twelfth year, on the fifteenth day of the month, Ezekiel is to wail over the multitude of Egypt and send them down to the Pit, where Assyria, Elam, Meshech and Tubal, Edom, the princes of the north and the Sidonians lie slain by the sword among the uncircumcised, and Pharaoh will see them and be comforted"},{"p":"contents","r":"NKJV notes, note on Ezekiel 33:21; Ezekiel 33:1–33","v":"The LORD sets Ezekiel again as a watchman for the house of Israel, to warn the wicked from his way, for a watchman who sees the sword coming and does not blow the trumpet answers for the blood of those taken; the LORD has no pleasure in the death of the wicked, but calls the house of Israel to turn and live, and judges each by his own ways, though the people say His way is not fair; in the twelfth year of the captivity, on the fifth day of the tenth month, one who escaped from Jerusalem tells Ezekiel that the city has been taken (struck down, by the NKJV note), and the LORD had opened his mouth the evening before, so that he is no longer mute; those living in the ruins of the land claim it as Abraham's heirs, but for their bloodshed and abominations they will fall by the sword, and the land will be made most desolate; Ezekiel's hearers come to him as to a lovely song, but do not do what he says"},{"p":"contents","r":"Ezekiel 34:1–31","v":"The LORD speaks against the shepherds of Israel who fed themselves, ate the fat and clothed themselves with the wool, but did not feed, heal or seek the flock, so that it was scattered and became food for the beasts: He will take His flock from them and Himself search for His sheep, gather them from the countries to the mountains of Israel and feed them in good pasture; He will judge between the fat sheep and the lean, set over them one shepherd, His servant David, a prince among them, make with them a covenant of peace, send showers of blessing, break their yoke and raise up for them a garden of renown, and they will know that He is with them and they are His people, the flock of His pasture"},{"p":"contents","r":"NKJV notes, note on Ezekiel 35:5; Ezekiel 35:1–15","v":"The LORD sets Ezekiel's face against Mount Seir: because it kept an ancient (or everlasting, by the NKJV note) hatred and shed the blood of the children of Israel in the time of their calamity, and said that the two nations and their two lands would be its own, and spoke against the mountains of Israel as given to it to consume, the LORD will make it most desolate, fill its mountains with the slain and leave its cities uninhabited forever; as it rejoiced over Israel's desolate inheritance, so Mount Seir and all Edom will be desolate"},{"p":"contents","r":"Ezekiel 36:1–38","v":"Ezekiel prophesies to the mountains of Israel, which the nations and all Edom took as their possession with spite and made a mockery: the nations will bear their own shame, but the mountains will bear fruit for the LORD's people Israel, soon to come, and be tilled and sown, the cities inhabited and the ruins rebuilt; Israel had defiled the land and profaned the LORD's holy name among the nations where He scattered them, so for His name's sake He will gather them, sprinkle clean water on them, give them a new heart and a new spirit, take away the heart of stone and give a heart of flesh, put His Spirit within them to walk in His statutes, and make the desolate land like the garden of Eden, its ruined cities filled with people like the flocks at Jerusalem at its feasts"},{"p":"contents","r":"NKJV notes, note on Ezekiel 37:9; Ezekiel 37:1–28; 2 Corinthians 6:16; Revelation 21:3","v":"The hand of the LORD sets Ezekiel down in the Spirit in a valley full of very dry bones and asks if they can live; at his prophesying the bones come together with a rattling, sinews, flesh and skin come on them, and when he prophesies to the breath (breath of life, by the NKJV note) it comes from the four winds and they live and stand up, a very great army: the bones are the whole house of Israel, who say their hope is lost, and the LORD will open their graves, put His Spirit in them and bring them into the land of Israel; Ezekiel writes on two sticks, for Judah and for Joseph, and joins them into one in his hand, for the LORD will gather the children of Israel into one nation on the mountains of Israel with one king, His servant David, their prince forever, make an everlasting covenant of peace with them and set His sanctuary among them, His tabernacle with them, He their God and they His people, as Revelation 21:3 hears of the tabernacle of God with men and 2 Corinthians 6:16 repeats the promise"},{"p":"contents","r":"NKJV notes, note on Ezekiel 38:2; Ezekiel 38:1–23; Revelation 20:8","v":"The LORD sets Ezekiel's face against Gog, of the land of Magog, the prince of Rosh, Meshech and Tubal (the chief prince of Meshech, by the NKJV note on other versions): He will put hooks in his jaws and lead him out in the latter years with his army and with Persia, Ethiopia, Libya, Gomer and the house of Togarmah from the far north against the land of Israel, gathered from the nations and dwelling safely in unwalled villages; Gog will plan to take plunder, and Sheba, Dedan and the merchants of Tarshish will ask if he has come for it; but in the LORD's fury there will be a great earthquake in the land of Israel, every man's sword will be against his brother, and the LORD will rain flooding rain, great hailstones, fire and brimstone on Gog and his troops; Revelation 20:8 names Gog and Magog gathered to battle"},{"p":"contents","r":"NKJV notes, note on Ezekiel 39:11; NKJV notes, note on Ezekiel 39:16; Ezekiel 39:1–29","v":"Gog will fall on the mountains of Israel and be given to the birds and beasts, and the LORD will send fire on Magog and the coastlands; the people of Israel's cities will burn his weapons for seven years, needing no wood, and bury Gog and his multitude for seven months in the valley of those who pass by east of the sea, called the Valley of Hamon Gog (the Multitude of Gog, by the NKJV note), with men set apart to search the land for bones, and a city there will be named Hamonah; the birds and beasts are called to the LORD's great sacrificial meal on the mountains of Israel; the nations will know that Israel went into captivity for its iniquity, and the LORD will bring back the captives of Jacob, leave none behind, hide His face no more and pour out His Spirit on the house of Israel"},{"p":"contents","r":"NKJV notes, note on Ezekiel 40:1; NKJV notes, note on Ezekiel 40:5; Ezekiel 40:1–49; Revelation 21:10, 15","v":"In the twenty-fifth year of the captivity, at the beginning of the year, on the tenth day of the month, the fourteenth year after the city was taken (struck, by the NKJV note), the LORD brings Ezekiel in the visions of God to the land of Israel and sets him on a very high mountain with something like a city to the south, where a man like bronze with a line of flax and a measuring rod of six cubits, each a cubit and a handbreadth (a royal cubit of about 21 inches, by the NKJV note), shows him the temple to declare to the house of Israel; he measures the wall around it, a rod thick and a rod high, the gateway facing east with its three chambers on each side, the outer court with thirty chambers on its pavement, the gateways facing north and south up seven steps, the three gateways of the inner court up eight steps, each fifty cubits long and twenty-five wide, the chamber and tables where the offerings were washed and slain, the chambers for the singers and for the priests, the sons of Zadok, who keep the altar, the inner court a hundred cubits square with the altar before the temple, and the vestibule of the temple; Revelation 21:10, 15 likewise is carried to a great and high mountain and sees a reed to measure the city"},{"p":"contents","r":"NKJV notes, note on Ezekiel 41:1; Ezekiel 41:1–26","v":"The man measures the sanctuary (heykal, the holy place, by the NKJV note), forty cubits long and twenty wide with doorposts six cubits on each side, and the Most Holy Place beyond it, twenty cubits square; the wall of the temple is six cubits, with side chambers four cubits wide in three stories, thirty in each, resting on ledges and widening as they rise, on a foundation a full rod high; the building at the western end is seventy cubits wide and ninety long; the temple is a hundred cubits long, and so is the separating courtyard with the building; the house is paneled with wood and carved all around with cherubim and palm trees, each cherub with the face of a man toward one palm tree and the face of a young lion toward the other; the wooden altar, three cubits high and two long, is the table before the LORD; and the temple and the sanctuary have two doors of two folding panels each"},{"p":"contents","r":"NKJV notes, note on Ezekiel 42:16; Ezekiel 42:1–20","v":"The man brings Ezekiel to the chambers north and south of the separating courtyard, a hundred cubits long and fifty wide, in three stories of galleries with a walk before them; they are the holy chambers where the priests who approach the LORD eat the most holy offerings, lay the grain, sin and trespass offerings, and leave the garments in which they minister before going out to the people; then he measures the whole all around with the measuring rod (about 10.5 feet, by the NKJV note), five hundred on each side, with a wall to separate the holy from the common (or profane, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Ezekiel 43:3; NKJV notes, note on Ezekiel 43:15; Ezekiel 43:1–27","v":"The man brings Ezekiel to the gate facing east, and the glory of the God of Israel comes from the east, His voice like many waters and the earth shining, as in the vision when he came to destroy the city (when He came, by the NKJV note on some manuscripts) and the vision by the River Chebar; the glory enters the temple by the east gate and fills it, and the LORD says it is the place of His throne, where He will dwell among the children of Israel forever, and they must put away their harlotry and their kings' carcasses; Ezekiel is to describe the temple and write down its design and ordinances, for the whole area around the mountaintop is most holy; the altar's hearth is twelve cubits square on ledges of fourteen and sixteen, its steps facing east, and it is to be cleansed and consecrated seven days with a bull, a goat and a ram, the priests of the seed of Zadok offering, so that from the eighth day the LORD will accept their offerings"},{"p":"contents","r":"Ezekiel 44:1–31","v":"The outer east gate is shut and will not be opened, for the LORD God of Israel entered by it, but the prince may sit in it to eat bread before the LORD; the glory fills the house of the LORD, and the LORD tells Ezekiel that no foreigner uncircumcised in heart or flesh may enter His sanctuary; the Levites who went astray after idols will bear their iniquity and serve as gatekeepers and ministers of the house, but the priests, the sons of Zadok, who kept charge of His sanctuary, will come near to minister, in linen garments, with trimmed hair, drinking no wine in the inner court, marrying virgins of Israel or priests' widows, teaching the people the holy and the unholy, judging by His judgments, keeping from the dead but for near kin, and having the LORD as their inheritance and the offerings as their food"},{"p":"contents","r":"NKJV notes, note on Ezekiel 45:5; Ezekiel 45:1–25","v":"When the land is divided by lot, a holy district of twenty-five thousand cubits by ten thousand is set apart for the LORD, with the sanctuary in it on a square plot of five hundred rods and fifty cubits of open space, for the priests and their houses; a like area belongs to the Levites, with twenty chambers (a possession, cities of dwelling, in the Greek, by the NKJV note); the city's property, five thousand by twenty-five thousand, belongs to the whole house of Israel; the prince has the land on either side, so that the princes no more oppress the people; they are to keep honest scales and measures, the ephah and bath each a tenth of a homer and the mina sixty shekels, and the people give their offering to the prince, who provides the offerings at the feasts, New Moons and Sabbaths; the sanctuary is cleansed on the first day of the first month, the Passover kept from the fourteenth day seven days, and the feast of the seventh month from the fifteenth day, with the prince's offerings"},{"p":"contents","r":"Ezekiel 46:1–24","v":"The gateway of the inner court facing east is opened on the Sabbath and the New Moon, when the prince worships at its threshold and the people at its entrance, with his burnt offerings of lambs, a ram and on the New Moon a bull; at the appointed feasts the people go in by the north or south gate and out by the other, the prince among them; a lamb with its grain offering is offered every morning; the prince's gift of land to a servant returns to him in the year of liberty, and he may not take the people's inheritance; the man shows Ezekiel the place where the priests boil and bake the offerings, and the four enclosed courts in the corners of the outer court, forty cubits by thirty, the kitchens where the sacrifices of the people are boiled"},{"p":"contents","r":"NKJV notes, note on Ezekiel 47:8; NKJV notes, note on Ezekiel 47:12; Ezekiel 47:1–23; Revelation 22:1–2","v":"Water flows from under the threshold of the temple toward the east, south of the altar; the man measures a thousand cubits at a time, and it rises to Ezekiel's ankles, knees and waist and then is a river too deep to cross; it goes down into the valley (the Arabah, by the NKJV note) and into the sea and heals its waters, so that everything lives where it goes, fishermen spread their nets from En Gedi to En Eglaim and only the marshes are left to salt, and on its banks grow trees bearing fruit every month, their fruit for food and their leaves for medicine, as Revelation 22:1–2 sees the river of the water of life and the tree of life whose leaves are for healing; the LORD gives the borders of the land, from the Great Sea by Hethlon to Hamath and Hazar Enan, down the Jordan, and from Tamar to the waters of Meribah by Kadesh and the brook, to be divided equally among the twelve tribes, Joseph having two portions, with an inheritance for the strangers who dwell among them"},{"p":"contents","r":"NKJV notes, note on Ezekiel 48:35; Ezekiel 48:1–35; Revelation 21:12–13","v":"The tribes' sections run from east to west: Dan, Asher, Naphtali, Manasseh, Ephraim, Reuben and Judah from the north; then the district set apart, twenty-five thousand cubits wide, with the holy portion of the priests, the sons of Zadok, and the sanctuary in its center, the Levites' portion, and the city's property with the city in its center and land to feed its workers, and the prince's land on either side; then Benjamin, Simeon, Issachar, Zebulun and Gad to the southern border; the city, four thousand five hundred cubits on each side and eighteen thousand around, has twelve gates named after the tribes of Israel, three on each side, as Revelation 21:12–13 sees the twelve gates with the names of the twelve tribes, and its name from that day is THE LORD IS THERE (YHWH Shammah, by the NKJV note)"},{"p":"designation","r":"Ezekiel 1:1","v":"In the thirtieth year"},{"p":"feature","r":"Ezekiel 1:1–3; 8:1; 20:1; 24:1; 31:1; 32:1, 17; 33:21; 40:1","v":"Ezekiel tells it in the first person among the captives in the land of the Chaldeans, and dates many of its visions and words by year, month and day, counting the years from King Jehoiachin's captivity"},{"p":"feature","r":"Ezekiel 2:1, 3; 3:1, 17; 24:25","v":"The LORD addresses Ezekiel throughout as son of man"},{"p":"feature","r":"Ezekiel 1:1; 8:3; 40:2","v":"Three times Ezekiel is shown visions of God: by the River Chebar, in the temple at Jerusalem, and in the land of Israel on a very high mountain"},{"p":"feature","r":"Ezekiel 6:7, 10, 13–14; 7:4, 9, 27; 26:6; 28:22–24, 26; 29:6, 9, 16, 21; 30:8, 19, 25–26; 32:15; 33:29; 34:27, 30; 35:4, 9, 12, 15; 36:11, 23, 38; 37:6, 13–14, 28; 38:23; 39:6–7, 22, 28","v":"A refrain runs through it that, when the LORD's judgments come, the people shall know that He is the LORD"},{"p":"made by","r":"Ezekiel 1:1–3; 24:2, 24","e":"PER-02943","b":"inferred","c":"probable","w":"The book tells its visions in the first person from its opening verse (Ezekiel 1:1), and the one to whom the word came is named as Ezekiel the priest, the son of Buzi (1:3; 24:24); the LORD told him to write down the day the siege of Jerusalem began (24:2)."}],"nm":{"PER-02943":"Ezekiel"}},"OBJ-00542":{"k":"object","n":"The scroll Ezekiel ate","d":"The scroll of a book, written inside and out with lamentations, mourning and woe, which a hand held out to Ezekiel and the LORD made him eat (Ezekiel 2:9–3:3)","f":[{"p":"contents","r":"Ezekiel 2:10","v":"Lamentations, mourning and woe, written on the inside and on the outside"},{"p":"designation","r":"Ezekiel 2:9","v":"a scroll of a book"},{"p":"feature","r":"Ezekiel 3:1–3","v":"When Ezekiel ate it at the LORD's word, it was as sweet as honey in his mouth"},{"p":"purpose","r":"Ezekiel 3:1","v":"Ezekiel was to eat it and then go and speak to the house of Israel"}],"nm":{}},"OBJ-00543":{"k":"object","n":"The image of jealousy","d":"The image whose seat was at the door of the north gate of the inner court of the LORD's house, which provoked Him to jealousy (Ezekiel 8:3–5)","f":[{"p":"designation","r":"Ezekiel 8:3, 5","v":"the image of jealousy"},{"p":"feature","r":"NKJV notes, note on Ezekiel 8:3; Ezekiel 8:3, 5","v":"Its seat was at the door of the north gate of the inner court, north of the altar gate in the entrance, and it provoked the LORD to jealousy (aroused His jealousy, by the NKJV note)"},{"p":"placed at","r":"Ezekiel 8:3, 5","e":"PLC-00921"}],"nm":{"PLC-00921":"The inner court of the temple"}},"OBJ-00544":{"k":"object","n":"The stick of Judah","d":"The stick on which Ezekiel was to write for Judah and its companions, joined with the stick of Joseph into one (Ezekiel 37:16–20)","f":[{"p":"contents","r":"Ezekiel 37:16","v":"Written for Judah and for the children of Israel, its companions"},{"p":"designation","r":"Ezekiel 37:19","v":"the stick of Judah"},{"p":"made by","r":"Ezekiel 37:16, 20","e":"PER-02943","b":"inferred","c":"probable","w":"The LORD told Ezekiel to take the sticks and write on them, and said they would be in his hand before the people's eyes (Ezekiel 37:16, 20)."},{"p":"sign of","r":"Ezekiel 37:16–22","e":"EVT-02525"}],"nm":{"EVT-02525":"Ezekiel joins the sticks of Judah and Joseph","PER-02943":"Ezekiel"}},"OBJ-00545":{"k":"object","n":"The stick of Joseph","d":"The stick on which Ezekiel was to write for Joseph, the stick of Ephraim, and all the house of Israel, joined with the stick of Judah into one (Ezekiel 37:16–20)","f":[{"p":"contents","r":"Ezekiel 37:16","v":"Written for Joseph, the stick of Ephraim, and for all the house of Israel, its companions"},{"p":"designation","r":"Ezekiel 37:19","v":"the stick of Joseph"},{"p":"designation","r":"Ezekiel 37:16","v":"the stick of Ephraim"},{"p":"made by","r":"Ezekiel 37:16, 20","e":"PER-02943","b":"inferred","c":"probable","w":"The LORD told Ezekiel to take the sticks and write on them, and said they would be in his hand before the people's eyes (Ezekiel 37:16, 20)."},{"p":"sign of","r":"Ezekiel 37:16–22","e":"EVT-02525"}],"nm":{"EVT-02525":"Ezekiel joins the sticks of Judah and Joseph","PER-02943":"Ezekiel"}},"OBJ-00546":{"k":"object","n":"The measuring rod in Ezekiel's vision","d":"The measuring rod of six cubits in the hand of the man like bronze, with which he measured the temple (Ezekiel 40:3, 5)","f":[{"p":"designation","r":"Ezekiel 40:3, 5","v":"a measuring rod"},{"p":"feature","r":"NKJV notes, note on Ezekiel 40:5; NKJV notes, note on Ezekiel 42:16; Ezekiel 40:5; 42:16–19","v":"Each of its six cubits was a cubit and a handbreadth (a royal cubit of about 21 inches, by the NKJV note)"},{"p":"length in cubits","r":"Ezekiel 40:5","v":"6 cubits"},{"p":"placed at","r":"Ezekiel 40:2–3","e":"PLC-01372","b":"inferred","c":"probable","w":"The man with the measuring rod stood in the gateway of the temple that Ezekiel saw on the very high mountain (Ezekiel 40:2–3)."}],"nm":{"PLC-01372":"The very high mountain of Ezekiel's vision"}},"OBJ-00547":{"k":"object","n":"The eight tables for the sacrifices in Ezekiel's vision","d":"The tables by the gateway, two on each side of the vestibule within and two on each side without, on which the sacrifices were slain (Ezekiel 40:39–43)","f":[{"p":"count","r":"Ezekiel 40:41","v":"8"},{"p":"designation","r":"Ezekiel 40:41","v":"eight tables"},{"p":"feature","r":"Ezekiel 40:39–41, 43","v":"Two stood on each side of the gateway's vestibule and two on each side outside it at the entrance of the northern gateway, four on this side and four on that; inside were hooks a handbreadth wide fastened all around, and the flesh of the sacrifices lay on the tables"},{"p":"placed at","r":"Ezekiel 40:39–41","e":"PLC-01382"},{"p":"purpose","r":"Ezekiel 40:39, 41","v":"To slay the burnt offering, the sin offering and the trespass offering"}],"nm":{"PLC-01382":"The north gateway of the inner court in Ezekiel's vision"}},"OBJ-00548":{"k":"object","n":"The four tables of hewn stone in Ezekiel's vision","d":"Four tables of hewn stone for the burnt offering, on which the instruments for slaughter were laid (Ezekiel 40:42)","f":[{"p":"count","r":"Ezekiel 40:42","v":"4"},{"p":"designation","r":"Ezekiel 40:42","v":"four tables of hewn stone"},{"p":"height in cubits","r":"Ezekiel 40:42","v":"1 cubits"},{"p":"length in cubits","r":"Ezekiel 40:42","v":"1.5 cubits"},{"p":"material","r":"Ezekiel 40:42","v":"Hewn stone"},{"p":"placed at","r":"Ezekiel 40:40–42","e":"PLC-01382","b":"inferred","c":"probable","w":"The four tables of hewn stone are told with the tables at the entrance of the northern gateway (Ezekiel 40:40–42)."},{"p":"purpose","r":"Ezekiel 40:42","v":"To hold the instruments with which they slaughtered the burnt offering and the sacrifice"},{"p":"width in cubits","r":"Ezekiel 40:42","v":"1.5 cubits"}],"nm":{"PLC-01382":"The north gateway of the inner court in Ezekiel's vision"}},"OBJ-00549":{"k":"object","n":"The altar in Ezekiel's vision","d":"The altar in the inner court before the temple in Ezekiel's vision (Ezekiel 40:47; 43:13–27)","f":[{"p":"designation","r":"Ezekiel 40:46–47; 47:1","v":"the altar"},{"p":"feature","r":"NKJV notes, note on Ezekiel 43:13; Ezekiel 43:13–14","v":"Measured in cubits of a cubit and a handbreadth (a royal cubit of about 21 inches, by the NKJV note): a base one cubit high and one wide with a rim of a span; two cubits from the base to the lower ledge, one cubit wide, and four from the smaller ledge to the larger, one cubit wide"},{"p":"feature","r":"NKJV notes, note on Ezekiel 43:15; Ezekiel 43:15–17","v":"Its hearth (ariel, by the NKJV note) was four cubits high, twelve long and twelve wide, square, with four horns rising from it; its ledge was fourteen cubits square with a rim of half a cubit, its base a cubit all around, and its steps faced east"},{"p":"length in cubits","r":"Ezekiel 43:16","v":"12 cubits"},{"p":"placed at","r":"Ezekiel 40:47","e":"PLC-01376"},{"p":"width in cubits","r":"Ezekiel 43:16","v":"12 cubits"}],"nm":{"PLC-01376":"The inner court in Ezekiel's vision"}},"OBJ-00550":{"k":"object","n":"The altar of wood in Ezekiel's vision","d":"The altar of wood, three cubits high and two long, which the man called the table that is before the LORD (Ezekiel 41:22)","f":[{"p":"designation","r":"Ezekiel 41:22","v":"the table that is before the LORD"},{"p":"height in cubits","r":"Ezekiel 41:22","v":"3 cubits"},{"p":"length in cubits","r":"Ezekiel 41:22","v":"2 cubits"},{"p":"material","r":"Ezekiel 41:22","v":"Wood: its corners, its length and its sides"},{"p":"placed at","r":"Ezekiel 41:21–22","e":"PLC-01386","b":"inferred","c":"probable","w":"The altar of wood is told among the things of the temple, after the doorposts of the temple and the front of the sanctuary (Ezekiel 41:21–22)."}],"nm":{"PLC-01386":"The house of the temple in Ezekiel's vision"}},"OBJ-00551":{"k":"object","n":"The Book of Daniel","d":"The book of Daniel and his companions at the courts of the kings of Babylon and of Darius the Mede, and of Daniel's visions of the kingdoms to come (Daniel 1–12)","f":[{"p":"contents","r":"NKJV notes, note on Daniel 1:2; NKJV notes, note on Daniel 1:11; Daniel 1:1–21","v":"In Jehoiakim's third year Nebuchadnezzar king of Babylon besieges Jerusalem; the Lord gives Jehoiakim into his hand with some of the articles of the house of God (the temple, by the NKJV note), which he takes to the house of his god in the land of Shinar and puts in its treasure house; the king has Ashpenaz, master of his eunuchs, bring young men of Israel, of the royal line and of the nobles, sound, handsome, wise and quick to learn, to be taught the tongue and writings of the Chaldeans for three years on a daily portion of the king's food and wine; among them, of Judah, are Daniel, Hananiah, Mishael and Azariah, whom the chief of the eunuchs renames Belteshazzar, Shadrach, Meshach and Abed-Nego; Daniel resolves not to defile himself with the king's food, God gives him favor with the chief of the eunuchs, and the steward (or Melzar, by the NKJV note) tests the four ten days on vegetables and water, after which they look healthier than all who ate the king's portion; God gives the four knowledge and skill in all learning and wisdom, and Daniel understanding of visions and dreams; brought before Nebuchadnezzar, they are found ten times better than all the magicians and astrologers of his realm, and Daniel continues until the first year of King Cyrus"},{"p":"contents","r":"NKJV notes, note on Daniel 2:4; NKJV notes, note on Daniel 2:42; Daniel 2:1–49","v":"In the second year of his reign Nebuchadnezzar has dreams that trouble him so that he cannot sleep; he calls his magicians, astrologers, sorcerers and Chaldeans and demands, on pain of death, that they tell him both the dream and its meaning; they answer in Aramaic (the tongue of the book from here to the end of chapter 7, by the NKJV note) that no man on earth can do it, and in fury he orders all the wise men of Babylon destroyed; Daniel, sought with his companions, answers Arioch the captain of the guard wisely, asks the king for time and has his companions seek mercy from the God of heaven; the secret is revealed to him in a night vision, and he blesses God, who rules the times and seasons, deposes kings and sets them up and makes known deep things; before the king he says that a God in heaven who reveals secrets has shown Nebuchadnezzar what will be in the latter days: a great image with a head of gold, chest and arms of silver, belly and thighs of bronze, legs of iron and feet of iron and clay, struck on its feet by a stone cut free by no human hand, so that the whole is crushed like chaff and blown away, while the stone grows into a great mountain filling the earth; the king is the head of gold, after whom a lesser kingdom will rise, then one of bronze over all the earth, then a fourth as strong as iron, divided and partly brittle, and in the days of those kings the God of heaven will set up a kingdom that will never be destroyed but will crush all these and stand forever; the king falls on his face before Daniel, owns his God as God of gods and Lord of kings, makes Daniel ruler over the province of Babylon and chief over all its wise men, and at Daniel's request sets Shadrach, Meshach and Abed-Nego over the province's affairs, while Daniel sits in the king's gate"},{"p":"contents","r":"NKJV notes, note on Daniel 3:1; NKJV notes, note on Daniel 3:25; Daniel 3:1–30; Hebrews 11:34","v":"Nebuchadnezzar makes a gold image sixty cubits high (about ninety feet, by the NKJV note) and six wide and sets it up on the plain of Dura in the province of Babylon; he gathers the satraps, governors and all the officials of the provinces to its dedication, and a herald commands all peoples, nations and languages to fall down and worship it at the sound of the horn, flute, harp, lyre and psaltery, on pain of being thrown into a burning fiery furnace; certain Chaldeans accuse the Jews Shadrach, Meshach and Abed-Nego, whom the king set over the province, of neither serving his gods nor worshiping the image; brought before the furious king, the three answer that their God is able to deliver them, and that even if He does not they will not serve his gods; the furnace is heated seven times hotter, its flame kills the men who throw them in, and the king sees four men walking loose and unhurt in the fire, the fourth like the Son of God (or a son of the gods, by the NKJV note); he calls them out as servants of the Most High God, and his officials see that the fire had no power on them, not a hair singed nor any smell of fire on them; Nebuchadnezzar blesses their God, who sent His Angel and delivered His servants, decrees that any who speak against their God be cut in pieces, since no other god can deliver like this, and promotes the three in the province of Babylon; Hebrews 11:34 counts among the works of faith the quenching of fire's violence"},{"p":"contents","r":"NKJV notes, note on Daniel 4:16; Daniel 4:1–37","v":"Nebuchadnezzar writes to all peoples, nations and languages to tell the signs and wonders the Most High God has worked for him: at rest in his palace he had a dream that frightened him, which his wise men could not interpret; Daniel, called Belteshazzar after the name of the king's god, in whom, the king says, is the Holy God's Spirit, hears it: a great tree reaching to heaven and seen to the ends of the earth, sheltering beasts and birds and feeding all, which a watcher, a holy one, coming down from heaven, orders cut down, its stump left in the ground bound with iron and bronze, while a man's heart becomes a beast's for seven times (possibly years, by the NKJV note), so that the living may know that the Most High rules over human kingdoms; Daniel, troubled, tells the king that the tree is he, that he will be driven from men to live with the beasts and eat grass like oxen until he learns that the Most High rules, and that his kingdom will be kept for him, and urges him to break off his sins by righteousness and mercy to the poor; twelve months later, boasting on the royal palace of the great Babylon he says he built by his own might, he hears a voice from heaven that the kingdom has gone from him, and that hour he is driven out to eat grass, his hair growing like eagles' feathers and his nails like claws; at the end of the time his understanding returns, he blesses the Most High, whose rule is everlasting and whose hand none can stay, is restored to his kingdom with greater majesty, and praises the King of heaven, who can humble the proud"},{"p":"contents","r":"NKJV notes, note on Daniel 5:2; NKJV notes, note on Daniel 5:25; Daniel 5:1–31","v":"Belshazzar the king makes a great feast for a thousand of his lords and, drinking wine, has the gold and silver vessels that his father (or ancestor, by the NKJV note) Nebuchadnezzar took from the temple in Jerusalem brought in, so that he, his lords, his wives and his concubines drink from them and praise gods of gold, silver, bronze, iron, wood and stone; in that hour the fingers of a man's hand write on the plaster of the palace wall by the lampstand, and the king, pale and shaking, promises purple, a gold chain and the third place in the kingdom to whoever can read it, but his wise men cannot; the queen tells him of Daniel, in whom is the Holy God's Spirit, whom Nebuchadnezzar made chief of the magicians; Daniel, refusing the gifts, reminds the king how the Most High humbled Nebuchadnezzar when he grew proud, and charges Belshazzar, who knew it, with lifting himself up against the Lord of heaven, drinking from the vessels of His house and praising gods that neither see nor hear; he reads MENE, MENE, TEKEL, UPHARSIN (a mina, a shekel and half-shekels, from the verbs to number, to weigh and to divide, by the NKJV notes): God has numbered the kingdom and ended it, the king is weighed and found wanting, and his kingdom is divided and given to the Medes and Persians; Daniel is clothed in purple and proclaimed third ruler, and that very night Belshazzar, king of the Chaldeans, is slain, and Darius the Mede, about sixty-two years old, receives the kingdom"},{"p":"contents","r":"Daniel 6:1–28; Hebrews 11:33","v":"Darius sets a hundred and twenty satraps over the kingdom and three governors over them, Daniel among them, and Daniel so excels, by the excellent spirit in him, that the king thinks to set him over the whole realm; finding no fault in him except concerning the law of his God, the governors and satraps have the king sign a decree that for thirty days anyone who petitions any god or man but the king be thrown to the lions, a law of the Medes and Persians that cannot be changed; Daniel goes home and, at his windows open toward Jerusalem, kneels and prays three times a day as he always has; accused, he is thrown into the den of lions in spite of the king's efforts to save him, and the stone over its mouth is sealed with the king's signet; after a sleepless night the king hurries to the den, and Daniel answers that his God sent His angel and shut the lions' mouths, for he was found innocent; Daniel is taken up unhurt because he trusted in his God, his accusers are thrown in with their children and wives and crushed by the lions, and Darius writes to all peoples that they must tremble before the God of Daniel, the living God, whose kingdom will never be destroyed; Daniel prospers in the reign of Darius and in that of Cyrus the Persian; Hebrews 11:33 counts among the works of faith the stopping of lions' mouths"},{"p":"contents","r":"NKJV notes, note on Daniel 7:1; Daniel 7:1–28; Matthew 24:30; 26:64; Mark 14:62; Revelation 1:13–14; 13:1–7; 17:12; 20:12","v":"In the first year of Belshazzar king of Babylon Daniel has a dream and visions in the night and writes down the sum of them: the four winds of heaven stir up the Great Sea, and four great beasts come up from it, one like a lion with eagle's wings that is made to stand like a man, one like a bear with three ribs in its mouth, one like a leopard with four wings and four heads, and a fourth, terrible and strong, with iron teeth and ten horns, among which a little horn with a man's eyes and a boastful mouth uproots three; thrones are set, the Ancient of Days sits clothed in white with hair like wool on a throne of fire, countless thousands serve Him, the court sits and the books are opened; the beast is slain and burned, and One like the Son of Man comes with the clouds of heaven to the Ancient of Days and is given dominion, glory and a kingdom that will never be destroyed; one who stands by tells the troubled Daniel that the beasts are four kings, that the saints of the Most High will receive the kingdom forever, and that the ten horns are ten kings, after whom another will rise, speak against the Most High, wear out the saints and seek to change times and law for a time and times and half a time, until the court sits, his dominion is taken away and the kingdom is given to the people of the saints; Daniel keeps the matter in his heart; Jesus speaks of the Son of Man coming on the clouds of heaven (Matthew 24:30; 26:64; Mark 14:62), John sees One like the Son of Man with hair white as wool and snow (Revelation 1:13–14), a beast rising from the sea with ten horns, like a leopard, a bear and a lion, speaking great things and making war with the saints (13:1–7), ten horns that are ten kings (17:12), and books opened before God (20:12)"},{"p":"contents","r":"NKJV notes, note on Daniel 8:1; Daniel 8:1–27","v":"In the third year of King Belshazzar, after his first vision, Daniel sees himself in Shushan the citadel in the province of Elam, by the River Ulai (the book's Hebrew resumes here, by the NKJV note): a ram with two high horns pushes west, north and south and grows great, until a male goat with a notable horn between its eyes comes from the west without touching the ground, shatters the ram's horns and tramples him; the goat grows great, its large horn is broken, and four notable horns rise toward the four winds; from one of them a little horn grows great toward the south, the east and the Glorious Land, casts down some of the host of heaven and of the stars, exalts itself against the Prince of the host, takes away the daily sacrifices and casts down His sanctuary; a holy one asks how long, and the answer is two thousand three hundred days, after which the sanctuary will be cleansed; at a voice from between the banks of the Ulai, Gabriel makes Daniel understand that the vision is for the time of the end: the ram is the kings of Media and Persia, the goat the kingdom of Greece and its large horn the first king, the four horns four kingdoms from that nation, and in their latter time a fierce king skilled in schemes will rise, destroy the mighty and the holy people and stand against the Prince of princes, but be broken by no human hand; Daniel is told to seal up the vision, faints and is sick for days, then goes about the king's business, astonished"},{"p":"contents","r":"NKJV notes, note on Daniel 9:24; Daniel 9:1–27; Matthew 24:15","v":"In the first year of Darius the son of Ahasuerus, a Mede made king over the realm of the Chaldeans, Daniel learns from the books that the LORD's word by Jeremiah the prophet set seventy years for the desolations of Jerusalem; with fasting, sackcloth and ashes he confesses that Israel has sinned, rebelled and ignored the prophets, so that the curse written in the Law of Moses has been poured out on them, owns that righteousness belongs to God and shame to them, and pleads that for His own sake and His great mercies He turn His anger from Jerusalem, His holy mountain, and look on His desolate sanctuary; while he is still praying, about the time of the evening offering, Gabriel, whom he had seen in the earlier vision, comes swiftly to give him understanding, calling him greatly beloved: seventy weeks (sevens, by the NKJV note) are set for his people and holy city, to end transgression, atone for iniquity, bring in everlasting righteousness, seal up vision and prophecy and anoint the Most Holy; from the command to restore and build Jerusalem to Messiah the Prince will be seven weeks and sixty-two weeks, the city being rebuilt in troublesome times; after the sixty-two weeks Messiah will be cut off, but not for Himself, the people of the prince to come will destroy the city and the sanctuary, and one who confirms a covenant with many for a week will end sacrifice and offering in its middle, with one who makes desolate on the wing of abominations until the end; Jesus names the abomination of desolation spoken of by Daniel the prophet (Matthew 24:15)"},{"p":"contents","r":"NKJV notes, note on Daniel 10:1; NKJV notes, note on Daniel 10:4; Daniel 10:1–11:1; Jude 1:9; Revelation 1:13–15; 12:7","v":"In the third year of Cyrus king of Persia a true message is revealed to Daniel, called Belteshazzar, though its appointed time is long (or of great conflict, by the NKJV note); after mourning three full weeks without pleasant food, meat or wine, on the twenty-fourth day of the first month, by the great river Tigris (Hiddekel, by the NKJV note), he sees a man clothed in linen, girded with gold of Uphaz, his body like beryl, his face like lightning, his eyes like torches of fire and his voice like a multitude; the men with him flee in terror, and Daniel, left alone and drained of strength, falls into a deep sleep on his face; a hand touches him, and he is told, as one greatly beloved, not to fear: his words were heard from the first day, but the prince of the kingdom of Persia withstood the one sent to him twenty-one days until Michael, one of the chief princes, came to help, and now he has come to show what will befall Daniel's people in the latter days; strengthened by the touch of one in the likeness of a man, Daniel hears that the messenger must return to fight the prince of Persia, after whom the prince of Greece will come, that none upholds him but Michael, Daniel's prince, and that in the first year of Darius the Mede he stood up to strengthen him; John sees One like the Son of Man girded with a golden band, with eyes like a flame of fire and feet like fine brass (Revelation 1:13–15), Michael and his angels fight the dragon (12:7), and Jude calls him Michael the archangel (Jude 9)"},{"p":"contents","r":"NKJV notes, note on Daniel 11:30; Daniel 11:2–45; Matthew 24:15; 2 Thessalonians 2:3–4","v":"The man clothed in linen tells Daniel what is noted in the Scripture of Truth: three more kings will rise in Persia and a fourth, richer than all, will stir up all against Greece; a mighty king will rule as he pleases, but his kingdom will be broken toward the four winds and not pass to his posterity; the kings of the South and the North will make alliance by a daughter and war against each other, with armies, fortresses and spoil carried to Egypt; the king of the North will stand in the Glorious Land, give a daughter of women to destroy a kingdom, turn to the coastlands and fall; one who taxes the glorious kingdom will soon perish; a vile person will seize the kingdom by intrigue, break the prince of the covenant and defeat the king of the South, and, turned back by ships from Cyprus (Kittim, by the NKJV note), rage against the holy covenant, defile the sanctuary, take away the daily sacrifices and set up the abomination of desolation, while the people who know their God stand firm and the wise instruct many and are refined through suffering; the king will exalt himself above every god and speak against the God of gods, honor a god of fortresses, and at the time of the end sweep through the countries and the Glorious Land and rule Egypt's treasures while Edom, Moab and Ammon escape him, until, troubled by news from the east and north, he pitches his royal tents between the seas and the glorious holy mountain and comes to his end with none to help; Jesus names the abomination of desolation spoken of by Daniel the prophet (Matthew 24:15), and Paul writes of the man of sin who sets himself above every so-called god (2 Thessalonians 2:3–4)"},{"p":"contents","r":"NKJV notes, note on Daniel 12:2; Daniel 12:1–13; Matthew 24:21; John 5:28–29; Revelation 10:5–6; 12:14","v":"At that time Michael the great prince, who watches over Daniel's people, will stand up, and there will be a time of trouble such as never was, but all of his people found written in the book will be delivered; many who sleep in the dust will awake, some to everlasting life and some to shame and everlasting contempt (abhorrence, by the NKJV note), and the wise will shine like the firmament and the stars; Daniel is told to seal the book until the time of the end; two others stand on the riverbanks, and the man clothed in linen, above the waters, swears by Him who lives forever that it will be for a time, times and half a time, until the power of the holy people is shattered; the words are sealed till the end, the wise will understand and the wicked will not, and from the taking away of the daily sacrifice and the setting up of the abomination of desolation there will be one thousand two hundred and ninety days, and blessed is he who reaches the one thousand three hundred and thirty-five days; Daniel is to go his way, rest, and rise to his inheritance at the end of the days; Jesus speaks of a great tribulation such as has never been (Matthew 24:21) and of the hour when all in the graves will come forth to the resurrection of life or of condemnation (John 5:28–29), and John sees an angel raise his hand to heaven and swear by Him who lives forever (Revelation 10:5–6) and a woman nourished for a time and times and half a time (Revelation 12:14)"},{"p":"designation","r":"Daniel 1:1","v":"In the third year"},{"p":"feature","r":"NKJV notes, note on Daniel 2:4; NKJV notes, note on Daniel 8:1; Daniel 2:4; 7:28; 8:1","v":"From the middle of 2:4 to the end of chapter 7 it is written in Aramaic, and from 8:1 in Hebrew again","b":"NKJV note"},{"p":"feature","r":"Daniel 1:1–6:28; 7:1–12:13","v":"Chapters 1–6 tell of Daniel and his companions at the kings' courts; chapters 7–12 give Daniel's visions in his own words"},{"p":"feature","r":"Daniel 12:4, 9","v":"Daniel was told to shut up its words and seal the book until the time of the end","b":"inferred","c":"probable","w":"The man clothed in linen told Daniel to shut up the words and seal the book until the time of the end (Daniel 12:4), the words being closed up and sealed till then (12:9); the book is taken to be the one in which Daniel set down his visions."},{"p":"made by","r":"Daniel 7:1–2; 8:1–2; 9:2; 10:2; 12:4","e":"PER-02957","b":"inferred","c":"probable","w":"Daniel wrote down his dream of the four beasts (Daniel 7:1), the visions of chapters 7–12 are told in his own words (7:2; 8:1–2; 9:2; 10:2), and he was told to shut up the words and seal the book (12:4); chapters 1–6 tell of him by name."}],"nm":{"PER-02957":"Daniel"}},"OBJ-00552":{"k":"object","n":"The gold image Nebuchadnezzar set up","d":"The image of gold, sixty cubits high and six wide, that Nebuchadnezzar set up on the plain of Dura for all peoples to worship (Daniel 3:1–18)","f":[{"p":"designation","r":"Daniel 3:5, 7, 10, 12, 14, 18","v":"the gold image"},{"p":"height in cubits","r":"NKJV notes, note on Daniel 3:1; Daniel 3:1","v":"60 cubits"},{"p":"made by","r":"Daniel 3:1, 15","e":"PER-01162"},{"p":"material","r":"Daniel 3:1","v":"Gold"},{"p":"placed at","r":"Daniel 3:1","e":"PLC-01423"},{"p":"purpose","r":"Daniel 3:4–5, 7","v":"To be worshiped by all peoples, nations and languages at the sound of the king's music"},{"p":"width in cubits","r":"Daniel 3:1","v":"6 cubits"}],"nm":{"PER-01162":"Nebuchadnezzar","PLC-01423":"The plain of Dura"}},"OBJ-00553":{"k":"object","n":"Nebuchadnezzar's decree to worship the gold image","d":"The king's decree that all who heard his music fall down and worship the gold image, or be thrown into the furnace (Daniel 3:4–6, 10–11)","f":[{"p":"contents","r":"Daniel 3:10–11","v":"All who heard the horn, flute, harp, lyre and psaltery and all kinds of music were to fall down and worship the gold image, and whoever did not was to be thrown into a burning fiery furnace"},{"p":"designation","r":"Daniel 3:10","v":"a decree"},{"p":"made by","r":"Daniel 3:10","e":"PER-01162"},{"p":"occasion","r":"Daniel 3:4–6, 10","e":"EVT-02559"}],"nm":{"EVT-02559":"Nebuchadnezzar sets up a gold image on the plain of Dura","PER-01162":"Nebuchadnezzar"}},"OBJ-00554":{"k":"object","n":"Nebuchadnezzar's decree for the God of Shadrach, Meshach and Abed-Nego","d":"The king's decree that any people who spoke against the God of Shadrach, Meshach and Abed-Nego be cut in pieces (Daniel 3:29)","f":[{"p":"contents","r":"Daniel 3:29","v":"Any people, nation or language that spoke anything amiss against the God of Shadrach, Meshach and Abed-Nego would be cut in pieces and their houses made an ash heap, since no other god can deliver like this"},{"p":"designation","r":"Daniel 3:29","v":"a decree"},{"p":"made by","r":"Daniel 3:29","e":"PER-01162"},{"p":"occasion","r":"Daniel 3:29","e":"EVT-02564"}],"nm":{"EVT-02564":"Nebuchadnezzar blesses the God of Shadrach, Meshach and Abed-Nego","PER-01162":"Nebuchadnezzar"}},"OBJ-00555":{"k":"object","n":"Nebuchadnezzar's proclamation to all peoples","d":"The letter in which Nebuchadnezzar told all peoples, nations and languages how the Most High humbled him and restored him (Daniel 4:1–37)","f":[{"p":"designation","r":"Daniel 4:1","v":"To all peoples, nations, and languages"},{"p":"made by","r":"Daniel 4:1, 4, 18, 34, 37","e":"PER-01162"},{"p":"occasion","r":"Daniel 4:1–3, 34–37","e":"EVT-02565"},{"p":"purpose","r":"Daniel 4:2–3","v":"To declare the signs and wonders the Most High God had worked for him"}],"nm":{"EVT-02565":"Nebuchadnezzar is humbled and restored","PER-01162":"Nebuchadnezzar"}},"OBJ-00556":{"k":"object","n":"The vessels from the temple at Belshazzar's feast","d":"The gold and silver vessels that Nebuchadnezzar had taken from the temple in Jerusalem, from which Belshazzar and his lords drank (Daniel 5:2–3, 23)","f":[{"p":"designation","r":"Daniel 5:2","v":"the gold and silver vessels"},{"p":"identified with","r":"Ezra 1:7; Daniel 5:2–3","e":"OBJ-00333","b":"inferred","c":"probable","w":"Both are the articles of the house of the LORD that Nebuchadnezzar had taken from Jerusalem (Daniel 5:2–3; Ezra 1:7), which Cyrus brought out from the temple of his gods."},{"p":"material","r":"Daniel 5:2–3","v":"Gold and silver"}],"nm":{"OBJ-00333":"The temple articles Cyrus restored"}},"OBJ-00557":{"k":"object","n":"The writing on the wall of Belshazzar's palace","d":"The words the fingers of a man's hand wrote on the plaster of the palace wall at Belshazzar's feast, which Daniel read (Daniel 5:5–28)","f":[{"p":"contents","r":"NKJV notes, note on Daniel 5:25; NKJV notes, note on Daniel 5:28; Daniel 5:25–28","v":"MENE, MENE, TEKEL, UPHARSIN: by the NKJV notes, a mina (fifty shekels) from the verb to number, a shekel from the verb to weigh, and half-shekels from the verb to divide, Upharsin being the plural of Peres, which sounds like Paras, Persia"},{"p":"designation","r":"Daniel 5:7–8, 15–17, 24","v":"this writing"},{"p":"made by","r":"Daniel 5:24","e":"DEI-00001"},{"p":"placed at","r":"Daniel 4:29; 5:5","e":"PLC-01425","b":"inferred","c":"probable","w":"The hand wrote on the plaster of the wall of the king's palace (Daniel 5:5), and the palace of the king of Babylon was the royal palace of Babylon (4:29)."}],"nm":{"DEI-00001":"God","PLC-01425":"The royal palace of Babylon"}},"OBJ-00558":{"k":"object","n":"Darius's decree of thirty days","d":"The statute that for thirty days anyone who petitioned any god or man but the king be cast into the den of lions, which Darius signed (Daniel 6:7–15)","f":[{"p":"contents","r":"Daniel 6:7, 12","v":"For thirty days anyone who petitioned any god or man except the king was to be cast into the den of lions"},{"p":"designation","r":"Daniel 6:9","v":"the written decree"},{"p":"feature","r":"NKJV notes, note on Daniel 6:8; Daniel 6:8–9, 12, 15","v":"Once signed it could not be changed, by the law of the Medes and Persians, which does not alter (pass away, by the NKJV note)"},{"p":"made by","r":"Daniel 6:9","e":"PER-02966"},{"p":"occasion","r":"Daniel 6:7–9","e":"EVT-02582"}],"nm":{"EVT-02582":"The governors and satraps plot against Daniel","PER-02966":"Darius the Mede"}},"OBJ-00559":{"k":"object","n":"Darius's decree to fear the God of Daniel","d":"The letter Darius wrote to all peoples, that in every dominion of his kingdom men must tremble before the God of Daniel (Daniel 6:25–27)","f":[{"p":"contents","r":"NKJV notes, note on Daniel 6:27; Daniel 6:25–27","v":"Peace to all peoples, nations and languages; in every dominion of the kingdom men must tremble and fear before the God of Daniel, the living God, steadfast forever, whose kingdom will not be destroyed and whose rule will endure to the end, who delivers and rescues and works signs and wonders, and who delivered Daniel from the power (hand, by the NKJV note) of the lions"},{"p":"designation","r":"Daniel 6:26","v":"a decree"},{"p":"made by","r":"Daniel 6:25–26","e":"PER-02966"},{"p":"occasion","r":"Daniel 6:25–27","e":"EVT-02587"}],"nm":{"EVT-02587":"Darius decrees that all men fear the God of Daniel","PER-02966":"Darius the Mede"}},"OBJ-00560":{"k":"object","n":"The Scripture of Truth","d":"The writing in which was noted what would befall Daniel's people, from which the man clothed in linen told him of the kings to come (Daniel 10:21–12:4)","f":[{"p":"contents","r":"Daniel 10:21; 11:2–12:4","v":"What would befall Daniel's people: the kings of Persia and Greece, the wars of the kings of the South and the North, the king who would exalt himself, and the time of trouble, deliverance and resurrection at the end"},{"p":"designation","r":"Daniel 10:21","v":"the Scripture of Truth"}],"nm":{}},"OBJ-00561":{"k":"object","n":"The Book of Hosea","d":"The word the LORD gave by Hosea the son of Beeri to Israel and Judah in the days of Uzziah, Jotham, Ahaz and Hezekiah, kings of Judah, and of Jeroboam the son of Joash, king of Israel (Hosea 1–14)","f":[{"p":"contents","r":"NKJV notes, note on Hosea 1:2; NKJV notes, note on Hosea 1:6; NKJV notes, note on Hosea 1:9; Hosea 1:1–11; Romans 9:26; 1 Peter 2:10","v":"The word of the LORD comes to Hosea the son of Beeri in the days of Uzziah, Jotham, Ahaz and Hezekiah, kings of Judah, and of Jeroboam the son of Joash, king of Israel; when the LORD begins to speak by him, He tells him to take a wife of harlotry and children of harlotry, for the land has committed great harlotry (spiritual adultery, by the NKJV note) by departing from the LORD; Hosea takes Gomer the daughter of Diblaim, who bears him a son, named Jezreel, for in a little while the LORD will avenge the bloodshed of Jezreel on the house of Jehu, end the kingdom of the house of Israel and break Israel's bow in the Valley of Jezreel; she bears a daughter, named Lo-Ruhamah (No-Mercy, by the NKJV note), for the LORD will no longer have mercy on the house of Israel, though He will save the house of Judah by the LORD their God, not by bow, sword or horsemen; after weaning her she bears a son, named Lo-Ammi (Not-My-People, by the NKJV note), for they are not His people; yet the children of Israel will be as countless as the sand of the sea, and where they were told they were not His people they will be called the sons of the living God, words Paul quotes (Romans 9:26) and Peter takes up (1 Peter 2:10); Judah and Israel will be gathered together under one head and come up out of the land, for the day of Jezreel will be great"},{"p":"contents","r":"NKJV notes, note on Hosea 2:1; NKJV notes, note on Hosea 2:16; NKJV notes, note on Hosea 2:22; Hosea 2:1–23; Romans 9:25; 1 Peter 2:10","v":"Israel's children are to call their brethren and sisters 'My people' and 'Mercy is shown' (Ammi and Ruhamah, by the NKJV notes) and to bring charges against their mother, no longer the LORD's wife, who went after lovers she thought gave her bread, water, wool, linen, oil and drink, not knowing that the LORD gave her grain, new wine, oil, silver and gold, which they used for Baal; so He will hedge up her way with thorns, take back His gifts, uncover her lewdness before her lovers, end her feasts, New Moons and Sabbaths, lay waste her vines and fig trees and punish her for the days of the Baals; then He will allure her into the wilderness and speak comfort to her, give her the Valley of Achor as a door of hope, and she will sing as when she came up from Egypt; she will call Him 'My Husband' and no longer 'My Master' (Ishi and Baali, by the NKJV notes), and the names of the Baals will be forgotten; He will make a covenant for them with the beasts, shatter bow and sword, betroth her to Himself forever in righteousness, justice, lovingkindness, mercy and faithfulness, and answer the heavens, which will answer the earth with grain, new wine and oil, and they Jezreel (God Will Sow, by the NKJV note); He will have mercy on her who had not obtained mercy and call those who were not His people His people, words Paul quotes (Romans 9:25) and Peter takes up (1 Peter 2:10)"},{"p":"contents","r":"NKJV notes, note on Hosea 3:1; Hosea 3:1–5","v":"The LORD tells Hosea to go again and love a woman loved by a lover (friend or husband, by the NKJV note) and committing adultery, as the LORD loves the children of Israel, who look to other gods and love the raisin cakes of the pagans; Hosea buys her for fifteen shekels of silver and one and one-half homers of barley and tells her to stay with him many days, without playing the harlot or having a man, and he will be the same toward her; so the children of Israel will abide many days without king or prince, sacrifice or sacred pillar, ephod or teraphim, and afterward return and seek the LORD their God and David their king, and fear the LORD and His goodness in the latter days"},{"p":"contents","r":"NKJV notes, note on Hosea 4:1; NKJV notes, note on Hosea 4:12; NKJV notes, note on Hosea 4:15; Hosea 4:1–19","v":"The LORD brings a charge (a legal complaint, by the NKJV note) against the inhabitants of the land: there is no truth, mercy or knowledge of God, but swearing, lying, killing, stealing and adultery, so the land will mourn and all in it waste away; His people are destroyed for lack of knowledge, and because the priests have rejected knowledge and forgotten His law He will reject them and forget their children; they feed on the people's sin, and it will be like people, like priest; the people ask counsel of wooden idols and a staff (a diviner's rod, by the NKJV note), sacrifice on the mountaintops and burn incense under the trees, while the men go apart with harlots; though Israel plays the harlot, Judah is not to offend nor go up to Gilgal or Beth Aven (House of Idolatry or Wickedness, by the NKJV note), for Israel is stubborn like a stubborn calf, Ephraim is joined to idols and is to be let alone, and the wind has wrapped her up in its wings"},{"p":"contents","r":"NKJV notes, note on Hosea 5:7; NKJV notes, note on Hosea 5:15; Hosea 5:1–15","v":"The priests, the house of Israel and the house of the king are told that the judgment is theirs, for they have been a snare at Mizpah and a net spread on Tabor; the LORD knows Ephraim, the spirit of harlotry is in their midst and they do not know the LORD, so Israel and Ephraim stumble in their iniquity and Judah with them; they will seek the LORD with flocks and herds and not find Him, for they have begotten pagan children (strange, by the NKJV note); the ram's horn is to sound in Gibeah and the trumpet in Ramah, and the cry go up at Beth Aven, for Ephraim will be desolate and the LORD's wrath poured out on the princes of Judah; He will be like a moth to Ephraim and rottenness to Judah; when Ephraim saw his sickness he went to Assyria and sent to King Jareb, who cannot heal him; the LORD will be like a lion to Ephraim and Judah, tear them and go away, and return to His place till they acknowledge their offense and seek His face in their affliction"},{"p":"contents","r":"NKJV notes, note on Hosea 6:1; NKJV notes, note on Hosea 6:6; NKJV notes, note on Hosea 6:7; Hosea 6:1–11; Matthew 9:13; 12:7","v":"Come, let us return to the LORD, who has torn and will heal and bind up (bandage, by the NKJV note), revive us after two days, raise us up on the third day, and come to us like the rain; but the LORD asks what He shall do with Ephraim and Judah, whose faithfulness is like a morning cloud and the early dew, so He has hewn them by the prophets, for He desires mercy (or faithfulness or loyalty, by the NKJV note) and not sacrifice, and the knowledge of God more than burnt offerings, words Jesus bids His hearers learn (Matthew 9:13; 12:7); like men (or Adam, by the NKJV note) they transgressed the covenant; Gilead is a city of evildoers, defiled with blood, the company of priests murder on the way to Shechem, Ephraim's harlotry is a horrible thing in the house of Israel, and a harvest is appointed for Judah when the LORD returns the captives of His people"},{"p":"contents","r":"NKJV notes, note on Hosea 7:11; Hosea 7:1–16","v":"When the LORD would heal Israel, the iniquity of Ephraim and the wickedness of Samaria are uncovered: fraud, thieves and robbers; they make the king glad with their wickedness and the princes with lies; they are all adulterers, hot like a baker's oven, and on the day of their king the princes made him sick with wine; they devour their judges, all their kings have fallen, and none calls on the LORD; Ephraim has mixed himself among the peoples, a cake unturned, his strength devoured by aliens and gray hairs on him unawares; like a silly dove without sense (heart, by the NKJV note) they call to Egypt and go to Assyria, but the LORD will spread His net on them; woe to them, for though He redeemed them they speak lies against Him, wail on their beds without crying to Him, and turn, but not to the Most High, like a treacherous bow; their princes will fall by the sword, and this will be their derision in the land of Egypt"},{"p":"contents","r":"NKJV notes, note on Hosea 8:1; NKJV notes, note on Hosea 8:5; NKJV notes, note on Hosea 8:14; Hosea 8:1–14","v":"The trumpet (ram's horn, by the NKJV note) is to be set to the mouth, for one comes like an eagle against the house of the LORD because they transgressed His covenant; Israel cries that it knows Him but has rejected the good; they set up kings and princes the LORD did not choose and made idols of their silver and gold; the calf of Samaria (a golden calf image, by the NKJV note), made by a workman and not God, will be broken in pieces; they sow the wind and reap the whirlwind, and Israel is swallowed up among the Gentiles; they have gone up to Assyria like a wild donkey, and Ephraim has hired lovers and will sorrow under the burden of the king of princes; Ephraim has made many altars for sin and counts the LORD's law a strange thing, so they will return to Egypt; Israel has forgotten his Maker and built temples (or palaces, by the NKJV note), and Judah has multiplied fortified cities, but fire will devour his cities and palaces"},{"p":"contents","r":"NKJV notes, note on Hosea 9:8; Hosea 9:1–17","v":"Israel is not to rejoice like other peoples, for it has played the harlot against its God; the threshing floor and winepress will not feed them, they will not dwell in the LORD's land, Ephraim will return to Egypt and eat unclean things in Assyria, their offerings will be like mourners' bread, and Egypt will gather them up and Memphis bury them; the days of punishment have come, and the prophet is a fool and a fowler's snare (one who traps birds, by the NKJV note); they are deeply corrupted as in the days of Gibeah; the LORD found Israel like grapes in the wilderness, but their fathers went to Baal Peor and became an abomination like what they loved; Ephraim's glory will fly away like a bird, without birth or conception, and he will bring out his children to the murderer; all their wickedness is in Gilgal, where the LORD hated them and will drive them from His house; Ephraim is stricken, its root dried up, and they will be wanderers among the nations"},{"p":"contents","r":"NKJV notes, note on Hosea 10:2; NKJV notes, note on Hosea 10:5; NKJV notes, note on Hosea 10:8; Hosea 10:1–15; Luke 23:30; Revelation 6:16","v":"Israel empties his vine and has increased his altars and sacred pillars with his fruit; their heart is divided (in loyalty, by the NKJV note), and the LORD will break down their altars; they say they have no king, and swear falsely; the people of Samaria fear for the calf of Beth Aven (calves, images, by the NKJV note), whose glory has departed, and it will be carried to Assyria as a present for King Jareb; Samaria's king is cut off like a twig on the water; the high places of Aven, the sin of Israel, will be destroyed, and they will say to the mountains 'Cover us!' and to the hills 'Fall on us!', words Jesus takes up (Luke 23:30) and John hears again (Revelation 6:16); Israel has sinned since the days of Gibeah, and peoples will be gathered against them; Ephraim, a heifer that loves to thresh, will pull the plow; they are to sow righteousness, reap in mercy and break up their fallow ground, for it is time to seek the LORD, but they have plowed wickedness and trusted in their mighty men, so their fortresses will be plundered as Shalman plundered Beth Arbel, and at dawn the king of Israel will be cut off"},{"p":"contents","r":"NKJV notes, note on Hosea 11:1; NKJV notes, note on Hosea 11:4; Hosea 11:1–12; Matthew 2:15","v":"When Israel was a child the LORD loved him and called His son out of Egypt, words Matthew says were fulfilled when Jesus came out of Egypt (Matthew 2:15); but they sacrificed to the Baals; He taught Ephraim to walk and drew them with gentle cords (cords of a man, by the NKJV note), with bands of love, and stooped to feed them; they will not return to Egypt, but the Assyrian will be their king and the sword will slash in their cities, for His people are bent on backsliding; yet He asks how He can give up Ephraim or make him like Admah and Zeboiim: His heart churns, and He will not destroy Ephraim again, for He is God and not man, the Holy One in their midst; they will walk after the LORD, who will roar like a lion, and His sons will come trembling from the west, from Egypt and from Assyria, to dwell in their houses; Ephraim has encircled Him with lies, but Judah still walks with God"},{"p":"contents","r":"NKJV notes, note on Hosea 12:1; NKJV notes, note on Hosea 12:2; NKJV notes, note on Hosea 12:7; Hosea 12:1–14","v":"Ephraim feeds on the wind and increases lies and desolation (ruin, by the NKJV note), makes a covenant (or treaty, by the NKJV note) with the Assyrians and carries oil to Egypt; the LORD brings a charge against Judah and will punish Jacob, who took his brother by the heel in the womb, struggled with God, with the Angel, and prevailed, wept and sought His favor, and found Him in Bethel, where He spoke with us: the LORD God of hosts, whose memorable name is the LORD; they are to return, keep mercy and justice and wait on God; Ephraim is a cunning Canaanite (or merchant, by the NKJV note) with deceitful scales who boasts that he has become rich without sin; the LORD, their God since Egypt, will again make them dwell in tents as in the days of the appointed feast, and has spoken by the prophets with visions and symbols; Gilead's idols are vanity, and the altars of Gilgal will be heaps in the furrows; Jacob fled to the country of Syria and served for a wife, tending sheep; by a prophet the LORD brought Israel out of Egypt and kept him; Ephraim provoked Him bitterly, and his Lord will leave his bloodshed on him"},{"p":"contents","r":"NKJV notes, note on Hosea 13:2; NKJV notes, note on Hosea 13:14; Hosea 13:1–16; 1 Corinthians 15:55","v":"When Ephraim spoke, men trembled and he was exalted in Israel, but he offended through Baal and died; now they sin more, make molded idols of silver, the work of craftsmen, and say that the men who sacrifice should kiss the calves (worship with kisses, by the NKJV note); so they will pass away like the morning cloud, the dew, chaff and smoke; the LORD has been their God since Egypt, there is no savior besides Him, and He knew them in the wilderness, but when they were filled they forgot Him, so He will meet them like a lion, a leopard and a bear robbed of her cubs; He will be their King, who gave them a king in His anger and took him away in His wrath; Ephraim's iniquity is stored up; yet He will ransom them from the power of the grave (or Sheol, by the NKJV note) and redeem them from death: O Death, He will be its plagues, O Grave its destruction, words Paul takes up as death is swallowed in victory (1 Corinthians 15:55); an east wind, the wind of the LORD, will dry up Ephraim's spring, and Samaria, which rebelled against her God, will fall by the sword"},{"p":"contents","r":"NKJV notes, note on Hosea 14:2; Hosea 14:1–9; Hebrews 13:15","v":"Israel is to return to the LORD with words, asking Him to take away all iniquity and receive them graciously, offering the sacrifices of their lips (bull calves, the Septuagint having fruit, by the NKJV note), as Hebrews speaks of the fruit of our lips (Hebrews 13:15), and saying that Assyria will not save them, that they will not ride on horses, nor call the work of their hands their gods; the LORD will heal their backsliding and love them freely, be like the dew to Israel, who will grow like the lily and root like Lebanon, with the beauty of the olive and the fragrance of Lebanon; Ephraim will have nothing more to do with idols, and the LORD is like a green cypress tree in whom his fruit is found; the wise will understand, for the ways of the LORD are right: the righteous walk in them, but transgressors stumble in them"},{"p":"designation","r":"Hosea 1:1","v":"The word of the LORD"},{"p":"feature","r":"Hosea 1:1","v":"The word of the LORD came to Hosea in the days of Uzziah, Jotham, Ahaz and Hezekiah, kings of Judah, and of Jeroboam the son of Joash, king of Israel"},{"p":"feature","r":"Hosea 1:2–2:1; 3:1–5","v":"Hosea's marriage to a wife of harlotry, the names of her children and his buying of an adulterous woman are signs of Israel's unfaithfulness to the LORD and of His mercy to come"},{"p":"feature","r":"Hosea 14:9","v":"It ends with a word to the wise and prudent: the ways of the LORD are right, and the righteous walk in them, but transgressors stumble in them"},{"p":"made by","r":"Hosea 1:1; 3:1–3","e":"PER-02968","b":"inferred","c":"probable","w":"The book is the word of the LORD that came to Hosea (Hosea 1:1), and Hosea tells chapter 3 in his own words (3:1–3)."}],"nm":{"PER-02968":"Hosea"}},"OBJ-00562":{"k":"object","n":"The Book of Joel","d":"The word the LORD gave by Joel the son of Pethuel: the locusts, the day of the LORD, the Spirit poured out and the judgment of the nations (Joel 1–3)","f":[{"p":"contents","r":"NKJV notes, note on Joel 1:4; NKJV notes, note on Joel 1:19; Joel 1:1–20","v":"The word of the LORD comes to Joel the son of Pethuel: the elders and all who live in the land are to tell their children's children of something unheard of, how the chewing, swarming, crawling and consuming locusts (whose exact kinds are unknown, by the NKJV note) have eaten what each left; a nation strong and without number, with a lion's teeth, has laid waste the LORD's vine and fig tree; the drunkards are to weep and the land is to lament like a young widow, for the grain and drink offerings are cut off from the house of the LORD, the grain, new wine and oil fail, and the trees wither; the priests are to put on sackcloth, consecrate a fast, call a sacred assembly and cry out to the LORD, for the day of the LORD is at hand, coming as destruction from the Almighty; the seed shrivels and the barns are broken down, the herds groan for want of pasture, and fire has devoured the open pastures (pastures of the wilderness, by the NKJV note) while the water brooks dry up"},{"p":"contents","r":"NKJV notes, note on Joel 2:1; NKJV notes, note on Joel 2:23; NKJV notes, note on Joel 2:32; Joel 2:1–32; Acts 2:16–21; Romans 10:13","v":"The trumpet (ram's horn, by the NKJV note) is to sound in Zion, for the day of the LORD comes, a day of darkness, with a people great and strong whose like has never been: fire goes before them, the land is like the garden of Eden before them and a wilderness behind; they look like horses, run like mighty men, climb the walls and enter the windows like a thief; the earth quakes, the sun and moon grow dark, and the LORD gives voice before His army; so the LORD calls His people to turn to Him with all their heart, to rend their heart and not their garments, for He is gracious and merciful, slow to anger and relents from harm; all are to gather for a fast, and the priests weep between the porch and the altar, asking Him to spare His people; then the LORD will be zealous for His land, send grain, new wine and oil, drive the northern army into a barren land, give the former and latter rain, and restore the years the locusts have eaten, His great army sent among them, so that they will know He is in the midst of Israel; afterward He will pour out His Spirit on all flesh, so that sons and daughters prophesy, old men dream dreams and young men see visions, and show wonders in the heavens and earth, the sun turned to darkness and the moon to blood before the great and awesome day of the LORD; and whoever calls on the name of the LORD will be saved, words Peter quotes as spoken by the prophet Joel (Acts 2:16–21) and Paul quotes (Romans 10:13)"},{"p":"contents","r":"NKJV notes, note on Joel 3:8; NKJV notes, note on Joel 3:18; Joel 3:1–21; Revelation 14:15–19","v":"When the LORD brings back the captives of Judah and Jerusalem, He will gather all nations into the Valley of Jehoshaphat and judge them for scattering His people Israel, dividing up His land and casting lots for His people, trading a boy for a harlot and a girl for wine; Tyre, Sidon and all the coasts of Philistia, who took His silver and gold into their temples and sold the people of Judah and Jerusalem to the Greeks, will have it returned on their heads, their own children sold by Judah to the Sabeans (Shebaites, by the NKJV note); the nations are to prepare for war and beat their plowshares into swords and their pruning hooks into spears, and come up to the valley, where the LORD will sit to judge them: the sickle is to be put in, for the harvest is ripe and the winepress full, as John sees the sickle thrust in and the winepress of God's wrath (Revelation 14:15–19); multitudes fill the valley of decision, for the day of the LORD is near; the LORD will roar from Zion and be a shelter for His people, and Jerusalem will be holy; in that day the mountains will drip new wine, a fountain from the house of the LORD will water the Valley of Acacias (Shittim, by the NKJV note), Egypt and Edom will be desolate for their violence against Judah, and Judah will abide forever, for the LORD dwells in Zion"},{"p":"designation","r":"Joel 1:1","v":"The word of the LORD"},{"p":"feature","r":"Joel 1:1","v":"Its heading names no king and gives no date"},{"p":"feature","r":"Joel 1:4; 2:1, 28; 3:2","v":"It turns from a plague of locusts in Joel's day to the day of the LORD, the Spirit poured out on all flesh, and the judgment of the nations"},{"p":"made by","r":"Joel 1:1; Acts 2:16","e":"PER-02977","b":"inferred","c":"probable","w":"The book is the word of the LORD that came to Joel (Joel 1:1), and Peter cites its words as spoken by the prophet Joel (Acts 2:16)."}],"nm":{"PER-02977":"Joel"}},"OBJ-00563":{"k":"object","n":"The Book of Amos","d":"The words Amos, one of the sheepbreeders of Tekoa, saw concerning Israel in the days of Uzziah king of Judah and of Jeroboam the son of Joash, king of Israel, two years before the earthquake (Amos 1–9)","f":[{"p":"contents","r":"NKJV notes, note on Amos 1:5; Amos 1:1–15","v":"The words Amos, one of the sheepbreeders of Tekoa, saw concerning Israel in the days of Uzziah king of Judah and of Jeroboam the son of Joash, king of Israel, two years before the earthquake: the LORD roars from Zion and utters His voice from Jerusalem, and the shepherds' pastures mourn and the top of Carmel withers; for three transgressions and for four He will not turn back the punishment of Damascus, which threshed Gilead with iron implements, but will send fire on the house of Hazael and the palaces of Ben-Hadad, break the gate bar of Damascus, cut off the inhabitant of the Valley of Aven and the one who holds the scepter (rules, by the NKJV note) in Beth Eden (House of Eden, by the NKJV note), and the people of Syria will go captive to Kir; nor that of Gaza, which carried a whole people captive to hand them over to Edom, so that fire will devour its wall and palaces, Ashdod, Ashkelon and Ekron will be cut off and the remnant of the Philistines perish; nor that of Tyre, which handed a whole people over to Edom and forgot the covenant of brotherhood; nor that of Edom, which pursued his brother with the sword without pity and kept his wrath forever, so that fire will come on Teman and the palaces of Bozrah; nor that of the people of Ammon, who ripped open the women with child in Gilead to enlarge their territory, so that fire will devour the wall and palaces of Rabbah amid shouting and storm, and their king and his princes will go into captivity together"},{"p":"contents","r":"NKJV notes, note on Amos 2:7; NKJV notes, note on Amos 2:8; NKJV notes, note on Amos 2:13; Amos 2:1–16","v":"For three transgressions and for four the LORD will not turn back the punishment of Moab, which burned the bones of the king of Edom to lime, so that fire will devour the palaces of Kerioth and Moab will die amid tumult, its judge and princes slain; nor that of Judah, which despised the law of the LORD and was led astray by the lies its fathers followed, so that fire will devour the palaces of Jerusalem; nor that of Israel, which sells the righteous for silver and the poor for a pair of sandals, pants after (or tramples on, by the NKJV note) the dust on the head of the poor, where a man and his father go in to the same girl, and which lies down by every altar on clothes taken in pledge and drinks the wine of the condemned (or of those punished by fines, by the NKJV note) in the house of its god, though the LORD destroyed the Amorite before them, brought them up from Egypt, led them forty years through the wilderness and raised up prophets and Nazirites from their sons, whom they made drink wine and forbade to prophesy; He is weighed down by them (or tottering under them, by the NKJV note) like a cart full of sheaves, and in that day neither the swift, the strong, the archer nor the horseman will escape, and the bravest of the mighty will flee naked"},{"p":"contents","r":"NKJV notes, note on Amos 3:9; NKJV notes, note on Amos 3:12; NKJV notes, note on Amos 3:15; Amos 3:1–15","v":"The LORD speaks against the children of Israel, the whole family He brought up from Egypt: He has known them only of all the families of the earth, so He will punish them for all their iniquities; as two do not walk together unless agreed, and a lion does not roar without prey, so calamity does not come on a city unless the LORD has done it, and He does nothing without revealing His secret to His servants the prophets: when the lion has roared all fear, and when the Lord GOD has spoken who can but prophesy; the palaces at Ashdod (Assyria in the Septuagint, by the NKJV note) and in Egypt are to gather on the mountains of Samaria and see the tumult and oppression within her, whose people store up violence and robbery in their palaces; an adversary will surround the land and plunder them, and as a shepherd snatches two legs or a piece of an ear from a lion's mouth, so the children of Israel who dwell in Samaria will be taken out, with a bed's corner and a couch's edge (the Hebrew uncertain, by the NKJV note); in the day He punishes Israel He will destroy the altars of Bethel, cutting off the horns of the altar, and strike the winter house with the summer house, and the houses of ivory and the great houses will end"},{"p":"contents","r":"NKJV notes, note on Amos 4:4; NKJV notes, note on Amos 4:6; NKJV notes, note on Amos 4:13; Amos 4:1–13","v":"The cows of Bashan on the mountain of Samaria, who oppress the poor, crush the needy and bid their husbands bring them wine, will be taken away with fishhooks, as the Lord GOD has sworn by His holiness, going out through broken walls each straight ahead and cast into Harmon; Israel is told to come to Bethel and transgress and to multiply transgression at Gilgal, with sacrifices every morning, tithes every three days (or years, by the NKJV note), thanksgiving with leaven and freewill offerings proclaimed, for this they love; the LORD gave them hunger (cleanness of teeth, by the NKJV note), withheld rain three months before the harvest and rained on one city and not another, struck them with blight and mildew and let the locust devour their gardens, vineyards, fig trees and olive trees, sent a plague after the manner of Egypt and killed their young men with the sword, and overthrew some of them as God overthrew Sodom and Gomorrah, so that they were like a firebrand plucked from the burning; yet after each they did not return to Him, so Israel is to prepare to meet its God, who forms the mountains, creates the wind (or spirit, by the NKJV note), declares to man his thought, makes the morning darkness and treads the high places of the earth, the LORD God of hosts"},{"p":"contents","r":"NKJV notes, note on Amos 5:11; NKJV notes, note on Amos 5:26; Amos 5:1–27; Acts 7:42–43","v":"Amos takes up a lament for the house of Israel: the virgin of Israel has fallen to rise no more, and the city that went out by a thousand will have a hundred left; the LORD bids them seek Him and live, not Bethel, Gilgal or Beersheba, for Gilgal will go into captivity and Bethel come to nothing, lest He break out like fire in the house of Joseph; He made the Pleiades and Orion and turns the shadow of death into morning, but they turn justice to wormwood, hate the one who rebukes in the gate, trample the poor and take bribes, so they will not live in their houses of hewn stone nor drink the wine of their pleasant (desirable, by the NKJV note) vineyards; they are to seek good and not evil, hate evil, love good and establish justice in the gate, and it may be the LORD God of hosts will be gracious to the remnant of Joseph; there will be wailing in every street and vineyard when He passes through; woe to those who desire the day of the LORD, for it is darkness and not light, as when one flees a lion and meets a bear; He hates their feasts and will not accept their offerings or hear their songs, but let justice run down like water and righteousness like a mighty stream; they did not offer Him sacrifices forty years in the wilderness, but carried Sikkuth (the tabernacle of Moloch in the Septuagint, by the NKJV note) their king and Chiun, the star of their gods, so He will send them into captivity beyond Damascus, words Stephen quotes (Acts 7:42–43)"},{"p":"contents","r":"NKJV notes, note on Amos 6:13; Amos 6:1–14","v":"Woe to those at ease in Zion and trusting in Mount Samaria, the notable persons of the chief nation: let them look at Calneh, Hamath the great and Gath of the Philistines, and see whether they are better than these kingdoms; they put off the day of doom, lie on beds of ivory, eat lambs and calves, sing idly to stringed instruments and invent instruments like David, drink wine from bowls and anoint themselves with the best ointments, but do not grieve for the affliction of Joseph, so they will go captive first; the Lord GOD swears by Himself that He abhors the pride of Jacob and will deliver up the city: if ten men are left in a house they will die, and the one who carries out the bodies will not dare to mention the name of the LORD; He will break the great house and the little house; they have turned justice into gall and rejoice over Lo Debar (Nothing, by the NKJV note) and taking Karnaim (Horns, by the NKJV note) by their own strength, so He will raise up a nation to afflict the house of Israel from the entrance of Hamath to the Valley of the Arabah"},{"p":"contents","r":"NKJV notes, note on Amos 7:1; NKJV notes, note on Amos 7:4; Amos 7:1–17","v":"The Lord GOD shows Amos locust swarms formed at the sprouting (by the NKJV note) of the late crop after the king's mowings, and a fire called to contend (by the NKJV note) that consumes the great deep and the land; at Amos's plea that Jacob may stand, for he is small, the LORD relents of both; then the Lord stands on a wall with a plumb line and sets it among His people Israel: the high places of Isaac will be desolate, the sanctuaries laid waste, and He will rise with the sword against the house of Jeroboam; Amaziah the priest of Bethel tells Jeroboam king of Israel that Amos has conspired against him, and bids Amos, as a seer, flee to Judah and prophesy no more at Bethel, the king's sanctuary; Amos answers that he was no prophet nor a prophet's son, but a sheepbreeder and tender of sycamore fruit whom the LORD took from following the flock and sent to prophesy to Israel, and foretells that Amaziah's wife will be a harlot in the city, his sons and daughters fall by the sword, his land be divided and he die in a defiled land, and that Israel will surely go captive from its land"},{"p":"contents","r":"NKJV notes, note on Amos 8:8; NKJV notes, note on Amos 8:14; Amos 8:1–14","v":"The Lord GOD shows Amos a basket of summer fruit: the end has come on His people Israel, the songs of the temple will be wailing and dead bodies be thrown out in silence; those who swallow up the needy, impatient for the New Moon and the Sabbath to pass so they may sell grain with a small ephah, a large shekel and false scales, buying the poor for silver and the needy for sandals, will not be forgotten, for the LORD has sworn by the pride of Jacob; the land will heave like the River (the Nile, by the NKJV note), the sun will go down at noon, feasts will turn to mourning as for an only son, and a famine will come, not of bread or water but of hearing the words of the LORD, so that they wander from sea to sea seeking it and do not find it; those who swear by the sin of Samaria (or Ashima, a Syrian goddess, by the NKJV note), the god of Dan and the way of Beersheba will fall, never to rise"},{"p":"contents","r":"NKJV notes, note on Amos 9:2; NKJV notes, note on Amos 9:7; NKJV notes, note on Amos 9:11; Amos 9:1–15; Acts 15:16–17","v":"Amos sees the Lord standing by the altar, who bids the doorposts be struck so that the thresholds shake: none will escape, though they dig into hell (or Sheol, by the NKJV note), climb to heaven, hide on Carmel or at the bottom of the sea, or go into captivity, for He has set His eyes on them for harm; He touches the earth and it melts; the children of Israel are to Him like the people of Ethiopia, and as He brought Israel up from Egypt He brought the Philistines from Caphtor (Crete, by the NKJV note) and the Syrians from Kir; He will destroy the sinful kingdom from the face of the earth, yet not utterly destroy the house of Jacob, but sift the house of Israel among the nations as grain in a sieve, and all the sinners of His people will die by the sword; on that day He will raise up the fallen tabernacle of David (a booth, a figure of a deposed dynasty, by the NKJV note) and rebuild it as in the days of old, that they may possess the remnant of Edom and all the Gentiles called by His name, words James quotes (Acts 15:16–17); the plowman will overtake the reaper and the mountains drip sweet wine, and He will bring back the captives of His people Israel, who will rebuild the waste cities, plant vineyards and gardens, and never again be pulled up from their land"},{"p":"designation","r":"Amos 1:1","v":"The words of Amos"},{"p":"feature","r":"Amos 1:1","v":"Its heading dates the words two years before the earthquake, in the days of Uzziah king of Judah and of Jeroboam the son of Joash, king of Israel"},{"p":"feature","r":"Amos 1:3–2:16","v":"Its words on Damascus, Gaza, Tyre, Edom, Ammon, Moab, Judah and Israel each begin with three transgressions and for four; seven end with a fire the LORD sends, and Israel's with the flight of its mighty men"},{"p":"feature","r":"Amos 7:1–9; 8:1–3; 9:1–4","v":"Five visions the Lord GOD showed Amos, told in his own words: locusts and fire, which the LORD turned back at his plea, a plumb line, a basket of summer fruit, and the Lord standing by the altar"},{"p":"feature","r":"Amos 9:11–15; Acts 15:16–17","v":"It ends with the LORD's promise to raise up the fallen tabernacle of David and to plant Israel in its land, never again to be pulled up, words James quotes"},{"p":"made by","r":"Amos 1:1; 7:1–8; 8:1–2","e":"PER-02979","b":"inferred","c":"probable","w":"The book is the words of Amos, which he saw (Amos 1:1), and Amos tells his visions in his own words (7:1–8; 8:1–2)."}],"nm":{"PER-02979":"Amos"}},"OBJ-00564":{"k":"object","n":"The Book of Obadiah","d":"The vision of Obadiah, in which the Lord GOD speaks concerning Edom and the kingdom that shall be His (Obadiah 1:1–21)","f":[{"p":"contents","r":"NKJV notes, note on Obadiah 1:7; NKJV notes, note on Obadiah 1:12; NKJV notes, note on Obadiah 1:19; NKJV notes, note on Obadiah 1:21; Obadiah 1:1–21","v":"The vision of Obadiah: the Lord GOD speaks concerning Edom, against whom a messenger has roused the nations to battle; He will make Edom small and despised, and though the pride of its heart has deceived it in the clefts of the rock, and it sets its nest among the stars, He will bring it down; thieves and grape-gatherers would leave something, but Esau will be searched out, his allies will deceive him and lay a trap (or wound, by the NKJV note), and the wise men of Edom and the mighty men of Teman will be cut off; for violence against his brother Jacob shame will cover him, for he stood aloof and was as one of the strangers who carried Jacob's forces captive and cast lots for Jerusalem, and he should not have gloated (by the NKJV note) over the children of Judah, entered the gate of the LORD's people, laid hands on their goods or stood at the crossroads to cut off those who escaped; the day of the LORD on all the nations is near, and as Edom has done it will be done to it; on Mount Zion there will be deliverance and holiness, the house of Jacob will be a fire, the house of Joseph a flame and the house of Esau stubble; the South (the Negev, by the NKJV note) will possess the mountains of Esau, the Lowland Philistia, Benjamin Gilead, Israel's captives the land as far as Zarephath, and the captives of Jerusalem in Sepharad the cities of the South; saviors (deliverers, by the NKJV note) will come to Mount Zion to judge the mountains of Esau, and the kingdom will be the LORD's"},{"p":"designation","r":"Obadiah 1:1","v":"The vision of Obadiah"},{"p":"feature","r":"Obadiah 1:1","v":"Its heading names no king and gives no date"},{"p":"feature","r":"Jeremiah 49:9–10, 14–16; Obadiah 1:1–6","v":"Its first words on Edom agree closely with Jeremiah's word against Edom: the messenger sent among the nations, Edom made small, deceived by the pride of its heart in the clefts of the rock and brought down from a nest as high as the eagle's, and the thieves and grape-gatherers who would leave something"},{"p":"feature","r":"Obadiah 1:1–21","v":"It is the shortest book of the Old Testament, one chapter of twenty-one verses"},{"p":"made by","r":"Obadiah 1:1","e":"PER-02981","b":"inferred","c":"probable","w":"The book is the vision of Obadiah, in which the Lord GOD speaks concerning Edom (Obadiah 1:1)."}],"nm":{"PER-02981":"Obadiah"}},"OBJ-00565":{"k":"object","n":"The Book of Jonah","d":"The account of Jonah the son of Amittai, whom the LORD sent to cry out against Nineveh: his flight toward Tarshish, the great fish, his preaching, Nineveh's repentance and the LORD's pity on the city (Jonah 1–4)","f":[{"p":"contents","r":"NKJV notes, note on Jonah 1:4; NKJV notes, note on Jonah 1:9; Jonah 1:1–17; Matthew 12:40","v":"The word of the LORD comes to Jonah the son of Amittai to go and cry out against Nineveh, that great city, for its wickedness has come up before Him; but Jonah flees from the presence of the LORD, goes down to Joppa and pays the fare of a ship going to Tarshish; the LORD hurls (by the NKJV note) a great wind on the sea, so that the ship is about to break up; the mariners cry each to his god and throw the cargo overboard, while Jonah sleeps in the lowest part of the ship until the captain wakes him to call on his God; the lot falls on Jonah, who tells them he is a Hebrew who fears the LORD (YHWH, by the NKJV note), the God of heaven, who made the sea and the dry land, and that the storm is because of him, so they must throw him in; they row hard to reach land and cannot, pray the LORD not to charge them with innocent blood, and throw him into the sea, which stops its raging; they fear the LORD exceedingly, offer a sacrifice and take vows; the LORD has prepared a great fish to swallow Jonah, and he is in its belly three days and three nights, as Jesus says the Son of Man will be in the heart of the earth (Matthew 12:40)"},{"p":"contents","r":"NKJV notes, note on Jonah 2:6; NKJV notes, note on Jonah 2:8; Jonah 2:1–10","v":"From the fish's belly Jonah prays to the LORD his God: he cried out of the belly of Sheol and the LORD heard him; cast into the deep, with the floods around him and weeds wrapped around his head, he went down to the moorings (foundations or bases, by the NKJV note) of the mountains, yet the LORD brought his life up from the pit; when his soul fainted he remembered the LORD, and his prayer came to His holy temple; those who regard worthless idols forsake their own Mercy (or Lovingkindness, by the NKJV note), but he will sacrifice with thanksgiving and pay what he has vowed, for salvation is of the LORD; at the LORD's word the fish vomits Jonah onto dry land"},{"p":"contents","r":"NKJV notes, note on Jonah 3:3; NKJV notes, note on Jonah 3:7; Jonah 3:1–10; Matthew 12:41; Luke 11:30, 32","v":"The word of the LORD comes to Jonah a second time, and he goes to Nineveh, an exceedingly great city of three days' journey (the exact meaning unknown, by the NKJV note), and on the first day's walk cries out that in forty days it will be overthrown; the people of Nineveh believe God, proclaim a fast and put on sackcloth, from the greatest to the least; the king rises from his throne, puts on sackcloth and sits in ashes, and by the decree of the king and his nobles (great ones, by the NKJV note) neither man nor beast is to eat or drink, but all are to be covered with sackcloth, cry mightily to God and turn from their evil way and violence, in hope that God will relent; God sees their works and relents from the disaster He had said He would bring, as Jesus says the men of Nineveh repented at the preaching of Jonah (Matthew 12:41; Luke 11:30, 32)"},{"p":"contents","r":"NKJV notes, note on Jonah 4:6; NKJV notes, note on Jonah 4:10; Jonah 4:1–11","v":"Jonah is greatly displeased and angry, and prays that the LORD take his life, for he fled to Tarshish because he knew the LORD to be a gracious and merciful God, slow to anger, abundant in lovingkindness and relenting from harm; the LORD asks whether it is right for him to be angry; Jonah makes a shelter east of the city to see what will become of it; the LORD God prepares a plant (kikayon, its exact identity unknown, by the NKJV note) to shade his head, and Jonah is very glad of it, but at dawn God prepares a worm that strikes it so that it withers, and then a vehement east wind, and with the sun on his head Jonah grows faint and wishes to die, saying it is right for him to be angry, even to death; the LORD answers that Jonah pitied a plant he did not labor for, which came up in a night and perished in a night (was a son of a night, by the NKJV note), and asks whether He should not pity Nineveh, that great city, with more than a hundred and twenty thousand persons who cannot discern their right hand from their left, and much livestock"},{"p":"designation","r":"Jonah 1:1","v":"The word of the LORD came to Jonah"},{"p":"feature","r":"Jonah 1:1–3; 2:1–9","v":"It tells of Jonah in the third person, with his prayer from the fish's belly in his own words"},{"p":"feature","r":"2 Kings 14:23–25; Jonah 1:1","v":"It names no king and gives no date; the LORD had spoken through Jonah the son of Amittai the word that Jeroboam the son of Joash fulfilled when he restored Israel's territory"},{"p":"feature","r":"Matthew 12:39–41; Luke 11:29–32","v":"Jesus names the sign of the prophet Jonah: as Jonah was three days and three nights in the great fish, so the Son of Man in the heart of the earth, and the men of Nineveh, who repented at Jonah's preaching, will condemn His generation"}],"nm":{}},"OBJ-00566":{"k":"object","n":"The great fish that swallowed Jonah","d":"The great fish the LORD prepared to swallow Jonah, in whose belly he was three days and three nights (Jonah 1:17; 2:10; Matthew 12:40)","f":[{"p":"designation","r":"Jonah 1:17; Matthew 12:40","v":"a great fish"},{"p":"feature","r":"Jonah 1:17; 2:10","v":"The LORD prepared it to swallow Jonah, and at His word it vomited Jonah onto dry land"}],"nm":{}},"OBJ-00567":{"k":"object","n":"Jonah's prayer from the fish's belly","d":"The prayer Jonah prayed to the LORD his God from the fish's belly (Jonah 2:1–9)","f":[{"p":"contents","r":"NKJV notes, note on Jonah 2:6; NKJV notes, note on Jonah 2:8; Jonah 2:2–9","v":"Jonah cried to the LORD in his affliction and was answered; out of the belly of Sheol he cried, and the LORD heard; cast into the deep, the floods around him and weeds wrapped around his head, he went down to the moorings (foundations or bases, by the NKJV note) of the mountains, yet the LORD brought his life up from the pit; when his soul fainted he remembered the LORD, and his prayer came into His holy temple; those who regard worthless idols forsake their own Mercy (or Lovingkindness, by the NKJV note), but he would sacrifice with thanksgiving and pay what he had vowed, for salvation is of the LORD"},{"p":"designation","r":"Jonah 2:7","v":"my prayer"},{"p":"made by","r":"Jonah 2:1–2","e":"PER-01084"},{"p":"occasion","r":"Jonah 2:1","e":"EVT-02663"}],"nm":{"EVT-02663":"Jonah prays from the fish's belly","PER-01084":"Jonah"}},"OBJ-00568":{"k":"object","n":"The decree of the king of Nineveh","d":"The decree of the king of Nineveh and his nobles, proclaimed throughout the city, that man and beast fast, be covered with sackcloth and cry mightily to God (Jonah 3:7–9)","f":[{"p":"contents","r":"Jonah 3:7–9","v":"Neither man nor beast, herd nor flock, was to taste anything, eat or drink water; man and beast were to be covered with sackcloth and cry mightily to God, and everyone was to turn from his evil way and the violence in his hands, for who could tell whether God would turn and relent from His fierce anger, so that they would not perish"},{"p":"designation","r":"NKJV notes, note on Jonah 3:7; Jonah 3:7","v":"the decree of the king and his nobles"},{"p":"made by","r":"Jonah 3:7","e":"PER-02983"},{"p":"made by","r":"Jonah 3:7","e":"GRP-01021"},{"p":"occasion","r":"Jonah 3:7","e":"EVT-02667"}],"nm":{"EVT-02667":"The people of Nineveh repent","GRP-01021":"The nobles of the king of Nineveh in Jonah's day","PER-02983":"The king of Nineveh in Jonah's day"}},"OBJ-00569":{"k":"object","n":"The plant the LORD prepared over Jonah","d":"The plant the LORD God made to come up over Jonah to shade his head, which a worm struck so that it withered (Jonah 4:6–10)","f":[{"p":"designation","r":"NKJV notes, note on Jonah 4:6; Jonah 4:6","v":"a plant"},{"p":"feature","r":"NKJV notes, note on Jonah 4:10; Jonah 4:6–7, 10","v":"It came up over Jonah to shade his head, and at the next dawn a worm God prepared struck it so that it withered: it came up in a night and perished in a night (was a son of a night, by the NKJV note)"}],"nm":{}},"OBJ-00570":{"k":"object","n":"The Book of Micah","d":"The word of the LORD that came to Micah of Moresheth in the days of Jotham, Ahaz and Hezekiah, kings of Judah, which he saw concerning Samaria and Jerusalem (Micah 1–7)","f":[{"p":"contents","r":"NKJV notes, note on Micah 1:10; NKJV notes, note on Micah 1:11; NKJV notes, note on Micah 1:12; NKJV notes, note on Micah 1:14; NKJV notes, note on Micah 1:15; Micah 1:1–16","v":"The word of the LORD that came to Micah of Moresheth in the days of Jotham, Ahaz and Hezekiah, kings of Judah, which he saw concerning Samaria and Jerusalem: all peoples are to hear, for the LORD comes down from His holy temple and the mountains melt under Him, for the transgression of Jacob, which is Samaria, and the high places of Judah, which are Jerusalem; He will make Samaria a heap of ruins in the field, pour her stones into the valley and beat her carved images to pieces; so Micah will wail and go stripped and naked, for her wound is incurable and has come to Judah, to the gate of Jerusalem; he laments over the towns, playing on their names, as the NKJV notes give them: Gath, Beth Aphrah (House of Dust), Shaphir (Beautiful), Zaanan (Going Out), Beth Ezel, Maroth (Bitterness), Lachish, the beginning of sin to the daughter of Zion, Moresheth Gath (Possession of Gath), Achzib (Lie), Mareshah (Inheritance) and Adullam (Refuge); the daughter of Zion is to make herself bald for her children, who will go into captivity"},{"p":"contents","r":"NKJV notes, note on Micah 2:4; NKJV notes, note on Micah 2:5; NKJV notes, note on Micah 2:6; NKJV notes, note on Micah 2:12; Micah 2:1–13","v":"Woe to those who plan iniquity on their beds and at morning seize the fields and houses they covet, oppressing a man and his inheritance: the LORD devises disaster against this family, from which they cannot free their necks, and they will lament that their portion is divided to a turncoat (an apostate, by the NKJV note), with none to cast the surveyor's line (by the NKJV note) in the assembly of the LORD; they tell the prophets not to prattle (drip words, by the NKJV note), though the LORD's words do good to the upright, while His people rise up as an enemy, strip the robes from those who pass by and cast the women out of their pleasant houses; they are to arise and depart, for this is not their rest, and a man who prophesied of wine and drink would be this people's prattler; yet the LORD will surely gather the remnant of Israel like sheep of the fold (Bozrah in Hebrew, by the NKJV note), and the one who breaks open will go up before them, their king passing before them with the LORD at their head"},{"p":"contents","r":"NKJV notes, note on Micah 3:2; NKJV notes, note on Micah 3:5; NKJV notes, note on Micah 3:11; Jeremiah 26:18; Micah 3:1–12","v":"Micah tells the heads of Jacob and rulers of Israel, who hate good and love evil, that they strip the skin from the LORD's people (them, by the NKJV note) and chop them like meat for the pot, so the LORD will not answer them; the prophets who cry 'Peace' (all is well, by the NKJV note) while they are fed will have night without vision, and no answer from God, but Micah is full of power by the Spirit of the LORD to declare to Jacob his transgression; because the heads build Zion with bloodshed, judge for a bribe, the priests teach for pay and the prophets divine for money (silver, by the NKJV note), Zion will be plowed like a field, Jerusalem become heaps of ruins and the mountain of the temple like the bare hills of the forest, the word the elders recalled in Jeremiah's day (Jeremiah 26:18)"},{"p":"contents","r":"NKJV notes, note on Micah 4:3; NKJV notes, note on Micah 4:9; Isaiah 2:2–4; Micah 4:1–13","v":"In the latter days the mountain of the LORD's house will be established above the hills, many nations will come to learn His ways, for the law will go forth from Zion, and they will beat their swords into plowshares and their spears into pruning hooks (knives, by the NKJV note) and learn war no more, each sitting under his vine and fig tree, as Isaiah also gives it (Isaiah 2:2–4); the LORD will gather the lame and the outcast and reign over them in Mount Zion forever, and the former dominion will come to the tower of the flock, the stronghold of the daughter of Zion; the daughter of Zion, in pangs like a woman in labor (childbirth, by the NKJV note), will go forth from the city to Babylon, and there the LORD will redeem her; the nations gathered against her do not know His counsel, for He will gather them like sheaves to the threshing floor, and she will thresh them with horn of iron and hooves of bronze and consecrate their gain to the Lord of the whole earth"},{"p":"contents","r":"NKJV notes, note on Micah 5:2; NKJV notes, note on Micah 5:14; NKJV notes, note on Micah 5:15; Micah 5:1–15; Matthew 2:4–6; John 7:42","v":"They lay siege and strike the judge of Israel with a rod on the cheek; but out of Bethlehem Ephrathah, little among the thousands of Judah, will come the One to be Ruler in Israel, whose goings forth are from of old, from everlasting (the days of eternity, by the NKJV note), the word the chief priests and scribes gave Herod (Matthew 2:4–6; John 7:42); He will shepherd His flock in the strength of the LORD, great to the ends of the earth, and He will be peace; when the Assyrian comes into the land they will raise seven shepherds and eight princely men against him, who will waste the land of Assyria and the land of Nimrod; the remnant of Jacob will be among many peoples like dew from the LORD and like a lion among the beasts of the forest; and in that day the LORD will cut off their horses and chariots, their cities and strongholds, their sorceries and soothsayers, their carved images, sacred pillars and wooden images (Asherim, Canaanite deities, by the NKJV note), and take vengeance on the nations that have not heard (obeyed, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Micah 6:2; NKJV notes, note on Micah 6:5; NKJV notes, note on Micah 6:8; Micah 6:1–16","v":"The LORD bids the mountains hear His complaint (bringing charges, by the NKJV note) against His people: what has He done to weary them, who brought them up from Egypt, redeemed them from the house of bondage and sent Moses, Aaron and Miriam before them? They are to remember what Balak king of Moab counseled and Balaam the son of Beor answered, and the way from Acacia Grove (Shittim, by the NKJV note) to Gilgal; not burnt offerings, thousands of rams or a firstborn for transgression, but to do justly, love mercy (or lovingkindness, by the NKJV note) and walk humbly with God is what the LORD requires; His voice cries to the city of treasures of wickedness, short measures and deceitful weights, whose rich men are full of violence: He will strike it, so that they eat and are not satisfied, sow and do not reap, tread olives and do not anoint themselves, for they keep the statutes of Omri and the works of Ahab's house, and He will make them a desolation and a hissing"},{"p":"contents","r":"NKJV notes, note on Micah 7:11; NKJV notes, note on Micah 7:12; Micah 7:1–20; Matthew 10:35–36","v":"Micah laments like one who finds no cluster after the harvest: the faithful man has perished, all lie in wait for blood, the prince and the judge seek bribes, none is to trust a friend, for son dishonors father, daughter rises against mother and a man's enemies are those of his own household, words Jesus takes up (Matthew 10:35–36); yet he will wait for the God of his salvation; though fallen and in darkness, Israel will bear the LORD's indignation until He pleads its case, and the enemy who asked where its God was will be trampled; in the day its walls are built the decree will go far and wide (or the boundary be extended, by the NKJV note), and they will come from Assyria and the fortified cities, from the fortress to the River (the Euphrates, by the NKJV note); Micah asks the LORD to shepherd His flock in Carmel, Bashan and Gilead as in days of old, and the LORD will show them wonders as when they came out of Egypt; who is a God like Him, pardoning iniquity and delighting in mercy, who will cast all their sins into the depths of the sea and give truth to Jacob and mercy to Abraham, as He swore to their fathers"},{"p":"designation","r":"Micah 1:1","v":"The word of the LORD"},{"p":"feature","r":"Micah 1:1","v":"Its heading dates the word in the days of Jotham, Ahaz and Hezekiah, kings of Judah, concerning Samaria and Jerusalem"},{"p":"feature","r":"Jeremiah 26:17–19; Micah 3:12","v":"Its word that Zion would be plowed like a field is the one the elders of Jeremiah's day recalled Micah of Moresheth speaking in the days of Hezekiah"},{"p":"feature","r":"Isaiah 2:2–4; Micah 4:1–3","v":"Its word of the mountain of the LORD's house agrees almost word for word with Isaiah's"},{"p":"feature","r":"Micah 5:2; Matthew 2:4–6; John 7:42","v":"Its word of the Ruler to come from Bethlehem Ephrathah is the one the chief priests and scribes gave Herod, as Matthew tells"},{"p":"made by","r":"Micah 1:1, 8; 3:1, 8; 7:1–7","e":"PER-02870","b":"inferred","c":"probable","w":"The book is the word of the LORD that came to Micah, which he saw (Micah 1:1), and Micah speaks in his own words (1:8; 3:1, 8; 7:1–7)."}],"nm":{"PER-02870":"Micah"}},"OBJ-00571":{"k":"object","n":"The Book of Nahum","d":"The burden against Nineveh, the book of the vision of Nahum the Elkoshite (Nahum 1–3)","f":[{"p":"contents","r":"NKJV notes, note on Nahum 1:1; NKJV notes, note on Nahum 1:5; NKJV notes, note on Nahum 1:9; NKJV notes, note on Nahum 1:11; NKJV notes, note on Nahum 1:12; NKJV notes, note on Nahum 1:14; NKJV notes, note on Nahum 1:15; Nahum 1:1–15","v":"The burden (oracle or prophecy, by the NKJV note) against Nineveh, the book of the vision of Nahum the Elkoshite: God is jealous and the LORD avenges, taking vengeance on His adversaries and keeping wrath for His enemies; slow to anger and great in power, He will not acquit the wicked; He has His way in whirlwind and storm, dries up the sea and the rivers, so that Bashan and Carmel wither and the flower of Lebanon wilts, and the mountains quake and the earth heaves (burns, in the Targum, by the NKJV note) at His presence; none can stand before His indignation; the LORD is good, a stronghold in the day of trouble, and knows those who trust in Him, but with an overflowing flood He will make an utter end of its place, and darkness will pursue His enemies; what is conspired (or devised, by the NKJV note) against the LORD He will end, and affliction will not rise a second time; from the one addressed comes one who plots evil against the LORD, a wicked counselor (counselor of Belial, lit., by the NKJV note); though they are safe (or at peace or complete, by the NKJV note) and many, they will be cut down, and the LORD will afflict no more the one He afflicted, but break off his yoke and burst the bonds; He has commanded that the name be perpetuated no longer (lit. that no more of it be fruitful, by the NKJV note), the carved and molded image be cut off from the house of the gods and a grave be dug, for the one addressed is vile (or contemptible, by the NKJV note); on the mountains are the feet of him who brings good tidings and proclaims peace: Judah is to keep its appointed feasts and perform its vows, for the wicked one (one of Belial, lit., by the NKJV note) will no more pass through it, being utterly cut off"},{"p":"contents","r":"NKJV notes, note on Nahum 2:1; NKJV notes, note on Nahum 2:3; NKJV notes, note on Nahum 2:7; NKJV notes, note on Nahum 2:8; NKJV notes, note on Nahum 2:9; NKJV notes, note on Nahum 2:12; Nahum 2:1–13","v":"He who scatters (He who destroys, in the Vulgate, by the NKJV note) has come up against the city, which is bidden to man the fort and watch the road; the LORD will restore the excellence of Jacob like that of Israel, for the emptiers have emptied them out; the shields of the mighty men are red and the valiant in scarlet, the chariots come like flaming torches, raging in the streets and running like lightning, and the spears are brandished (lit. the cypresses are shaken, by the NKJV note); the nobles stumble to the walls, the gates of the rivers are opened and the palace is dissolved; it is decreed (Huzzab in Hebrew, by the NKJV note) that she be led away captive, her maidservants moaning like doves and beating their breasts; Nineveh, of old like a pool of water, sees her people flee, and none turns back though they cry 'Halt!' (lit. Stand, by the NKJV note); her silver and gold are taken as spoil (plunder, by the NKJV note) without end, and she is empty, desolate and waste, every heart melting; where now is the den of the lions, where the lion killed (lit. strangled, by the NKJV note) for his lionesses and filled his caves with prey? The LORD of hosts is against it: He will burn the chariots in smoke, the sword will devour the young lions, the prey will be cut off from the earth, and the voice of the messengers will be heard no more"},{"p":"contents","r":"NKJV notes, note on Nahum 3:1; NKJV notes, note on Nahum 3:2; NKJV notes, note on Nahum 3:4; NKJV notes, note on Nahum 3:6; NKJV notes, note on Nahum 3:8; NKJV notes, note on Nahum 3:9; Nahum 3:1–19","v":"Woe to the bloody city, all full of lies and robbery, whose victim (lit. prey, by the NKJV note) never departs: the whip, the rattling wheels, the galloping horses and the clattering (bounding or jolting, by the NKJV note) chariots, and corpses beyond counting; for the harlotries (spiritual unfaithfulness, by the NKJV note) of the seductive harlot (lit. goodly charm, in a bad sense, by the NKJV note), the mistress of sorceries who sells nations and families, the LORD of hosts is against her: He will show the nations her nakedness and make her vile (despicable, by the NKJV note) and a spectacle, and all who see her will say that Nineveh is laid waste; she is no better than No Amon (ancient Thebes, by the NKJV note), which sat by the River (lit. rivers, the Nile and the surrounding canals, by the NKJV note) with the sea for her rampart and wall, whose strength was Ethiopia and Egypt, with Put and Lubim as helpers (the text has 'your helpers', and the NKJV note 'LXX her'), and yet was carried into captivity, her children dashed to pieces, lots cast for her honorable men and her great men bound in chains; Nineveh too will be drunk and hidden, her strongholds will fall like ripe figs, her gates will stand open and fire devour their bars; though she draw water for the siege and strengthen her forts, fire and sword will devour her; her merchants, commanders and generals are like locusts that fly away when the sun rises; the shepherds of the king of Assyria slumber and his people are scattered on the mountains; his wound has no healing, and all who hear the news will clap their hands, for upon whom has his wickedness not passed continually?"},{"p":"designation","r":"Nahum 1:1","v":"The book of the vision of Nahum the Elkoshite"},{"p":"designation","r":"NKJV notes, note on Nahum 1:1; Nahum 1:1","v":"The burden against Nineveh"},{"p":"feature","r":"Nahum 1:1","v":"Its heading calls it both the burden against Nineveh and the book of the vision of Nahum the Elkoshite; it names no king and gives no date"},{"p":"feature","r":"Isaiah 52:7; Nahum 1:15","v":"Its word of the feet on the mountains of him who brings good tidings and proclaims peace agrees with Isaiah's"},{"p":"feature","r":"Nahum 3:8–10","v":"It tells that No Amon, though Ethiopia and Egypt were her strength, had already gone into captivity, and asks Nineveh whether she is any better"},{"p":"feature","r":"Nahum 3:18–19","v":"It ends with a question to the king of Assyria: upon whom has his wickedness not passed continually?"},{"p":"made by","r":"Nahum 1:1","e":"PER-02984","b":"inferred","c":"probable","w":"The heading calls it the book of the vision of Nahum the Elkoshite (Nahum 1:1)."}],"nm":{"PER-02984":"Nahum"}},"OBJ-00572":{"k":"object","n":"The Book of Habakkuk","d":"The burden which the prophet Habakkuk saw: his complaints to the LORD and the LORD's answers, and his prayer on Shigionoth (Habakkuk 1–3)","f":[{"p":"contents","r":"NKJV notes, note on Habakkuk 1:1; NKJV notes, note on Habakkuk 1:3; NKJV notes, note on Habakkuk 1:8; NKJV notes, note on Habakkuk 1:11; NKJV notes, note on Habakkuk 1:16; Habakkuk 1:1–17; Acts 13:40–41","v":"The burden (oracle or prophecy, by the NKJV note) which the prophet Habakkuk saw: he asks the LORD how long he must cry out against violence and not be heard or saved, for iniquity and trouble (or toil, by the NKJV note), plundering and strife are before him, the law is powerless and justice perverted; the LORD answers that He will work a work in their days that they would not believe (words taken up in Acts 13:40–41): He is raising up the Chaldeans, a bitter and hasty nation, terrible and dreadful, whose horses are swifter than leopards and whose chargers (lit. horsemen, by the NKJV note) spring ahead, who come for violence, gather captives like sand, scoff at kings and seize every stronghold, and whose mind (lit. spirit or wind, by the NKJV note) changes as he ascribes his power to his god; Habakkuk owns the LORD as from everlasting, his Holy One and Rock, who has appointed them for correction, and asks why He, of purer eyes than to behold evil, looks on the treacherous while the wicked devour the more righteous and men are caught like fish by those who sacrifice to their net, because by it their share is sumptuous (lit. fat, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Habakkuk 2:5; Habakkuk 2:1–20; Romans 1:17; Galatians 3:11; Hebrews 10:37–38","v":"Habakkuk stands his watch on the rampart, and the LORD answers: he is to write the vision plainly on tablets, for it is for an appointed time and, though it tarries, will surely come; the proud man's soul is not upright, but the just will live by his faith (words taken up in Romans 1:17, Galatians 3:11 and Hebrews 10:37–38); the proud man, whose desire is wide as hell (or Sheol, by the NKJV note), gathers all nations, and they will take up a taunt against him in woes: on him who increases what is not his, whom the remnant of the peoples will plunder; on him who covets evil gain to set his nest on high, while the stone cries out from the wall; on him who builds a town with bloodshed, though the earth will be filled with the knowledge of the LORD's glory as the waters cover the sea; on him who makes his neighbor drunk to see his nakedness, to whom the cup of the LORD's right hand will come, with the violence done to Lebanon; and on him who bids wood and stone awake, though no breath is in them; but the LORD is in His holy temple, and all the earth is to keep silence before Him"},{"p":"contents","r":"NKJV notes, note on Habakkuk 3:1; NKJV notes, note on Habakkuk 3:9; NKJV notes, note on Habakkuk 3:12; NKJV notes, note on Habakkuk 3:19; Habakkuk 3:1–19","v":"A prayer of Habakkuk the prophet, on Shigionoth (exact meaning unknown, by the NKJV note): he has heard the LORD's speech and is afraid, and prays Him to revive His work in the midst of the years and in wrath to remember mercy; God came from Teman, the Holy One from Mount Paran, His glory covering the heavens and His brightness like the light; pestilence went before Him, He measured the earth and startled the nations, the everlasting mountains were scattered, and the tents of Cushan and the curtains of the land of Midian trembled; was He angry with the rivers and the sea, that He rode on His horses and chariots of salvation, with oaths sworn over His arrows (lit. tribes or rods, by the NKJV note)? The mountains trembled, the deep lifted its hands, and the sun and moon stood still at the light of His arrows; He trampled (or threshed, by the NKJV note) the nations in anger and went forth for the salvation of His people, with His Anointed, striking the head of the house of the wicked, and walked through the sea with His horses; Habakkuk trembles at what he has heard, yet will rest in the day of trouble, when he comes up to invade the people with his troops; though the fig tree not blossom and vine, olive, field, flock and herd fail, he will rejoice in the LORD, the God of his salvation; the LORD God (YHWH Adonai in Hebrew, by the NKJV note) is his strength, making his feet like deer's feet on his high hills; to the Chief Musician, with his stringed instruments"},{"p":"designation","r":"NKJV notes, note on Habakkuk 1:1; Habakkuk 1:1","v":"The burden which the prophet Habakkuk saw"},{"p":"feature","r":"Habakkuk 1:1","v":"Its heading names no king and gives no date"},{"p":"feature","r":"Habakkuk 1:2–2:4","v":"It is set as a dialogue: twice the prophet asks the LORD how long and why, and twice the LORD answers him"},{"p":"feature","r":"Habakkuk 1:5; Acts 13:14–16, 40–41","v":"Its word of a work in their days that would not be believed is the warning with which Paul ends his sermon in the synagogue at Antioch in Pisidia"},{"p":"feature","r":"Habakkuk 2:4; Romans 1:17; Galatians 3:11; Hebrews 10:38","v":"Its word on the just living by faith is taken up in Romans, Galatians and Hebrews"},{"p":"feature","r":"Isaiah 11:9; Habakkuk 2:14","v":"Its word that the earth will be filled with the knowledge of the LORD's glory as the waters cover the sea agrees closely with Isaiah's"},{"p":"feature","r":"Habakkuk 3:1, 19","v":"Its last chapter is the prophet's own prayer, headed and closed as a psalm and given to the Chief Musician"},{"p":"feature","r":"2 Samuel 22:34; Psalms 18:33; Habakkuk 3:19","v":"Its prayer ends, as David's song does, with feet made like the feet of deer and set on high places"},{"p":"made by","r":"Habakkuk 1:1, 2–4, 12–2:1; 3:1","e":"PER-02985","b":"inferred","c":"probable","w":"The book is the burden the prophet Habakkuk saw (Habakkuk 1:1); he speaks in his own words (1:2–4; 1:12–2:1), and its prayer is his (3:1)."}],"nm":{"PER-02985":"Habakkuk"}},"OBJ-00573":{"k":"object","n":"Habakkuk's prayer on Shigionoth","d":"The prayer of Habakkuk the prophet, on Shigionoth, given to the Chief Musician (Habakkuk 3:1–19)","f":[{"p":"designation","r":"Habakkuk 3:1","v":"A prayer of Habakkuk the prophet"},{"p":"feature","r":"NKJV notes, note on Habakkuk 3:1; Habakkuk 3:1","v":"Set on Shigionoth (exact meaning unknown, by the NKJV note)"},{"p":"feature","r":"Habakkuk 3:3, 9, 13","v":"Selah stands in it three times"},{"p":"feature","r":"Habakkuk 3:19","v":"To be played with his stringed instruments"},{"p":"made by","r":"Habakkuk 3:1","e":"PER-02985"},{"p":"occasion","r":"Habakkuk 3:1","e":"EVT-02705"},{"p":"purpose","r":"Habakkuk 3:19","v":"Given to the Chief Musician"}],"nm":{"EVT-02705":"Habakkuk prays that the LORD revive His work","PER-02985":"Habakkuk"}},"OBJ-00574":{"k":"object","n":"The Book of Zephaniah","d":"The word of the LORD that came to Zephaniah son of Cushi in the days of Josiah son of Amon, king of Judah (Zephaniah 1–3)","f":[{"p":"contents","r":"NKJV notes, note on Zephaniah 1:2; NKJV notes, note on Zephaniah 1:3; NKJV notes, note on Zephaniah 1:4; NKJV notes, note on Zephaniah 1:5; NKJV notes, note on Zephaniah 1:7; NKJV notes, note on Zephaniah 1:11; NKJV notes, note on Zephaniah 1:12; 2 Kings 23:4–5; Zephaniah 1:1–18","v":"The word of the LORD which came to Zephaniah son of Cushi, son of Gedaliah, son of Amariah, son of Hezekiah, in the days of Josiah son of Amon, king of Judah: the LORD will utterly consume (lit. make a complete end of, by the NKJV note) all from the face of the land, man, beast, bird and fish, and the stumbling blocks (idols, by the NKJV note) with the wicked; He will stretch out His hand against Judah and Jerusalem and cut off every trace of Baal and the idolatrous priests (chemarim in Hebrew, by the NKJV note, which says the word was fulfilled in 2 Kings 23:4–5), those who worship the host of heaven on the housetops, those who swear by Milcom (or Malcam, an Ammonite god, by the NKJV note) and those who have turned back from Him; all are to be silent before the Lord GOD, for the day of the LORD is at hand, and He has prepared a sacrifice and invited (lit. set apart, by the NKJV note) His guests: He will punish the princes, the king's children and those clothed in foreign apparel; there will be crying from the Fish Gate and wailing from the Second Quarter, and the merchants of Maktesh (a market district of Jerusalem, lit. Mortar, by the NKJV note) will be cut down; He will search Jerusalem with lamps and punish the men settled in complacency (lit. on their lees, by the NKJV note), and their houses will be a desolation; the great day of the LORD is near, a day of wrath, trouble and distress, darkness and gloominess, trumpet and alarm, when neither silver nor gold will deliver them and the whole land will be devoured by the fire of His jealousy"},{"p":"contents","r":"NKJV notes, note on Zephaniah 2:1; NKJV notes, note on Zephaniah 2:6; NKJV notes, note on Zephaniah 2:7; NKJV notes, note on Zephaniah 2:9; Zephaniah 2:1–15","v":"The undesirable (or shameless, by the NKJV note) nation is to gather before the day of the LORD's anger, and the meek of the earth to seek the LORD, righteousness and humility, that they may be hidden in that day; Gaza will be forsaken, Ashkelon desolate, Ashdod driven out and Ekron uprooted, and the LORD is against the Cherethites of the seacoast and Canaan, land of the Philistines, whose coast will be pastures with shelters (underground huts or cisterns, by the NKJV note) for the remnant of Judah when the LORD intervenes for them (lit. visits them, by the NKJV note) and returns their captives; for their reproach and arrogance against His people, Moab will be like Sodom and the people of Ammon like Gomorrah, overrun with weeds (lit. possessed by nettles, by the NKJV note) and saltpits, a perpetual desolation (or permanent ruin, by the NKJV note), and the LORD will reduce all the gods of the earth to nothing and be worshiped from every shore; the Ethiopians will be slain by His sword, and He will destroy Assyria and make Nineveh, the rejoicing city that said there was none besides her, a desolation where beasts lie down and passers-by hiss"},{"p":"contents","r":"NKJV notes, note on Zephaniah 3:4; NKJV notes, note on Zephaniah 3:5; NKJV notes, note on Zephaniah 3:7; NKJV notes, note on Zephaniah 3:8; NKJV notes, note on Zephaniah 3:9; NKJV notes, note on Zephaniah 3:15; NKJV notes, note on Zephaniah 3:20; Zephaniah 3:1–20","v":"Woe to the rebellious, polluted and oppressing city, which has not obeyed or trusted the LORD: her princes are roaring lions, her judges evening wolves, her prophets treacherous, and her priests have polluted (or profaned, by the NKJV note) the sanctuary, though the LORD in her midst brings His justice to light every morning (lit. morning by morning, by the NKJV note); He cut off nations that she might fear Him, but they were eager (by the NKJV note) to corrupt their deeds; they are to wait for Him until the day He rises up for plunder (for witness, in the Septuagint and the Syriac, by the NKJV note), when He will gather the nations for His indignation, give the peoples a pure language (lit. lip, by the NKJV note) to call on His name, receive His offering from beyond the rivers of Ethiopia, and leave in her midst a meek and humble remnant of Israel who will speak no lies and lie down unafraid; the daughter of Zion is to sing and Israel to shout, for the LORD, the King of Israel, is in her midst, and she will see (fear, in the Masoretic text and the Vulgate, by the NKJV note) disaster no more; the LORD her God, the Mighty One, will rejoice over her with singing, gather the outcasts, save the lame, and give them fame and praise (lit. a name, by the NKJV note) when He returns their captives before their eyes"},{"p":"designation","r":"Zephaniah 1:1","v":"The word of the LORD"},{"p":"feature","r":"Zephaniah 1:1","v":"Its heading traces Zephaniah's line four generations back, to Hezekiah, and dates the word in the days of Josiah son of Amon, king of Judah"},{"p":"feature","r":"NKJV notes, note on Zephaniah 1:4; 2 Kings 23:4–5; Zephaniah 1:4","v":"Its word against every trace of Baal and the idolatrous priests was fulfilled, by the NKJV note, in Josiah's purge of Judah and Jerusalem"},{"p":"feature","r":"Zephaniah 1:14–16","v":"It sets out the great day of the LORD as a day of wrath, trouble and distress, devastation, darkness and clouds, trumpet and alarm"},{"p":"feature","r":"Zephaniah 3:14–20","v":"It ends with the LORD in Zion's midst, rejoicing over her with singing and bringing back her captives before her eyes"},{"p":"made by","r":"Zephaniah 1:1","e":"PER-02986","b":"inferred","c":"probable","w":"The book is the word of the LORD that came to Zephaniah (Zephaniah 1:1)."}],"nm":{"PER-02986":"Zephaniah"}},"OBJ-00575":{"k":"object","n":"The Book of Haggai","d":"The words of the LORD that came by Haggai the prophet to Zerubbabel, governor of Judah, to Joshua the high priest and to the remnant of the people, in the days of King Darius (Haggai 1–2)","f":[{"p":"contents","r":"NKJV notes, note on Haggai 1:4; NKJV notes, note on Haggai 1:8; Haggai 1:1–15","v":"In the second year of King Darius, on the first day of the sixth month, the word of the LORD came by Haggai the prophet to Zerubbabel son of Shealtiel, governor of Judah, and to Joshua son of Jehozadak, the high priest: the people said the time had not come to build the LORD's house, though they dwelt in paneled houses while this temple (lit. house, by the NKJV note) lay in ruins; they were to consider their ways, for they had sown much and brought in little, and their wages went into a bag with holes; they were to go up to the mountains, bring wood and build the temple (lit. house, by the NKJV note), for the LORD's pleasure and His glory; because His house lay in ruins while each of them ran to his own house, the dew and the harvest were withheld, and He had called for a drought on the land, on grain, new wine and oil, on men and livestock. Then Zerubbabel, Joshua and all the remnant of the people obeyed the voice of the LORD and the words of Haggai, and stood in fear of the LORD; Haggai, the LORD's messenger, told them that the LORD was with them; and the LORD stirred up the spirit of Zerubbabel, of Joshua and of all the remnant, and they set to work on the house of the LORD on the twenty-fourth day of the sixth month, in the second year of King Darius"},{"p":"contents","r":"NKJV notes, note on Haggai 2:1; NKJV notes, note on Haggai 2:3; NKJV notes, note on Haggai 2:7; NKJV notes, note on Haggai 2:9; Haggai 2:1–23; Hebrews 12:26–27","v":"On the twenty-first of the seventh month the word of the LORD came by (lit. by the hand of, by the NKJV note) Haggai to Zerubbabel, Joshua and the remnant of the people: who among them had seen this temple (lit. house, by the NKJV note) in its former glory, and was it not as nothing to them now? Yet they were to be strong and work, for the LORD was with them and His Spirit remained among them, as He had covenanted when they came out of Egypt; in a little while He would once more shake heaven and earth, the sea, the dry land and all nations, and they would come to the Desire of All Nations (or desire of all nations, by the NKJV note), and He would fill this temple (lit. house, by the NKJV note) with glory; the silver and the gold are His, and the glory of this latter temple (lit. house, by the NKJV note) would be greater than the former, and in this place He would give peace. On the twenty-fourth of the ninth month, in the second year of Darius, Haggai asked the priests whether holy meat carried in a garment makes the food it touches holy (they said no) and whether one unclean by a dead body makes it unclean (they said it would be); so, said the LORD, were this people and nation and every work of their hands, and what they offered was unclean; they were to consider how, before stone was laid on stone in the temple, their heaps and wine vats gave half or less, and how He struck them with blight, mildew and hail, yet they did not turn to Him; from that day, the day the foundation of the LORD's temple was laid, He would bless them. The same day the word came again to Haggai for Zerubbabel, governor of Judah: the LORD would shake heaven and earth, overthrow the throne of kingdoms and the strength of the Gentile kingdoms, their chariots, horses and riders, and in that day He would take Zerubbabel His servant and make him like a signet ring, for He had chosen him. The shaking of heaven and earth once more is quoted in Hebrews 12:26–27"},{"p":"designation","r":"Haggai 1:1","v":"In the second year"},{"p":"feature","r":"Haggai 1:1, 15; 2:1, 10, 20","v":"Each of its words is dated by the month and the day, in the second year of King Darius"},{"p":"feature","r":"Haggai 1:12–15","v":"It tells how Zerubbabel, Joshua and the remnant of the people obeyed the word and set to work on the house of the LORD"},{"p":"feature","r":"Haggai 2:20–23","v":"It ends with the LORD's word to Zerubbabel, that He has chosen him and will make him like a signet ring"},{"p":"made by","r":"Haggai 1:1, 3; 2:1, 10, 20","e":"PER-02290","b":"inferred","c":"probable","w":"The book is made up of the words of the LORD that came by Haggai the prophet (Haggai 1:1, 3; 2:1, 10, 20); it speaks of him by name and does not say who wrote it down."}],"nm":{"PER-02290":"Haggai"}},"OBJ-00576":{"k":"object","n":"The Book of Zechariah","d":"The words of the LORD that came to Zechariah the son of Berechiah, the son of Iddo, in the days of King Darius: his call to return, his visions by night, the word about the fasts, and two burdens (Zechariah 1–14)","f":[{"p":"contents","r":"NKJV notes, note on Zechariah 1:11; NKJV notes, note on Zechariah 1:14; NKJV notes, note on Zechariah 1:17; NKJV notes, note on Zechariah 1:19; Zechariah 1:1–21","v":"In the eighth month of the second year of Darius the word of the LORD came to Zechariah the son of Berechiah, the son of Iddo: the people were to return to the LORD and not be like their fathers, whom His words overtook. On the twenty-fourth day of the eleventh month, Shebat, Zechariah saw by night a man on a red horse among the myrtle trees, with horses behind him that the LORD had sent through the earth, which was at rest (lit. sitting and quiet, by the NKJV note); the Angel of the LORD asked how long the LORD would withhold mercy from Jerusalem after seventy years, and the LORD, zealous (or jealous, by the NKJV note) for Jerusalem and Zion, promised to return to Jerusalem with mercy: His house would be built there, and His cities would again spread out (or overflow with good, by the NKJV note). Then Zechariah saw four horns (kingdoms or powers, by the NKJV note) that had scattered Judah, Israel and Jerusalem, and four craftsmen coming to terrify them"},{"p":"contents","r":"NKJV notes, note on Zechariah 2:8; NKJV notes, note on Zechariah 2:9; Zechariah 2:1–13","v":"Zechariah saw a man with a measuring line going to measure Jerusalem; another angel said that Jerusalem would be inhabited as towns without walls, with the LORD a wall of fire around her and the glory in her midst. The LORD called those who dwelt with the daughter of Babylon to flee from the land of the north; whoever touched His people touched the apple (lit. pupil, by the NKJV note) of His eye, and their plunderers would become spoil (booty or plunder, by the NKJV note); the LORD would dwell in the midst of Zion, many nations would be joined to Him, and He would take Judah as His inheritance in the Holy Land and again choose Jerusalem; all flesh was to be silent before Him"},{"p":"contents","r":"NKJV notes, note on Zechariah 3:1; NKJV notes, note on Zechariah 3:8; Zechariah 3:1–10; Jude 1:9","v":"Zechariah was shown Joshua the high priest standing before the Angel of the LORD, with Satan (lit. the Adversary, by the NKJV note) at his right hand to oppose him; the LORD rebuked Satan, for Joshua was a brand plucked from the fire. His filthy garments were taken away, his iniquity removed, and he was clothed with rich robes and a clean turban. The Angel admonished Joshua that if he walked in the LORD's ways he would judge His house; Joshua and his companions were a wondrous sign (lit. men of a sign or wonder, by the NKJV note), for the LORD would bring forth His Servant the BRANCH; on the stone laid before Joshua were seven eyes, and the LORD would remove the iniquity of the land in one day. The words 'The Lord rebuke you!' are also Michael's in Jude 1:9"},{"p":"contents","r":"NKJV notes, note on Zechariah 4:9; NKJV notes, note on Zechariah 4:10; NKJV notes, note on Zechariah 4:14; Zechariah 4:1–14; Revelation 11:3–4","v":"The angel woke Zechariah, and he saw a lampstand of solid gold with seven lamps, and two olive trees beside it. The word of the LORD to Zerubbabel was that the work would be done not by might or power but by His Spirit; the great mountain would become a plain before him, and he would bring forth the capstone; his hands had laid the foundation of this temple (lit. house, by the NKJV note) and would finish it, and the seven eyes of the LORD would rejoice to see the plumb line (lit. plummet stone, by the NKJV note) in his hand. The two olive trees were the two anointed ones (lit. sons of fresh oil, by the NKJV note) who stand beside the Lord of the whole earth. Revelation 11:3–4 calls the two witnesses the two olive trees and the two lampstands standing before the God of the earth"},{"p":"contents","r":"NKJV notes, note on Zechariah 5:6; NKJV notes, note on Zechariah 5:11; Zechariah 5:1–11","v":"Zechariah saw a flying scroll twenty cubits long and ten wide, the curse going out over the whole earth, by which every thief and every perjurer would be expelled, and which would enter their houses and consume them. Then the angel showed him a basket (Heb. ephah, by the NKJV note) going forth, with a woman called Wickedness sitting inside, thrust down under a lead cover; two women with wings like a stork's carried it away, to build a house for it in the land of Shinar (Babylon, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Zechariah 6:11; NKJV notes, note on Zechariah 6:14; Zechariah 6:1–15","v":"Zechariah saw four chariots come from between two mountains of bronze, with red, black, white and dappled horses: the four spirits of heaven, who went out from before the Lord of all the earth to walk to and fro throughout it, and those that went to the north country gave rest to His Spirit there. Then the word of the LORD came to him to take silver and gold from the captives Heldai, Tobijah and Jedaiah, come from Babylon, make an elaborate crown (lit. crowns, by the NKJV note) and set it on the head of Joshua the son of Jehozadak, the high priest: the Man whose name is the BRANCH would build the temple of the LORD and be a priest on His throne; the crown would be a memorial in the temple for Helem, Tobijah, Jedaiah and Hen, and those from afar would come and build the temple"},{"p":"contents","r":"NKJV notes, note on Zechariah 7:2; Zechariah 7:1–14","v":"In the fourth year of King Darius, on the fourth day of the ninth month, Chislev, the word of the LORD came to Zechariah, when the people sent Sherezer (or Sar-Ezer, by the NKJV note) with Regem-Melech and his men to the house of God (Heb. Bethel, by the NKJV note) to pray before the LORD and to ask the priests and the prophets whether they should still weep and fast in the fifth month. The LORD asked whether their fasts in the fifth and seventh months during those seventy years had been for Him, and bade them execute true justice and show mercy, as their fathers would not: they made their hearts like flint against the law and the former prophets, so He scattered them among the nations, and the pleasant land was made desolate"},{"p":"contents","r":"Zechariah 8:1–23; Ephesians 4:25","v":"The LORD, zealous for Zion, would return and dwell in Jerusalem, the City of Truth; old men and women would sit in its streets and children play there; He would gather His people from east and west; those who heard the prophets of the day the foundation was laid were to be strong, for the seed would prosper, and Judah and Israel, once a curse, would be a blessing; they were to speak truth and judge justly. The fasts of the fourth, fifth, seventh and tenth months would become cheerful feasts, and many peoples would come to seek the LORD in Jerusalem, ten men grasping the sleeve of a Jewish man. Ephesians 4:25 takes up the call for each to speak truth with his neighbor"},{"p":"contents","r":"NKJV notes, note on Zechariah 9:1; NKJV notes, note on Zechariah 9:6; Zechariah 9:1–17; Matthew 21:4–5; John 12:14–15","v":"The burden (oracle, prophecy, by the NKJV note) of the word of the LORD against the land of Hadrach, with Damascus its resting place: Hamath, Tyre and Sidon would be judged, and Tyre, for all her silver and gold, cast out and devoured by fire; Ashkelon, Gaza and Ekron would fear, a mixed race (lit. an illegitimate one, by the NKJV note) would settle in Ashdod, and the LORD would camp around His house. The daughter of Zion was to rejoice, for her King was coming, just and having salvation, lowly and riding on a donkey, a colt, and He would speak peace to the nations. Because of the blood of the covenant the LORD would set the prisoners of hope free, bend Judah as His bow against the sons of Greece, and save His people as His flock. Matthew 21:4–5 and John 12:14–15 quote the King coming lowly on a donkey's colt"},{"p":"contents","r":"NKJV notes, note on Zechariah 10:2; NKJV notes, note on Zechariah 10:11; Zechariah 10:1–12","v":"They were to ask the LORD for rain; the people wandered like sheep with no shepherd, for the idols (Heb. teraphim, by the NKJV note) and the diviners spoke lies, and the LORD's anger was against the shepherds; He would visit the house of Judah and make them His royal horse in battle, and from Judah would come the cornerstone, the tent peg and the battle bow; He would strengthen Judah, save the house of Joseph and gather them from Egypt and Assyria into Gilead and Lebanon, drying up the depths of the River (the Nile, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Zechariah 11:7; Zechariah 11:1–17; Matthew 27:9–10","v":"Lebanon's cedars and Bashan's oaks would be laid low. At the LORD's word the prophet fed the flock for slaughter with two staffs, Beauty and Bonds (or Grace and Unity, by the NKJV notes); he dismissed three shepherds in one month, broke Beauty to break the covenant with the peoples, was paid thirty pieces of silver as his wages and threw them to the potter in the house of the LORD, and broke Bonds to break the brotherhood between Judah and Israel; then he took the implements of a foolish shepherd, for the LORD would raise up a worthless shepherd. Matthew 27:9–10, which names Jeremiah the prophet, takes up the thirty pieces of silver and the potter"},{"p":"contents","r":"NKJV notes, note on Zechariah 12:1; NKJV notes, note on Zechariah 12:2; NKJV notes, note on Zechariah 12:11; Zechariah 12:1–14; John 19:37; Revelation 1:7","v":"The burden (oracle, prophecy, by the NKJV note) of the word of the LORD against Israel, from the LORD who stretches out the heavens: He would make Jerusalem a cup of drunkenness (lit. reeling, by the NKJV note) and a heavy stone for all the peoples who besiege it, strike their horses with madness, make the governors of Judah like a firepan among sheaves, and defend the inhabitants of Jerusalem, the feeble among them like David. He would pour on the house of David and on Jerusalem the Spirit of grace and supplication; they would look on Him whom they pierced and mourn for Him as for an only son, a great mourning like that at Hadad Rimmon in the plain of Megiddo (Heb. Megiddon, by the NKJV note), every family apart. John 19:37 quotes its word of the One they pierced, and Revelation 1:7 echoes it"},{"p":"contents","r":"Zechariah 13:1–9; Matthew 26:31; Mark 14:27","v":"In that day a fountain would be opened for the house of David and Jerusalem, for sin and uncleanness; the LORD would cut off the names of the idols and make the false prophets and the unclean spirit depart, so that a prophet would be ashamed of his vision and deny he was one. The sword was to awake against the LORD's Shepherd, the Man who is His Companion: the Shepherd struck, the sheep would be scattered; two-thirds in the land would be cut off, and the third brought through the fire and refined would call on His name. Matthew 26:31 and Mark 14:27 quote the Shepherd struck and the sheep scattered"},{"p":"contents","r":"NKJV notes, note on Zechariah 14:8; Zechariah 14:1–21","v":"The day of the LORD: all nations gathered against Jerusalem, the city taken and half of it led captive; then the LORD would fight against those nations, His feet standing on the Mount of Olives, which would split in two from east to west, and they would flee through His valley to Azal, as they fled from the earthquake in the days of Uzziah king of Judah. Living waters would flow from Jerusalem to the eastern sea and the western sea (the Dead Sea and the Mediterranean Sea, by the NKJV notes); the LORD would be King over all the earth; the land would become a plain from Geba to Rimmon, and Jerusalem be inhabited from Benjamin's Gate to the Corner Gate and from the Tower of Hananel to the king's winepresses. A plague would strike the nations that fought against Jerusalem; those left would go up year by year to worship the King, the LORD of hosts, and keep the Feast of Tabernacles, with no rain on those who did not come; HOLINESS TO THE LORD would be on the bells of the horses, and every pot in Jerusalem and Judah would be holy"},{"p":"designation","r":"Zechariah 1:1","v":"In the eighth month"},{"p":"feature","r":"Zechariah 1:1, 7; 7:1","v":"Its first words are dated by the year of King Darius and the month: the eighth month of his second year, the twenty-fourth day of the eleventh month, Shebat, of that year, and the fourth day of the ninth month, Chislev, of his fourth year"},{"p":"feature","r":"Zechariah 1:7–6:8","v":"Zechariah tells in the first person eight visions he saw by night, with an angel who talked with him and told him what they were"},{"p":"feature","r":"NKJV notes, note on Zechariah 9:1; Zechariah 9:1; 12:1","v":"Two burdens (oracles, by the NKJV note) of the word of the LORD, against the land of Hadrach and against Israel, end the book; they bear no date and do not name the prophet"},{"p":"feature","r":"Zechariah 9:9; 11:12–13; 12:10; 13:7; Matthew 21:4–5; 26:31; 27:9–10; Mark 14:27; John 12:14–15; 19:37","v":"The New Testament quotes it: the King coming lowly on a donkey, the thirty pieces of silver and the potter, the One they pierced, and the Shepherd struck"},{"p":"made by","r":"Zechariah 1:1, 7–8; 7:1, 8","e":"PER-02291","b":"inferred","c":"probable","w":"The book gives the words of the LORD that came to Zechariah (Zechariah 1:1, 7; 7:1, 8) and tells his visions in the first person (1:8); it does not say who wrote it down."}],"nm":{"PER-02291":"Zechariah"}},"OBJ-00577":{"k":"object","n":"The flying scroll","d":"The flying scroll Zechariah saw in his vision by night, twenty cubits long and ten cubits wide, the curse going out over the whole earth (Zechariah 5:1–4)","f":[{"p":"contents","r":"Zechariah 5:3","v":"On one side, that every thief would be expelled; on the other, that every perjurer would be expelled"},{"p":"designation","r":"Zechariah 5:3","v":"the curse that goes out over the face of the whole earth"},{"p":"length in cubits","r":"Zechariah 5:2","v":"20 cubits"},{"p":"width in cubits","r":"Zechariah 5:2","v":"10 cubits"}],"nm":{}},"OBJ-00578":{"k":"object","n":"The crown for Joshua the high priest","d":"The elaborate crown of the silver and gold received from the captives, which Zechariah was to set on the head of Joshua the high priest, to be a memorial in the temple of the LORD (Zechariah 6:10–14)","f":[{"p":"designation","r":"NKJV notes, note on Zechariah 6:11; Zechariah 6:11, 14","v":"an elaborate crown"},{"p":"material","r":"Zechariah 6:11","v":"Silver and gold"},{"p":"purpose","r":"NKJV notes, note on Zechariah 6:14; Zechariah 6:14","v":"A memorial in the temple of the LORD for Helem, Tobijah, Jedaiah and Hen the son of Zephaniah"}],"nm":{}},"OBJ-00579":{"k":"object","n":"The staff called Beauty","d":"One of the two staffs the prophet took to feed the flock for slaughter, which he cut in two to break the covenant made with all the peoples (Zechariah 11:7, 10–11)","f":[{"p":"name","r":"Zechariah 11:7, 10","v":"Beauty"},{"p":"name","r":"NKJV notes, note on Zechariah 11:7; NKJV notes, note on Zechariah 11:10; Zechariah 11:7, 10","v":"Grace","b":"NKJV note"},{"p":"purpose","r":"Zechariah 11:7, 10–11","v":"To feed the flock for slaughter; cut in two, to break the covenant He had made with all the peoples"}],"nm":{}},"OBJ-00580":{"k":"object","n":"The staff called Bonds","d":"One of the two staffs the prophet took to feed the flock for slaughter, which he cut in two to break the brotherhood between Judah and Israel (Zechariah 11:7, 14)","f":[{"p":"name","r":"Zechariah 11:7, 14","v":"Bonds"},{"p":"name","r":"NKJV notes, note on Zechariah 11:7; NKJV notes, note on Zechariah 11:14; Zechariah 11:7, 14","v":"Unity","b":"NKJV note"},{"p":"purpose","r":"Zechariah 11:7, 14","v":"To feed the flock for slaughter; cut in two, to break the brotherhood between Judah and Israel"}],"nm":{}},"OBJ-00581":{"k":"object","n":"The Book of Malachi","d":"The burden of the word of the LORD to Israel by Malachi: His love for Jacob, His charges against the priests and the people, the messenger who will prepare His way, the book of remembrance and the day of the LORD (Malachi 1–4)","f":[{"p":"contents","r":"NKJV notes, note on Malachi 1:1; NKJV notes, note on Malachi 1:7; Malachi 1:1–14; Romans 9:13","v":"The burden (oracle, prophecy, by the NKJV note) of the word of the LORD to Israel by Malachi. The LORD had loved Jacob and hated Esau, laying waste his mountains and his heritage; if Edom built again He would throw it down, and it would be called the Territory of Wickedness. The priests despised His name, offering defiled food on His altar and calling His table contemptible (or to be despised, by the NKJV note); they brought the blind, the lame and the sick, which they would not offer their governor, and one of them should shut the temple doors rather than kindle fire on His altar in vain; yet from the rising of the sun to its going down His name would be great among the Gentiles, and cursed was the deceiver who vowed a male and sacrificed a blemished one, for He is a great King. Romans 9:13 quotes the LORD's word that He loved Jacob and hated Esau"},{"p":"contents","r":"NKJV notes, note on Malachi 2:6; Malachi 2:1–16","v":"The commandment for the priests: if they would not give glory to His name He would curse their blessings and spread the refuse of their feasts on their faces. His covenant with Levi was one of life and peace; the law of truth was in Levi's mouth, and the lips of a priest should keep knowledge, for he is the messenger of the LORD of hosts; but they had departed from the way, corrupted the covenant of Levi and shown partiality in the law. Judah dealt treacherously, profaning the LORD's holy institution, and married the daughter of a foreign god; they covered His altar with tears, for He no longer regarded their offering, because they dealt treacherously with the wives of their youth; the LORD God of Israel hates divorce, and they were to take heed to their spirit"},{"p":"contents","r":"NKJV notes, note on Malachi 3:17; Malachi 2:17–3:18; Matthew 11:10; Mark 1:2; Luke 7:27","v":"The people wearied the LORD, saying that He delighted in evildoers and asking where the God of justice was. He would send His messenger to prepare the way before Him, and the Lord they sought, the Messenger of the covenant, would suddenly come to His temple, like a refiner's fire and launderers' soap, purifying the sons of Levi, and would be a swift witness against sorcerers, adulterers, perjurers and oppressors. He does not change: they had robbed Him in tithes and offerings, and were to bring all the tithes into the storehouse, and He would open the windows of heaven. When they said it was useless to serve God, those who feared the LORD spoke to one another, and a book of remembrance was written before Him: they would be His jewels (lit. special treasure, by the NKJV note). Matthew 11:10, Mark 1:2 and Luke 7:27 quote the messenger sent to prepare the way, of John the Baptist"},{"p":"contents","r":"Malachi 4:1–6; Matthew 11:14; 17:10–13; Mark 9:11–13; Luke 1:17","v":"The day was coming, burning like an oven, when the proud would be stubble; to those who fear His name the Sun of Righteousness would arise with healing in His wings. They were to remember the Law of Moses, commanded him in Horeb, and the LORD would send Elijah the prophet before the great and dreadful day of the LORD, to turn the hearts of the fathers to the children and of the children to their fathers. Luke 1:17 says John would go before the Lord in the spirit and power of Elijah to turn the hearts of the fathers to the children, and Matthew 11:14; 17:10–13 and Mark 9:11–13 speak of Elijah as come already"},{"p":"designation","r":"NKJV notes, note on Malachi 1:1; Malachi 1:1","v":"The burden of the word of the LORD to Israel"},{"p":"feature","r":"Malachi 1:1","v":"It names no king and gives no date"},{"p":"feature","r":"Malachi 1:2, 6–7; 2:14, 17; 3:7–8, 13","v":"The LORD's sayings are met with the people's and the priests' questions, 'In what way?', and answered in turn"},{"p":"feature","r":"Malachi 4:4–6","v":"It ends with the call to remember the Law of Moses and the promise to send Elijah the prophet before the great and dreadful day of the LORD"},{"p":"feature","r":"Malachi 1:2–3; 3:1; 4:5–6; Matthew 11:10, 14; 17:10–13; Mark 1:2; 9:11–13; Luke 1:17; 7:27; Romans 9:13","v":"The New Testament takes up its word that the LORD loved Jacob and hated Esau, and its messenger who prepares the way and its Elijah, of John the Baptist"},{"p":"made by","r":"NKJV notes, note on Malachi 1:1; Malachi 1:1","e":"PER-02998","b":"inferred","c":"probable","w":"The book is the burden of the word of the LORD to Israel by Malachi (Malachi 1:1; lit. by the hand of, by the NKJV note); it does not say who wrote it down."}],"nm":{"PER-02998":"Malachi"}},"OBJ-00582":{"k":"object","n":"The book of remembrance","d":"The book of remembrance written before the LORD for those who fear Him and meditate on His name (Malachi 3:16)","f":[{"p":"designation","r":"Malachi 3:16","v":"a book of remembrance"},{"p":"purpose","r":"NKJV notes, note on Malachi 3:16; Malachi 3:16","v":"Written before the LORD for those who fear the LORD and who meditate on (or esteem, by the NKJV note) His name"}],"nm":{}},"OBJ-00583":{"k":"object","n":"The star of the King of the Jews","d":"The star the wise men saw in the East, which went before them to Bethlehem and stood over where the young Child was (Matthew 2:2, 7–10)","f":[{"p":"designation","r":"Matthew 2:2","v":"His star"},{"p":"feature","r":"Matthew 2:2, 9","v":"Seen in the East, it went before the wise men and stood over where the young Child was"}],"nm":{}},"OBJ-00584":{"k":"object","n":"The gifts of the wise men","d":"The gifts the wise men presented to the young Child when they opened their treasures (Matthew 2:11)","f":[{"p":"contents","r":"Matthew 2:11","v":"Gold, frankincense and myrrh"},{"p":"designation","r":"Matthew 2:11","v":"gifts"}],"nm":{}},"OBJ-00585":{"k":"object","n":"The Gospel according to Matthew","d":"The book of the genealogy of Jesus Christ, the Son of David, the Son of Abraham: His birth, His teaching and works, His death and His rising again (Matthew 1–28)","f":[{"p":"contents","r":"NKJV notes, note on Matthew 1:1; NKJV notes, note on Matthew 1:11; NKJV notes, note on Matthew 1:19; NKJV notes, note on Matthew 1:21; NKJV notes, note on Matthew 1:25; Matthew 1:1–25","v":"The book of the genealogy (lit. generation, by the NKJV note) of Jesus Christ, the Son of David, the Son of Abraham: from Abraham through Isaac, Jacob, Judah, Perez (by Tamar), Hezron, Ram, Amminadab, Nahshon, Salmon, Boaz (by Rahab), Obed (by Ruth) and Jesse to David the king; from David through Solomon (by the wife of Uriah) and the kings of Judah, from Joram to Uzziah and from Josiah to Jeconiah (or Coniah or Jehoiachin, by the NKJV note), to the carrying away to Babylon; and after it through Shealtiel, Zerubbabel, Abiud, Eliakim, Azor, Zadok, Achim, Eliud, Eleazar, Matthan and Jacob to Joseph the husband of Mary, of whom Jesus was born, three sets of fourteen generations. Mary, betrothed to Joseph, was found with child of the Holy Spirit; Joseph, a just man (an upright, by the NKJV note), meant to put her away secretly, but an angel of the Lord told him in a dream to take her as his wife, for her Son, whom he was to call Jesus (lit. Savior, by the NKJV note), would save His people from their sins; so the prophet's word was fulfilled, that the virgin would bear a Son called Immanuel, God with us. Joseph took Mary as his wife and did not know her (kept her a virgin, by the NKJV note) till she had brought forth her firstborn Son, and he called His name Jesus"},{"p":"contents","r":"NKJV notes, note on Matthew 2:1; Matthew 2:1–23","v":"In the days of Herod the king wise men (Gr. magoi, by the NKJV note) came from the East to Jerusalem seeking the newborn King of the Jews, whose star they had seen; Herod, troubled, learned from the chief priests and scribes that the Christ was to be born in Bethlehem of Judea, as the prophet wrote, and sent the wise men there; the star went before them to where the young Child was, and they worshiped Him with gifts of gold, frankincense and myrrh and, warned in a dream, went home another way. Warned by an angel, Joseph fled with the young Child and His mother to Egypt until Herod's death, fulfilling the word that the Lord called His Son out of Egypt; Herod put to death the male children of Bethlehem two years old and under, fulfilling Jeremiah's word of Rachel weeping. After Herod died, Joseph brought them back to the land of Israel, but, as Archelaus reigned over Judea, turned aside to Galilee and dwelt in Nazareth, that Jesus would be called a Nazarene"},{"p":"contents","r":"NKJV notes, note on Matthew 3:11; Isaiah 40:3; Matthew 3:1–17","v":"John the Baptist came preaching repentance in the wilderness of Judea, for the kingdom of heaven was at hand: he was the voice crying in the wilderness of whom Isaiah spoke, clothed in camel's hair and living on locusts and wild honey; Jerusalem, Judea and the region around the Jordan were baptized by him, confessing their sins, and he warned the Pharisees and Sadducees, a brood of vipers, to bear fruits worthy of repentance, for One mightier was coming who would baptize with the Holy Spirit and fire (M omits and fire, by the NKJV note). Jesus came from Galilee to be baptized by John, to fulfill all righteousness; as He came up from the water the heavens were opened, the Spirit of God descended on Him like a dove, and a voice from heaven called Him His beloved Son"},{"p":"contents","r":"NKJV notes, note on Matthew 4:17; NKJV notes, note on Matthew 4:24; Deuteronomy 6:13, 16; 8:3; Psalms 91:11–12; Isaiah 9:1–2; Matthew 4:1–25","v":"The Spirit led Jesus into the wilderness, and after He had fasted forty days and forty nights the devil tempted Him to turn stones into bread, to throw Himself down from the pinnacle of the temple, and to worship him for all the kingdoms of the world; Jesus answered each time from Scripture (Deuteronomy 8:3; 6:16; 6:13), against the devil's use of Psalm 91:11–12, and angels came and ministered to Him. When John was put in prison Jesus left Nazareth and dwelt in Capernaum by the sea, in the regions of Zebulun and Naphtali, fulfilling Isaiah's word of a great light in Galilee of the Gentiles; from that time He preached that the kingdom of heaven was at hand (has drawn near, by the NKJV note), called the fishermen Simon Peter and Andrew, and James and John the sons of Zebedee, to follow Him, and went about all Galilee teaching, preaching and healing, while His fame (lit. the report of Him, by the NKJV note) went through all Syria and great multitudes followed Him"},{"p":"contents","r":"NKJV notes, note on Matthew 5:5; NKJV notes, note on Matthew 5:18; Matthew 5:1–48","v":"Seeing the multitudes, Jesus went up on a mountain and taught His disciples: blessed are the poor in spirit, the mourners, the meek, who will inherit the earth (or land, by the NKJV note), the hungry for righteousness, the merciful, the pure in heart, the peacemakers and the persecuted; they are the salt of the earth and the light of the world. He came not to destroy the Law or the Prophets but to fulfill them, and not one jot or tittle (the smallest letter and stroke, by the NKJV notes) would pass from the law; anger and contempt are judged like murder, and lust like adultery; divorce except for sexual immorality causes adultery; they are not to swear at all, nor resist an evil person, but turn the other cheek, go the second mile, love their enemies and be perfect as their Father in heaven is perfect"},{"p":"contents","r":"NKJV notes, note on Matthew 6:5; NKJV notes, note on Matthew 6:24; Matthew 6:1–34","v":"Charitable deeds, prayer and fasting are to be done in secret, not before men as the hypocrites (pretenders, by the NKJV note) do, and the Father who sees in secret will reward them; they are to pray to their Father in heaven, that His name be hallowed, His kingdom come and His will be done, for daily bread, forgiveness and deliverance from the evil one, and to forgive others; they are to lay up treasures in heaven, for no one can serve God and mammon (lit. riches, in Aramaic, by the NKJV note), and not to worry about food or clothing, for the Father feeds the birds and clothes the lilies more richly than Solomon in all his glory, but to seek first the kingdom of God and His righteousness"},{"p":"contents","r":"NKJV notes, note on Matthew 7:1; Matthew 7:1–29","v":"They are not to judge (condemn, by the NKJV note), but first remove the plank from their own eye; they are to ask, seek and knock, for the Father gives good things to those who ask; whatever they want men to do to them they are to do, for this is the Law and the Prophets; they are to enter by the narrow gate, beware of false prophets, known by their fruits, and do the will of His Father, for whoever hears His sayings and does them is like a wise man who built his house on the rock. The people were astonished, for He taught them as one having authority, and not as the scribes"},{"p":"contents","r":"NKJV notes, note on Matthew 8:27; NKJV notes, note on Matthew 8:28; Matthew 8:1–34","v":"Coming down from the mountain, Jesus cleansed a leper and sent him to the priest; in Capernaum He healed a centurion's servant by a word, marveling at such faith, and Peter's wife's mother of a fever, and at evening He healed many, fulfilling Isaiah's word that He bore our sicknesses. He told a scribe that the Son of Man had nowhere to lay His head, and a disciple to let the dead bury their dead; in the boat He rebuked the wind and the sea, and on the other side, in the country of the Gergesenes (NU Gadarenes, by the NKJV note), He sent the demons out of two fierce men into a herd of swine, which ran into the sea, and the city begged Him to leave"},{"p":"contents","r":"NKJV notes, note on Matthew 9:15; Hosea 6:6; Matthew 9:1–38","v":"In His own city Jesus forgave and healed a paralytic, to show that the Son of Man has power to forgive sins; He called Matthew from the tax office and ate with tax collectors and sinners, telling the Pharisees to learn what 'I desire mercy' means (Hosea 6:6); He told John's disciples that His disciples (lit. sons of the bridechamber, by the NKJV note) would fast when the bridegroom was taken away. On the way to raise a ruler's daughter He healed a woman who touched His garment; He opened the eyes of two blind men and made a mute man speak, while the Pharisees said He cast out demons by the ruler of the demons; moved with compassion for the multitudes, He bade His disciples pray the Lord of the harvest for laborers"},{"p":"contents","r":"NKJV notes, note on Matthew 10:3; NKJV notes, note on Matthew 10:25; Micah 7:6; Matthew 10:1–42","v":"Jesus gave His twelve disciples power over unclean spirits and every sickness; the twelve apostles were Simon called Peter and Andrew, James and John the sons of Zebedee, Philip and Bartholomew, Thomas and Matthew the tax collector, James the son of Alphaeus and Lebbaeus called Thaddaeus, Simon the Cananite and Judas Iscariot, who betrayed Him. He sent them to the lost sheep of the house of Israel to preach and heal, taking nothing for the journey; He warned them that they would be delivered up and hated for His name's sake, as sheep among wolves, and bade them not fear those who kill the body; He came to bring not peace but a sword, a man's enemies being of his own household (words from Micah 7:6), and whoever gives a cup of cold water to one of these little ones will not lose his reward. Beelzebub (NU, M Beelzebul, a Philistine deity, by the NKJV note) is named"},{"p":"contents","r":"NKJV notes, note on Matthew 11:29; Malachi 3:1; 4:5; Matthew 11:1–30","v":"Jesus went on to teach in their cities. John, in prison, sent his disciples to ask whether He was the Coming One, and Jesus answered with His works; He told the multitudes that John was more than a prophet, the messenger of whom it is written, and Elijah who is to come, and that this generation had refused both John and the Son of Man. He rebuked Chorazin, Bethsaida and Capernaum, where most of His mighty works were done, for they did not repent; He thanked the Father, Lord of heaven and earth, for revealing these things to babes, and called all who labor and are heavy laden to come to Him, for He is gentle (meek, by the NKJV note) and lowly in heart"},{"p":"contents","r":"NKJV notes, note on Matthew 12:24; Isaiah 42:1–4; Matthew 12:1–50","v":"When the Pharisees blamed His disciples for plucking grain on the Sabbath, Jesus answered with what David did and the priests in the temple, for the Son of Man is Lord even of the Sabbath; He healed a withered hand in the synagogue, and the Pharisees plotted to destroy Him. He withdrew and healed the multitudes, fulfilling Isaiah's word of the Servant on whom the Spirit would rest (Isaiah 42:1–4). When He healed a blind and mute demoniac the Pharisees said He cast out demons by Beelzebub (NU, M Beelzebul, a Philistine deity, by the NKJV note); He answered that Satan does not cast out Satan, that blasphemy against the Spirit will not be forgiven, and that no sign would be given but the sign of the prophet Jonah, three days and nights in the great fish; the men of Nineveh and the queen of the South would condemn this generation. Whoever does the will of His Father is His brother and sister and mother"},{"p":"contents","r":"NKJV notes, note on Matthew 13:55; Psalms 78:2; Isaiah 6:9–10; Matthew 13:1–58","v":"The same day He taught the multitude by the sea in parables, of the sower, the tares, the mustard seed and the leaven, as Isaiah foretold that they would hear and not understand (Isaiah 6:9–10) and as the prophet said He would open His mouth in parables (Psalm 78:2); in the house He explained to His disciples the sower and the tares, and told of the hidden treasure, the pearl of great price and the dragnet. In His own country they were offended at Him, asking whether He was not the carpenter's son, whose mother was Mary and whose brothers were James, Joses (NU Joseph, by the NKJV note), Simon and Judas, and He did not do many mighty works there because of their unbelief"},{"p":"contents","r":"Matthew 14:1–36","v":"Herod the tetrarch, hearing of Jesus, said John the Baptist was risen: he had imprisoned John for the sake of Herodias, his brother Philip's wife, and at his birthday, bound by his oath to her dancing daughter, had him beheaded, and John's disciples buried him and told Jesus. In a deserted place Jesus fed about five thousand men, besides women and children, with five loaves and two fish, and twelve baskets of fragments were left; that night He walked on the sea to the boat, Peter walked on the water and began to sink, and those in the boat worshiped Him as the Son of God. In the land of Gennesaret all who touched the hem of His garment were made well"},{"p":"contents","r":"NKJV notes, note on Matthew 15:39; Exodus 20:12; 21:17; Isaiah 29:13; Matthew 15:1–39","v":"To the scribes and Pharisees from Jerusalem Jesus answered that by their tradition they made the commandment of God of no effect (Exodus 20:12; 21:17), as Isaiah prophesied of lip worship (Isaiah 29:13), and that what comes out of the heart defiles a man. In the region of Tyre and Sidon He healed the daughter of a woman of Canaan for her great faith; on a mountain by the Sea of Galilee He healed great multitudes, and fed four thousand men, besides women and children, with seven loaves and a few little fish, and seven large baskets were left; then He crossed to the region of Magdala (NU Magadan, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Matthew 16:6; NKJV notes, note on Matthew 16:18; Matthew 16:1–28","v":"The Pharisees and Sadducees asked for a sign from heaven and were given none but the sign of the prophet Jonah; Jesus warned His disciples of their leaven (yeast, by the NKJV note), their doctrine. In the region of Caesarea Philippi, when the disciples said men took Him for John the Baptist, Elijah, Jeremiah or a prophet, Simon Peter confessed Him as the Christ, the Son of the living God, and Jesus said He would build His church on this rock and give Peter the keys of the kingdom of heaven. From that time He showed them that He must suffer at Jerusalem, be killed and be raised the third day, and rebuked Peter, who would not have it; whoever would come after Him must deny himself and take up his cross, for the Son of Man will come in the glory of His Father with His angels"},{"p":"contents","r":"NKJV notes, note on Matthew 17:15; NKJV notes, note on Matthew 17:24; Matthew 17:1–27","v":"After six days He was transfigured before Peter, James and John on a high mountain, His face shining like the sun, and Moses and Elijah talked with Him; a voice from a bright cloud called Him the beloved Son and bade them hear Him. Coming down, He told them that Elijah had come already, and they understood He spoke of John the Baptist. He healed an epileptic (lit. moonstruck, by the NKJV note) boy whom the disciples could not cure, for faith as a mustard seed moves mountains; in Galilee He foretold again His betrayal, death and rising; and in Capernaum He had Peter pay the temple tax (lit. double drachma, by the NKJV note) for both with a coin from a fish's mouth"},{"p":"contents","r":"NKJV notes, note on Matthew 18:9; Deuteronomy 19:15; Matthew 18:1–35","v":"When the disciples asked who was greatest in the kingdom of heaven, Jesus set a little child among them: whoever humbles himself as a child is greatest; woe to him by whom offenses come; their Father in heaven does not will that one of these little ones perish, as a man seeks the one straying sheep; a brother who sins is to be told his fault alone, then before two or three witnesses (Deuteronomy 19:15), then before the church; and Peter was to forgive up to seventy times seven, for the servant forgiven ten thousand talents who would not forgive a hundred denarii was handed to the torturers (Gehenna named, by the NKJV note)"},{"p":"contents","r":"NKJV notes, note on Matthew 19:9; Genesis 1:27; 2:24; Leviticus 19:18; Deuteronomy 24:1; Matthew 19:1–30","v":"Jesus left Galilee for the region of Judea beyond the Jordan; to the Pharisees He answered that God made them male and female and the two one flesh (Genesis 1:27; 2:24), and that Moses allowed a certificate of divorce (Deuteronomy 24:1) for the hardness of their hearts, but whoever divorces except for sexual immorality (or fornication, by the NKJV note) and remarries commits adultery. He blessed little children, for of such is the kingdom of heaven; He bade a rich young man keep the commandments, love his neighbor as himself (Leviticus 19:18), sell what he had and follow Him, and the young man went away sorrowful; with God all things are possible, and those who have left all for His name's sake will receive a hundredfold and sit on twelve thrones judging the twelve tribes of Israel"},{"p":"contents","r":"Matthew 20:1–34","v":"The kingdom of heaven is like a landowner who paid the laborers hired at the eleventh hour as much as those who bore the heat of the day, so the last will be first. Going up to Jerusalem Jesus foretold a third time that He would be condemned, mocked, scourged and crucified, and rise the third day; to the mother of Zebedee's sons, who asked that they sit at His right and left, He answered that whoever would be great must serve, as the Son of Man came to give His life a ransom for many; and leaving Jericho He opened the eyes of two blind men who cried to Him as the Son of David"},{"p":"contents","r":"NKJV notes, note on Matthew 21:15; Psalms 8:2; 118:22–23, 26; Isaiah 56:7; Jeremiah 7:11; Matthew 21:1–46","v":"At Bethphage by the Mount of Olives Jesus sent for a donkey and a colt and rode into Jerusalem, fulfilling the word of Zion's King coming lowly on a donkey, while the multitudes spread their clothes and branches and cried Hosanna to the Son of David, blessed is He who comes in the name of the LORD (Psalm 118:26). He drove the buyers and sellers out of the temple, for His house is a house of prayer (Isaiah 56:7) made a den of thieves (Jeremiah 7:11), healed the blind and the lame, answered the indignant (angry, by the NKJV note) chief priests with the praise from the mouth of babes (Psalm 8:2), and lodged at Bethany; in the morning He cursed a barren fig tree, which withered. Questioned on His authority, He asked whether John's baptism was from heaven, and told of the two sons and of the vinedressers who killed the owner's son, the stone the builders rejected (Psalm 118:22–23)"},{"p":"contents","r":"Exodus 3:6; Leviticus 19:18; Deuteronomy 6:5; 25:5; Psalms 110:1; Matthew 22:1–46","v":"Jesus told of the king whose invited guests would not come to his son's wedding, so that the highways filled the hall; many are called, but few are chosen. To the Pharisees and Herodians He said to render to Caesar what is Caesar's and to God what is God's; to the Sadducees, that in the resurrection they neither marry nor are given in marriage, for God is the God of Abraham, Isaac and Jacob, the God of the living (Exodus 3:6; Deuteronomy 25:5); to a lawyer, that the great commandment is to love God with all one's heart, soul and mind, and the second to love one's neighbor as oneself (Deuteronomy 6:5; Leviticus 19:18); and He asked the Pharisees how David in the Spirit could call the Christ his Lord (Psalm 110:1), and none dared question Him any more"},{"p":"contents","r":"NKJV notes, note on Matthew 23:8; Matthew 23:1–39","v":"Jesus told the multitudes and His disciples to observe what the scribes and Pharisees in Moses' seat taught, but not to do their works, for they did all to be seen, and not to be called Rabbi, for One is their Teacher (Leader, by the NKJV note), the Christ. He pronounced woes on the scribes and Pharisees, hypocrites and blind guides, who shut up the kingdom of heaven, made proselytes sons of hell, tithed mint and neglected justice, mercy and faith, and were like whitewashed tombs, and said that the righteous blood from Abel to Zechariah son of Berechiah would come on this generation; He lamented over Jerusalem, which killed the prophets, and whose house would be left desolate"},{"p":"contents","r":"NKJV notes, note on Matthew 24:31; Matthew 24:1–51","v":"Leaving the temple, Jesus foretold that not one stone of it would be left on another. On the Mount of Olives He told His disciples of the signs of His coming and the end of the age: false christs, wars, famines and earthquakes, persecution, the gospel preached to all nations; the abomination of desolation spoken of by Daniel the prophet standing in the holy place, and a great tribulation; then the Son of Man coming on the clouds with power and great glory, and His angels gathering His elect (chosen ones, by the NKJV note); the lesson of the fig tree; no one knows the day or hour, which will come as the flood in the days of Noah; and blessed is the faithful servant whom his master finds watching"},{"p":"contents","r":"Matthew 25:1–46","v":"The kingdom of heaven is like ten virgins, five wise who took oil and went in to the wedding, five foolish who were shut out, so they are to watch; and like a man who gave his servants five, two and one talents, praising those who traded and casting out the servant who hid his talent. When the Son of Man comes in His glory He will sit on the throne of His glory and separate the nations as sheep from goats: what they did or did not do for the least of His brethren they did or did not do for Him, and they go away into everlasting punishment or into eternal life"},{"p":"contents","r":"NKJV notes, note on Matthew 26:4; NKJV notes, note on Matthew 26:28; Zechariah 13:7; Matthew 26:1–75","v":"Two days before the Passover the chief priests and elders at the palace of Caiaphas plotted to take Jesus by trickery (deception, by the NKJV note); at Bethany, in the house of Simon the leper, a woman poured costly fragrant oil on His head for His burial; Judas Iscariot agreed with the chief priests for thirty pieces of silver. Jesus ate the Passover with the twelve, foretold that one of them would betray Him, and gave them the bread, His body, and the cup, His blood of the new covenant (NU omits new, by the NKJV note) for the remission of sins. On the Mount of Olives He foretold that all would stumble, as it is written that the Shepherd would be struck and the sheep scattered (Zechariah 13:7), and that Peter would deny Him three times; in Gethsemane He prayed three times that the cup might pass, not as He willed but as the Father willed. Judas came with a multitude and kissed Him, and all the disciples fled; before Caiaphas and the council He said they would see the Son of Man at the right hand of the Power, and was condemned for blasphemy; and Peter denied Him three times before the rooster crowed, and wept bitterly"},{"p":"contents","r":"NKJV notes, note on Matthew 27:26; NKJV notes, note on Matthew 27:27; NKJV notes, note on Matthew 27:35; Psalms 22:1, 18; Matthew 27:1–66","v":"In the morning Jesus was delivered bound to Pontius Pilate the governor. Judas, remorseful, threw down the thirty pieces of silver in the temple and hanged himself, and the chief priests bought with them the potter's field, the Field of Blood, fulfilling the word Matthew gives as spoken by Jeremiah the prophet. Before Pilate Jesus answered nothing; the multitude, persuaded by the chief priests, asked for Barabbas and cried for Jesus to be crucified, and Pilate washed his hands, released Barabbas and, having scourged Jesus (flogged with a Roman scourge, by the NKJV note), delivered Him up; the soldiers mocked Him in the Praetorium (the governor's headquarters, by the NKJV note) with a scarlet robe and a crown of thorns. Simon of Cyrene bore His cross to Golgotha, the Place of a Skull, where He was crucified between two robbers and His garments divided by lot (NU, M omit the word of fulfillment, by the NKJV note; Psalm 22:18). After darkness from the sixth hour to the ninth He cried, My God, My God, why have You forsaken Me (Psalm 22:1), and yielded up His spirit; the veil of the temple was torn, the earth quaked, and the centurion said He was truly the Son of God. Joseph of Arimathea laid His body in his new tomb, and the chief priests had the stone sealed and a guard set"},{"p":"contents","r":"NKJV notes, note on Matthew 28:9; Matthew 28:1–20","v":"After the Sabbath, at the dawn of the first day of the week, Mary Magdalene and the other Mary came to the tomb; there was a great earthquake, an angel of the Lord rolled back the stone and sat on it, and the guards became like dead men. The angel told the women that Jesus was risen, as He said, and was going before the disciples into Galilee; as they went (NU omits as they went to tell His disciples, by the NKJV note) Jesus met them, and they held Him by the feet and worshiped Him. The chief priests and elders paid the soldiers to say the disciples had stolen Him while they slept. On the mountain in Galilee the eleven worshiped Him, though some doubted, and He, with all authority in heaven and on earth, sent them to make disciples of all the nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit, and promised to be with them always, to the end of the age"},{"p":"designation","r":"NKJV notes, note on Matthew 1:1; Matthew 1:1","v":"The book of the genealogy of Jesus Christ"},{"p":"feature","r":"NKJV notes, note on Matthew 1:1; Matthew 1:1–17","v":"It opens with the genealogy (lit. generation, by the NKJV note) of Jesus Christ from Abraham, in three sets of fourteen generations: from Abraham to David, from David to the captivity in Babylon, and from the captivity to the Christ"},{"p":"feature","r":"Matthew 1:22–23; 2:5–6, 15, 17–18, 23; 3:3; 4:14–16; 8:17; 12:17–21; 13:14–15, 35; 21:4–5; 27:9–10, 35","v":"It tells again and again that what was done fulfilled what the Lord had spoken by the prophets"},{"p":"feature","r":"Matthew 28:16–20","v":"It ends with the risen Jesus sending the eleven to make disciples of all the nations, with Him always, to the end of the age"}],"nm":{}},"OBJ-00586":{"k":"object","n":"The prayer Jesus taught His disciples","d":"The manner of prayer Jesus taught His disciples on the mountain, to their Father in heaven (Matthew 6:9–13)","f":[{"p":"contents","r":"NKJV notes, note on Matthew 6:13; Matthew 6:9–13","v":"That the Father's name be hallowed, His kingdom come and His will be done on earth as in heaven; for daily bread; for the forgiveness of their debts as they forgive their debtors; not to be led into temptation but delivered from the evil one; for His is the kingdom and the power and the glory forever (NU omits the rest of 6:13, by the NKJV note)"},{"p":"designation","r":"Matthew 6:9","v":"Our Father in heaven"},{"p":"made by","r":"Matthew 6:9","e":"PER-03010"},{"p":"occasion","r":"Matthew 6:9","e":"EVT-02795"}],"nm":{"EVT-02795":"Jesus teaches His disciples on the mountain","PER-03010":"Jesus"}},"OBJ-00587":{"k":"object","n":"The parable of the sower","d":"A sower's seed fell by the wayside, on stony places, among thorns and on good ground, where it yielded a hundredfold, sixty and thirty (Matthew 13:3–9; 13:18)","f":[{"p":"contents","r":"Matthew 13:3–9, 18; Mark 4:3–8","v":"A sower's seed fell by the wayside, on stony places, among thorns and on good ground, where it yielded a hundredfold, sixty and thirty"},{"p":"contents","r":"Matthew 13:18–23; Mark 4:13–20","v":"As Jesus explained it: The seed is the word of the kingdom: snatched by the wicked one from him who does not understand, withering in him who has no root, choked by cares and riches, and fruitful in him who hears and understands"},{"p":"designation","r":"Matthew 13:3–9, 18","v":"the parable of the sower"},{"p":"made by","r":"Matthew 13:3–9, 18; Mark 4:2–3","e":"PER-03010"},{"p":"occasion","r":"Matthew 13:3–9, 18; Mark 4:1–3","e":"EVT-02825"}],"nm":{"EVT-02825":"Jesus teaches the multitude in parables by the sea","PER-03010":"Jesus"}},"OBJ-00588":{"k":"object","n":"The parable of the tares of the field","d":"An enemy sowed tares among the good seed in a man's field; both were left to grow together until the harvest, when the tares would be bundled and burned and the wheat gathered into the barn (Matthew 13:24–30; 13:36)","f":[{"p":"contents","r":"Matthew 13:24–30, 36","v":"An enemy sowed tares among the good seed in a man's field; both were left to grow together until the harvest, when the tares would be bundled and burned and the wheat gathered into the barn"},{"p":"contents","r":"Matthew 13:37–39","v":"As Jesus explained it: the sower is the Son of Man, the field the world, the good seed the sons of the kingdom, the tares the sons of the wicked one, the enemy the devil, the harvest the end of the age and the reapers the angels"},{"p":"designation","r":"Matthew 13:24–30, 36","v":"the parable of the tares of the field"},{"p":"made by","r":"Matthew 13:24–30, 36","e":"PER-03010"},{"p":"occasion","r":"Matthew 13:24–30, 36","e":"EVT-02825"}],"nm":{"EVT-02825":"Jesus teaches the multitude in parables by the sea","PER-03010":"Jesus"}},"OBJ-00589":{"k":"object","n":"The parable of the mustard seed","d":"The kingdom of heaven is like a mustard seed, the least of all seeds, which grows into a tree in whose branches the birds of the air nest (Matthew 13:31–32)","f":[{"p":"contents","r":"Matthew 13:31–32","v":"The kingdom of heaven is like a mustard seed, the least of all seeds, which grows into a tree in whose branches the birds of the air nest"},{"p":"contents","r":"Mark 4:30–32","v":"As Mark tells it: the kingdom of God is like a mustard seed, smaller when sown than all the seeds on earth, which grows greater than all herbs and shoots out large branches, so that the birds of the air nest under its shade"},{"p":"designation","r":"Matthew 13:31–32","v":"The kingdom of heaven is like a mustard seed"},{"p":"made by","r":"Matthew 13:31–32; Mark 4:30","e":"PER-03010"},{"p":"occasion","r":"Matthew 13:31–32; Mark 4:30–32","e":"EVT-02825"}],"nm":{"EVT-02825":"Jesus teaches the multitude in parables by the sea","PER-03010":"Jesus"}},"OBJ-00590":{"k":"object","n":"The parable of the leaven","d":"The kingdom of heaven is like leaven which a woman hid in three measures of meal till it was all leavened (Matthew 13:33)","f":[{"p":"contents","r":"NKJV notes, note on Matthew 13:33; Matthew 13:33","v":"The kingdom of heaven is like leaven which a woman hid in three measures of meal till it was all leavened"},{"p":"designation","r":"Matthew 13:33","v":"The kingdom of heaven is like leaven"},{"p":"made by","r":"Matthew 13:33","e":"PER-03010"},{"p":"occasion","r":"Matthew 13:33","e":"EVT-02825"}],"nm":{"EVT-02825":"Jesus teaches the multitude in parables by the sea","PER-03010":"Jesus"}},"OBJ-00591":{"k":"object","n":"The parable of the hidden treasure","d":"The kingdom of heaven is like treasure hidden in a field, for joy over which a man sells all that he has and buys that field (Matthew 13:44)","f":[{"p":"contents","r":"Matthew 13:44","v":"The kingdom of heaven is like treasure hidden in a field, for joy over which a man sells all that he has and buys that field"},{"p":"designation","r":"Matthew 13:44","v":"The kingdom of heaven is like treasure hidden in a field"},{"p":"made by","r":"Matthew 13:44","e":"PER-03010"},{"p":"occasion","r":"Matthew 13:44","e":"EVT-02826"}],"nm":{"EVT-02826":"Jesus explains the parables to His disciples in the house","PER-03010":"Jesus"}},"OBJ-00592":{"k":"object","n":"The parable of the pearl of great price","d":"The kingdom of heaven is like a merchant who, finding one pearl of great price, sold all that he had and bought it (Matthew 13:45–46)","f":[{"p":"contents","r":"Matthew 13:45–46","v":"The kingdom of heaven is like a merchant who, finding one pearl of great price, sold all that he had and bought it"},{"p":"designation","r":"Matthew 13:45–46","v":"The kingdom of heaven is like a merchant seeking beautiful pearls"},{"p":"made by","r":"Matthew 13:45–46","e":"PER-03010"},{"p":"occasion","r":"Matthew 13:45–46","e":"EVT-02826"}],"nm":{"EVT-02826":"Jesus explains the parables to His disciples in the house","PER-03010":"Jesus"}},"OBJ-00593":{"k":"object","n":"The parable of the dragnet","d":"The kingdom of heaven is like a dragnet cast into the sea, gathering every kind, from which the good were gathered into vessels and the bad thrown away (Matthew 13:47–50)","f":[{"p":"contents","r":"Matthew 13:47–50","v":"The kingdom of heaven is like a dragnet cast into the sea, gathering every kind, from which the good were gathered into vessels and the bad thrown away"},{"p":"contents","r":"Matthew 13:49–50","v":"As Jesus explained it: So it will be at the end of the age, when the angels separate the wicked from among the just"},{"p":"designation","r":"Matthew 13:47–50","v":"The kingdom of heaven is like a dragnet"},{"p":"made by","r":"Matthew 13:47–50","e":"PER-03010"},{"p":"occasion","r":"Matthew 13:47–50","e":"EVT-02826"}],"nm":{"EVT-02826":"Jesus explains the parables to His disciples in the house","PER-03010":"Jesus"}},"OBJ-00594":{"k":"object","n":"The parable of the lost sheep","d":"A man with a hundred sheep leaves the ninety-nine to seek the one that strays, and rejoices more over it than over the ninety-nine; so the Father wills that none of these little ones perish (Matthew 18:12–14)","f":[{"p":"contents","r":"Matthew 18:12–14","v":"A man with a hundred sheep leaves the ninety-nine to seek the one that strays, and rejoices more over it than over the ninety-nine; so the Father wills that none of these little ones perish"},{"p":"designation","r":"Matthew 18:12–14","v":"If a man has a hundred sheep"},{"p":"made by","r":"Matthew 18:12–14","e":"PER-03010"},{"p":"occasion","r":"Matthew 18:12–14","e":"EVT-02849"}],"nm":{"EVT-02849":"Jesus teaches His disciples who is the greatest in the kingdom of heaven","PER-03010":"Jesus"}},"OBJ-00595":{"k":"object","n":"The parable of the unforgiving servant","d":"A king forgave a servant who owed ten thousand talents, but the servant seized a fellow servant who owed him a hundred denarii and threw him into prison; the king delivered him to the torturers until he paid all (Matthew 18:23–35)","f":[{"p":"contents","r":"Matthew 18:23–35","v":"A king forgave a servant who owed ten thousand talents, but the servant seized a fellow servant who owed him a hundred denarii and threw him into prison; the king delivered him to the torturers until he paid all"},{"p":"designation","r":"Matthew 18:23–35","v":"the kingdom of heaven is like a certain king"},{"p":"made by","r":"Matthew 18:23–35","e":"PER-03010"},{"p":"occasion","r":"Matthew 18:23–35","e":"EVT-02849"}],"nm":{"EVT-02849":"Jesus teaches His disciples who is the greatest in the kingdom of heaven","PER-03010":"Jesus"}},"OBJ-00596":{"k":"object","n":"The parable of the laborers in the vineyard","d":"A landowner hired laborers for his vineyard through the day and paid those hired at the eleventh hour a denarius, as much as those who bore the heat of the day, who grumbled; so the last will be first (Matthew 20:1–16)","f":[{"p":"contents","r":"Matthew 20:1–16","v":"A landowner hired laborers for his vineyard through the day and paid those hired at the eleventh hour a denarius, as much as those who bore the heat of the day, who grumbled; so the last will be first"},{"p":"designation","r":"Matthew 20:1–16","v":"the kingdom of heaven is like a landowner"},{"p":"made by","r":"Matthew 20:1–16","e":"PER-03010"},{"p":"occasion","r":"Matthew 20:1–16","e":"EVT-02853"}],"nm":{"EVT-02853":"Jesus counsels a rich young man","PER-03010":"Jesus"}},"OBJ-00597":{"k":"object","n":"The fig tree Jesus cursed","d":"A fig tree by the road with nothing on it but leaves, which withered at Jesus's word (Matthew 21:19–20)","f":[{"p":"designation","r":"Matthew 21:19","v":"a fig tree by the road"},{"p":"designation","r":"Mark 11:13","v":"a fig tree having leaves"},{"p":"feature","r":"Matthew 21:19–20","v":"Finding nothing on it but leaves, Jesus said no fruit would grow on it again, and it withered at once"},{"p":"feature","r":"Mark 11:13","v":"It was not the season for figs"},{"p":"feature","r":"Matthew 21:19; Mark 11:14, 20","v":"Jesus said no one would eat fruit from it ever again, and the next morning the disciples saw it dried up from the roots","s":"alternative","w":"Mark tells that the tree was seen dried up from the roots the morning after Jesus cursed it (Mark 11:14, 20), where Matthew tells that it withered at once (Matthew 21:19); Matthew's telling, entered first, stands as the preferred."}],"nm":{}},"OBJ-00598":{"k":"object","n":"The parable of the two sons","d":"A man bade his two sons work in his vineyard: the first said he would not, but afterward went; the second said he would go, but did not; the first did his father's will (Matthew 21:28–32)","f":[{"p":"contents","r":"Matthew 21:28–32","v":"A man bade his two sons work in his vineyard: the first said he would not, but afterward went; the second said he would go, but did not; the first did his father's will"},{"p":"designation","r":"Matthew 21:28–32","v":"A man had two sons"},{"p":"made by","r":"Matthew 21:28–32","e":"PER-03010"},{"p":"occasion","r":"Matthew 21:28–32","e":"EVT-02861"}],"nm":{"EVT-02861":"The chief priests and elders question Jesus's authority","PER-03010":"Jesus"}},"OBJ-00599":{"k":"object","n":"The parable of the wicked vinedressers","d":"A landowner leased his vineyard to vinedressers who beat, killed and stoned the servants he sent for its fruit, and at last killed his son, the heir; he will destroy them and lease the vineyard to others (Matthew 21:33–41)","f":[{"p":"contents","r":"Matthew 21:33–41","v":"A landowner leased his vineyard to vinedressers who beat, killed and stoned the servants he sent for its fruit, and at last killed his son, the heir; he will destroy them and lease the vineyard to others"},{"p":"contents","r":"NKJV notes, note on Mark 12:1; NKJV notes, note on Mark 12:4; Mark 12:1–9","v":"As Mark tells it: a man planted a vineyard with a hedge, a wine vat and a tower and leased it to vinedressers (tenant farmers, by the NKJV note); the servants he sent for the fruit they beat, stoned (NU omits, by the NKJV note), wounded and killed, and last he sent his beloved son, whom they killed and cast out of the vineyard; the owner will come, destroy the vinedressers and give the vineyard to others"},{"p":"designation","r":"Matthew 21:33–41","v":"a certain landowner who planted a vineyard"},{"p":"made by","r":"Matthew 21:33–41; Mark 12:1","e":"PER-03010"},{"p":"occasion","r":"Matthew 21:33–41; Mark 12:1–12","e":"EVT-02861"}],"nm":{"EVT-02861":"The chief priests and elders question Jesus's authority","PER-03010":"Jesus"}}});
